window.STORIES = [{"n":1,"t":"Hallo, ich bin Mia!","l":"A1","review":false,"p":[["Freiburg. Sonntag, vierzehn Uhr. Hier ist die Lindenstraße, Nummer zwölf. Das ist Mia. Mia ist neu hier. Der Koffer ist groß und schwer. Puh!"],["Die Tür ist offen. Ein Mann ist auf der Treppe."],["Mann","Hallo! Bist du die neue Nachbarin?"],["Mia","Hallo! Ja, ich bin neu hier. Ich bin Mia."],["Mann","Freut mich, Mia! Ich bin Jonas."],["Mia","Freut mich auch, Jonas."],["Jonas","Der Koffer – ist er schwer?"],["Mia","Ja, sehr!"],["Jonas","Moment … So! Bitte schön."],["Mia","Oh, danke!"],["Unten ist eine Tür. Die Tür ist offen. Da ist eine Frau. Sie ist alt, aber sie ist sehr elegant."],["Frau","Guten Tag! Sind Sie die neue Nachbarin?"],["Mia","Guten Tag! Ja. Ich bin Mia Costa."],["Frau","Ich heiße Schulz. Frau Schulz. Herzlich willkommen!"],["Mia","Danke, Frau Schulz!"],["Frau Schulz","Und das ist Felix."],["Mia","Felix? Wer ist Felix?"],["Felix","Miau!"],["Mia","Oh! Hallo, Felix!"],["Jonas","Felix ist der Chef hier im Haus."],["Frau Schulz","Ja, das ist richtig. Felix ist der Chef. Und ich bin die Chefin von Felix!"],["Mia lacht. Jonas lacht. Felix lacht nicht. Felix ist ein Chef."],["Mia","Wie heißt du, Felix? Felix Schulz?"],["Felix","Miau."],["Jonas","Ja, Felix Schulz. Sehr wichtig!"],["Mia","Tschüss, Frau Schulz! Tschüss, Felix! Und danke, Jonas!"],["Jonas","Tschüss, Mia!"],["Die Wohnung ist oben. Wohnung Nummer drei. Mia ist allein. Sie ist müde, sehr müde. Aber sie ist auch froh. Hallo, Freiburg!"],["Am Abend ist da ein Zettel. Er ist unter der Tür. Auf dem Zettel steht:"],["Hallo Nachbarin! Woher bist du? – J."],["Mia lächelt. J? Wer ist J? Ist das … Jonas?"]],"q":["Wo ist Mia? (Stadt und Straße)","Richtig oder falsch? Der Koffer ist klein.","Wer ist Felix?","Was steht auf dem Zettel?","Und du? Wer bist du? Wie heißt du? Bist du auch neu hier?"],"a":["In Freiburg, in der Lindenstraße 12. The story starts: „Hier ist die Lindenstraße, Nummer zwölf.“","Falsch. „Der Koffer ist groß und schwer.“","Frau Schulz's cat, the \"boss\" of the house. Jonas says: „Felix ist der Chef hier im Haus.“","„Hallo Nachbarin! Woher bist du? – J.“ The note is under Mia's door in the evening.","Example: Ich bin Sam. Ich heiße Sam Taylor. Ja, ich bin auch neu hier."],"w":[["sein (bin, bist, ist, sind)","to be","Mia ist neu hier."],["heißen","to be called","Ich heiße Schulz."],["der Nachbar, die Nachbarn / die Nachbarin, die Nachbarinnen","neighbour","Bist du die neue Nachbarin?"],["der Koffer, die Koffer","suitcase","Der Koffer ist groß und schwer."],["die Tür, die Türen","door","Die Tür ist offen."],["die Treppe, die Treppen","stairs","Ein Mann ist auf der Treppe."],["die Wohnung, die Wohnungen","flat, apartment","Die Wohnung ist oben."],["der Zettel, die Zettel","note, slip of paper","Am Abend ist da ein Zettel."],["neu","new","Mia ist neu hier."],["müde","tired","Sie ist müde, sehr müde."],["froh","glad, happy","Aber sie ist auch froh."],["offen","open","Die Tür ist offen."],["oben / unten","upstairs / downstairs","Unten ist eine Tür."],["allein","alone","Mia ist allein."],["wer","who","Wer ist Felix?"]],"c":[["Freut mich!","Nice to meet you!","Freut mich, Mia!"],["Herzlich willkommen!","Welcome!","Ich heiße Schulz. Herzlich willkommen!"],["Bitte schön.","Here you are.","So! Bitte schön."],["Guten Tag! / Tschüss!","Hello (formal) / Bye!","Tschüss, Frau Schulz!"]],"x":[["hallo","hello",""],["guten Abend","good evening",""],["auf Wiedersehen","goodbye (formal)",""],["bis später","see you later",""]],"g":["das Verb sein",["sein (to be) is irregular: ich bin, du bist, er/sie/es ist, Sie sind.","du = friends, young people, family. Sie (capital S) = strangers, older people, formal.","Jonas and Mia say du. Frau Schulz and Mia say Sie.","Beispiele: Ich bin neu hier. · Sind Sie die neue Nachbarin?"]]},{"n":2,"t":"Woher kommst du?","l":"A1","review":false,"p":[["Montag, acht Uhr. Mia ist wach. Der Zettel ist auf dem Tisch: Hallo Nachbarin! Woher bist du? – J."],["Mia schreibt auf den Zettel: Hallo J.! Ich komme aus Portugal. Und du? – M. Dann geht sie zur Tür. Und da ist Jonas, auf der Treppe, mit Kaffee."],["Jonas","Guten Morgen, Mia!"],["Mia","Guten Morgen, Jonas! Ist der Zettel von dir?"],["Jonas","Ja! Also: Woher kommst du?"],["Mia","Ich komme aus Portugal."],["Jonas","Aus Portugal! Super! Woher genau? Aus Lissabon?"],["Mia","Nein, ich komme aus Porto."],["Jonas","Porto! Ich liebe Porto!"],["Mia","Und du? Woher kommst du?"],["Jonas","Ich komme aus Freiburg. Ich wohne hier oben, Wohnung vier."],["Mia","Und was machst du?"],["Jonas","Ich koche. Ich arbeite im Café Sonne. Und du? Was machst du hier in Freiburg?"],["Mia","Ich lerne Deutsch. Morgen ist der Kurs."],["Jonas","Wo ist der Kurs?"],["Mia","In der Sprachschule. Der Lehrer heißt Herr Brandt."],["Jonas","Herr Brandt? Ha!"],["Mia","Was? Wie bitte? Wer ist Herr Brandt?"],["Jonas","Ach … nichts. Viel Glück, Mia! Tschüss!"],["Und weg ist er."],["Unten ist Frau Schulz. Felix ist auch da."],["Frau Schulz","Guten Morgen, Frau Costa! Woher kommen Sie? Aus Spanien?"],["Mia","Nein, ich komme aus Portugal. Und Sie, Frau Schulz? Woher kommen Sie?"],["Frau Schulz","Ich komme aus Berlin. Aber ich wohne schon lange hier."],["Mia","Wohnen Sie gern hier?"],["Frau Schulz","Ja, sehr gern. Freiburg ist schön. Und Felix wohnt auch gern hier, nicht wahr, Felix?"],["Felix","Miau!"],["Mia","Frau Schulz, kennen Sie Herrn Brandt? Er ist Lehrer."],["Frau Schulz","Brandt? Nein. Aber Felix kennt alle."],["Felix","Miau."],["Mia geht in die Wohnung. Sie denkt: Viel Glück? Warum viel Glück? Wer ist Herr Brandt?"]],"q":["Woher kommt Mia genau?","Richtig oder falsch? Jonas kommt aus Berlin.","Was macht Jonas? Wo arbeitet er?","Was sagt Jonas über Herrn Brandt?","Und du? Woher kommst du? Wo wohnst du? Was machst du?"],"a":["Aus Porto, in Portugal. Mia says: „Nein, ich komme aus Porto.“","Falsch. Jonas says: „Ich komme aus Freiburg.“ Frau Schulz comes from Berlin.","He is a cook at Café Sonne. „Ich koche. Ich arbeite im Café Sonne.“","Only „Ha!“ and „Viel Glück, Mia!“ He laughs and doesn't explain. That's the mystery.","Example: Ich komme aus Irland. Ich wohne in Dublin. Ich arbeite und ich lerne Deutsch."],"w":[["kommen","to come","Ich komme aus Portugal."],["wohnen","to live (somewhere)","Ich wohne hier oben."],["lernen","to learn","Ich lerne Deutsch."],["machen","to do, make","Was machst du?"],["arbeiten","to work","Ich arbeite im Café Sonne."],["kochen","to cook","Ich koche."],["kennen","to know (a person)","Kennen Sie Herrn Brandt?"],["woher","where from","Woher kommst du?"],["wo","where","Wo ist der Kurs?"],["was","what","Und was machst du?"],["aus","from","Ich komme aus Berlin."],["der Kurs, die Kurse","course, class","Morgen ist der Kurs."],["der Lehrer, die Lehrer","teacher","Der Lehrer heißt Herr Brandt."],["morgen","tomorrow","Morgen ist der Kurs."],["genau","exactly","Woher genau?"]],"c":[["Guten Morgen!","Good morning!","Guten Morgen, Mia!"],["Ich komme aus …","I'm from …","Ich komme aus Freiburg."],["Wie bitte?","Sorry? Pardon?","Was? Wie bitte?"],["Viel Glück!","Good luck!","Viel Glück, Mia!"],["schon lange","for a long time","Ich wohne schon lange hier."]],"x":[["bis morgen","see you tomorrow",""],["danke","thanks",""],["danke schön","thank you very much",""],["Wie geht's?","how are you?",""],["sehr gut","very good",""]],"g":["regelmäßige Verben (ich, du, Sie) und W-Fragen",["A verb = stem + ending: komm-en, wohn-en, lern-en.","Endings: ich -e, du -st, Sie -en → ich komme, du kommst, Sie kommen.","W-questions start with wer, was, wo, woher, wie. The verb is in position 2.","Beispiele: Woher kommst du? · Wo wohnen Sie?"]]},{"n":3,"t":"Der erste Tag im Kurs","l":"A1","review":false,"p":[["Dienstag, neun Uhr. Die Sprachschule ist in der Altstadt. Mia ist im Kursraum. Sie ist nervös. Neben Mia sitzt eine junge Frau mit langen, schwarzen Haaren."],["Elif","Hallo! Ich bin Elif. Ich komme aus der Türkei, aus İzmir."],["Mia","Hallo, Elif! Ich bin Mia. Ich komme aus Portugal."],["Mann","Und ich bin Tom. Ich komme aus Polen, aus Krakau. Ihr seid auch neu, oder?"],["Elif","Ja, wir sind neu. Wir lernen ab heute Deutsch."],["Dann kommt der Lehrer. Er ist groß und er trägt eine Brille. Das ist Herr Brandt. Und er spricht schnell. Sehr schnell."],["Herr Brandt","GutenMorgenichheißeBrandtundichbinIhrLehrer!"],["Alle","…"],["Mia","Wie bitte?"],["Herr Brandt","Guten Morgen. Ich heiße Brandt. Ich bin der Lehrer. Und Sie? WieheißenSieundwasmachenSie?"],["Mia","Ich heiße Mia Costa. Ich komme aus Portugal. Ich bin Webdesignerin."],["Herr Brandt","Gut. Und Sie?"],["Elif","Ich heiße Elif. Ich studiere Medizin."],["Herr Brandt","Und Sie?"],["Tom","Äh … Noch einmal, bitte. Langsam, bitte!"],["Herr Brandt","Was – ma – chen – Sie?"],["Tom","Ach so! Ich bin Busfahrer."],["Herr Brandt lacht nicht. Er schreibt an die Tafel: ich lerne, du lernst, er lernt, wir lernen, ihr lernt, sie lernen. Die Gruppe schreibt und schreibt."],["Um halb elf ist Pause."],["Tom","Er ist streng, oder?"],["Elif","Ja, aber er erklärt gut."],["Mia","Mein Nachbar kennt Herrn Brandt. Er sagt nur: „Viel Glück!“"],["Tom","Ha! Viel Glück! Ja, das brauchen wir!"],["Elif","Mia, wo wohnst du?"],["Mia","In der Lindenstraße. Und ihr? Wo wohnt ihr?"],["Elif","Ich wohne im Studentenwohnheim. Und Tom wohnt in Haslach."],["Tom","Wir trinken mal zusammen Kaffee, okay?"],["Elif","Gute Idee! Mia, wie ist deine Telefonnummer?"],["Mia","Meine Nummer? Äh … Ich habe eine neue Nummer. Eine deutsche Nummer. Und … ich weiß sie nicht!"],["Elif und Tom lachen. Mia lacht auch. Aber sie denkt: Oh nein. Wie ist meine Nummer?"]],"q":["Woher kommt Elif?","Was ist Tom von Beruf?","Richtig oder falsch? Herr Brandt spricht sehr langsam.","Was sagen Elif und Tom über Herrn Brandt?","Und du? Was machst du? Wo wohnst du?"],"a":["Aus der Türkei, aus İzmir. „Ich komme aus der Türkei, aus İzmir.“","Er ist Busfahrer. Tom finally understands and says: „Ich bin Busfahrer.“","Falsch. „Und er spricht schnell. Sehr schnell.“","He is strict, but he explains well. Tom: „Er ist streng, oder?“ – Elif: „Ja, aber er erklärt gut.“","Example: Ich bin Lehrer. Ich wohne in Manchester."],"w":[["er, sie, es / wir / ihr / sie","he, she, it / we / you (pl.) / they","Ihr seid auch neu, oder?"],["die Sprachschule, die Sprachschulen","language school","Die Sprachschule ist in der Altstadt."],["heute","today","Wir lernen ab heute Deutsch."],["studieren","to study (at university)","Ich studiere Medizin."],["der Busfahrer, die Busfahrer","bus driver","Ich bin Busfahrer."],["schreiben","to write","Er schreibt an die Tafel."],["die Tafel, die Tafeln","board (in class)","Er schreibt an die Tafel."],["die Pause, die Pausen","break","Um halb elf ist Pause."],["schnell","fast","Er spricht sehr schnell."],["langsam","slow(ly)","Langsam, bitte!"],["streng","strict","Er ist streng, oder?"],["erklären","to explain","Aber er erklärt gut."],["trinken","to drink","Wir trinken mal zusammen Kaffee."],["zusammen","together","Wir trinken mal zusammen Kaffee."],["die Telefonnummer, die Telefonnummern","phone number","Wie ist deine Telefonnummer?"]],"c":[["Noch einmal, bitte.","Once more, please.","Noch einmal, bitte. Langsam, bitte!"],["…, oder?","…, right?","Er ist streng, oder?"],["Ach so!","Oh, I see!","Ach so! Ich bin Busfahrer."],["Gute Idee!","Good idea!","Gute Idee!"]],"x":[["nicht so gut","not so good",""],["es geht","so-so",""],["nein","no",""],["Ich heiße …","my name is …",""],["Mein Name ist …","my name is … (formal)",""]],"g":["das Präsens – alle Personen",["ich lerne · du lernst · er/sie/es lernt · wir lernen · ihr lernt · sie/Sie lernen","Stem ends in -t or -d? Add -e-: er arbeitet.","ihr = you (two or more friends). sie = they. Sie = you (formal).","sein again: wir sind, ihr seid, sie sind.","Beispiele: Wo wohnt ihr? · Wir lernen ab heute Deutsch."]]},{"n":4,"t":"Wie ist deine Nummer?","l":"A1","review":false,"p":[["Mittwoch, sieben Uhr. Mia sucht. Wo ist die SIM-Karte? Wo ist die Box? Ah, hier! Auf der Box steht die Nummer: 0176 12 19 08 04. Mia lernt die Nummer: Null, eins, sieben, sechs … zwölf … neunzehn …"],["Im Kurs schreibt Herr Brandt an die Tafel: 0, 1, 2, 3 … 20."],["Herr Brandt","Heute lernen wir Zahlen. Null, eins, zwei, drei, vier, fünf, sechs, sieben, acht, neun, zehn. Und jetzt: elf, zwölf, dreizehn, vierzehn, fünfzehn, sechzehn, siebzehn, achtzehn, neunzehn, zwanzig."],["Alle","Elf, zwölf, dreizehn …"],["Herr Brandt","Herr Nowak, ist drei plus vier sieben?"],["Tom","Ja, drei plus vier ist sieben."],["Herr Brandt","Richtig. Ist acht plus sechs fünfzehn?"],["Tom","Ja! … Nein! Moment … Acht plus sechs ist vierzehn!"],["Herr Brandt","Richtig. Frau Costa, wissen Sie jetzt Ihre Nummer?"],["Mia","Ja! Null, eins, sieben, sechs, zwölf, neunzehn, null acht, null vier."],["Herr Brandt","Sehr gut. Sie lernen schnell."],["Und dann – ein Wunder! – lächelt Herr Brandt. Nur eine Sekunde. Aber er lächelt."],["In der Pause schreibt Elif die Nummer in ihr Handy."],["Elif","Und meine Nummer ist: null, eins, fünf, zwei, sechzehn, elf, drei, zwanzig."],["Mia","Null, eins, fünf, zwei, sechs …"],["Elif","Nein, falsch! Sechzehn! Nicht sechs!"],["Mia","Ach so, sechzehn. Ist das jetzt richtig?"],["Elif","Ja, richtig!"],["Tom","Und meine Nummer? Ist sie auch wichtig?"],["Mia und Elif","Ja, klar!"],["Tom","Null, eins, sieben, null, elf, elf, elf. Bus Nummer elf!"],["Am Nachmittag ist Jonas auf der Treppe."],["Jonas","Mia! Hast du eine deutsche Nummer?"],["Mia","Ja, seit heute. Warum?"],["Jonas","Für Notfälle. Zum Beispiel: Felix ist weg!"],["Mia","Ist Felix oft weg?"],["Jonas","Felix? Felix ist immer unterwegs. Also: Wie ist deine Nummer?"],["Mia","Null, eins, sieben, sechs, zwölf, neunzehn, null acht, null vier."],["Jonas","Zwölf, sechzehn …"],["Mia","Nein! Neunzehn!"],["Am Abend macht das Handy pling! Eine Nachricht von Elif: Hallo Mia! Lernen wir morgen zusammen? Bei dir? Um vier?"],["Mia schreibt","Ja, klar! Dann sieht sie die Wohnung. Kartons. Kartons überall. Kein Tisch, kein Stuhl, kein Bett. Oh nein. Die Wohnung!"]],"q":["Wo findet Mia ihre Nummer?","Richtig oder falsch? Acht plus sechs ist fünfzehn.","Elif sagt „sechzehn“. Was schreibt Mia zuerst?","Warum möchte Jonas Mias Nummer?","Und du? Wie ist deine Telefonnummer? Sag sie auf Deutsch."],"a":["Auf der Box von der SIM-Karte. „Auf der Box steht die Nummer.“","Falsch. Tom says: „Acht plus sechs ist vierzehn!“","Sechs. Elif corrects her: „Nein, falsch! Sechzehn! Nicht sechs!“","For emergencies, e.g. when Felix is gone. „Für Notfälle. Zum Beispiel: Felix ist weg!“","Example: Meine Nummer ist null, sieben, neun, zwölf, achtzehn …"],"w":[["null … zwanzig","numbers 0–20","Elf, zwölf, dreizehn …"],["die Zahl, die Zahlen","number (maths)","Heute lernen wir Zahlen."],["die Nummer, die Nummern","number (phone, bus)","Wie ist deine Nummer?"],["das Handy, die Handys","mobile phone","Elif schreibt die Nummer in ihr Handy."],["die Nachricht, die Nachrichten","message","Eine Nachricht von Elif."],["suchen","to look for","Mia sucht."],["wissen (ich weiß)","to know (a fact)","Wissen Sie jetzt Ihre Nummer?"],["richtig","right, correct","Ist das jetzt richtig?"],["falsch","wrong","Nein, falsch!"],["plus","plus","Drei plus vier ist sieben."],["jetzt","now","Ist das jetzt richtig?"],["immer","always","Felix ist immer unterwegs."],["oft","often","Ist Felix oft weg?"],["der Karton, die Kartons","cardboard box","Kartons überall."]],"c":[["Moment!","Just a moment!","Moment … Acht plus sechs ist vierzehn!"],["Ja, klar!","Yes, of course!","Ja, klar!"],["zum Beispiel","for example","Zum Beispiel: Felix ist weg!"],["Oh nein!","Oh no!","Oh nein. Die Wohnung!"]],"x":[["Woher kommst du?","where are you from?",""],["Ich wohne in …","I live in …",""],["der Vorname, die Vornamen","first name",""],["Frau","Mrs / Ms",""],["Schönes Wochenende!","have a nice weekend!",""]],"g":["Ja/Nein-Fragen und Zahlen 0–20",["In a yes/no question the verb comes first: Ist das richtig?","Compare: W-question Wo wohnst du? – yes/no question Wohnst du hier?","13–19 = small number + zehn: dreizehn, vierzehn. Careful: sechzehn, siebzehn lose letters.","Beispiele: Ist acht plus sechs fünfzehn? · Lernen wir morgen zusammen?"]]},{"n":5,"t":"Mias Wohnung","l":"A1","review":false,"p":[["Donnerstag, drei Uhr. Mia räumt auf. Schnell, schnell! Die Kartons sind jetzt in der Ecke. Um vier klingelt es."],["Elif","Hallo, Mia! Wohnung Nummer drei – richtig?"],["Mia","Richtig! Hallo, Elif! Komm rein!"],["Elif","Danke! Oh, schön! Ist das die Küche?"],["Mia","Ja, das ist die Küche. Die Küche ist klein, aber sie ist neu. Der Herd ist neu, und der Kühlschrank ist auch neu."],["Elif","Und der Kühlschrank? Ist er voll?"],["Mia","Nein, er ist leer. Leider!"],["Elif lacht."],["Mia","Und das ist das Bad. Das Bad ist sehr klein. Die Dusche ist auch klein."],["Elif","Und das Zimmer?"],["Mia","Schau mal! Das ist das Zimmer."],["Elif","Wow! Das Zimmer ist groß und hell. Und das Fenster ist riesig!"],["Mia","Ja. Und hier ist der Balkon."],["Elif","Ein Balkon! Toll! … Oh! Wer ist das?"],["Auf dem Balkon sitzt eine Katze. Nein, ein Kater. Er ist grau und dick."],["Felix","Miau."],["Mia","Das ist Felix. Er wohnt unten. Aber er ist überall."],["Elif","Und Jonas? Wohnt er auch hier?"],["Mia","Ja, oben. Warum?"],["Elif","Nur so. Ist Jonas nett?"],["Mia","Ja … er ist nett."],["Elif","Aha!"],["Mia","Elif! Wir lernen jetzt Deutsch!"],["Sie lernen","der, die, das."],["Elif","Der Balkon, die Küche, das Bad, das Zimmer … Warum das Fenster? Warum die Tür? Das ist so schwer!"],["Mia","Ein Trick: Der Kühlschrank – er ist leer. Die Küche – sie ist klein. Das Bad – es ist klein."],["Elif","Und Felix? Der, die oder das?"],["Mia","Der Felix. Er ist der Chef!"],["Felix","Miau!"],["Um sieben geht Elif."],["Elif","Tschüss, Mia! Die Wohnung ist wirklich schön. Moment … Mia, wo ist das Bett?"],["Mia","Das Bett? Gute Frage. Das Bett kommt … bald. Vielleicht."],["Elif","Und heute Nacht?"],["Mia sieht auf den Boden. Der Boden ist hart. Sehr hart."]],"q":["Wie ist die Küche?","Richtig oder falsch? Der Kühlschrank ist voll.","Wie ist das Zimmer?","Welche Frage hat Elif über Jonas?","Und du? Wie ist deine Wohnung? Ist die Küche groß oder klein?"],"a":["Klein, aber neu. „Die Küche ist klein, aber sie ist neu.“","Falsch. Mia says: „Nein, er ist leer. Leider!“","Groß und hell, mit einem riesigen Fenster. „Das Zimmer ist groß und hell.“","„Ist Jonas nett?“ Elif is curious about Jonas.","Example: Meine Wohnung ist klein. Die Küche ist auch klein, aber das Zimmer ist hell."],"w":[["die Küche, die Küchen","kitchen","Die Küche ist klein."],["das Bad, die Bäder","bathroom","Das Bad ist sehr klein."],["das Zimmer, die Zimmer","room","Das Zimmer ist groß und hell."],["der Balkon, die Balkone","balcony","Hier ist der Balkon."],["das Fenster, die Fenster","window","Das Fenster ist riesig!"],["der Kühlschrank, die Kühlschränke","fridge","Der Kühlschrank ist auch neu."],["der Herd, die Herde","stove","Der Herd ist neu."],["die Dusche, die Duschen","shower","Die Dusche ist auch klein."],["das Bett, die Betten","bed","Mia, wo ist das Bett?"],["der Boden, die Böden","floor","Der Boden ist hart."],["klein / hell","small / bright","Das Zimmer ist groß und hell."],["leer / voll","empty / full","Ist er voll? – Nein, er ist leer."],["nett","nice, kind","Ist Jonas nett?"],["leider","unfortunately","Leider!"],["vielleicht","maybe","Das Bett kommt … bald. Vielleicht."]],"c":[["Komm rein!","Come in!","Hallo, Elif! Komm rein!"],["Schau mal!","Look!","Schau mal! Das ist das Zimmer."],["Nur so.","Just because. / No reason.","Warum? – Nur so."],["Gute Frage.","Good question.","Das Bett? Gute Frage."]],"x":[["Bis bald!","see you soon!",""],["die Person, die Personen","person",""],["der Großvater, die Großväter","grandfather",""],["die Cousine, die Cousinen","cousin (f)",""],["die Partnerin, die Partnerinnen","partner (f)",""]],"g":["der, die, das",["Every German noun has a gender: der (masculine), die (feminine), das (neuter).","Learn every noun WITH its article: der Balkon, die Küche, das Bad.","The pronoun follows the gender: der → er, die → sie, das → es.","Tip: nouns ending in -ung are always die: die Wohnung.","Beispiele: Der Kühlschrank – er ist leer. · Das Bad – es ist klein."]]},{"n":6,"t":"Kein Bett!","l":"A1","review":false,"p":[["Freitag, sechs Uhr. Mia ist wach. Der Boden ist hart, und der Rücken ist kaputt. Die Nacht war lang."],["Mia sieht das Zimmer an. Hier ist ein Tisch, aber da ist kein Stuhl. Hier ist eine Lampe, aber da ist kein Sofa. Und da ist kein Bett. Nur Kartons. Und eine Jacke – das ist das „Bett“."],["Um neun ruft Mia das Möbelhaus an."],["Frau","Möbel König, guten Tag!"],["Mia","Guten Tag, hier ist Costa. Wo ist mein Bett?"],["Frau","Moment … Ein Bett und ein Schrank für Costa, Lindenstraße zwölf? Das Bett kommt am Montag."],["Mia","Am Montag?! Ist das ein Witz?"],["Frau","Nein, das ist kein Witz. Tut mir leid."],["Mia geht nach unten. Jonas und Frau Schulz sind im Flur."],["Jonas","Mia! Du bist so blass. Ist alles okay?"],["Mia","Nein. Ich habe kein Bett. Ich schlafe auf dem Boden."],["Frau Schulz","Kein Bett? Das geht nicht! Im Keller ist ein Sofa. Es ist alt, aber es ist bequem."],["Mia","Ein Sofa? Wirklich?"],["Jonas","Kein Problem. Ich bin stark!"],["Das Sofa ist grün, mit Blumen. Es ist nicht schön. Aber es ist sehr, sehr schwer. Jonas und Mia tragen das Sofa nach oben. Eine Treppe. Zwei Treppen."],["Jonas","Puh! Das ist kein Sofa. Das ist ein Elefant!"],["Mia lacht. Endlich steht das Sofa im Zimmer. Und sofort springt Felix auf das Sofa."],["Felix","Miau!"],["Frau Schulz","Felix sagt: „Das ist kein Sofa für Frau Costa. Das ist ein Sofa für Felix!“"],["Mia","Danke, Frau Schulz! Und danke, Jonas!"],["Jonas","Mia, du brauchst Kaffee. Morgen um zehn – Café Sonne. Ich mache einen Kaffee für dich."],["Mia","Ist das eine Einladung?"],["Jonas","Nein. Das ist ein Befehl!"],["Er lacht und geht. Mia lächelt. Morgen. Café Sonne. Zehn Uhr."]],"q":["Wo schläft Mia in der Nacht?","Wann kommt das Bett?","Richtig oder falsch? Das Sofa ist neu und leicht.","Was sagt Frau Schulz für Felix?","Und du? Was ist in deinem Zimmer? Was ist nicht da? (Hier ist ein …, aber kein …)"],"a":["Auf dem Boden, mit einer Jacke. „Ich schlafe auf dem Boden.“","Am Montag. The woman from the shop says: „Das Bett kommt am Montag.“","Falsch. „Es ist alt, aber es ist bequem.“ And it is very heavy: „Das ist ein Elefant!“","„Das ist ein Sofa für Felix!“ Felix jumps on the sofa at once.","Example: Hier ist ein Bett und ein Tisch, aber kein Sofa."],"w":[["ein / eine","a, an","Hier ist eine Lampe."],["kein / keine","no, not a","Da ist kein Bett."],["der Tisch, die Tische","table","Hier ist ein Tisch."],["der Stuhl, die Stühle","chair","Da ist kein Stuhl."],["die Lampe, die Lampen","lamp","Hier ist eine Lampe."],["das Sofa, die Sofas","sofa","Im Keller ist ein Sofa."],["der Schrank, die Schränke","wardrobe, cupboard","Ein Bett und ein Schrank für Costa."],["der Keller, die Keller","cellar","Im Keller ist ein Sofa."],["die Jacke, die Jacken","jacket","Und eine Jacke – das ist das „Bett“."],["der Witz, die Witze","joke","Ist das ein Witz?"],["die Einladung, die Einladungen","invitation","Ist das eine Einladung?"],["alt","old","Es ist alt, aber es ist bequem."],["bequem","comfortable","Es ist alt, aber es ist bequem."],["stark","strong","Ich bin stark!"],["schlafen","to sleep","Ich schlafe auf dem Boden."]],"c":[["Tut mir leid.","I'm sorry.","Nein, das ist kein Witz. Tut mir leid."],["Ist alles okay?","Is everything okay?","Du bist so blass. Ist alles okay?"],["Kein Problem!","No problem!","Kein Problem. Ich bin stark!"],["Das geht nicht!","That's not okay! / That won't do!","Kein Bett? Das geht nicht!"]],"x":[["der Freund, die Freunde","friend / boyfriend",""],["das Alter","age",""],["ledig","single",""],["geschieden","divorced",""],["jung","young",""]],"g":["ein/eine und kein/keine",["ein for der- and das-words, eine for die-words: ein Tisch, ein Sofa, eine Lampe.","kein / keine means \"no\" or \"not a\": kein Stuhl, kein Bett, keine Lampe.","Use kein for nouns. (For verbs and adjectives you will learn nicht in story 9.)","Beispiele: Hier ist ein Tisch, aber da ist kein Stuhl. · Das ist kein Witz."]]},{"n":7,"t":"Im Café Sonne","l":"A1","review":false,"p":[["Samstag, zehn Uhr. Das Café Sonne ist klein und gemütlich. Es riecht nach Kaffee und Kuchen. Jonas steht hinter der Theke. Er hat eine Schürze und er hat Mehl auf der Nase."],["Jonas","Mia! Hallo! Was möchtest du?"],["Mia","Hm … Was habt ihr?"],["Jonas","Wir haben Kaffee, Cappuccino, Tee und Kakao. Und wir haben Kuchen: Apfelkuchen und Käsekuchen."],["Mia","Ich hätte gern einen Cappuccino. Und ein Stück Apfelkuchen, bitte."],["Jonas","Sehr gern! Der Apfelkuchen ist von mir."],["Mia","Mmm! Der Kuchen ist fantastisch!"],["Jonas","Hast du noch Hunger? Möchtest du ein Brötchen?"],["Mia","Nein, danke. Ich habe keinen Hunger mehr."],["Dann geht die Tür auf. Ein Mann kommt rein. Groß, mit Brille. Mia trinkt – und hustet."],["Mia","Herr Brandt?!"],["Herr Brandt","Frau Costa! Guten Morgen."],["Jonas","Guten Morgen, Herr Brandt. Wie immer? Ein Espresso und eine Brezel?"],["Herr Brandt","Wie immer, Jonas."],["Mia","Sie kennen Jonas?"],["Herr Brandt","Natürlich. Jonas war mein Schüler. Am Gymnasium. Er war … sehr kreativ. Besonders in Deutsch."],["Jonas","Ich hatte immer eine Fünf in Deutsch!"],["Mia lacht. Jetzt versteht sie: Viel Glück!"],["Herr Brandt","Frau Costa, haben Sie am Montag Zeit? Nach dem Kurs ist Markt am Münster. Ihre Hausaufgabe: Kaufen Sie Obst und Gemüse. Nur auf Deutsch! Kein Englisch!"],["Mia","Nur auf Deutsch? Oh je."],["Jonas","Keine Angst. Ich habe am Montag frei. Ich bin auch da."],["Mia möchte bezahlen."],["Mia","Was kostet das?"],["Jonas","Nichts. Der Cappuccino ist für dich, der Kuchen auch."],["Herr Brandt","Und mein Espresso, Jonas? Auch gratis?"],["Jonas","Nein, Herr Brandt. Zwei Euro achtzig, bitte."],["Herr Brandt lacht. Ja, er lacht – zum ersten Mal."],["Auf dem Weg nach Hause denkt Mia: Montag. Das Bett kommt. Der Markt. Nur Deutsch. Und Jonas ist auch da."]],"q":["Was bestellt Mia?","Was nimmt Herr Brandt immer?","Richtig oder falsch? Jonas war ein sehr guter Schüler in Deutsch.","Was ist Mias Hausaufgabe?","Und du? Was möchtest du im Café? (Ich hätte gern …)"],"a":["Einen Cappuccino und ein Stück Apfelkuchen. „Ich hätte gern einen Cappuccino. Und ein Stück Apfelkuchen, bitte.“","Einen Espresso und eine Brezel. Jonas asks: „Wie immer? Ein Espresso und eine Brezel?“","Falsch. Jonas says: „Ich hatte immer eine Fünf in Deutsch!“ (In Germany, 5 is a very bad mark.)","Buy fruit and vegetables at the market, only in German. „Kaufen Sie Obst und Gemüse. Nur auf Deutsch!“","Example: Ich hätte gern einen Tee und ein Stück Käsekuchen, bitte."],"w":[["haben (habe, hast, hat, habt)","to have","Was habt ihr?"],["möchten (möchte, möchtest)","would like","Was möchtest du?"],["der Tee, die Tees","tea","Wir haben Kaffee, Cappuccino, Tee …"],["der Kuchen, die Kuchen","cake","Der Kuchen ist fantastisch!"],["das Stück, die Stücke","piece","Ein Stück Apfelkuchen, bitte."],["das Brötchen, die Brötchen","bread roll","Möchtest du ein Brötchen?"],["die Brezel, die Brezeln","pretzel","Ein Espresso und eine Brezel?"],["der Hunger","hunger","Hast du noch Hunger?"],["die Zeit, die Zeiten","time","Haben Sie am Montag Zeit?"],["der Schüler, die Schüler","pupil, student","Jonas war mein Schüler."],["die Hausaufgabe, die Hausaufgaben","homework","Ihre Hausaufgabe: Kaufen Sie Obst."],["das Obst / das Gemüse","fruit / vegetables","Kaufen Sie Obst und Gemüse."],["kosten","to cost","Was kostet das?"],["der Euro, die Euro","euro","Zwei Euro achtzig, bitte."],["gemütlich","cosy","Das Café ist klein und gemütlich."]],"c":[["Ich hätte gern …","I'd like … (polite)","Ich hätte gern einen Cappuccino."],["Was kostet das?","How much is it?","Was kostet das?"],["Wie immer?","The usual?","Wie immer? Ein Espresso?"],["Keine Angst!","Don't worry!","Keine Angst. Ich bin auch da."],["frei haben","to have the day off","Ich habe am Montag frei."]],"x":[["das Haus, die Häuser","house",""],["das Schlafzimmer, die Schlafzimmer","bedroom",""],["die Waschmaschine, die Waschmaschinen","washing machine",""],["die Toilette, die Toiletten","toilet",""],["das Stockwerk, die Stockwerke","floor, storey",""]],"g":["haben und möchten",["haben: ich habe, du hast, er/sie/es hat, wir haben, ihr habt, sie/Sie haben.","möchten (would like): ich möchte, du möchtest, er möchte, wir möchten, ihr möchtet, Sie möchten.","Ich hätte gern … is the most polite way to order in a café or shop.","Beispiele: Hast du noch Hunger? · Was möchtest du?"]]},{"n":8,"t":"Auf dem Markt","l":"A1","review":false,"p":[["Montag, ein Uhr. Der Markt am Münster ist bunt und laut. Hier sind viele Stände: Obst, Gemüse, Blumen, Käse und Würste. Mia hat eine Liste: zwei Kilo Äpfel, ein Kilo Tomaten, sechs Eier."],["Am ersten Stand steht eine alte Frau."],["Verkäuferin","Grüß Gott! Was darf's sein?"],["Mia","Wie bitte?"],["Verkäuferin","Was möchten Sie?"],["Mia","Ah! Ich hätte gern zwei Kilo Äpfel."],["Verkäuferin","Die roten Äpfel oder die grünen?"],["Mia","Die roten, bitte."],["Verkäuferin","Das macht vier Euro zwanzig."],["Mia","Hier sind fünf Euro."],["Verkäuferin","Und achtzig Cent zurück. Danke schön!"],["Am zweiten Stand spricht der Verkäufer sehr schnell. Mia versteht nichts."],["Mia","Sorry, do you speak Eng…"],["Stimme","Frau Costa! Nur Deutsch!"],["Mia dreht sich um. Da steht Herr Brandt, mit einem Korb."],["Mia","Herr Brandt! Sind Sie … die Kontrolle?"],["Herr Brandt","Nein, nein. Ich kaufe nur Kartoffeln."],["Er lächelt – ein bisschen – und geht. Dann kommt Jonas."],["Jonas","Mia! Wie läuft's?"],["Mia","Zwei Kilo Äpfel – fertig! Jetzt Tomaten und Eier."],["Jonas","Und ich kaufe für das Café: zwanzig Kilo Kartoffeln, zehn Kilo Zwiebeln und fünfzig Eier."],["Mia","Fünfzig Eier?!"],["Jonas","Klar! Für die Kuchen. Du bist dran!"],["Mia","Ich hätte gern ein Kilo Tomaten und sechs Eier, bitte. Was kostet das?"],["Verkäufer","Die Tomaten drei Euro fünfzig, die Eier zwei Euro neunzig. Zusammen sechs Euro vierzig."],["Mia rechnet","drei fünfzig plus zwei neunzig … sechs vierzig. Richtig!"],["Jonas","Super, Mia! Hausaufgabe fertig. Und heute Abend? Ich koche, mit den Tomaten. Frau Schulz kommt auch. Um sieben?"],["Mia","Gern! … Moment. Wie spät ist es?"],["Jonas","Zwei Uhr fünfzig."],["Mia","Oh nein! Das Bett! Das Bett kommt um drei!"],["Mia rennt. Ein Apfel fällt aus der Tasche. Dann zwei Äpfel. Dann drei. Kommt sie pünktlich nach Hause?"]],"q":["Was kauft Mia am ersten Stand?","Was kosten die Äpfel?","Richtig oder falsch? Herr Brandt kauft Tomaten.","Was kauft Jonas für das Café?","Und du? Was kaufst du auf dem Markt? (Ich hätte gern …)"],"a":["Zwei Kilo rote Äpfel. „Ich hätte gern zwei Kilo Äpfel.“ – „Die roten, bitte.“","Vier Euro zwanzig. „Das macht vier Euro zwanzig.“","Falsch. He says: „Ich kaufe nur Kartoffeln.“","20 Kilo Kartoffeln, 10 Kilo Zwiebeln und 50 Eier. „Zwanzig Kilo Kartoffeln, zehn Kilo Zwiebeln und fünfzig Eier.“","Example: Ich hätte gern ein Kilo Tomaten und zehn Eier, bitte."],"w":[["einundzwanzig … hundert","numbers 21–100","Zwanzig Kilo Kartoffeln, fünfzig Eier."],["der Markt, die Märkte","market","Der Markt am Münster ist bunt."],["der Stand, die Stände","(market) stall","Hier sind viele Stände."],["der Apfel, die Äpfel","apple","Zwei Kilo Äpfel."],["die Tomate, die Tomaten","tomato","Ein Kilo Tomaten."],["die Kartoffel, die Kartoffeln","potato","Ich kaufe nur Kartoffeln."],["die Zwiebel, die Zwiebeln","onion","Zehn Kilo Zwiebeln."],["das Ei, die Eier","egg","Sechs Eier."],["der Käse","cheese","Obst, Gemüse, Blumen, Käse …"],["die Blume, die Blumen","flower","Obst, Gemüse, Blumen …"],["das Kilo, die Kilo","kilo","Zwei Kilo Äpfel."],["der Cent, die Cent","cent","Und achtzig Cent zurück."],["die Tasche, die Taschen","bag","Ein Apfel fällt aus der Tasche."],["bunt / laut","colourful / loud","Der Markt ist bunt und laut."],["fertig","finished, done","Zwei Kilo Äpfel – fertig!"]],"c":[["Was darf's sein?","What would you like? (shop)","Grüß Gott! Was darf's sein?"],["Das macht …","That comes to …","Das macht vier Euro zwanzig."],["Wie läuft's?","How's it going?","Mia! Wie läuft's?"],["Du bist dran!","It's your turn!","Klar! Du bist dran!"],["Wie spät ist es?","What time is it?","Moment. Wie spät ist es?"]],"x":[["der Quadratmeter, die Quadratmeter","square metre",""],["mieten","to rent",""],["umziehen","to move house",""],["der Kaffee","coffee",""],["die Banane, die Bananen","banana",""]],"g":["der Plural und die Zahlen bis 100",["The plural article is always die: der Apfel → die Äpfel.","Plural endings vary, so learn them with the noun: -n/-en (Tomaten), -e (Stände), -er (Eier), -s (Kartons), often with an umlaut (Äpfel).","Numbers 21–99: say the small number first: einundzwanzig (21), vierundfünfzig (54).","Beispiele: Ich hätte gern zwei Kilo Äpfel. · Fünfzig Eier!"]]},{"n":9,"t":"Das esse ich nicht gern","l":"A1","review":false,"p":[["Drei Uhr fünf. Mia ist da! Vor dem Haus steht ein Lastwagen. Zwei Männer – und ein Bett. Ihr Bett! Heute Nacht schläft Mia nicht auf dem Boden."],["Um sieben klingelt Mia bei Jonas. Wohnung vier ist ein bisschen chaotisch: Bücher, Pflanzen, eine Gitarre. Frau Schulz ist schon da. Felix auch, natürlich."],["Jonas","Herzlich willkommen! Heute gibt es Tomatensuppe und Käsespätzle."],["Mia","Käsespätzle? Was ist das?"],["Jonas","Spätzle sind Nudeln aus Süddeutschland. Mit viel Käse und Zwiebeln. Isst du gern Käse?"],["Mia","Ja, sehr gern!"],["Frau Schulz","Jonas, ist Knoblauch in der Suppe?"],["Jonas","Ja, ein bisschen."],["Frau Schulz","Oh. Knoblauch esse ich nicht gern. Gar nicht gern."],["Jonas","Nur ein bisschen, Frau Schulz! Wirklich!"],["Frau Schulz probiert die Suppe."],["Frau Schulz","Hm. Das ist nicht ein bisschen. Das ist viel! … Aber die Suppe ist gut. Nicht schlecht, Jonas."],["Jonas","Mia, trinkst du gern Bier?"],["Mia","Nein, Bier trinke ich nicht gern. Ich trinke gern Wein."],["Jonas","Moment … Ich habe einen Wein aus Portugal! Vinho Verde!"],["Mia","Wirklich? Toll! In Portugal esse ich oft Fisch und ich trinke Vinho Verde."],["Plötzlich ist Felix auf dem Tisch. Er nimmt ein Stück Käse."],["Frau Schulz","Felix! Das ist nicht dein Käse!"],["Felix","Miau."],["Jonas","Felix isst alles gern. Nur Gemüse nicht."],["Jonas","Und du, Mia? Kochst du gern?"],["Mia","Nein, ich koche nicht gern. Und nicht gut!"],["Jonas","Kein Problem. Ich koche, und du isst."],["Mia lacht. Frau Schulz sieht Mia an. Dann sieht sie Jonas an. Und sie sagt nur: „Aha.“"],["Da macht Mias Handy brrr, brrr. Ein Videoanruf. Auf dem Display steht: MAMA."],["Mia","Oh nein! Nicht jetzt!"],["Aber sie drückt aus Versehen auf „Ja“. Und da ist Mama, auf dem Display, in Porto."],["Mama","Mia! Wo bist du? Und … wer ist der Mann?"],["Jonas winkt in die Kamera."],["Jonas","Hallo! Ich bin Jonas!"],["Mama sagt nichts. Ihre Augen sind sehr, sehr groß."]],"q":["Was kommt um drei Uhr?","Was kocht Jonas?","Richtig oder falsch? Frau Schulz isst gern Knoblauch.","Trinkt Mia gern Bier? Was trinkt sie gern?","Und du? Was isst du gern? Was isst du nicht gern?"],"a":["Mias Bett. „Zwei Männer – und ein Bett. Ihr Bett!“","Tomatensuppe und Käsespätzle. „Heute gibt es Tomatensuppe und Käsespätzle.“","Falsch. „Knoblauch esse ich nicht gern. Gar nicht gern.“","Nein, sie trinkt gern Wein. „Bier trinke ich nicht gern. Ich trinke gern Wein.“","Example: Ich esse gern Pizza. Fisch esse ich nicht gern."],"w":[["nicht","not","Bier trinke ich nicht gern."],["gern","gladly; (to like doing)","Isst du gern Käse?"],["essen (du isst, er isst)","to eat","Felix isst alles gern."],["die Suppe, die Suppen","soup","Die Suppe ist gut."],["die Nudel, die Nudeln","noodle, pasta","Spätzle sind Nudeln."],["der Knoblauch","garlic","Ist Knoblauch in der Suppe?"],["der Fisch, die Fische","fish","In Portugal esse ich oft Fisch."],["das Bier, die Biere","beer","Trinkst du gern Bier?"],["der Wein, die Weine","wine","Ich trinke gern Wein."],["das Buch, die Bücher","book","Bücher, Pflanzen, eine Gitarre."],["schlecht","bad","Nicht schlecht, Jonas."],["viel","a lot, much","Das ist viel!"],["alles","everything","Felix isst alles gern."],["probieren","to taste, to try","Frau Schulz probiert die Suppe."],["die Mutter (Mama), die Mütter","mother (mum)","Auf dem Display steht: MAMA."]],"c":[["Heute gibt es …","Today there is …","Heute gibt es Tomatensuppe."],["gar nicht","not at all","Gar nicht gern."],["Nicht schlecht!","Not bad!","Nicht schlecht, Jonas."],["aus Versehen","by mistake","Sie drückt aus Versehen auf „Ja“."]],"x":[["das Gemüse","vegetables",""],["das Hähnchen, die Hähnchen","chicken",""],["der Reis","rice",""],["die Nudeln (plural only)","pasta",""],["das Salz","salt",""]],"g":["nicht und gern",["nicht negates a verb, an adjective or a whole sentence: Ich koche nicht. · Das ist nicht schlecht.","kein negates a noun (story 6). nicht is for everything else.","gern after a verb = you like doing it: Ich esse gern Käse. Negative: nicht gern.","Beispiele: Bier trinke ich nicht gern. · Isst du gern Käse?"]]},{"n":10,"t":"Wiederholung: Mias Tagebuch","l":"A1","review":true,"p":[["Montag, zweiundzwanzig Uhr"],["Ich bin im Bett! Im Bett! Kein Boden, keine Jacke. Ein Bett. Ich bin sehr froh."],["Eine Woche in Freiburg. Was ist neu?"],["Sonntag","Freiburg, Lindenstraße zwölf. Der Koffer ist schwer. Jonas ist nett – und stark. Frau Schulz ist streng, aber auch nett. Und Felix? Felix ist der Chef."],["Dienstag","der Kurs. Herr Brandt spricht schnell, sehr schnell. Elif kommt aus der Türkei, und Tom kommt aus Polen. Wir lernen zusammen."],["Mittwoch","Zahlen! Meine Nummer ist null, eins, sieben, sechs, zwölf, neunzehn, null acht, null vier. Jonas hat meine Nummer. Hm."],["Donnerstag","Elif ist hier. Die Wohnung ist klein, aber schön. Elif fragt: „Ist Jonas nett?“ Elif!"],["Freitag","Kein Bett. Aber Frau Schulz hat ein Sofa. Es ist alt und grün. Felix schläft auf dem Sofa – nicht ich."],["Samstag","Café Sonne. Der Apfelkuchen ist fantastisch. Und Herr Brandt kennt Jonas! Jonas war sein Schüler, mit einer Fünf in Deutsch. Ha!"],["Heute","der Markt. Nur Deutsch! Ich kaufe Äpfel, Tomaten und Eier. Dann kommt das Bett. Und am Abend gibt es Käsespätzle bei Jonas. Frau Schulz isst nicht gern Knoblauch. Felix isst gern Käse – alles Käse."],["Und dann","Mama. Videoanruf. Mama sieht Jonas. Mama fragt: „Wer ist Jonas?“ Ich sage: „Mama, Jonas ist nur der Nachbar!“ Mama sagt: „Aha.“"],["Alle sagen „Aha“! Elif, Frau Schulz, Mama …"],["Jetzt macht das Handy pling. Eine Nachricht von Rui: Nur der Nachbar? Ha ha ha!"],["Morgen ist Dienstag. Morgen ist der Kurs, und dann der Supermarkt mit Tom. Der Kühlschrank ist leer: nur zwei Äpfel und eine Tomate."],["Und ich habe eine Frage. Ist Jonas wirklich nur der Nachbar?"]],"q":["Woher kommt Mia? a) aus Spanien b) aus Portugal c) aus Polen","Wo arbeitet Jonas?","Ergänze sein: Ich ___ Mia. Du ___ Jonas. Wir ___ Nachbarn.","Ergänze das Verb: Wir ___ (lernen) Deutsch. Ihr ___ (wohnen) in Freiburg. Er ___ (arbeiten) im Café.","der, die oder das? ___ Küche · ___ Balkon · ___ Bad","ein oder kein? Hier ist ___ Tisch, aber hier ist ___ Stuhl.","Plural: der Apfel → die ___ · das Ei → die ___ · die Tomate → die ___","Schreib die Zahl als Wort: 54 = ___ · 17 = ___","Mach eine Ja/Nein-Frage: Du trinkst gern Bier. → ___?","nicht oder kein? Frau Schulz isst ___ gern Knoblauch. Das ist ___ Witz."],"a":["b) aus Portugal. Mia says in story 2: „Ich komme aus Portugal.“","Im Café Sonne. Story 2: „Ich arbeite im Café Sonne.“","bin · bist · sind. sein: ich bin, du bist, wir sind.","lernen · wohnt · arbeitet. wir -en, ihr -t; after -t add -e-: er arbeitet.","die Küche · der Balkon · das Bad. Learn every noun with its article.","ein · kein. ein for \"a\", kein for \"no\" with nouns.","Äpfel · Eier · Tomaten. Plural endings vary: umlaut, -er, -n.","vierundfünfzig · siebzehn. Small number first + und; siebzehn drops the -en.","Trinkst du gern Bier? In yes/no questions the verb comes first.","nicht · kein. nicht for verbs (isst nicht gern), kein for nouns (kein Witz)."],"w":[],"c":[],"x":[],"g":["Wiederholung",["sein and haben: ich bin, du bist · ich habe, du hast (stories 1, 7).","Present tense: ich -e, du -st, er -t, wir -en, ihr -t, sie -en (stories 2–3).","Questions: W-question = verb second; yes/no question = verb first (stories 2, 4).","Nouns: der/die/das, ein/kein, plural (stories 5, 6, 8). Negation: kein + noun, nicht for the rest (story 9).","Beispiele: Wo wohnst du? · Ist Jonas wirklich nur der Nachbar?"]],"exam":{"task":"Schreiben Sie eine kurze Nachricht an Ihre neue Nachbarin.","points":["Wer sind Sie?","Woher kommen Sie?","Laden Sie sie zum Kaffee ein (Tag und Uhrzeit)."],"words":30,"en":"Short message to a new neighbour: who you are, where you are from, invite her for coffee."}},{"n":11,"t":"Der Einkaufszettel","l":"A1","review":false,"p":[["Dienstag, halb eins. Der Kurs ist fast vorbei."],["Herr Brandt","Hausaufgabe für Donnerstag: Bringen Sie ein Foto mit. Ein Foto von Ihrer Familie."],["Elif lächelt. Mia lächelt. Aber Tom sieht auf den Boden. Er sagt nichts."],["Nach dem Kurs gehen Mia und Tom in den Supermarkt. Mia hat einen Einkaufszettel: Milch, Brot, Butter, einen Käse, Joghurt, Reis, einen Saft, Kaffee. Tom hat keinen Zettel."],["Tom","Ich brauche keinen Zettel. Ich brauche Pizza!"],["Er nimmt drei Pizzas."],["Mia","Tom! Du brauchst einen Salat. Und Obst!"],["Tom","Ich brauche keinen Salat. Salat esse ich nicht gern."],["Mia","Und Gemüse?"],["Tom","Ketchup ist Gemüse!"],["Mia lacht. Sie sucht den Kaffee. Da ist ein Mitarbeiter."],["Mia","Entschuldigung, wo finde ich den Kaffee?"],["Mitarbeiter","Den Kaffee finden Sie da hinten, in Gang drei."],["Mia","Danke! Und haben Sie auch einen Kuchen?"],["Mitarbeiter","Nein, wir haben keinen Kuchen. Aber vorne ist eine Bäckerei."],["Mia nimmt den Kaffee, einen Käse und einen Saft. Dann sieht sie Tom. Er trägt einen großen Sack: Hundefutter. Zehn Kilo!"],["Mia","Hundefutter? Hast du einen Hund?"],["Tom","Äh … nein. Doch. Also … ja."],["Mia","Ja oder nein?"],["Tom","Komm, wir bezahlen."],["An der Kasse:"],["Kassiererin","Das macht dreiundzwanzig Euro vierzig. Haben Sie eine Kundenkarte?"],["Mia","Nein, ich habe keine Kundenkarte."],["Tom öffnet sein Portemonnaie. Da fällt ein Foto auf den Boden. Mia nimmt das Foto. Eine alte Frau und ein großer, schwarzer Hund."],["Mia","Wer ist das? Deine Oma?"],["Tom","Das ist … kompliziert."],["Er nimmt das Foto schnell zurück."],["Auf dem Weg nach Hause denkt Mia: Donnerstag ist das Familienfoto. Und Tom? Was ist mit Tom?"]],"q":["Was ist die Hausaufgabe für Donnerstag?","Was kauft Tom?","Richtig oder falsch? Tom isst gern Salat.","Was ist auf dem Foto?","Und du? Was brauchst du heute? (Ich brauche einen … / eine … / ein …)"],"a":["Ein Foto von der Familie mitbringen. „Bringen Sie ein Foto mit. Ein Foto von Ihrer Familie.“","Drei Pizzas und zehn Kilo Hundefutter. „Er nimmt drei Pizzas.“ … „Hundefutter. Zehn Kilo!“","Falsch. „Ich brauche keinen Salat. Salat esse ich nicht gern.“","Eine alte Frau und ein großer, schwarzer Hund. Tom only says: „Das ist … kompliziert.“","Example: Ich brauche einen Kaffee, eine Banane und ein Brot."],"w":[["der Supermarkt, die Supermärkte","supermarket","Mia und Tom gehen in den Supermarkt."],["der Einkaufszettel, die Einkaufszettel","shopping list","Mia hat einen Einkaufszettel."],["die Milch","milk","Milch, Brot, Butter …"],["das Brot, die Brote","bread","Milch, Brot, Butter …"],["die Butter","butter","Milch, Brot, Butter …"],["der Saft, die Säfte","juice","Mia nimmt einen Saft."],["der Salat, die Salate","salad, lettuce","Du brauchst einen Salat."],["der Hund, die Hunde","dog","Hast du einen Hund?"],["die Kasse, die Kassen","checkout, till","An der Kasse."],["das Foto, die Fotos","photo","Da fällt ein Foto auf den Boden."],["die Familie, die Familien","family","Ein Foto von Ihrer Familie."],["brauchen","to need","Ich brauche Pizza!"],["nehmen (du nimmst, er nimmt)","to take","Er nimmt drei Pizzas."],["finden","to find","Wo finde ich den Kaffee?"],["bezahlen","to pay","Komm, wir bezahlen."]],"c":[["Entschuldigung, …","Excuse me, …","Entschuldigung, wo finde ich den Kaffee?"],["da hinten / vorne","back there / at the front","Den Kaffee finden Sie da hinten."],["Doch.","Yes (after a negative).","Äh … nein. Doch."],["Das ist kompliziert.","It's complicated.","Das ist … kompliziert."]],"x":[["das Abendessen","dinner",""],["der Durst","thirst",""],["Guten Appetit!","enjoy your meal",""],["die Speisekarte, die Speisekarten","menu",""],["der Preis, die Preise","price",""]],"g":["der Akkusativ",["The object of a verb (the thing you need, buy, take, have) is in the accusative.","Only masculine articles change: der → den, ein → einen, kein → keinen.","die, das, eine, ein (neuter), keine stay the same.","Typical verbs: haben, brauchen, kaufen, nehmen, finden, möchten.","Beispiele: Du brauchst einen Salat. · Wo finde ich den Kaffee?"]]},{"n":12,"t":"Das ist meine Familie","l":"A1","review":false,"p":[["Donnerstag. Alle haben ein Foto. Nur Tom ist still."],["Herr Brandt","Frau Costa, bitte. Wer ist auf Ihrem Foto?"],["Mia","Das ist meine Familie. Das ist meine Mutter. Sie heißt Ana. Sie ist Lehrerin. Und das ist mein Bruder Rui. Er ist zweiundzwanzig. Er studiert in Porto. Und das ist mein Opa. Er ist sehr lustig."],["Elif","Und dein Vater?"],["Mia","Mein Vater wohnt in Brasilien. Ich sehe ihn nicht oft."],["Herr Brandt","Danke. Frau Yılmaz?"],["Elif","Das ist meine Familie in İzmir. Meine Eltern, meine Oma und meine Geschwister. Ich habe drei Schwestern und zwei Brüder."],["Tom","Sechs Kinder?! Wow!"],["Elif","Ja. Unser Haus ist immer laut!"],["Herr Brandt","Herr Nowak?"],["Tom steht auf. Er zeigt das Foto aus dem Supermarkt."],["Tom","Das ist meine Oma. Sie heißt Zofia. Sie wohnt in Krakau. Meine Eltern … mein Vater ist weg, und meine Mutter arbeitet in England. Meine Oma ist meine Familie."],["Im Kurs ist es ganz still."],["Mia","Und der Hund?"],["Tom","Das ist mein Hund. Er heißt Bruno. Er wohnt hier, in Freiburg. Bei mir."],["Elif","Aber das ist doch super!"],["Tom","Nein. Mein Vermieter weiß das nicht. Hunde sind im Haus verboten!"],["Jetzt lachen alle. Auch Tom. Endlich."],["Elif","Und Sie, Herr Brandt? Wo ist Ihr Foto?"],["Herr Brandt zeigt ein Foto. Eine Katze. Weiß und sehr dick."],["Herr Brandt","Das ist meine Familie. Mozart."],["Am Nachmittag kommt Mia nach Hause. Vor dem Haus steht Jonas. Bei ihm ist eine junge Frau, sehr hübsch, mit langen, blonden Haaren. Und ein Kind, ein kleiner Junge. Jonas umarmt die Frau. Der Junge ruft: „Jonas! Jonas!“"],["Mia bleibt stehen. Wer ist die Frau? Hat Jonas eine Freundin? Und … ein Kind?"],["Mia geht schnell ins Haus. Sie ist plötzlich ein bisschen traurig. Warum eigentlich?"]],"q":["Wer ist auf Mias Foto?","Wie viele Geschwister hat Elif?","Richtig oder falsch? Toms Mutter wohnt in Krakau.","Was ist Toms Problem mit Bruno?","Und du? Wer ist in deiner Familie? (Das ist mein … / meine …)"],"a":["Ihre Mutter Ana, ihr Bruder Rui und ihr Opa. „Das ist meine Mutter … mein Bruder Rui … mein Opa.“","Fünf: drei Schwestern und zwei Brüder. „Ich habe drei Schwestern und zwei Brüder.“","Falsch. „Meine Mutter arbeitet in England.“ His grandmother lives in Kraków.","Dogs are not allowed in his building. „Mein Vermieter weiß das nicht. Hunde sind im Haus verboten!“","Example: Das ist meine Mutter. Das ist mein Bruder. Meine Familie ist klein."],"w":[["mein / meine","my","Das ist meine Mutter."],["dein / deine","your (informal)","Und dein Vater?"],["der Vater, die Väter","father","Mein Vater wohnt in Brasilien."],["die Eltern (Plural)","parents","Meine Eltern …"],["der Bruder, die Brüder","brother","Das ist mein Bruder Rui."],["die Schwester, die Schwestern","sister","Ich habe drei Schwestern."],["die Geschwister (Plural)","siblings","Meine Eltern, meine Oma und meine Geschwister."],["die Oma, die Omas / der Opa, die Opas","grandma / grandpa","Das ist meine Oma."],["das Kind, die Kinder","child","Sechs Kinder?!"],["der Junge, die Jungen","boy","Ein Kind, ein kleiner Junge."],["die Freundin, die Freundinnen","girlfriend; female friend","Hat Jonas eine Freundin?"],["der Vermieter, die Vermieter","landlord","Mein Vermieter weiß das nicht."],["zeigen","to show","Er zeigt das Foto."],["lustig","funny","Er ist sehr lustig."],["traurig","sad","Sie ist plötzlich ein bisschen traurig."]],"c":[["Das ist meine Familie.","This is my family.","Das ist meine Familie in İzmir."],["Ich habe … Geschwister.","I have … siblings.","Ich habe drei Schwestern und zwei Brüder."],["Warum eigentlich?","Why, actually?","Warum eigentlich?"]],"x":[["die Packung, die Packungen","packet",""],["das Gramm, die Gramm","gram",""],["der Liter, die Liter","litre",""],["das Angebot, die Angebote","special offer",""],["die Kreditkarte, die Kreditkarten","credit card",""]],"g":["mein und dein",["mein = my, dein = your (du). They work like ein.","der- and das-words: mein / dein (mein Bruder, dein Vater). die-words and plural: meine / deine (meine Mutter, meine Eltern).","Formal Sie → Ihr / Ihre (capital I): Wo ist Ihr Foto?","Beispiele: Das ist mein Hund. · Und dein Vater?"]]},{"n":13,"t":"Jonas hat eine Schwester","l":"A1","review":false,"p":[["Freitag. Mia hört Jonas auf der Treppe. Sie macht die Tür nicht auf. Sie ist nicht da. Für niemanden."],["Aber um fünf klingelt es. Einmal, zweimal, dreimal. Mia macht auf. Vor der Tür steht der kleine Junge."],["Junge","Hallo! Ich bin Paul. Ich bin sechs. Wo ist die Katze?"],["Mia","Die Katze? Äh …"],["Dann kommen Jonas und die blonde Frau die Treppe hoch."],["Jonas","Paul! Nicht klingeln! … Hallo, Mia. Das ist meine Schwester Lena. Und Paul ist ihr Sohn."],["Mia","Deine Schwester?! Oh! Hallo, Lena!"],["Mia lächelt. Plötzlich ist sie gar nicht mehr traurig."],["Lena","Hallo, Mia! Freut mich. Jonas erzählt viel von seiner Nachbarin."],["Jonas","Lena!"],["Jonas wird rot. Lena lacht."],["Mia","Wohnt ihr auch in Freiburg?"],["Lena","Ja, in der Wiehre. Mein Mann heißt Stefan. Er arbeitet in Basel. Unser Sohn geht in die erste Klasse."],["Paul","Und wo ist die Katze?"],["Da kommt Felix langsam die Treppe hoch. Paul ist sofort bei ihm."],["Paul","Ist das eure Katze?"],["Jonas","Nein, das ist nicht unsere Katze. Das ist Frau Schulz' Kater. Ihr Kater. Er heißt Felix."],["Paul","Felix! Und das ist sein Bauch? Er ist so dick!"],["Felix","Miau!"],["Frau Schulz macht unten die Tür auf."],["Frau Schulz","Was ist denn hier los? Ah, Lena! Und der kleine Paul! Ist das Ihr Sohn, Lena? Er ist so groß!"],["Lena","Ja, Frau Schulz. Unser Paul wird jeden Tag größer."],["Paul","Mama, ist Mia die Freundin von Jonas?"],["Stille. Jonas sieht an die Decke. Mia sieht auf den Boden."],["Lena","Paul! Du fragst immer alles!"],["Paul","Mia, kommst du am Sonntag in den Park? Ich spiele Fußball! Mein Papa spielt auch, und Onkel Jonas auch."],["Mia","Am Sonntag? Ja, gern!"],["Paul","Spielst du gut Fußball?"],["Mia","Äh …"],["Mia spielt nicht Fußball. Nie. Nicht einmal in Portugal."]],"q":["Wer ist die blonde Frau?","Wie alt ist Paul?","Richtig oder falsch? Felix ist Jonas' Kater.","Was fragt Paul seine Mama?","Und du? Hast du eine Schwester oder einen Bruder? Wie heißt sein/ihr Kind?"],"a":["Lena, Jonas' Schwester. „Das ist meine Schwester Lena.“","Sechs. Paul says: „Ich bin Paul. Ich bin sechs.“","Falsch. „Das ist Frau Schulz' Kater. Ihr Kater.“","„Mama, ist Mia die Freundin von Jonas?“ Everyone goes quiet.","Example: Ja, ich habe eine Schwester. Ihr Sohn heißt Leo."],"w":[["sein / ihr","his / her","Paul ist ihr Sohn."],["unser / euer","our / your (pl.)","Ist das eure Katze?"],["der Sohn, die Söhne","son","Unser Sohn geht in die erste Klasse."],["der Mann, die Männer","man; husband","Mein Mann heißt Stefan."],["der Onkel, die Onkel","uncle","Onkel Jonas auch."],["die Katze, die Katzen / der Kater, die Kater","cat / tomcat","Das ist Frau Schulz' Kater."],["die Klasse, die Klassen","class (school)","Er geht in die erste Klasse."],["der Park, die Parks","park","Kommst du am Sonntag in den Park?"],["der Fußball","football","Ich spiele Fußball!"],["spielen","to play","Mein Papa spielt auch."],["klingeln","to ring (a bell)","Paul! Nicht klingeln!"],["erzählen","to tell","Jonas erzählt viel von seiner Nachbarin."],["rot","red","Jonas wird rot."],["dick","fat","Er ist so dick!"],["nie","never","Mia spielt nicht Fußball. Nie."]],"c":[["Was ist denn hier los?","What's going on here?","Was ist denn hier los?"],["rot werden","to blush","Jonas wird rot."],["Ja, gern!","Yes, I'd love to!","Am Sonntag? Ja, gern!"]],"x":[["bar","in cash",""],["kaufen","to buy",""],["billig","cheap",""],["günstig","good value",""],["Sonst noch etwas?","anything else?",""]],"g":["sein, ihr, unser, euer, Ihr",["er → sein (his) · sie → ihr (her) · wir → unser · ihr → euer · Sie → Ihr.","They take the same endings as mein: sein Bauch, seine Nachbarin, unsere Katze.","Careful: euer loses an e with an ending: eure Katze.","Beispiele: Paul ist ihr Sohn. · Das ist nicht unsere Katze."]]},{"n":14,"t":"Was machst du gern?","l":"A1","review":false,"p":[["Sonntag, elf Uhr. Die Sonne scheint. Mia fährt mit der Straßenbahn zum Seepark. Jonas fährt mit dem Fahrrad. Er ist schon da – mit Lena, Paul und einem großen Mann."],["Lena","Mia, das ist Stefan, mein Mann."],["Stefan","Hallo, Mia! Spielst du mit? Wir brauchen eine Spielerin!"],["Mia","Ich spiele nicht gut Fußball. Ehrlich!"],["Paul","Egal! Du bist in meinem Team!"],["Das Spiel beginnt. Paul läuft schnell. Stefan läuft noch schneller. Mia läuft … und fällt. Paul lacht. Jonas lacht. Mia lacht auch. Am Ende steht es zehn zu zwei. Für Stefan."],["Dann sitzen alle auf einer Decke. Lena liest ein Buch."],["Mia","Was liest du?"],["Lena","Einen Krimi. Ich lese gern Krimis. Und du? Was machst du gern?"],["Mia","Ich lese auch gern. Und ich fotografiere gern. In Porto schwimme ich viel, im Meer."],["Stefan","Ich laufe gern. Jeden Morgen zehn Kilometer."],["Jonas","Ich koche gern, natürlich. Und ich fahre gern Fahrrad. Und ich spiele Gitarre."],["Mia","Du spielst Gitarre? Ich höre gern Musik!"],["Lena","Jonas spielt Gitarre … und er singt. Leider!"],["Jonas","Hey!"],["Paul","Und ich sehe gern fern!"],["Lena","Ja, Paul sieht zu viel fern."],["Paul","Mia, sprichst du Englisch?"],["Mia","Ja. Ich spreche Portugiesisch, Englisch und ein bisschen Deutsch."],["Paul","Und Katze? Sprichst du Katze?"],["Mia","Miau!"],["Paul lacht so laut, alle Leute im Park sehen her."],["Am Abend ist Mia müde und glücklich. Sie schläft fast auf dem Sofa ein. Dann sieht sie ihr Handy: 2 %. Wo ist das Ladekabel? Sie sucht. Im Bad? Nein. In der Küche? Nein. In einem Karton? Aber in welchem? Es sind zwanzig Kartons!"],["Das Handy ist schwarz. Aus."],["Morgen ist Montag. Der Kurs ist um neun. Und der Wecker? Der Wecker ist das Handy."]],"q":["Wie kommt Mia zum Seepark?","Wer gewinnt das Fußballspiel?","Richtig oder falsch? Stefan liest gern Krimis.","Was ist Mias Problem am Abend?","Und du? Was machst du gern? Was liest du gern? Welche Sprachen sprichst du?"],"a":["Mit der Straßenbahn. „Mia fährt mit der Straßenbahn zum Seepark.“","Stefan, zehn zu zwei. „Am Ende steht es zehn zu zwei. Für Stefan.“","Falsch. Lena reads crime novels: „Ich lese gern Krimis.“ Stefan likes running.","Her phone is dead, she can't find the charger, and the phone is her alarm clock. „Der Wecker ist das Handy.“","Example: Ich koche gern und ich lese gern Krimis. Ich spreche Englisch und ein bisschen Deutsch."],"w":[["fahren (du fährst, er fährt)","to go (by vehicle), drive, ride","Jonas fährt mit dem Fahrrad."],["lesen (du liest, er liest)","to read","Lena liest ein Buch."],["sprechen (du sprichst, er spricht)","to speak","Sprichst du Englisch?"],["sehen (du siehst, er sieht)","to see","Paul sieht zu viel fern."],["laufen (du läufst, er läuft)","to run","Stefan läuft noch schneller."],["schwimmen","to swim","In Porto schwimme ich viel."],["hören","to hear, listen","Ich höre gern Musik!"],["singen","to sing","Er singt. Leider!"],["das Fahrrad, die Fahrräder","bicycle","Ich fahre gern Fahrrad."],["die Straßenbahn, die Straßenbahnen","tram","Mia fährt mit der Straßenbahn."],["die Musik","music","Ich höre gern Musik!"],["das Meer, die Meere","sea","Ich schwimme viel, im Meer."],["der Wecker, die Wecker","alarm clock","Und der Wecker?"],["das Ladekabel, die Ladekabel","charging cable","Wo ist das Ladekabel?"],["glücklich","happy","Mia ist müde und glücklich."]],"c":[["Was machst du gern?","What do you like doing?","Und du? Was machst du gern?"],["fernsehen","to watch TV","Ich sehe gern fern!"],["Egal!","Doesn't matter!","Egal! Du bist in meinem Team!"],["Ehrlich!","Honestly!","Ich spiele nicht gut Fußball. Ehrlich!"]],"x":[["Das ist alles.","that's all",""],["die Kundin, die Kundinnen","customer (f)",""],["der Verkäufer, die Verkäufer","shop assistant (m)",""],["die Verkäuferin, die Verkäuferinnen","shop assistant (f)",""],["geschlossen","closed",""]],"g":["Verben mit Vokalwechsel",["Some verbs change their vowel, but only with du and er/sie/es.","e → i / ie: sprechen → du sprichst, er spricht · lesen → du liest, er liest · sehen → er sieht.","a → ä / au → äu: fahren → du fährst, er fährt · laufen → er läuft · schlafen → er schläft.","ich, wir, ihr, sie stay normal: ich fahre, wir lesen.","Beispiele: Lena liest ein Buch. · Sprichst du Englisch?"]]},{"n":15,"t":"Wie spät ist es?","l":"A1","review":false,"p":[["Montag. Mia ist wach. Draußen ist es hell. Sehr hell. Zu hell? Wie spät ist es? Das Handy ist aus. In der Wohnung ist keine Uhr."],["Mia läuft im Schlafanzug nach unten und klingelt bei Frau Schulz."],["Mia","Entschuldigung, Frau Schulz! Wie spät ist es?"],["Frau Schulz","Guten Morgen, Frau Costa. Es ist acht Uhr fünfzig."],["Mia","Acht Uhr fünfzig?! Der Kurs beginnt um neun!"],["Frau Schulz","Dann – schnell, schnell!"],["Mia zieht sich in drei Minuten an. Kein Kaffee, kein Frühstück. Sie rennt zur Straßenbahn."],["Um neun Uhr fünfundzwanzig macht sie die Tür vom Kursraum auf. Alle sehen Mia an."],["Herr Brandt","Frau Costa. Der Kurs beginnt um neun Uhr. Nicht um neun Uhr fünfundzwanzig."],["Mia","Entschuldigung, Herr Brandt. Mein Handy ist kaputt. Und mein Wecker ist das Handy."],["Herr Brandt","Dann ist das Thema heute perfekt: die Uhrzeit."],["Er schreibt an die Tafel: Wie spät ist es? – Es ist neun Uhr dreißig. Wann beginnt der Kurs? – Um neun Uhr."],["Herr Brandt","Unser Kurs ist von Montag bis Donnerstag, von neun Uhr bis zwölf Uhr dreißig. Am Freitag ist kein Kurs. Herr Nowak, wann arbeiten Sie?"],["Tom","Am Freitag, am Samstag und am Sonntag. Ich beginne um fünf Uhr dreißig."],["Elif","Um fünf Uhr dreißig? Am Morgen?! Da schlafe ich!"],["Herr Brandt","Frau Yılmaz, und Sie? Wann haben Sie Vorlesungen?"],["Elif","Am Montag und am Mittwoch, um vierzehn Uhr."],["In der Pause gibt Elif Mia ein Ladekabel."],["Elif","Hier. Mein Handy ist auch alt. Das Kabel passt."],["Mia","Elif, du bist meine Heldin!"],["Am Nachmittag kommt Mia nach Hause. Das Handy ist wieder an: sechzehn Uhr zwölf. Vor ihrer Tür liegt eine kleine Papiertüte. Mia macht die Tüte auf. Darin ist eine Brezel. Frisch und noch warm. Kein Zettel. Kein Name. Nichts."],["Mia sieht nach oben, zu Wohnung vier. Dann nach unten, zu Frau Schulz."],["Eine Brezel? Für mich? Aber … von wem?"]],"q":["Wie spät ist es, als Mia bei Frau Schulz klingelt?","Wann ist der Kurs? (Tage und Uhrzeit)","Richtig oder falsch? Tom arbeitet von Montag bis Donnerstag.","Was liegt vor Mias Tür?","Und du? Wann stehst du auf? Wann arbeitest oder lernst du? (Um … Uhr.)"],"a":["Acht Uhr fünfzig. Frau Schulz says: „Es ist acht Uhr fünfzig.“","Montag bis Donnerstag, 9.00 bis 12.30 Uhr. „Unser Kurs ist von Montag bis Donnerstag, von neun Uhr bis zwölf Uhr dreißig.“","Falsch. Tom: „Am Freitag, am Samstag und am Sonntag.“","Eine Papiertüte mit einer warmen Brezel – ohne Namen. „Darin ist eine Brezel … Kein Zettel. Kein Name.“","Example: Ich arbeite von Montag bis Freitag, von acht Uhr bis sechzehn Uhr."],"w":[["die Uhr, die Uhren","clock; o'clock","Es ist acht Uhr fünfzig."],["die Uhrzeit, die Uhrzeiten","time (of day)","Das Thema heute: die Uhrzeit."],["die Minute, die Minuten","minute","Mia zieht sich in drei Minuten an."],["Montag … Sonntag","Monday … Sunday","Von Montag bis Donnerstag."],["der Morgen / der Nachmittag","morning / afternoon","Am Nachmittag kommt Mia nach Hause."],["wann","when","Wann beginnt der Kurs?"],["um (+ Uhrzeit)","at (+ time)","Der Kurs beginnt um neun."],["beginnen","to begin","Ich beginne um fünf Uhr dreißig."],["das Frühstück","breakfast","Kein Kaffee, kein Frühstück."],["der Schlafanzug, die Schlafanzüge","pyjamas","Mia läuft im Schlafanzug nach unten."],["die Vorlesung, die Vorlesungen","lecture","Wann haben Sie Vorlesungen?"],["kaputt","broken","Mein Handy ist kaputt."],["frisch","fresh","Frisch und noch warm."],["warm","warm","Frisch und noch warm."],["die Tüte, die Tüten","(paper/plastic) bag","Vor ihrer Tür liegt eine Papiertüte."]],"c":[["Wie spät ist es?","What time is it?","Entschuldigung! Wie spät ist es?"],["Es ist … Uhr …","It's … o'clock","Es ist neun Uhr dreißig."],["von … bis …","from … to …","von neun Uhr bis zwölf Uhr dreißig"],["am Montag","on Monday","Am Montag und am Mittwoch."],["Von wem?","From whom?","Aber … von wem?"]],"x":[["die Kleidung","clothes",""],["das T-Shirt, die T-Shirts","T-shirt",""],["das Kleid, die Kleider","dress",""],["die Socke, die Socken","sock",""],["weiß","white",""]],"g":["Uhrzeit und Wochentage",["Ask the time: Wie spät ist es? – Es ist acht Uhr fünfzig. (formal time: hour + Uhr + minutes).","Ask when: Wann …? / Um wie viel Uhr …? – um neun Uhr.","Days: am Montag, am Freitag. All days are masculine: der Montag.","From–to: von Montag bis Donnerstag.","Beispiele: Der Kurs beginnt um neun. · Am Freitag ist kein Kurs."]]},{"n":16,"t":"Mias Tag","l":"A1","review":false,"p":[["Mia erzählt","„Mein Tag hat jetzt einen Rhythmus. Morgens klingelt der Wecker um sieben. Dann dusche ich. Um halb acht frühstücke ich: eine Tasse Kaffee und ein Müsli. Um halb neun fahre ich mit der Straßenbahn in die Stadt. Von neun bis halb eins habe ich Kurs. Mittags esse ich mit Elif und Tom in der Mensa. Nachmittags lerne ich Vokabeln. Abends koche ich. Leider schlecht.“"],["Aber diese Woche ist etwas anders."],["Am Dienstag liegt wieder eine Tüte vor der Tür. Wieder eine Brezel. Wieder kein Name."],["Am Mittwoch liegt wieder eine Tüte da. Diesmal ist ein Croissant darin."],["Mia ist jetzt Detektivin. In ihrem Notizbuch steht eine Liste:"],["Wer bringt die Brezeln?"],["Jonas? Er ist Koch. Er steht früh auf. Er ist nett."],["Frau Schulz? Sie ist immer zu Hause. Aber sie ist streng."],["Tom? Er macht gern Witze. Aber er wohnt in Haslach."],["Elif? Sie wohnt im Studentenwohnheim. Sehr weit weg."],["Am Mittwochabend trifft Mia Jonas auf der Treppe."],["Mia","Jonas, eine Frage. Isst du gern Brezeln?"],["Jonas","Brezeln? Nein, nicht so gern. Morgens esse ich lieber ein Croissant."],["Mia","Ein Croissant? Aha!"],["Jonas","Warum „aha“?"],["Mia","Nur so."],["Jonas sieht Mia komisch an. Dann geht er nach oben."],["Mia denkt nach. Croissant! Heute ist ein Croissant in der Tüte. Ist das Jonas? Aber warum sagt er nichts?"],["Dann hat sie eine Idee. Morgen früh steht sie sehr früh auf. Um Viertel vor sechs. Dann wartet sie hinter der Tür. Und dann sieht sie: Wer ist es?"],["Donnerstag, sechs Uhr zehn. Es ist dunkel und still. Mia sitzt hinter der Tür, im Schlafanzug, mit einer Tasse Kaffee. Sie ist sehr müde."],["Da hört sie etwas. Schritte. Auf der Treppe. Leise. Sehr leise."],["Mia hält die Luft an."],["Wer ist da?"]],"q":["Was isst Mia zum Frühstück?","Was ist am Mittwoch in der Tüte?","Richtig oder falsch? Jonas isst morgens gern Brezeln.","Was ist Mias Plan für Donnerstag?","Und du? Wie ist dein Tag? (Morgens … Dann … Abends …)"],"a":["Eine Tasse Kaffee und ein Müsli. „Um halb acht frühstücke ich: eine Tasse Kaffee und ein Müsli.“","Ein Croissant. „Diesmal ist ein Croissant darin.“","Falsch. „Brezeln? Nein, nicht so gern. Morgens esse ich lieber ein Croissant.“","Very early, she wants to wait behind the door and see who brings the bag. „Dann wartet sie hinter der Tür.“","Example: Morgens trinke ich Tee. Dann fahre ich zur Arbeit. Abends lese ich."],"w":[["morgens / mittags / nachmittags / abends","in the morning / at noon / in the afternoon / in the evening","Abends koche ich."],["dann","then","Dann dusche ich."],["duschen","to shower","Dann dusche ich."],["frühstücken","to have breakfast","Um halb acht frühstücke ich."],["die Tasse, die Tassen","cup","Eine Tasse Kaffee."],["das Müsli, die Müslis","muesli, cereal","Eine Tasse Kaffee und ein Müsli."],["die Mensa, die Mensen","university canteen","Mittags esse ich in der Mensa."],["die Vokabel, die Vokabeln","vocabulary word","Nachmittags lerne ich Vokabeln."],["das Notizbuch, die Notizbücher","notebook","In ihrem Notizbuch steht eine Liste."],["wieder","again","Wieder eine Brezel."],["früh","early","Er steht früh auf."],["warten","to wait","Dann wartet sie hinter der Tür."],["dunkel","dark","Es ist dunkel und still."],["leise","quiet(ly)","Leise. Sehr leise."],["der Schritt, die Schritte","step, footstep","Schritte. Auf der Treppe."]],"c":[["um halb acht","at half past seven","Um halb acht frühstücke ich."],["um Viertel vor sechs","at quarter to six","Um Viertel vor sechs."],["Eine Frage, …","A question, …","Jonas, eine Frage."],["die Luft anhalten","to hold one's breath","Mia hält die Luft an."]],"x":[["braun","brown",""],["rosa","pink",""],["lila","purple",""],["schön","beautiful",""],["die Sekunde, die Sekunden","second",""]],"g":["das Verb auf Position 2",["In a German statement, the verb is always in position 2.","You can put a time or other word in position 1. Then the subject moves after the verb.","Ich frühstücke um halb acht. → Um halb acht frühstücke ich.","Position 1 can be one word or a group of words: Am Mittwochabend · Morgens · Dann.","Beispiele: Abends koche ich. · Am Dienstag liegt wieder eine Tüte vor der Tür."]]},{"n":17,"t":"Ich stehe um halb sechs auf","l":"A1","review":false,"p":[["Die Schritte kommen näher. Jetzt! Mia macht die Tür auf."],["Mia","Hab ich dich!"],["Jonas","Aaah! Mia! Was machst du da? Im Schlafanzug? Um sechs Uhr?"],["Mia","Und du? Was machst du da?"],["Jonas","Ich gehe zur Arbeit. Ich stehe jeden Tag um halb sechs auf. Um Viertel nach sechs fahre ich los. Um halb sieben fange ich im Café an."],["Mia","Und die Brezel? Das Croissant?"],["Jonas","Welche Brezel?"],["Mia erzählt alles","die Tüten, die Brezeln, das Croissant, die Liste."],["Jonas","Nein, das bin ich nicht. Ehrlich! Aber … die Idee ist schön. Hm. Ich habe Konkurrenz!"],["Er lacht, macht die Haustür auf und fährt los."],["Mia macht ihre Tür wieder zu. Sie setzt sich auf den Boden, hinter die Tür. Sie wartet. Und wartet. Ihre Augen sind so schwer …"],["Um zwanzig nach sieben wacht Mia auf. Auf dem Boden. Der Rücken tut weh. Sie macht die Tür auf. Und da liegt sie: die Tüte. Darin ist ein Croissant, noch warm."],["Mia","Nein! Ich schlafe ein – und dann kommt der Brezel-Mensch!"],["Sie isst das Croissant. Es ist sehr gut. Das ist das Problem."],["Mia zieht sich an und kauft schnell Milch im Supermarkt ein. Um acht kommt sie zurück. Da ruft Frau Schulz von unten:"],["Frau Schulz","Frau Costa! Kommen Sie bitte mal runter?"],["Mia","Ja, ich komme! Was ist los?"],["Frau Schulz","Ich habe ein Problem. Ein großes Problem."],["Ihre Stimme klingt komisch. Ein bisschen leise. Ein bisschen traurig."],["Mia läuft die Treppe hinunter. Was ist mit Frau Schulz?"]],"q":["Wann steht Jonas jeden Tag auf?","Wann fängt Jonas im Café an?","Richtig oder falsch? Jonas bringt die Brezeln.","Warum sieht Mia den „Brezel-Menschen“ nicht?","Und du? Wann stehst du auf? Wann fängt deine Arbeit oder dein Kurs an?"],"a":["Um halb sechs. „Ich stehe jeden Tag um halb sechs auf.“","Um halb sieben. „Um halb sieben fange ich im Café an.“","Falsch. Jonas says: „Nein, das bin ich nicht. Ehrlich!“","She falls asleep behind the door. „Ich schlafe ein – und dann kommt der Brezel- Mensch!“","Example: Ich stehe um sieben auf. Meine Arbeit fängt um neun an."],"w":[["aufstehen","to get up","Ich stehe jeden Tag um halb sechs auf."],["anfangen (er fängt an)","to start","Um halb sieben fange ich an."],["losfahren (er fährt los)","to set off","Um Viertel nach sechs fahre ich los."],["aufmachen / zumachen","to open / to close","Mia macht ihre Tür wieder zu."],["einschlafen (er schläft ein)","to fall asleep","Ich schlafe ein."],["aufwachen","to wake up","Um zwanzig nach sieben wacht Mia auf."],["anziehen (sich)","to get dressed","Mia zieht sich an."],["einkaufen","to go shopping","Sie kauft schnell Milch ein."],["zurückkommen","to come back","Um acht kommt sie zurück."],["anrufen / rufen","to call (phone) / to shout","Frau Schulz ruft von unten."],["die Arbeit, die Arbeiten","work","Ich gehe zur Arbeit."],["das Auge, die Augen","eye","Ihre Augen sind so schwer."],["der Rücken, die Rücken","back","Der Rücken tut weh."],["die Stimme, die Stimmen","voice","Ihre Stimme klingt komisch."],["komisch","strange; funny","Ihre Stimme klingt komisch."]],"c":[["Hab ich dich!","Got you!","Hab ich dich!"],["jeden Tag","every day","Ich stehe jeden Tag um halb sechs auf."],["Viertel nach sechs","quarter past six","Um Viertel nach sechs fahre ich los."],["Was ist los?","What's the matter?","Ja, ich komme! Was ist los?"],["… tut weh","… hurts","Der Rücken tut weh."]],"x":[["der Tag, die Tage","day",""],["die Woche, die Wochen","week",""],["der Mittag, die Mittage","noon",""],["der Nachmittag, die Nachmittage","afternoon",""],["der Abend, die Abende","evening",""]],"g":["trennbare Verben",["Some verbs have a prefix that separates: auf|stehen, an|fangen, ein|kaufen.","The verb goes to position 2; the prefix goes to the end: Ich stehe um halb sechs auf.","In the dictionary and with modal verbs they stay together: aufstehen.","The stress is always on the prefix: AUFstehen, ANfangen.","Beispiele: Um halb sieben fange ich im Café an. · Mia macht die Tür auf."]]},{"n":18,"t":"Ich kann das nicht!","l":"A1","review":false,"p":[["Frau Schulz sitzt in der Küche. Vor ihr liegen zwei Briefe, ein neues Handy und eine Brille – in zwei Teilen."],["Frau Schulz","Meine Brille ist kaputt. Felix! Er springt auf den Tisch, und – zack! Ohne Brille kann ich nicht lesen."],["Mia","Oh nein! Kann ich Ihnen helfen?"],["Frau Schulz","Ja, bitte. Können Sie den Brief hier lesen? Er ist von meinem Sohn Michael. Er wohnt in Hamburg."],["Mia liest laut","Liebe Mama, ich komme an Weihnachten nach Freiburg! Ich kann zehn Tage bleiben. Und: Kannst du dein neues Handy benutzen? Bitte ruf mich an! Dein Michael."],["Frau Schulz","Zehn Tage! Wie schön! Aber das Handy … Ich kann gut kochen. Ich kann gut stricken. Ich kann Klavier spielen. Aber das Handy – das kann ich nicht!"],["Mia","Das ist nicht schwer. Schauen Sie: Hier können Sie tippen. Hier können Sie Michael anrufen. Und hier können Sie Fotos sehen."],["Frau Schulz","Kann ich auch Fotos machen?"],["Mia","Ja, klar. Hier."],["Klick! Das erste Foto: Felix. Er sitzt auf dem Kühlschrank und sieht sehr zufrieden aus."],["Mia","Wie kommt Felix auf den Kühlschrank?"],["Frau Schulz","Ach, Felix kann alles. Er kann springen wie ein Tiger. Er kann sogar Türen aufmachen!"],["Mia","Türen aufmachen? Wirklich?"],["Frau Schulz","Ja. Mit der Pfote. Er ist sehr intelligent. Aber nicht sehr brav."],["Mia sieht Felix an. Felix sieht Mia an. Hm."],["Frau Schulz","Und der zweite Brief? Der ist nicht für mich. Der ist für Sie, Frau Costa. Der Postbote macht immer Fehler."],["Auf dem Brief steht","Stadt Freiburg – Bürgeramt. Mia macht den Brief auf und liest. Ihr Gesicht wird blass."],["Frau Schulz","Was ist los?"],["Mia","Hier steht: Ich muss mich anmelden. In Freiburg. Bis zum zweiten Oktober."],["Frau Schulz","Der zweite Oktober? Das ist nächste Woche!"],["Mia","Und ich habe keinen Termin. Kein Formular. Nichts!"],["Frau Schulz","Oh je. Das Bürgeramt. Viel Glück, Frau Costa."],["Schon wieder","Viel Glück."]],"q":["Warum ist die Brille kaputt?","Was schreibt Michael?","Richtig oder falsch? Frau Schulz kann sehr gut mit dem Handy telefonieren.","Was kann Felix?","Und du? Was kannst du gut? Was kannst du nicht so gut?"],"a":["Felix springt auf den Tisch. „Felix! Er springt auf den Tisch, und – zack!“","He is coming to Freiburg for Christmas for ten days. „Ich komme an Weihnachten nach Freiburg! Ich kann zehn Tage bleiben.“","Falsch. „Aber das Handy – das kann ich nicht!“","Jump like a tiger and open doors. „Er kann springen wie ein Tiger. Er kann sogar Türen aufmachen!“ (A clue?)","Example: Ich kann gut kochen. Ich kann nicht gut singen."],"w":[["können (kann, kannst)","can, to be able to","Ohne Brille kann ich nicht lesen."],["die Brille, die Brillen","glasses","Meine Brille ist kaputt."],["der Brief, die Briefe","letter","Er ist von meinem Sohn Michael."],["Weihnachten","Christmas","Ich komme an Weihnachten nach Freiburg!"],["bleiben","to stay","Ich kann zehn Tage bleiben."],["benutzen","to use","Kannst du dein neues Handy benutzen?"],["helfen","to help","Kann ich Ihnen helfen?"],["springen","to jump","Er kann springen wie ein Tiger."],["stricken","to knit","Ich kann gut stricken."],["das Klavier, die Klaviere","piano","Ich kann Klavier spielen."],["der Termin, die Termine","appointment","Ich habe keinen Termin."],["das Formular, die Formulare","form","Kein Formular. Nichts!"],["der Fehler, die Fehler","mistake","Der Postbote macht immer Fehler."],["das Gesicht, die Gesichter","face","Ihr Gesicht wird blass."],["brav","well-behaved, good","Aber nicht sehr brav."]],"c":[["Kann ich Ihnen helfen?","Can I help you?","Oh nein! Kann ich Ihnen helfen?"],["Hier steht: …","It says here: …","Hier steht: Ich muss mich anmelden."],["nächste Woche","next week","Das ist nächste Woche!"],["Oh je!","Oh dear!","Oh je. Das Bürgeramt."]],"x":[["der Montag, die Montage","Monday",""],["der Dienstag, die Dienstage","Tuesday",""],["der Mittwoch, die Mittwoche","Wednesday",""],["der Donnerstag, die Donnerstage","Thursday",""],["der Freitag, die Freitage","Friday",""]],"g":["das Modalverb können",["können: ich kann, du kannst, er/sie/es kann, wir können, ihr könnt, sie/Sie können.","No ending for ich and er/sie/es: ich kann, er kann.","The second verb goes to the end in the infinitive: Ich kann gut kochen.","Use it for ability, possibility and polite requests (Können Sie …?).","Beispiele: Ohne Brille kann ich nicht lesen. · Können Sie den Brief lesen?"]]},{"n":19,"t":"Termin beim Bürgeramt","l":"A1","review":false,"p":[["Freitag, sieben Uhr. Mia sitzt am Laptop. Elif ist am Telefon."],["Elif","Du musst jetzt online gehen! Um sieben gibt es neue Termine."],["Mia","Ich will einen Termin, aber hier steht: „Keine Termine frei.“"],["Elif","Klick noch einmal! Schnell!"],["Mia","Da! Ein Termin! Dienstag, acht Uhr fünfzehn!"],["Elif","Super! Du musst den Pass mitnehmen, das Formular und die Wohnungsgeberbestätigung."],["Mia","Die Wohnungs… was?"],["Elif","Ein Papier vom Vermieter. Das musst du haben!"],["Mia","Ich habe einen Mietvertrag. Das ist sicher okay."],["Dienstag, acht Uhr. Das Bürgeramt ist voll. Mia muss eine Nummer ziehen: B 47. Sie wartet. Und wartet. Um acht Uhr vierzig steht auf dem Bildschirm: B 47 – Platz 6."],["Herr Krause","Guten Morgen. Was wollen Sie?"],["Mia","Guten Morgen. Ich will mich anmelden."],["Herr Krause","Den Pass, bitte. Das Formular. Und die Wohnungsgeberbestätigung."],["Mia","Hier ist mein Mietvertrag."],["Herr Krause","Das ist ein Mietvertrag. Ich brauche die Wohnungsgeberbestätigung."],["Mia","Muss ich die wirklich haben?"],["Herr Krause","Ja, die müssen Sie haben. Ohne Bestätigung keine Anmeldung."],["Mia","Aber ich muss mich bis zum zweiten Oktober anmelden!"],["Herr Krause sieht Mia an. Er seufzt."],["Herr Krause","Okay. Kommen Sie am Donnerstag um acht noch einmal. Mit dem Papier. Das ist eine Ausnahme."],["Mia","Danke! Vielen Dank!"],["Zu Hause liest Mia den Mietvertrag. Zum ersten Mal genau. Oben steht: Vermieterin: Renate Schulz, Lindenstraße 12."],["Renate Schulz? Schulz?! Mia läuft nach unten."],["Mia","Frau Schulz … sind Sie meine Vermieterin?"],["Frau Schulz","Natürlich! Das Haus gehört mir. Das wissen Sie nicht?"],["Mia","Nein! Ich brauche ein Papier von Ihnen. Eine Wohnungsgeberbestätigung."],["Frau Schulz","Kein Problem. Ich unterschreibe sofort. Aber Sie müssen das Formular ausfüllen. Ohne Brille kann ich nichts lesen!"],["Mia füllt das Formular aus. Frau Schulz unterschreibt. Fertig!"],["Am Abend will Mia feiern. Sie macht die Tür auf und will zu Jonas gehen. Da sieht sie den Boden vor ihrer Tür. Keine Tüte. Keine Brezel. Nichts."],["Zum ersten Mal seit einer Woche."],["Warum?"]],"q":["Wann gibt es online neue Termine?","Welches Papier hat Mia nicht?","Richtig oder falsch? Herr Krause sagt: „Sie müssen nie wieder kommen.“","Wer ist Mias Vermieterin?","Und du? Was musst du diese Woche machen? Was willst du machen?"],"a":["Um sieben Uhr. Elif: „Um sieben gibt es neue Termine.“","Die Wohnungsgeberbestätigung (ein Papier vom Vermieter). „Ich brauche die Wohnungsgeberbestätigung.“","Falsch. He says: „Kommen Sie am Donnerstag um acht noch einmal.“","Frau Schulz (Renate Schulz). „Natürlich! Das Haus gehört mir.“","Example: Ich muss arbeiten und einkaufen. Ich will am Samstag schwimmen."],"w":[["müssen (muss, musst)","must, to have to","Du musst jetzt online gehen!"],["wollen (will, willst)","to want","Ich will einen Termin."],["das Bürgeramt, die Bürgerämter","citizens' office","Das Bürgeramt ist voll."],["sich anmelden","to register","Ich will mich anmelden."],["die Anmeldung, die Anmeldungen","registration","Ohne Bestätigung keine Anmeldung."],["der Pass, die Pässe","passport","Den Pass, bitte."],["das Papier, die Papiere","paper, document","Ein Papier vom Vermieter."],["der Mietvertrag, die Mietverträge","rental contract","Hier ist mein Mietvertrag."],["die Vermieterin, die Vermieterinnen","landlady","Sind Sie meine Vermieterin?"],["ausfüllen","to fill in","Sie müssen das Formular ausfüllen."],["unterschreiben","to sign","Ich unterschreibe sofort."],["gehören","to belong to","Das Haus gehört mir."],["feiern","to celebrate","Am Abend will Mia feiern."],["die Ausnahme, die Ausnahmen","exception","Das ist eine Ausnahme."],["sofort","immediately","Ich unterschreibe sofort."]],"c":[["eine Nummer ziehen","to take a number (ticket)","Mia muss eine Nummer ziehen."],["Vielen Dank!","Thank you very much!","Danke! Vielen Dank!"],["zum ersten Mal","for the first time","Zum ersten Mal genau."],["bis zum zweiten Oktober","by 2 October","bis zum zweiten Oktober"]],"x":[["der Samstag, die Samstage","Saturday",""],["der Sonntag, die Sonntage","Sunday",""],["der Januar","January",""],["der Februar","February",""],["der März","March",""]],"g":["müssen und wollen",["müssen: ich muss, du musst, er muss, wir müssen, ihr müsst, sie müssen (obligation).","wollen: ich will, du willst, er will, wir wollen, ihr wollt, sie wollen (strong wish, plan).","Like können: modal verb in position 2, the infinitive at the end.","Careful: ich will means \"I want\", not \"I will\".","Beispiele: Du musst jetzt online gehen! · Ich will mich anmelden."]]},{"n":20,"t":"Wiederholung: Ein ganz normaler Tag?","l":"A1","review":true,"p":[["Donnerstag, einundzwanzig Uhr"],["Heute um acht Uhr bin ich wieder im Bürgeramt. Herr Krause sieht das Papier von Frau Schulz an. Dann sagt er: „Fertig. Herzlich willkommen in Freiburg, Frau Costa.“ Und er lächelt! Ein Mann vom Bürgeramt lächelt. Das ist kein normaler Tag."],["Ich bin jetzt zwei Wochen hier. Was ist neu?"],["Tom hat einen Hund. Er heißt Bruno, und er ist groß und schwarz. Aber Hunde sind im Haus verboten. Toms Vermieter weiß nichts. Ich sage auch nichts!"],["Jonas hat keine Freundin. Die Frau ist seine Schwester Lena. Ihr Sohn Paul ist sechs und er fragt immer alles. Am Sonntag spielen wir Fußball im Park. Ich spiele schlecht. Sehr schlecht. Aber es ist ein schöner Tag."],["Meine Vermieterin ist Frau Schulz! Das Haus gehört ihr. Und ich weiß das nicht – zwei Wochen lang. Ich muss den Mietvertrag lesen. Immer!"],["Und dann die Brezeln. Jeden Morgen liegt eine Tüte vor meiner Tür. Eine Brezel oder ein Croissant. Frisch und warm. Jonas sagt: „Das bin ich nicht.“ Ich glaube, er sagt die Wahrheit. Wer dann? Frau Schulz? Sie kann ohne Brille nicht lesen. Kann sie Brezeln kaufen? Vielleicht."],["Frau Schulz sagt","Felix kann Türen aufmachen. Aber Felix? Nein. Eine Katze kann keine Brezeln kaufen. Ha ha."],["Seit Dienstag ist keine Tüte da. Keine Brezel, kein Croissant. Warum? Ist der Brezel- Mensch krank? Oder böse?"],["Ich bin ein bisschen traurig. Ich esse gern Brezeln."],["Jetzt macht das Handy pling. Eine Nachricht von Jonas:"],["Hallo Mia! Am Samstag habe ich frei. Ich zeige dir Freiburg. Um siebzehn Uhr im Park? J."],["Ist das eine Einladung? Oder … mehr?"],["Ich schreibe","Ja, gern! Dann lösche ich das. Ich schreibe: Okay. Dann lösche ich das auch. Am Ende schreibe ich: Ja, gern! :)"],["Was ziehe ich am Samstag an?"]],"q":["Akkusativ: Ich brauche ___ Salat (ein). Wo finde ich ___ Kaffee (der)?","mein / dein: Das ist ___ Mutter. Ist das ___ Hund, Tom?","sein / ihr: Paul ist Lenas Sohn → Paul ist ___ Sohn. Bruno ist Toms Hund → Bruno ist ___ Hund.","Ergänze das Verb: Lena ___ (lesen) ein Buch. Du ___ (fahren) mit dem Fahrrad.","8:50 → Es ist ___. Wann beginnt der Kurs? ___ neun Uhr.","Stell das Wort an Position 1: Ich koche abends. → Abends ___.","Trennbares Verb: Jonas / aufstehen / um halb sechs → Jonas ___ um halb sechs ___.","Ergänze können: Frau Schulz ___ ohne Brille nicht lesen.","müssen oder wollen? Ich ___ mich bis zum zweiten Oktober anmelden. Am Abend ___ Mia feiern.","Was ist Toms Geheimnis?"],"a":["einen · den. Masculine nouns change in the accusative: ein → einen, der → den.","meine · dein. Mutter is feminine → meine; Hund is masculine → dein.","ihr · sein. Lena is a woman → ihr; Tom is a man → sein.","liest · fährst. Stem change with du and er/sie/es: e → ie, a → ä.","acht Uhr fünfzig · Um. Time: hour + Uhr + minutes; \"at\" = um.","Abends koche ich. The verb stays in position 2; the subject moves after it.","steht … auf. The prefix of a separable verb goes to the end.","kann. er/sie/es kann – no ending.","muss · will. müssen = obligation (the letter from the city); wollen = wish.","He has a dog, Bruno, but dogs are not allowed in his building. Story 12: „Hunde sind im Haus verboten!“"],"w":[],"c":[],"x":[],"g":["Wiederholung",["Accusative: den, einen, keinen for masculine nouns (story 11).","Possessives: mein, dein, sein, ihr, unser, euer, Ihr (stories 12–13).","Verb forms: stem changes (story 14), separable verbs (story 17), verb in position 2 (story 16).","Time: Wie spät ist es? – um neun Uhr, am Montag (story 15).","Modal verbs können, müssen, wollen + infinitive at the end (stories 18–19).","Beispiele: Am Samstag habe ich frei. · Ich muss den Mietvertrag lesen."]],"exam":{"task":"Sie können morgen nicht zum Deutschkurs kommen. Schreiben Sie Ihrem Lehrer eine E-Mail.","points":["Entschuldigen Sie sich.","Warum können Sie nicht kommen?","Fragen Sie nach den Hausaufgaben."],"words":30,"en":"Email to your teacher: say sorry, why you can't come, ask about homework."}},{"n":21,"t":"Wo ist die Post?","l":"A1","review":false,"p":[["Samstag, zehn Uhr. Rui hat nächste Woche Geburtstag. Mia hat ein Paket für ihn: ein T- Shirt vom SC Freiburg und Schokolade aus dem Schwarzwald. Sie muss das Paket heute nach Porto schicken. Die Post ist bis dreizehn Uhr offen."],["Das Handy hat keinen Akku – schon wieder! Also fragt Mia auf der Straße."],["Mia","Entschuldigung, wie komme ich zur Post?"],["Mann","Zur Post? Gehen Sie hier geradeaus. Dann die zweite Straße links. An der Ampel gehen Sie rechts. Dann sehen Sie die Post."],["Mia","Geradeaus, die zweite Straße links, an der Ampel rechts. Danke!"],["Mia geht geradeaus. Erste Straße, zweite Straße – links. Aber da ist keine Ampel. Da ist eine Kirche. Und viele kleine Straßen. Mia hat sich verlaufen."],["Sie fragt eine Frau mit zwei Kindern."],["Mia","Entschuldigung, ich suche die Post."],["Frau","Oh, das ist nicht hier. Gehen Sie zurück bis zum Münsterplatz. Dann nehmen Sie die Kaiser-Joseph-Straße. Die Post ist rechts, neben der Bank. … Kinder, wartet! Lauft nicht so schnell! Bleibt hier!"],["Mia geht zurück. Sie sieht nicht nach unten. Und plötzlich – platsch! Ihr Fuß ist im Wasser. Ein kleiner Kanal, mitten auf der Straße! Der Schuh ist nass. Die Socke ist nass. Alles ist nass."],["Ein alter Mann auf einer Bank lacht."],["Alter Mann","Ha! Das ist ein Bächle! Die Bächle sind typisch für Freiburg. Und wissen Sie was? Eine alte Geschichte sagt: Wer in ein Bächle tritt, heiratet einen Freiburger!"],["Mia","Was? Nein!"],["Alter Mann","Doch, doch! Viel Glück, junge Frau!"],["Viel Glück. Immer Viel Glück!"],["Um zwölf Uhr vierzig findet Mia endlich die Post. Mit einem nassen Schuh. Am Schalter steht eine junge Frau."],["Mitarbeiterin","Was möchten Sie schicken?"],["Mia","Ein Paket nach Portugal, bitte."],["Mitarbeiterin","Füllen Sie bitte dieses Formular aus. Schreiben Sie hier die Adresse. Und legen Sie das Paket auf die Waage. … Zwei Kilo. Das macht siebzehn Euro neunundneunzig."],["Mia","Wann ist das Paket in Porto?"],["Mitarbeiterin","In fünf bis sieben Tagen."],["Perfekt. Pünktlich zu Ruis Geburtstag!"],["Auf dem Weg nach Hause denkt Mia an den alten Mann. Einen Freiburger heiraten? Quatsch. Aber … Jonas ist Freiburger."],["Zu Hause lädt sie das Handy auf. Dann liest sie noch einmal die Nachricht von Jonas: Um siebzehn Uhr im Park."],["Im Park. Aber in welchem Park? Freiburg hat viele Parks!"],["Sie schreibt","Welcher Park? Keine Antwort. Es ist halb fünf."]],"q":["Was ist in dem Paket für Rui?","Was sagt der Mann: Wie kommt Mia zur Post?","Richtig oder falsch? Die Post ist am Samstag bis achtzehn Uhr offen.","Was ist ein „Bächle“ und was sagt die alte Geschichte?","Und du? Wie kommt man von deiner Wohnung zum Supermarkt? (Geh geradeaus, dann …)"],"a":["Ein T-Shirt vom SC Freiburg und Schokolade. „Ein T-Shirt vom SC Freiburg und Schokolade aus dem Schwarzwald.“","Geradeaus, die zweite Straße links, an der Ampel rechts. „Gehen Sie hier geradeaus. Dann die zweite Straße links. An der Ampel gehen Sie rechts.“","Falsch. „Die Post ist bis dreizehn Uhr offen.“","A small water channel in the streets of Freiburg. If you step in one, you marry someone from Freiburg. „Wer in ein Bächle tritt, heiratet einen Freiburger!“","Example: Geh geradeaus, dann die erste Straße rechts. Der Supermarkt ist links, neben der Bank."],"w":[["die Post","post office","Die Post ist bis dreizehn Uhr offen."],["das Paket, die Pakete","parcel","Mia hat ein Paket für ihn."],["der Geburtstag, die Geburtstage","birthday","Rui hat nächste Woche Geburtstag."],["schicken","to send","Sie muss das Paket nach Porto schicken."],["die Straße, die Straßen","street","Dann die zweite Straße links."],["geradeaus","straight on","Gehen Sie hier geradeaus."],["links / rechts","left / right","An der Ampel gehen Sie rechts."],["die Ampel, die Ampeln","traffic light","An der Ampel gehen Sie rechts."],["die Kirche, die Kirchen","church","Da ist eine Kirche."],["die Bank, die Banken / die Bänke","bank / bench","neben der Bank · auf einer Bank"],["der Schuh, die Schuhe","shoe","Der Schuh ist nass."],["nass","wet","Alles ist nass."],["heiraten","to marry","Wer in ein Bächle tritt, heiratet einen Freiburger!"],["die Adresse, die Adressen","address","Schreiben Sie hier die Adresse."],["die Antwort, die Antworten","answer","Keine Antwort."]],"c":[["Wie komme ich zur …?","How do I get to …?","Wie komme ich zur Post?"],["die zweite Straße links","the second street on the left","Dann die zweite Straße links."],["sich verlaufen","to get lost (on foot)","Mia hat sich verlaufen."],["Quatsch!","Nonsense!","Einen Freiburger heiraten? Quatsch."]],"x":[["der April","April",""],["der Mai","May",""],["der Juni","June",""],["der Juli","July",""],["der August","August",""]],"g":["der Imperativ",["Sie-form: verb + Sie: Gehen Sie geradeaus! · Füllen Sie das Formular aus!","du-form: verb stem, no du: gehen → Geh! · warten → Warte! · Stem change e→i stays: nehmen → Nimm!","ihr-form: like the present tense, no ihr: Wartet! Bleibt hier!","Separable verbs: the prefix goes to the end. Bitte makes it polite.","Beispiele: Gehen Sie zurück bis zum Münsterplatz. · Kinder, wartet!"]]},{"n":22,"t":"Im Park und auf dem Berg","l":"A1","review":false,"p":[["Siebzehn Uhr. Mia ist im Seepark. Hier spielen sie am Sonntag Fußball. Das ist sicher der Park. Sie sitzt auf einer Bank am See und wartet."],["Siebzehn Uhr zehn. Kein Jonas. Siebzehn Uhr fünfzehn. Dann klingelt das Handy."],["Jonas","Mia! Wo bist du?"],["Mia","Ich bin im Park! Auf einer Bank, am See."],["Jonas","Am See? Im Seepark? Ich bin im Stadtgarten! Das ist in der Stadt, an der Altstadt."],["Mia","Oh nein!"],["Jonas","Kein Problem. Bleib da! Ich komme mit dem Rad. Zehn Minuten!"],["Nach zehn Minuten ist Jonas da. Er lacht."],["Jonas","Mein Fehler. Ich schreibe „im Park“, aber Freiburg hat zwanzig Parks!"],["Sie fahren mit der Straßenbahn in die Stadt. Jonas zeigt Mia alles."],["Jonas","Hier ist die Uni. Elif studiert hier, oder? Da drüben ist das Theater. Und im Münster ist es ganz still – schön zum Nachdenken."],["Mia","Und wo bist du am liebsten?"],["Jonas","In der Küche, natürlich! Und auf dem Schlossberg. Komm, ich zeige dir den Schlossberg!"],["Sie gehen einen kleinen Berg hoch. Viele Treppen. Mia ist müde. Aber oben ist ein Turm, und vom Turm sieht man ganz Freiburg: die Dächer, das Münster, die Berge vom Schwarzwald. Die Sonne geht unter. Alles ist rot und gold."],["Mia","Wow. Das ist wunderschön."],["Im Café auf dem Schlossberg sitzen sie auf der Terrasse. Mia trinkt einen Tee, Jonas ein Bier."],["Jonas","Und du? Wo bist du am liebsten, in Porto?"],["Mia","Am Meer. Und im Café von meiner Oma. Und in der Bibliothek."],["Dann erzählt Mia vom Bächle. Und von dem alten Mann. Jonas lacht laut."],["Jonas","Das stimmt! Meine Oma kommt aus Hamburg. Sie ist im Urlaub in Freiburg, und – platsch! – ihr Fuß ist im Bächle. Ein Jahr später heiratet sie meinen Opa. Einen Freiburger."],["Mia","Wirklich?"],["Jonas","Wirklich."],["Es ist plötzlich ganz still. Jonas sieht Mia an. Mia sieht Jonas an."],["Um neun Uhr sind sie wieder in der Lindenstraße, vor Mias Tür."],["Jonas","Mia, ich …"],["Da springt Felix zwischen die beiden. „Miau!“ Laut und frech."],["Jonas","Felix! … Na gut. Gute Nacht, Mia."],["Mia","Gute Nacht, Jonas."],["Jonas geht die Treppe hoch. Dann dreht er sich um."],["Jonas","Ach, Mia – kannst du Fahrrad fahren? Morgen habe ich eine Idee."]],"q":["In welchem Park wartet Mia? Und wo ist Jonas?","Wo ist Jonas am liebsten?","Was sieht man vom Turm auf dem Schlossberg?","Richtig oder falsch? Jonas' Oma kommt aus Freiburg.","Und du? Wo bist du am liebsten? (im Park, am Meer, in der Küche …)"],"a":["Mia ist im Seepark, Jonas ist im Stadtgarten. „Am See? Im Seepark? Ich bin im Stadtgarten!“","In der Küche und auf dem Schlossberg. „In der Küche, natürlich! Und auf dem Schlossberg.“","Ganz Freiburg: die Dächer, das Münster, die Berge vom Schwarzwald. „Vom Turm sieht man ganz Freiburg.“","Falsch. „Meine Oma kommt aus Hamburg.“ She married a man from Freiburg.","Example: Ich bin am liebsten am Meer. Und zu Hause, auf dem Sofa."],"w":[["der See, die Seen","lake","Sie sitzt auf einer Bank am See."],["die Stadt, die Städte","town, city","Das ist in der Stadt."],["die Uni (Universität), die Unis","university","Hier ist die Uni."],["das Theater, die Theater","theatre","Da drüben ist das Theater."],["der Berg, die Berge","mountain, hill","Sie gehen einen kleinen Berg hoch."],["der Turm, die Türme","tower","Oben ist ein Turm."],["das Dach, die Dächer","roof","die Dächer, das Münster …"],["die Sonne","sun","Die Sonne geht unter."],["die Terrasse, die Terrassen","terrace","Sie sitzen auf der Terrasse."],["die Bibliothek, die Bibliotheken","library","Und in der Bibliothek."],["der Urlaub, die Urlaube","holiday","Sie ist im Urlaub in Freiburg."],["der Fuß, die Füße","foot","Ihr Fuß ist im Bächle."],["wunderschön","beautiful","Das ist wunderschön."],["still","quiet, silent","Es ist plötzlich ganz still."],["frech","cheeky","Laut und frech."]],"c":[["am liebsten","most of all, best","Wo bist du am liebsten?"],["da drüben","over there","Da drüben ist das Theater."],["Die Sonne geht unter.","The sun is setting.","Die Sonne geht unter."],["Das stimmt!","That's true!","Das stimmt!"],["Gute Nacht!","Good night!","Gute Nacht, Mia."]],"x":[["der September","September",""],["der Oktober","October",""],["der November","November",""],["der Dezember","December",""],["der Winter","winter",""]],"g":["Wo? – im, am, auf dem, in der",["To say where something is, use in, an, auf + dative.","der/das-words: im (= in dem), am (= an dem), auf dem: im Park, am See, auf dem Berg.","die-words: in der, an der, auf der: in der Stadt, auf der Terrasse.","in = inside · an = next to, at the edge (water, wall) · auf = on top of, on a surface.","Beispiele: Ich bin im Park, auf einer Bank, am See. · Jonas ist am liebsten in der Küche."]]},{"n":23,"t":"Mit dem Rad zum Bahnhof","l":"A1","review":false,"p":[["Sonntag, zehn Uhr. Vor dem Haus stehen zwei Fahrräder. Ein blaues von Jonas und ein rotes mit einem Korb. Es gehört Lena."],["Jonas","Das ist meine Idee: eine Radtour! Freiburg ist eine Fahrradstadt. Hier fahren alle Rad."],["Mia","Ich fahre seit zehn Jahren nicht mehr Rad. Wohin fahren wir?"],["Jonas","Zuerst zum Bahnhof. Dann in die Altstadt. Dann an die Dreisam, das ist unser Fluss. Und am Ende nach Hause."],["Mia steigt auf das Rad. Sie fährt. Links, rechts, links … Ein Bus kommt. Mia ruft: „Hilfe!“ Aber sie bleibt auf dem Rad. Nach fünf Minuten geht es besser. Nach zehn Minuten macht es Spaß."],["Zuerst fahren sie zum Bahnhof. Er ist groß und modern. Auf der Anzeigetafel stehen Züge: nach Basel, nach Karlsruhe, nach Hamburg, nach Paris."],["Mia","Nach Paris? Direkt?"],["Jonas","Ja, in drei Stunden! Und nach Hamburg in sieben Stunden. Meine Oma wohnt in Hamburg. Ich fahre einmal im Jahr zu ihr."],["Mia","Und ich? Wann fahre ich nach Hause, nach Porto?"],["Jonas","Nach Porto fährst du nicht mit dem Zug. Da musst du fliegen. … Aber bitte nicht so bald."],["Mia sieht ihn an. Er sieht schnell auf die Anzeigetafel."],["Dann fahren sie in die Altstadt. Die Straßen sind klein und voll. Am Münsterplatz kaufen sie zwei Würste. Danach fahren sie an die Dreisam. Hier ist ein Radweg, direkt am Fluss. Die Bäume sind gelb und orange. Es ist Herbst."],["Jonas","Am Wochenende fahre ich oft hierher. Oder in den Schwarzwald. Kommst du mal mit?"],["Mia","In den Schwarzwald? Mit dem Rad? Das sind Berge!"],["Jonas","Okay, okay. Mit dem Zug. Zum Titisee. Das ist ein See im Schwarzwald. Sehr schön."],["Mia","Gern!"],["Um sechs Uhr fahren sie nach Hause. Mia ist müde, aber glücklich. Die Beine tun weh."],["Im Flur sitzt Frau Schulz auf der Treppe. Sie hat ihr Handy in der Hand. Ihre Augen sind rot."],["Frau Schulz","Frau Costa! Jonas! Felix ist weg!"],["Jonas","Weg? Seit wann?"],["Frau Schulz","Seit heute Morgen. Er kommt nicht nach Hause. Er kommt immer zum Essen. Immer! Um zwölf Uhr und um sechs Uhr. Aber heute nicht."],["Draußen wird es dunkel. Und kalt."]],"q":["Wem gehört das rote Fahrrad?","Wohin fahren Mia und Jonas zuerst, dann und am Ende?","Wie lange fährt der Zug nach Paris?","Richtig oder falsch? Felix kommt immer um zwölf und um sechs Uhr zum Essen.","Und du? Wohin fährst du gern am Wochenende? Wie fährst du? (mit dem Rad, mit dem Bus …)"],"a":["Lena. „Ein rotes mit einem Korb. Es gehört Lena.“","Zum Bahnhof, in die Altstadt, an die Dreisam, nach Hause. „Zuerst zum Bahnhof. Dann in die Altstadt. Dann an die Dreisam … am Ende nach Hause.“","Drei Stunden. „Ja, in drei Stunden!“","Richtig. Frau Schulz: „Er kommt immer zum Essen. Immer! Um zwölf Uhr und um sechs Uhr.“","Example: Am Wochenende fahre ich gern an den See. Ich fahre mit dem Rad."],"w":[["wohin","where to","Wohin fahren wir?"],["nach","to (cities, countries, home)","Und am Ende nach Hause."],["zu (zum, zur)","to (places, people)","Zuerst zum Bahnhof."],["der Bahnhof, die Bahnhöfe","station","Er ist groß und modern."],["der Zug, die Züge","train","Auf der Anzeigetafel stehen Züge."],["der Fluss, die Flüsse","river","Das ist unser Fluss."],["der Radweg, die Radwege","cycle path","Hier ist ein Radweg, direkt am Fluss."],["der Baum, die Bäume","tree","Die Bäume sind gelb und orange."],["der Herbst","autumn","Es ist Herbst."],["die Wurst, die Würste","sausage","Sie kaufen zwei Würste."],["die Stunde, die Stunden","hour","In drei Stunden!"],["fliegen","to fly","Da musst du fliegen."],["das Bein, die Beine","leg","Die Beine tun weh."],["gelb / blau / orange","yellow / blue / orange","Die Bäume sind gelb und orange."],["kalt","cold","Draußen wird es dunkel. Und kalt."]],"c":[["nach Hause","(to) home","Um sechs Uhr fahren sie nach Hause."],["Rad fahren","to cycle","Hier fahren alle Rad."],["Es macht Spaß.","It's fun.","Nach zehn Minuten macht es Spaß."],["Hilfe!","Help!","Mia ruft: „Hilfe!“"],["Seit wann?","Since when?","Weg? Seit wann?"]],"x":[["spät","late",""],["am Morgen","in the morning",""],["der Platz, die Plätze","square, place",""],["der Bus, die Busse","bus",""],["die U-Bahn, die U-Bahnen","underground",""]],"g":["Wohin? – nach, zu, in",["nach + cities and countries without an article, and nach Hause: nach Paris, nach Portugal.","zu + places and people (+ dative): zum Bahnhof (zu dem), zur Post (zu der), zu ihr.","in / an + accusative for going into or to the edge of a place: in die Altstadt, in den Schwarzwald, an die Dreisam.","Compare: Wo? → in der Stadt · Wohin? → in die Stadt.","Beispiele: Zuerst fahren sie zum Bahnhof. · Kommst du mit in den Schwarzwald?"]]},{"n":24,"t":"Wo ist Felix?","l":"A1","review":false,"p":[["Jonas","Keine Panik, Frau Schulz. Wir finden ihn!"],["Mia","Ich rufe Elif und Tom an. Sie können uns helfen."],["Zwanzig Minuten später sind alle da: Elif, Tom – und Bruno, der große, schwarze Hund. Auch Lena und Paul kommen. Paul hat eine Taschenlampe."],["Tom","Bruno hat eine super Nase. Er findet alles. Gebt mir etwas von Felix!"],["Frau Schulz bringt eine kleine Decke. Bruno riecht an der Decke. Dann läuft er los."],["Jonas","Okay. Wir teilen uns auf. Elif und Tom, ihr sucht im Park. Lena und Paul, ihr sucht in den Gärten hinter dem Haus. Mia und ich, wir fragen die Nachbarn."],["Mia und Jonas klingeln bei allen Nachbarn in der Lindenstraße. Mia zeigt das Foto auf dem Handy – das Foto vom Kühlschrank."],["Mia","Entschuldigung, das ist Felix. Kennen Sie ihn? Haben Sie ihn heute gesehen?"],["Mann","Den dicken Grauen? Ja, ich kenne ihn. Aber heute sehe ich ihn nicht."],["Frau","Felix? Ach, den kennt hier jeder! Morgens sitzt er oft vor der Bäckerei an der Ecke. Jeden Tag."],["Mia","Vor der Bäckerei? Jeden Morgen?"],["Mia denkt nach. Die Bäckerei. Die Brezeln. Nein … das ist verrückt."],["Die Bäckerei ist am Sonntagabend zu. Alles ist dunkel. Kein Felix."],["Um zehn Uhr kommen alle zurück. Niemand hat Felix gefunden. Bruno ist müde. Paul schläft auf Lenas Arm."],["Paul hat ein Plakat gemalt: ein dicker grauer Kater und ein großes Herz. Darunter steht: FELIX IST WEG! HABEN SIE IHN GESEHEN? BITTE RUFEN SIE UNS AN! Jonas hängt es an die Haustür."],["Frau Schulz sitzt in der Küche. Sie trinkt keinen Tee. Sie sieht nur das Fenster an."],["Frau Schulz","Er ist alt, wissen Sie. Vierzehn Jahre. Mein Mann und ich – wir finden ihn als Baby. In einem Karton, vor dem Haus. Mein Mann ist jetzt fünf Jahre tot. Felix ist meine Familie hier."],["Mia","Frau Schulz, wir finden ihn. Ganz sicher. Morgen früh suchen wir weiter."],["Mia umarmt sie. Frau Schulz ist klein und leicht, wie ein Vogel."],["Aber Mia kann nicht schlafen. Um zwei Uhr nachts liegt sie wach im Bett. Draußen regnet es. Der Wind ist laut."],["Dann hört sie es. Ganz leise. Weit weg."],["Miau."],["Mia ist sofort wach. Sie geht zum Fenster. Nichts. Nur Regen."],["Miau."],["Woher kommt das? Mia zieht ihre Jacke über den Schlafanzug und nimmt die Taschenlampe von Paul."]],"q":["Wer hilft bei der Suche?","Was weiß die Nachbarin über Felix?","Richtig oder falsch? Felix ist ein junger Kater.","Was schreibt Paul auf das Plakat?","Und du? Hast du ein Haustier? Wie heißt es? Wann siehst du es? (Ich sehe ihn / sie / es …)"],"a":["Jonas, Mia, Elif, Tom, Bruno, Lena und Paul. „Zwanzig Minuten später sind alle da: Elif, Tom – und Bruno … Auch Lena und Paul kommen.“","He often sits in front of the bakery on the corner every morning. „Morgens sitzt er oft vor der Bäckerei an der Ecke.“","Falsch. „Er ist alt, wissen Sie. Vierzehn Jahre.“","„FELIX IST WEG! HABEN SIE IHN GESEHEN? BITTE RUFEN SIE UNS AN!“","Example: Ich habe eine Katze. Sie heißt Luna. Ich sehe sie jeden Morgen."],"w":[["mich / dich / ihn / sie / es / uns / euch","me / you / him / her / it / us / you (pl.)","Wir finden ihn!"],["die Bäckerei, die Bäckereien","bakery","Er sitzt oft vor der Bäckerei."],["die Ecke, die Ecken","corner","die Bäckerei an der Ecke"],["die Nase, die Nasen","nose","Bruno hat eine super Nase."],["die Taschenlampe, die Taschenlampen","torch, flashlight","Paul hat eine Taschenlampe."],["die Decke, die Decken","blanket","Frau Schulz bringt eine kleine Decke."],["der Garten, die Gärten","garden","in den Gärten hinter dem Haus"],["das Plakat, die Plakate","poster","Paul hat ein Plakat gemalt."],["das Herz, die Herzen","heart","ein großes Herz"],["der Regen / regnen","rain / to rain","Draußen regnet es."],["der Wind","wind","Der Wind ist laut."],["der Vogel, die Vögel","bird","wie ein Vogel"],["tot","dead","Mein Mann ist jetzt fünf Jahre tot."],["verrückt","crazy","Das ist verrückt."],["niemand","nobody","Niemand hat Felix gefunden."]],"c":[["Keine Panik!","Don't panic!","Keine Panik, Frau Schulz."],["Haben Sie ihn gesehen?","Have you seen him?","Haben Sie ihn heute gesehen?"],["Ganz sicher.","Definitely.","Wir finden ihn. Ganz sicher."],["weit weg","far away","Ganz leise. Weit weg."]],"x":[["die S-Bahn, die S-Bahnen","suburban train",""],["das Taxi, die Taxis","taxi",""],["die Fahrkarte, die Fahrkarten","ticket",""],["der Fahrplan, die Fahrpläne","timetable",""],["die Abfahrt, die Abfahrten","departure",""]],"g":["Personalpronomen im Akkusativ",["When a person or thing is the object, the pronoun changes.","ich → mich · du → dich · er → ihn · sie → sie · es → es · wir → uns · ihr → euch · Sie → Sie.","Only ich, du, er, wir, ihr really change. sie, es, Sie stay the same.","Beispiele: Wir finden ihn! · Bitte rufen Sie uns an!"]]},{"n":25,"t":"Regen und ein nasser Kater","l":"A1","review":false,"p":[["Draußen ist es kalt und nass. Es regnet stark, und der Wind ist laut. Mia hört wieder: Miau. Das kommt von links, von der Ecke. Von der Bäckerei!"],["Mia läuft. Ihre Schuhe sind sofort nass, aber das ist egal. Hinter der Bäckerei ist ein kleiner Hof. Unten an der Wand ist ein kleines Fenster. Mia leuchtet mit der Taschenlampe hinein."],["Zwei grüne Augen. Ein grauer Kater – ganz weiß vom Mehl."],["Mia","Felix!"],["Felix","Miau!"],["Das Fenster ist zu, und die Tür ist auch zu. Mia kann nichts machen. Sie ruft Jonas an, denn das ist ein Notfall. Ein echter Notfall."],["Jonas","Hallo? … Mia? Es ist zwei Uhr!"],["Mia","Ich habe Felix gefunden! In der Bäckerei, im Keller!"],["Jonas","Was?! Ich komme!"],["Fünf Minuten später ist Jonas da, im Schlafanzug und mit Regenschirm."],["Jonas","Wir können die Polizei anrufen, oder wir warten. Bäcker fangen sehr früh an. Um halb vier, glaube ich."],["Mia","Dann warten wir."],["Sie stehen zusammen unter dem Regenschirm. Er ist klein, aber es ist warm. Und es ist schön, aber Mia sagt das nicht."],["Um halb vier kommt ein Mann mit einem Fahrrad. Der Bäcker. Er ist groß, und er hat einen weißen Bart."],["Bäcker","Was machen Sie hier? Um diese Zeit?"],["Mia","Unser Kater ist in Ihrem Keller!"],["Der Bäcker macht die Tür auf. Felix läuft sofort zu Mia."],["Bäcker","Ach, der Kater! Den kenne ich. Jeden Morgen kommt er hier rein, denn er liebt meine Wurst. Und dann nimmt er eine Tüte – mit einer Brezel oder einem Croissant – und weg ist er!"],["Mia und Jonas sehen sich an."],["Mia","Eine Tüte? Jeden Morgen?"],["Bäcker","Ja! Aber seit Dienstag mache ich die Tür zu, denn meine Chefin sagt: „Keine Katzen in der Bäckerei!“ Und am Sonntag ist er im Keller, und ich sehe ihn nicht. Tut mir leid, Kleiner."],["Jonas lacht so laut, das ganze Haus wacht auf."],["Jonas","Mia! Das ist dein Brezel-Mensch! Felix bringt dir das Frühstück!"],["Mia","Felix! Du bist es!"],["Felix","Miau."],["Um vier Uhr klingeln sie bei Frau Schulz. Sie macht die Tür auf und sieht Felix. Sie sagt nichts. Sie nimmt ihn nur in den Arm und weint. Aber jetzt weint sie vor Glück."],["Um sieben Uhr scheint die Sonne. Der Himmel ist blau. Felix schläft auf seiner Decke, satt und zufrieden."],["Und Mia? Mia liegt im Bett. Ihr Kopf ist heiß. Ihr Hals ist rot. Und dann:"],["„Hatschi!“"]],"q":["Wo findet Mia Felix?","Warum ruft Mia Jonas an?","Was macht Felix jeden Morgen in der Bäckerei?","Richtig oder falsch? Frau Schulz ist traurig, denn Felix ist ganz weiß.","Und du? Wie ist das Wetter heute? Was machst du gern bei Regen, und was machst du gern bei Sonne?"],"a":["Im Keller von der Bäckerei an der Ecke. „Ich habe Felix gefunden! In der Bäckerei, im Keller!“","Because it's an emergency. „Sie ruft Jonas an, denn das ist ein Notfall.“ (Remember story 4: „Für Notfälle“.)","He eats sausage and takes a bag with a pretzel or croissant – to Mia! „Und dann nimmt er eine Tüte … und weg ist er!“","Falsch. She cries, but „jetzt weint sie vor Glück.“","Example: Heute ist es kalt und es regnet. Bei Regen lese ich gern, aber bei Sonne fahre ich Rad."],"w":[["und / aber / oder / denn","and / but / or / because","Sie ruft Jonas an, denn das ist ein Notfall."],["das Wetter","weather","Wie ist das Wetter heute?"],["der Regenschirm, die Regenschirme","umbrella","im Schlafanzug und mit Regenschirm"],["der Himmel","sky","Der Himmel ist blau."],["scheinen","to shine","Um sieben Uhr scheint die Sonne."],["stark","strong; heavily","Es regnet stark."],["der Notfall, die Notfälle","emergency","Ein echter Notfall."],["die Polizei","police","Wir können die Polizei anrufen."],["der Bäcker, die Bäcker","baker","Der Bäcker macht die Tür auf."],["das Mehl","flour","ganz weiß vom Mehl"],["der Hof, die Höfe","courtyard","Hinter der Bäckerei ist ein kleiner Hof."],["weinen","to cry","Sie nimmt ihn in den Arm und weint."],["der Kopf, die Köpfe","head","Ihr Kopf ist heiß."],["der Hals, die Hälse","throat, neck","Ihr Hals ist rot."],["heiß","hot","Ihr Kopf ist heiß."]],"c":[["Es regnet.","It's raining.","Es regnet stark."],["Das ist egal.","It doesn't matter.","Ihre Schuhe sind nass, aber das ist egal."],["um diese Zeit","at this time","Was machen Sie hier? Um diese Zeit?"],["in den Arm nehmen","to hug","Sie nimmt ihn in den Arm."],["vor Glück","with happiness","Jetzt weint sie vor Glück."]],"x":[["die Ankunft, die Ankünfte","arrival",""],["das Hotel, die Hotels","hotel",""],["das Café, die Cafés","café",""],["gehen","to go, to walk",""]],"g":["und, aber, oder, denn",["These four words join two sentences. They stand in position 0, so the word order does not change.","und = and · aber = but · oder = or · denn = because.","After all four, the verb stays in position 2: …, denn das ist ein Notfall.","Tip: think of them as \"ADUSO\" words (aber, denn, und, sondern, oder) – you'll meet sondern later.","Beispiele: Die Schuhe sind nass, aber das ist egal. · Wir rufen die Polizei an, oder wir warten."]]},{"n":26,"t":"Mir geht es nicht gut","l":"A1","review":false,"p":[["Montag, zehn Uhr. Mia ist nicht im Kurs. Sie liegt im Bett. Sie hustet, und ihre Nase läuft. Sie schreibt Herrn Brandt eine kurze E-Mail: Ich bin krank. Ich kann heute nicht kommen. Entschuldigung! Mia Costa."],["Um zwölf klopft es an der Tür."],["Jonas","Mia? Ich bin's. Wie geht es dir?"],["Mia","Mir geht es nicht gut. Mir ist kalt, und dann ist mir heiß. Mir tut der Hals weh. Und der Kopf."],["Jonas","Hier, eine Hühnersuppe für dich. Das Rezept ist von meiner Oma. Sie hilft immer."],["Mia","Danke. Das ist lieb von dir."],["Jonas","Kann ich dir noch etwas bringen? Tee? Taschentücher?"],["Mia","Taschentücher, bitte. Viele!"],["Dann kommt Frau Schulz mit einer Kanne Tee. Felix kommt auch. Er springt sofort auf das Bett und legt sich auf Mias Füße."],["Frau Schulz","Frau Costa, ich bringe Ihnen einen Kamillentee mit Honig. Der hilft Ihnen."],["Mia","Danke, Frau Schulz. Wie geht es Ihnen? Und Felix?"],["Frau Schulz","Uns geht es sehr gut, danke. Felix ist wieder gesund. Und er hat jetzt keine Erlaubnis mehr für die Bäckerei! Ich gebe ihm morgens eine Wurst. Dann bleibt er zu Hause."],["Mia","Gefällt dir mein Bett, Felix?"],["Felix","Miau."],["Jonas","Das heißt: Ja, es gefällt ihm sehr."],["Am Nachmittag ruft Elif an. Mit Video."],["Elif","Mia! Du siehst schlecht aus. Hast du Fieber?"],["Mia","Ich weiß nicht. Ich habe kein Thermometer."],["Jonas","Moment, ich habe eins!"],["Er läuft nach oben und kommt mit einem Thermometer zurück. Neununddreißig Komma zwei."],["Elif","Neununddreißig zwei! Das ist hoch. Du musst zum Arzt!"],["Mia","Ich habe hier keinen Arzt."],["Frau Schulz","Mein Hausarzt ist Doktor Lehmann. Er ist sehr gut und sehr nett. Seine Praxis ist in der Goethestraße. Rufen Sie ihn an!"],["Mia ruft die Praxis an. Die Frau am Telefon ist freundlich: Morgen um acht Uhr dreißig. Bringen Sie Ihre Versicherungskarte mit. Gute Besserung!"],["Am Abend kommt eine E-Mail von Herrn Brandt: Liebe Frau Costa, gute Besserung! Wir vermissen Sie. Und: Trinken Sie viel Tee. Herzliche Grüße, R. Brandt."],["Um zehn Uhr ist alles still. Dann macht das Handy pling. Jonas: Schlaf gut. Brauchst du etwas? Klopf einfach an die Decke!"],["Mia lächelt. Sie nimmt einen Schuh und klopft einmal an die Decke. Von oben kommt sofort eine Antwort: klopf, klopf."],["Aber dann denkt Mia an morgen. Der Arzt. Mia hat Angst vor Ärzten. Große Angst. Seit sie ein Kind ist."]],"q":["Was tut Mia weh?","Was bringt Jonas? Was bringt Frau Schulz?","Richtig oder falsch? Mia hat achtunddreißig Grad Fieber.","Wann hat Mia einen Termin beim Arzt?","Und du? Wie geht es dir heute? Was machst du, wenn du krank bist?"],"a":["Der Hals und der Kopf. „Mir tut der Hals weh. Und der Kopf.“","Jonas: Hühnersuppe und Taschentücher. Frau Schulz: Kamillentee mit Honig. „Ich bringe Ihnen einen Kamillentee mit Honig.“","Falsch. The thermometer says „Neununddreißig Komma zwei.“","Morgen um acht Uhr dreißig. The practice says: „Morgen um acht Uhr dreißig.“","Example: Mir geht es gut, danke. Wenn ich krank bin, trinke ich Tee und schlafe viel."],"w":[["mir / dir / ihm / ihr / uns / euch / Ihnen","(to) me / you / him / her / us / you / you (formal)","Der hilft Ihnen."],["krank / gesund","ill / healthy","Ich bin krank. · Felix ist wieder gesund."],["husten","to cough","Sie hustet."],["das Fieber","fever","Hast du Fieber?"],["der Arzt, die Ärzte / die Ärztin","doctor","Du musst zum Arzt!"],["der Hausarzt, die Hausärzte","family doctor, GP","Mein Hausarzt ist Doktor Lehmann."],["die Praxis, die Praxen","(doctor's) practice","Seine Praxis ist in der Goethestraße."],["die Versicherungskarte, die Versicherungskarten","health insurance card","Bringen Sie Ihre Versicherungskarte mit."],["das Taschentuch, die Taschentücher","tissue, handkerchief","Taschentücher, bitte. Viele!"],["der Honig","honey","Kamillentee mit Honig."],["das Rezept, die Rezepte","recipe; prescription","Das Rezept ist von meiner Oma."],["bringen","to bring","Kann ich dir noch etwas bringen?"],["gefallen (es gefällt)","to please, to like","Gefällt dir mein Bett, Felix?"],["vermissen","to miss","Wir vermissen Sie."],["freundlich","friendly","Die Frau am Telefon ist freundlich."]],"c":[["Wie geht es dir / Ihnen?","How are you?","Wie geht es Ihnen?"],["Mir geht es (nicht) gut.","I'm (not) well.","Mir geht es nicht gut."],["Mir ist kalt / heiß.","I'm cold / hot.","Mir ist kalt, und dann ist mir heiß."],["Gute Besserung!","Get well soon!","Gute Besserung!"],["Das ist lieb von dir.","That's kind of you.","Danke. Das ist lieb von dir."]],"x":[["abfahren","to depart",""],["weit","far",""],["der Chef, die Chefs","boss (m)",""],["die Kollegin, die Kolleginnen","colleague (f)",""],["die Lehrerin, die Lehrerinnen","teacher (f)",""]],"g":["Personalpronomen im Dativ",["The dative answers \"to whom / for whom\": Ich bringe dir einen Tee.","ich → mir · du → dir · er → ihm · sie → ihr · es → ihm · wir → uns · ihr → euch · Sie → Ihnen.","Many fixed phrases use the dative: Wie geht es dir? · Mir ist kalt. · Mir tut der Kopf weh.","Some verbs always take the dative: helfen, gefallen, danken, gehören.","Beispiele: Der Tee hilft Ihnen. · Gefällt dir mein Bett?"]]},{"n":27,"t":"Beim Arzt","l":"A1","review":false,"p":[["Dienstag, acht Uhr fünfundzwanzig. Die Praxis von Doktor Lehmann ist im ersten Stock. An der Anmeldung sitzt eine junge Frau."],["Arzthelferin","Guten Morgen. Haben Sie einen Termin?"],["Mia","Ja, um acht Uhr dreißig. Costa ist mein Name."],["Arzthelferin","Ihre Versicherungskarte, bitte. Danke. Nehmen Sie bitte noch im Wartezimmer Platz."],["Im Wartezimmer sitzen fünf Leute. Ein Mann hustet laut. Ein Kind weint. Mia ist sehr nervös. Ihre Hände sind kalt."],["Arzthelferin","Frau Costa, bitte!"],["Doktor Lehmann ist alt, mit weißen Haaren und einer roten Fliege. Er lächelt."],["Dr. Lehmann","Guten Morgen, Frau Costa. Frau Schulz hat mich angerufen. Sie sind also die Heldin mit dem Kater! Was fehlt Ihnen denn?"],["Mia","Ich habe Fieber. Mir tut der Hals weh, und ich huste viel."],["Dr. Lehmann","Seit wann?"],["Mia","Seit Sonntag."],["Dr. Lehmann","Machen Sie bitte den Mund auf. Sagen Sie „Aaa“."],["Mia","Aaaa …"],["Dr. Lehmann","Hm. Der Hals ist sehr rot. Atmen Sie bitte tief ein. Und aus. Gut. Die Lunge ist okay. Sie haben eine starke Erkältung. Keine Grippe, aber fast."],["Mia","Darf ich morgen in den Kurs gehen?"],["Dr. Lehmann","Nein, das dürfen Sie nicht. Sie sollen fünf Tage im Bett bleiben. Sie sollen viel trinken – Wasser und Tee. Und Sie dürfen keinen Sport machen."],["Mia","Sport? Ich mache nie Sport. Nur Fußball mit einem Sechsjährigen."],["Dr. Lehmann lacht."],["Dr. Lehmann","Hier ist ein Rezept. Holen Sie die Tabletten in der Apotheke. Sie sollen dreimal am Tag eine Tablette nehmen, immer nach dem Essen."],["Die Apotheke ist gleich unten im Haus. Die Apothekerin erklärt alles noch einmal."],["Apothekerin","Eine Tablette morgens, eine mittags, eine abends. Nach dem Essen. Sie dürfen keinen Alkohol trinken."],["Mia","Kein Wein?"],["Apothekerin","Kein Wein. Tut mir leid. Das macht fünf Euro Zuzahlung."],["Zu Hause liegt Mia wieder im Bett. Aber um drei Uhr klingelt es. Vor der Tür steht niemand. Nur ein großer Blumenstrauß: gelbe und orange Blumen. Daran hängt eine Karte."],["Gute Besserung! Wir denken an Sie."],["Kein Name. Schon wieder kein Name!"],["Mia sieht Felix an. Felix sitzt auf der Treppe und putzt sich."],["Mia","Felix, warst du das?"],["Felix","Miau."],["Nein. Eine Katze kann keine Blumen kaufen. Ganz sicher nicht. Aber wer dann? „Wir denken an Sie.“ Wer ist wir?"]],"q":["Was fehlt Mia? Was sagt Dr. Lehmann?","Darf Mia morgen in den Kurs gehen?","Wie oft soll Mia eine Tablette nehmen?","Richtig oder falsch? Mia darf am Abend ein Glas Wein trinken.","Und du? Was sollst du machen, wenn du erkältet bist? Was darfst du nicht machen?"],"a":["Eine starke Erkältung, keine Grippe. „Sie haben eine starke Erkältung. Keine Grippe, aber fast.“","Nein. „Nein, das dürfen Sie nicht. Sie sollen fünf Tage im Bett bleiben.“","Dreimal am Tag, nach dem Essen. „Sie sollen dreimal am Tag eine Tablette nehmen, immer nach dem Essen.“","Falsch. The pharmacist says: „Sie dürfen keinen Alkohol trinken.“ – „Kein Wein. Tut mir leid.“","Example: Ich soll viel Tee trinken und schlafen. Ich darf keinen Sport machen."],"w":[["dürfen (darf, darfst)","may, to be allowed to","Darf ich morgen in den Kurs gehen?"],["sollen (soll, sollst)","should, to be supposed to","Sie sollen viel trinken."],["das Wartezimmer, die Wartezimmer","waiting room","Im Wartezimmer sitzen fünf Leute."],["der Stock, die Stockwerke","floor (of a building)","Die Praxis ist im ersten Stock."],["der Mund, die Münder","mouth","Machen Sie bitte den Mund auf."],["die Hand, die Hände","hand","Ihre Hände sind kalt."],["die Erkältung, die Erkältungen","cold (illness)","Sie haben eine starke Erkältung."],["die Grippe","flu","Keine Grippe, aber fast."],["die Tablette, die Tabletten","pill, tablet","Holen Sie die Tabletten in der Apotheke."],["die Apotheke, die Apotheken","pharmacy","Die Apotheke ist gleich unten im Haus."],["das Wasser","water","Wasser und Tee."],["der Sport","sport","Sie dürfen keinen Sport machen."],["der Alkohol","alcohol","Sie dürfen keinen Alkohol trinken."],["holen","to fetch, get","Holen Sie die Tabletten."],["die Leute (Plural)","people","Im Wartezimmer sitzen fünf Leute."]],"c":[["Was fehlt Ihnen?","What's wrong with you?","Was fehlt Ihnen denn?"],["Nehmen Sie Platz.","Take a seat.","Nehmen Sie bitte noch im Wartezimmer Platz."],["dreimal am Tag","three times a day","dreimal am Tag eine Tablette"],["nach dem Essen","after meals","immer nach dem Essen"],["tief einatmen","to breathe in deeply","Atmen Sie bitte tief ein."]],"x":[["der Student, die Studenten","student (m)",""],["die Studentin, die Studentinnen","student (f)",""],["die Schule, die Schulen","school",""],["das Heft, die Hefte","exercise book",""],["der Kuli, die Kulis","pen",""]],"g":["dürfen und sollen",["dürfen (permission): ich darf, du darfst, er darf, wir dürfen, ihr dürft, sie dürfen.","sollen (someone else says you should): ich soll, du sollst, er soll, wir sollen, ihr sollt, sie sollen.","nicht dürfen = must not (forbidden): Sie dürfen keinen Alkohol trinken.","Like all modal verbs: modal verb in position 2, infinitive at the end.","Beispiele: Darf ich morgen in den Kurs gehen? · Sie sollen fünf Tage im Bett bleiben."]]},{"n":28,"t":"Was hast du am Wochenende gemacht?","l":"A1","review":false,"p":[["Montag. Mia ist wieder gesund und wieder im Kurs. Elif umarmt sie. Tom gibt ihr ein Stück Schokolade."],["Herr Brandt","Willkommen zurück, Frau Costa! Heute lernen wir das Perfekt. Wir sprechen über die Vergangenheit. Also: Was haben Sie am Wochenende gemacht? Frau Yılmaz?"],["Elif","Am Samstag habe ich gelernt. Acht Stunden! Wir haben nächste Woche eine Prüfung in Anatomie. Aber am Abend habe ich mit Freundinnen getanzt."],["Herr Brandt","Sehr gut. Herr Nowak?"],["Tom","Am Samstag habe ich gearbeitet. Zwölf Stunden im Bus. Und am Sonntag habe ich mit Bruno im Wald gespielt."],["Herr Brandt","Und Sie, Frau Costa? Eine ganze Woche im Bett. Was haben Sie gemacht?"],["Mia","Ich habe viel gehustet. Ich habe Tee gekocht – viel Tee. Ich habe Musik gehört und deutsche Serien geschaut. Und ich habe Vokabeln gelernt!"],["Herr Brandt","Ausgezeichnet. Und … haben Sie die Blumen bekommen?"],["Mia sieht ihn an. Die Blumen! „Wir denken an Sie.“"],["Mia","Die Blumen sind von Ihnen?"],["Herr Brandt","Von uns. Die Gruppe hat Geld gesammelt. Frau Yılmaz hat die Adresse gesucht. Und ich habe die Blumen gekauft. Gelb und orange – Sie mögen den Herbst, glaube ich."],["Mia","Ich … danke! Danke an alle!"],["Mia ist ganz gerührt. Herr Brandt sieht schnell auf seine Papiere. Er ist streng, ja. Aber er hat ein großes Herz."],["In der Pause sitzen die drei in der Cafeteria. Tom ist still. Er hat seinen Kaffee nicht getrunken. Er spielt nur mit dem Löffel."],["Elif","Tom, was ist los? Du hast heute noch keinen Witz gemacht."],["Tom","Ich habe ein Problem. Ein großes Problem. Am Freitag hat mein Vermieter Bruno gehört. Er hat gebellt, nur einmal! Und gestern hat der Vermieter einen Brief geschickt."],["Tom zeigt den Brief. Mia liest laut: Herr Nowak, Hunde sind im Haus verboten. Der Hund muss bis zum 31. Oktober weg. Sonst müssen Sie die Wohnung kündigen."],["Mia","Bis zum einunddreißigsten Oktober? Das sind nur zwei Wochen!"],["Tom","Ich habe schon alles versucht. Ich habe Wohnungen gesucht – mit Hund. Ich habe zwanzig Vermieter angerufen. Niemand will einen Hund. Und Bruno ist meine Familie. Ich gebe ihn nicht weg. Nie."],["Elif und Mia sehen sich an. Was machen sie jetzt?"]],"q":["Was hat Elif am Samstag gemacht?","Wer hat die Blumen gekauft?","Richtig oder falsch? Bruno hat die ganze Nacht gebellt.","Was steht im Brief vom Vermieter?","Und du? Was hast du am Wochenende gemacht? (Ich habe … gemacht / gekauft / gelernt …)"],"a":["Sie hat gelernt und am Abend getanzt. „Am Samstag habe ich gelernt … am Abend habe ich mit Freundinnen getanzt.“","Herr Brandt (mit Geld von der Gruppe). „Die Gruppe hat Geld gesammelt … ich habe die Blumen gekauft.“","Falsch. „Er hat gebellt, nur einmal!“","The dog must be gone by 31 October, or Tom must give up the flat. „Der Hund muss bis zum 31. Oktober weg. Sonst müssen Sie die Wohnung kündigen.“","Example: Am Samstag habe ich eingekauft und gekocht. Am Sonntag habe ich Deutsch gelernt."],"w":[["das Wochenende, die Wochenenden","weekend","Was haben Sie am Wochenende gemacht?"],["die Vergangenheit","past","Wir sprechen über die Vergangenheit."],["die Prüfung, die Prüfungen","exam","Wir haben nächste Woche eine Prüfung."],["tanzen","to dance","Ich habe mit Freundinnen getanzt."],["der Wald, die Wälder","forest","Ich habe mit Bruno im Wald gespielt."],["die Serie, die Serien","(TV) series","Ich habe deutsche Serien geschaut."],["schauen","to watch, to look","deutsche Serien geschaut"],["das Geld","money","Die Gruppe hat Geld gesammelt."],["sammeln","to collect","Die Gruppe hat Geld gesammelt."],["der Löffel, die Löffel","spoon","Er spielt nur mit dem Löffel."],["bellen","to bark","Er hat gebellt, nur einmal!"],["gestern","yesterday","Gestern hat der Vermieter einen Brief geschickt."],["kündigen","to cancel, give notice","Sonst müssen Sie die Wohnung kündigen."],["versuchen","to try","Ich habe schon alles versucht."],["ausgezeichnet","excellent","Ausgezeichnet."]],"c":[["Willkommen zurück!","Welcome back!","Willkommen zurück, Frau Costa!"],["Danke an alle!","Thanks, everyone!","Danke an alle!"],["gerührt sein","to be moved (emotionally)","Mia ist ganz gerührt."],["sonst","otherwise","Sonst müssen Sie die Wohnung kündigen."]],"x":[["der Computer, die Computer","computer",""],["die E-Mail, die E-Mails","email",""],["das Amt, die Ämter","public office",""],["der Ausweis, die Ausweise","ID card",""],["die Unterschrift, die Unterschriften","signature",""]],"g":["das Perfekt mit haben (regelmäßige Verben)",["The Perfekt is the normal spoken past tense: haben (position 2) + participle (end).","Regular participle: ge- + stem + -t: machen → gemacht, kaufen → gekauft.","Stem ends in -t/-d: add -et: arbeiten → gearbeitet.","Verbs on -ieren and verbs with be-, ver- have no ge-: versucht, bekommen.","Beispiele: Ich habe Tee gekocht. · Was haben Sie am Wochenende gemacht?"]]},{"n":29,"t":"Kino und Pizza","l":"A1","review":false,"p":[["Freitagabend. Tom braucht eine Pause von seinem Problem. Also gehen Mia, Elif und Tom ins Kino. Sie sehen einen deutschen Film, eine Komödie. Danach treffen sie Jonas in der Pizzeria „Da Marco“."],["Jonas","Und? Wie war der Film?"],["Elif","Super! Ich habe so viel gelacht. Und am Ende habe ich ein bisschen geweint."],["Tom","Ich habe nicht viel verstanden. Die Leute im Film haben sehr schnell gesprochen. Wie Herr Brandt!"],["Mia","Ich habe fast alles verstanden. Na ja – die Hälfte."],["Der Kellner kommt."],["Kellner","Was darf ich Ihnen bringen?"],["Jonas","Wir nehmen zwei Pizzas Margherita, eine Pizza Funghi und eine Pizza Diavolo. Und eine große Flasche Wasser, bitte."],["Sie essen und trinken. Aber Tom isst nicht viel."],["Elif","Tom, hast du schon eine Wohnung gefunden?"],["Tom","Nein. Ich habe die ganze Woche Anzeigen gelesen. Ich habe zwanzig E-Mails geschrieben. Ich habe drei Wohnungen gesehen. Eine war zu teuer, eine war zu klein, und bei der dritten hat der Vermieter Bruno gesehen und gesagt: „Nein, danke.“"],["Jonas","Und wo schläft Bruno jetzt?"],["Tom","Bei mir. Er hat nichts gemerkt. Er hat heute Abend seinen Teller leer gegessen und ist zufrieden. Ich nicht. Ich habe drei Nächte nicht geschlafen."],["Mia denkt nach. Dann hat sie eine Idee. Eine verrückte Idee."],["Mia","Jonas – die Wohnung im Erdgeschoss, neben Frau Schulz. Wohnung eins. Wohnt da jemand?"],["Jonas","Nein. Seit dem Sommer ist sie leer. Frau Schulz hat noch keinen Mieter gefunden. Sie ist sehr … wählerisch."],["Mia","Und ein Garten ist auch da, oder?"],["Jonas","Ja, ein kleiner Garten hinter dem Haus. Aber Mia – Frau Schulz und ein Hund? Und Felix? Felix hasst Hunde!"],["Tom","Bitte! Ich muss es versuchen."],["Mia nimmt das Handy und ruft Frau Schulz an. Frau Schulz kann jetzt gut telefonieren – Mia hat es ihr gezeigt."],["Frau Schulz","Schulz?"],["Mia","Guten Abend, Frau Schulz! Hier ist Mia. Entschuldigung, es ist spät. Ich habe eine Frage. Die Wohnung eins ist doch frei. Ein Freund von mir sucht eine Wohnung. Er ist sehr nett, er ist Busfahrer, er ist ruhig … und er hat einen Hund."],["Stille. Lange Stille."],["Frau Schulz","Einen Hund. In meinem Haus."],["Mia","Er ist ein sehr lieber Hund!"],["Frau Schulz","Und Felix? … Ich muss nachdenken, Frau Costa. Morgen bekommen Sie meine Antwort. Gute Nacht."],["Klick."],["Tom sieht Mia an. Elif sieht Mia an. Jonas sieht Mia an."],["Mia","Morgen. Morgen wissen wir es."]],"q":["Was haben die Freunde am Freitagabend gemacht?","Was hat Tom die ganze Woche gemacht? (Nenne zwei Dinge.)","Richtig oder falsch? Wohnung eins ist frei.","Was ist Jonas' Sorge?","Und du? Welchen Film hast du zuletzt gesehen? Was hast du gestern gegessen?"],"a":["Sie sind ins Kino gegangen und haben in der Pizzeria gegessen. „Also gehen Mia, Elif und Tom ins Kino … Danach treffen sie Jonas in der Pizzeria.“","E.g. Anzeigen gelesen, zwanzig E-Mails geschrieben, drei Wohnungen gesehen. „Ich habe die ganze Woche Anzeigen gelesen. Ich habe zwanzig E-Mails geschrieben.“","Richtig. Jonas: „Seit dem Sommer ist sie leer.“","That Frau Schulz and Felix won't accept a dog. „Felix hasst Hunde!“","Example: Ich habe zuletzt eine Komödie gesehen. Gestern habe ich Pizza gegessen."],"w":[["das Kino, die Kinos","cinema","Sie gehen ins Kino."],["der Film, die Filme","film","Wie war der Film?"],["lachen","to laugh","Ich habe so viel gelacht."],["der Kellner, die Kellner","waiter","Der Kellner kommt."],["die Flasche, die Flaschen","bottle","eine große Flasche Wasser"],["der Teller, die Teller","plate","Er hat seinen Teller leer gegessen."],["die Anzeige, die Anzeigen","ad, listing","Ich habe Anzeigen gelesen."],["teuer","expensive","Eine war zu teuer."],["das Erdgeschoss","ground floor","die Wohnung im Erdgeschoss"],["der Sommer","summer","Seit dem Sommer ist sie leer."],["der Mieter, die Mieter","tenant","Sie hat noch keinen Mieter gefunden."],["hassen","to hate","Felix hasst Hunde!"],["ruhig","quiet, calm","Er ist ruhig."],["die Hälfte, die Hälften","half","Na ja – die Hälfte."],["die Nacht, die Nächte","night","Ich habe drei Nächte nicht geschlafen."]],"c":[["Wie war …?","How was …?","Wie war der Film?"],["Was darf ich Ihnen bringen?","What can I get you?","Was darf ich Ihnen bringen?"],["Na ja …","Well …","Na ja – die Hälfte."],["zu teuer / zu klein","too expensive / too small","Eine war zu teuer, eine war zu klein."]],"x":[["einen Termin machen","to make an appointment",""],["ein Formular ausfüllen","to fill in a form",""],["das Ohr, die Ohren","ear",""],["der Zahn, die Zähne","tooth",""],["der Arm, die Arme","arm",""]],"g":["das Perfekt mit haben (unregelmäßige Verben)",["Irregular verbs end in -en in the participle, and the stem often changes.","sehen → gesehen · essen → gegessen · lesen → gelesen · schreiben → geschrieben · finden → gefunden · sprechen → gesprochen.","No ge- with ver-: verstehen → verstanden.","Learn these participles by heart, together with the verb.","Beispiele: Ich habe zwanzig E-Mails geschrieben. · Hast du schon eine Wohnung gefunden?"]]},{"n":30,"t":"Wiederholung: Eine E-Mail an Rui","l":"A1","review":true,"p":[["Von","Mia Costa An: Rui Costa Betreff: Viele Neuigkeiten aus Freiburg!"],["Lieber Rui,"],["wie geht es dir? Hast du mein Paket bekommen? Gefällt dir das T-Shirt?"],["Hier ist viel passiert. Zuerst: Ich war krank. Eine starke Erkältung, mit Fieber. Ich habe eine Woche im Bett gelegen. Der Arzt, Doktor Lehmann, ist sehr nett. Ich soll viel trinken, und ich darf keinen Wein trinken. Keinen Wein, Rui! Das war schwer."],["Jonas hat mir eine Hühnersuppe gebracht. Frau Schulz hat mir Tee gebracht. Und mein Kurs hat mir Blumen geschickt! Gelb und orange. Herr Brandt hat sie gekauft. Er ist streng, aber er hat ein großes Herz."],["Dann Tom. Du kennst Tom nicht, aber er ist mein Freund aus dem Kurs. Er hat einen Hund, Bruno. Aber sein Vermieter hat Bruno gehört und hat geschrieben: Der Hund muss weg! Tom hat eine Woche lang eine Wohnung gesucht. Nichts."],["Und jetzt kommt das Beste. Die Wohnung eins in unserem Haus ist frei. Ich habe Frau Schulz angerufen. Sie hat lange nachgedacht. Am Samstag hat sie gesagt: „Ja. Aber nur für einen Monat, zur Probe. Und der Hund darf nicht in den Garten von Felix!“"],["Am Sonntag hat Tom seine Kartons gebracht. Jonas und ich haben geholfen. Bruno ist sofort in die neue Wohnung gelaufen und hat alles gesucht – das Bett, den Kühlschrank, die Wurst. Und Felix? Felix sitzt auf dem Schrank im Flur und sieht Bruno an. Er ist gar nicht froh. Aber Bruno hat Angst vor Felix! Ein großer, schwarzer Hund – und er hat Angst vor einer Katze. Ich habe so gelacht."],["Tom ist sehr glücklich. Er hat Frau Schulz einen großen Kuchen gekauft. Sie hat gelächelt. Ich glaube, sie mag ihn."],["Und Jonas? Ja, Rui, ich weiß, du fragst immer nach Jonas. Jonas hat gestern geschrieben: Samstag, acht Uhr dreißig, Bahnhof. Wir fahren zum Titisee. Nur wir zwei."],["Nur wir zwei. Was heißt das? Ist das ein Date? Ich weiß es nicht!"],["Schreib mir bald. Und sag Mama nichts!"],["Viele Grüße und bis bald, deine Mia"],["PS","Sag Mama wirklich NICHTS!"]],"q":["Imperativ (Sie): Sie gehen geradeaus. → ___!","Imperativ (du): Du wartest hier. → ___!","Wo? oder Wohin? Ergänze: Mia sitzt ___ Park (in). Mia fährt ___ Bahnhof (zu).","nach oder zu? Tom fährt ___ Polen. Mia geht ___ Arzt.","Akkusativ-Pronomen: Wo ist Felix? Wir finden ___!","Dativ-Pronomen: Frau Schulz bringt ___ (Mia) einen Tee. Wie geht es ___ (du)?","und, aber, oder, denn: Mia ruft Jonas an, ___ das ist ein Notfall.","dürfen oder sollen? Sie ___ keinen Alkohol trinken. Sie ___ viel Wasser trinken.","Perfekt: Ich ___ Tee ___ (kochen).","Perfekt: Tom ___ zwanzig E-Mails ___ (schreiben)."],"a":["Gehen Sie geradeaus! Sie-form: verb first, then Sie.","Warte hier! du-form: stem + -e, no du.","im · zum. Wo? → im Park (dative); Wohin? → zum Bahnhof.","nach · zum. nach + countries; zu + places and people (zum Arzt).","ihn. Felix is masculine; object → ihn.","ihr · dir. Dative: sie → ihr, du → dir.","denn. denn = because; the word order doesn't change.","darf · soll. nicht dürfen / kein … dürfen = forbidden; sollen = advice from the doctor.","habe … gekocht. Regular verb: ge- + stem + -t.","hat … geschrieben. Irregular verb: ge- + changed stem + -en."],"w":[],"c":[],"x":[],"g":["Wiederholung",["Imperative: Gehen Sie! · Geh! · Geht! (story 21).","Wo? + dative (im Park) · Wohin? + nach / zu / in (stories 22–23).","Pronouns: accusative mich, dich, ihn (story 24) · dative mir, dir, ihm (story 26).","und, aber, oder, denn (story 25) · dürfen, sollen (story 27).","Perfekt with haben: gekocht (regular) · geschrieben (irregular) (stories 28–29).","Beispiele: Jonas hat mir eine Suppe gebracht. · Ich darf keinen Wein trinken."]],"exam":{"task":"Schreiben Sie eine E-Mail an eine Freundin über Ihr Wochenende.","points":["Was haben Sie am Samstag gemacht?","Was haben Sie am Sonntag gegessen?","Was machen Sie nächstes Wochenende?"],"words":35,"en":"Email about your weekend: Saturday, Sunday food, next weekend."}},{"n":31,"t":"Ausflug zum Titisee","l":"A1","review":false,"p":[["Montag, Pause. Elif hat zwei Kaffee geholt. Sie stellt einen vor Mia."],["Elif","So. Jetzt erzähl! Alles! Wie war der Ausflug?"],["Mia","Also … Ich bin um sieben Uhr aufgestanden. Um halb neun bin ich zum Bahnhof gegangen. Jonas war schon da, mit zwei Brezeln."],["Elif","Natürlich."],["Mia","Wir sind mit dem Zug in den Schwarzwald gefahren. Die Fahrt ist wunderschön: Berge, Wälder, kleine Dörfer. Um zehn sind wir am Titisee angekommen. Der See ist so blau!"],["Tom","Und dann?"],["Mia","Dann sind wir um den See gewandert. Zwei Stunden. Mittags sind wir in ein kleines Restaurant gegangen. Ich habe Schwarzwälder Kirschtorte gegessen. Die ist sehr, sehr süß."],["Elif","Und dann? Mia! Was ist passiert?"],["Mia","Am Nachmittag sind wir Tretboot gefahren. Auf dem See war viel Wind. Und plötzlich – mein Hut! Er ist ins Wasser geflogen. Jonas will den Hut holen. Er beugt sich über das Boot und … platsch! Er ist ins Wasser gefallen!"],["Tom","Ha! Im Oktober! Das Wasser ist so kalt!"],["Mia","Zwölf Grad! Er ist schnell wieder ins Boot geklettert. Mit dem Hut! Ganz nass, aber mit dem Hut."],["Elif","Wie romantisch!"],["Mia","Romantisch? Er hat gezittert! Wir sind schnell in ein Geschäft gelaufen. Er hat einen Pullover gekauft – mit einem Hirsch darauf. Sehr hässlich. Aber warm."],["Elif","Und auf der Rückfahrt?"],["Mia wird ein bisschen rot."],["Mia","Im Zug ist es dunkel geworden. Ich bin müde gewesen. Ich bin fast eingeschlafen. Und dann … hat Jonas meine Hand genommen."],["Elif","Aaaah!"],["Alle im Café sehen zu Elif."],["Tom","Und dann? Habt ihr euch geküsst?"],["Mia","Nein. Dann hat sein Handy geklingelt. Seine Mutter. Seine Oma in Hamburg ist gefallen. Sie ist im Krankenhaus."],["Elif","Oh nein!"],["Mia","Es ist nicht so schlimm, sagt der Arzt. Aber sie ist alt. Jonas ist heute Morgen um sechs nach Hamburg gefahren. Für eine Woche."],["Mia sieht in ihren Kaffee. Eine Woche ohne Jonas. Keine Schritte auf der Treppe. Kein Klopfen an der Decke."],["Am Abend sitzt sie allein auf ihrem Sofa. Die Wohnung ist sehr still. Zum ersten Mal denkt sie an Porto. An ihr altes Zimmer. An Mama. An das Meer."],["Und dann klopft es an der Tür. Unten. Frau Schulz."]],"q":["Wie sind Mia und Jonas zum Titisee gefahren?","Was hat Mia im Restaurant gegessen?","Warum ist Jonas ins Wasser gefallen?","Richtig oder falsch? Jonas ist nach Hamburg gefahren, denn seine Mutter ist krank.","Und du? Wohin bist du zuletzt gefahren? Was hast du dort gemacht?"],"a":["Mit dem Zug. „Wir sind mit dem Zug in den Schwarzwald gefahren.“","Schwarzwälder Kirschtorte. „Ich habe Schwarzwälder Kirschtorte gegessen.“","He wanted to get Mia's hat out of the water. „Jonas will den Hut holen. Er beugt sich über das Boot und … platsch!“","Falsch. His grandmother fell and is in hospital: „Seine Oma in Hamburg ist gefallen.“","Example: Ich bin nach Berlin gefahren. Ich bin viel gelaufen und habe Museen gesehen."],"w":[["der Ausflug, die Ausflüge","trip, outing","Wie war der Ausflug?"],["ankommen (ist angekommen)","to arrive","Um zehn sind wir angekommen."],["wandern (ist gewandert)","to hike","Wir sind um den See gewandert."],["fallen (ist gefallen)","to fall","Er ist ins Wasser gefallen!"],["passieren (ist passiert)","to happen","Was ist passiert?"],["werden (ist geworden)","to become, get","Im Zug ist es dunkel geworden."],["das Dorf, die Dörfer","village","kleine Dörfer"],["das Restaurant, die Restaurants","restaurant","in ein kleines Restaurant"],["süß","sweet","Die ist sehr, sehr süß."],["der Hut, die Hüte","hat","Mein Hut!"],["das Boot, die Boote","boat","Er ist wieder ins Boot geklettert."],["der Pullover, die Pullover","jumper, sweater","Er hat einen Pullover gekauft."],["hässlich","ugly","Sehr hässlich. Aber warm."],["das Krankenhaus, die Krankenhäuser","hospital","Sie ist im Krankenhaus."],["schlimm","bad, serious","Es ist nicht so schlimm."]],"c":[["Jetzt erzähl!","Tell me now!","So. Jetzt erzähl! Alles!"],["Tretboot fahren","to go pedal-boating","Wir sind Tretboot gefahren."],["die Rückfahrt","the journey back","Und auf der Rückfahrt?"],["Wie romantisch!","How romantic!","Wie romantisch!"]],"x":[["der Finger, die Finger","finger",""],["der Bauch, die Bäuche","belly",""],["die Ärztin, die Ärztinnen","doctor (f)",""],["das Medikament, die Medikamente","medicine",""],["der Schnupfen","cold (runny nose)",""]],"g":["das Perfekt mit sein",["Verbs of movement (from A to B) and change of state use sein in the Perfekt.","Movement: gehen → ist gegangen · fahren → ist gefahren · laufen → ist gelaufen · kommen → ist gekommen.","Change: einschlafen → ist eingeschlafen · werden → ist geworden. Also: sein → ist gewesen, bleiben → ist geblieben, passieren → ist passiert.","Everything else uses haben.","Beispiele: Wir sind mit dem Zug gefahren. · Er ist ins Wasser gefallen!"]]},{"n":32,"t":"Früher in Porto","l":"A1","review":false,"p":[["Vor der Tür steht Frau Schulz. Sie hat einen Teller in der Hand. Darauf liegt ein Apfelstrudel, noch warm."],["Frau Schulz","Jonas ist weg, und Sie sind allein. Das ist nicht gut. Darf ich reinkommen?"],["Mia","Natürlich! Bitte!"],["Sie sitzen in der Küche. Frau Schulz sieht Mias Gesicht."],["Frau Schulz","Sie haben Heimweh, oder?"],["Mia","Ein bisschen. Heute denke ich viel an Porto."],["Frau Schulz","Erzählen Sie. Wie war es früher, in Porto?"],["Mia","Früher war alles einfach. Wir hatten eine kleine Wohnung, direkt am Meer. Mein Opa hatte ein Café. Jeden Sonntag war ich dort. Ich hatte immer eine heiße Schokolade und ein Pastel de Nata. Mein Opa war sehr lustig. Er hatte immer einen Witz für mich."],["Frau Schulz","Und Ihr Vater?"],["Mia","Mein Vater war oft weg. Er war Seemann. Dann war er plötzlich ganz weg – in Brasilien. Ich war zehn. Das war eine schwere Zeit. Aber wir hatten Opa. Und das Meer."],["Frau Schulz nickt. Dann nimmt sie ein kleines, altes Fotoalbum aus ihrer Tasche."],["Frau Schulz","Ich zeige Ihnen etwas. Das bin ich. Neunzehnhundertsiebzig."],["Auf dem Foto ist eine junge Frau mit kurzen Haaren und einem kurzen Rock. Sie lacht."],["Mia","Das sind Sie? Sie waren sehr schön!"],["Frau Schulz","Und sehr frech! Ich war Musiklehrerin. Ich hatte dreißig Schüler. Und das hier ist mein Mann, Heinrich."],["Mia","Was war er von Beruf?"],["Frau Schulz","Bäcker. Er hatte eine Bäckerei – an der Ecke."],["Mia","An der Ecke? Die Bäckerei von Felix?!"],["Frau Schulz","Genau die. Heute gehört sie einer anderen Familie. Aber Felix weiß es, glaube ich. Er hatte immer eine gute Nase für Brezeln."],["Mia lacht. Zum ersten Mal heute."],["Frau Schulz","Wissen Sie, ich hatte auch Heimweh. Ich war aus Berlin. Freiburg war am Anfang so klein und so fremd. Ich war ein Jahr lang traurig. Dann hatte ich Freunde. Dann hatte ich Heinrich. Und dann war Freiburg mein Zuhause."],["Mia","Wie lange hat das gedauert?"],["Frau Schulz","Ein Jahr. Bei Ihnen geht es schneller. Sie haben ja schon Freunde. Und einen Nachbarn mit einem hässlichen Hirsch-Pullover."],["Mia wird rot. Frau Schulz lächelt."],["Um zehn Uhr geht Frau Schulz nach unten. Mia isst noch ein Stück Apfelstrudel. Da macht das Handy pling. Elif:"],["Mia!!! Ich habe am 4. November Geburtstag! Party am Samstag bei mir. Du kommst, oder? 🎉 Und wann hast DU eigentlich Geburtstag? Ich weiß das gar nicht!"]],"q":["Was hat Frau Schulz mitgebracht?","Was hatte Mias Opa?","Was war Frau Schulz von Beruf? Und ihr Mann?","Richtig oder falsch? Frau Schulz hatte nie Heimweh.","Und du? Wie war es früher, als Kind? Was hattest du? (Früher war ich … / hatte ich …)"],"a":["Einen Apfelstrudel. „Darauf liegt ein Apfelstrudel, noch warm.“","Ein Café. „Mein Opa hatte ein Café.“","Sie war Musiklehrerin, ihr Mann war Bäcker. „Ich war Musiklehrerin.“ – „Bäcker. Er hatte eine Bäckerei – an der Ecke.“","Falsch. „Wissen Sie, ich hatte auch Heimweh. … Ich war ein Jahr lang traurig.“","Example: Früher war ich sehr schüchtern. Ich hatte eine Katze und viele Bücher."],"w":[["war (sein, Präteritum)","was","Früher war alles einfach."],["hatte (haben, Präteritum)","had","Mein Opa hatte ein Café."],["früher","in the past, formerly","Wie war es früher, in Porto?"],["das Heimweh","homesickness","Sie haben Heimweh, oder?"],["einfach","simple, easy","Früher war alles einfach."],["die Schokolade","chocolate","eine heiße Schokolade"],["der Seemann, die Seeleute","sailor","Er war Seemann."],["der Beruf, die Berufe","job, profession","Was war er von Beruf?"],["der Rock, die Röcke","skirt","einem kurzen Rock"],["kurz / lang","short / long","mit kurzen Haaren"],["das Haar, die Haare","hair","mit kurzen Haaren"],["fremd","foreign, strange","Freiburg war so fremd."],["der Anfang, die Anfänge","beginning","am Anfang"],["dauern","to last, take (time)","Wie lange hat das gedauert?"],["das Zuhause","home","Dann war Freiburg mein Zuhause."]],"c":[["Was sind Sie von Beruf?","What's your job?","Was war er von Beruf?"],["Heimweh haben","to be homesick","Ich hatte auch Heimweh."],["ein Jahr lang","for a year","Ich war ein Jahr lang traurig."],["Genau!","Exactly!","Genau die."]],"x":[["die Schmerzen (plural only)","pain",""],["Ich habe Kopfschmerzen.","I have a headache.",""],["wehtun","to hurt",""],["die Versichertenkarte, die Versichertenkarten","health insurance card",""],["die Freizeit","free time",""]],"g":["Präteritum von sein und haben",["For sein and haben, Germans use the Präteritum (simple past) more than the Perfekt.","sein: ich war, du warst, er war, wir waren, ihr wart, sie waren.","haben: ich hatte, du hattest, er hatte, wir hatten, ihr hattet, sie hatten.","ich and er/sie/es have the same form: ich war, er war.","Beispiele: Ich war Musiklehrerin. · Wir hatten eine kleine Wohnung am Meer."]]},{"n":33,"t":"Wann hast du Geburtstag?","l":"A1","review":false,"p":[["Herr Brandt","Guten Morgen! Der Wievielte ist heute?"],["Tom","Heute ist … Montag?"],["Herr Brandt","Nein, Herr Nowak. Nicht der Tag. Das Datum."],["Elif","Heute ist der dreißigste Oktober!"],["Herr Brandt","Richtig. Und Frau Yılmaz hat bald Geburtstag, habe ich gehört. Wann?"],["Elif","Am vierten November! Am Samstag. Sie sind auch eingeladen, Herr Brandt!"],["Herr Brandt","Danke, aber ich bin zu alt für Partys. Also, wir lernen heute die Daten. Wann haben Sie Geburtstag? Herr Nowak?"],["Tom","Am siebzehnten Februar. Im Winter. Es ist immer kalt, und niemand hat Zeit."],["Herr Brandt","Frau Costa?"],["Mia","Am einundzwanzigsten März. Im Frühling."],["Elif","Der erste Frühlingstag! Wie schön!"],["Tom","Und Sie, Herr Brandt?"],["Herr Brandt","Am ersten April."],["Tom","Ha! Das ist ein Witz, oder?"],["Herr Brandt","Nein. Das ist kein Witz. Am ersten April geboren und nie lustig. Das sagen alle."],["Die ganze Klasse lacht. Herr Brandt auch – ein bisschen."],["An der Tafel stehen jetzt alle zwölf Monate: Januar, Februar, März, April, Mai, Juni, Juli, August, September, Oktober, November, Dezember. Und die vier Jahreszeiten: der Frühling, der Sommer, der Herbst, der Winter."],["Herr Brandt","Wichtig: Heute ist der dritte November – aber: Ich habe am dritten November Geburtstag. Mit „am“ kommt ein -n."],["In der Pause schreibt Mia Jonas eine Nachricht nach Hamburg."],["Hallo! Wie geht es deiner Oma? Und eine Frage: Wann hast du eigentlich Geburtstag?"],["Nach fünf Minuten kommt die Antwort."],["Hallo Mia! Oma geht es besser. Sie lacht schon wieder und isst viel Kuchen. Sie hat nach dir gefragt – ich habe ihr vom Bächle erzählt! 😄 Mein Geburtstag? Am fünfzehnten November. Warum?"],["Am fünfzehnten November! Das ist in zwei Wochen! Mia schreibt: Nur so. Dann lächelt sie."],["Nach dem Kurs nimmt Elif Mias Arm."],["Elif","Mia, eine Bitte. Für meine Party … Kannst du einen Kuchen backen? Etwas aus Portugal? Das wäre so toll!"],["Mia","Einen Kuchen? Klar! Kein Problem!"],["Elif umarmt sie und läuft weg. Mia bleibt stehen."],["Kein Problem? Doch. Ein großes Problem. Mia hat noch nie einen Kuchen gebacken. Nie. Nicht einmal in Porto. In Porto hatte sie ja Opa – und sein Café."]],"q":["Der Wievielte ist heute?","Wann hat Tom Geburtstag? Und Mia?","Richtig oder falsch? Herr Brandt hat am ersten April Geburtstag, und das ist ein Witz.","Wann hat Jonas Geburtstag?","Und du? Wann hast du Geburtstag? In welcher Jahreszeit? Der Wievielte ist heute?"],"a":["Der dreißigste Oktober. „Heute ist der dreißigste Oktober!“","Tom: am 17. Februar. Mia: am 21. März. „Am siebzehnten Februar.“ – „Am einundzwanzigsten März.“","Falsch. It's his real birthday: „Nein. Das ist kein Witz.“","Am fünfzehnten November. Jonas writes: „Am fünfzehnten November.“","Example: Ich habe am achten Juli Geburtstag, im Sommer. Heute ist der fünfundzwanzigste Oktober."],"w":[["das Datum, die Daten","date","Nicht der Tag. Das Datum."],["erste, zweite, dritte, vierte …","first, second, third, fourth …","Am ersten April."],["Januar … Dezember","January … December","Am siebzehnten Februar."],["der Monat, die Monate","month","alle zwölf Monate"],["die Jahreszeit, die Jahreszeiten","season","die vier Jahreszeiten"],["der Frühling / der Winter","spring / winter","Im Frühling. · Im Winter."],["das Jahr, die Jahre","year","(story 32) ein Jahr lang"],["eingeladen","invited","Sie sind auch eingeladen."],["die Party, die Partys","party","Ich bin zu alt für Partys."],["geboren","born","Am ersten April geboren."],["backen","to bake","Kannst du einen Kuchen backen?"],["die Bitte, die Bitten","request","Mia, eine Bitte."],["bald","soon","Frau Yılmaz hat bald Geburtstag."],["wichtig","important","Wichtig: Heute ist der dritte November."],["fragen nach","to ask about","Sie hat nach dir gefragt."]],"c":[["Der Wievielte ist heute?","What's the date today?","Guten Morgen! Der Wievielte ist heute?"],["Wann hast du Geburtstag?","When is your birthday?","Wann hast du eigentlich Geburtstag?"],["am ersten / am vierten …","on the first / fourth …","Am vierten November!"],["noch nie","never (yet)","Mia hat noch nie einen Kuchen gebacken."]],"x":[["das Hobby, die Hobbys","hobby",""],["das Schwimmbad, die Schwimmbäder","swimming pool",""],["das Spiel, die Spiele","game",""],["fotografieren","to take photos",""],["treffen","to meet",""]],"g":["Datum und Ordinalzahlen",["Ordinal numbers 1–19: number + -te: zweite, vierte, siebzehnte. Irregular: erste, dritte, siebte.","From 20: number + -ste: zwanzigste, einundzwanzigste, dreißigste.","Heute ist der dritte November. · But with am (on): am dritten November.","Months and seasons: im März, im Frühling.","Beispiele: Heute ist der dreißigste Oktober. · Ich habe am einundzwanzigsten März Geburtstag."]]},{"n":34,"t":"Was isst du am liebsten?","l":"A1","review":false,"p":[["Donnerstagabend. Elif und Tom sitzen in Mias Küche. Sie planen das Essen für die Party."],["Elif","Also, ich mache Börek. Und Baklava. Ich mag Baklava sehr, aber am liebsten esse ich Mantı – kleine Nudeln mit Fleisch. Die macht meine Mutter am besten."],["Tom","Ich bringe Pierogi. Ich mag Pierogi mit Kartoffeln und Käse. Die esse ich lieber als die mit Fleisch. Und am liebsten esse ich die Pierogi von meiner Oma."],["Elif","Und Mia? Was isst du am liebsten?"],["Mia","Pastéis de Nata. Kleine Törtchen mit Vanillecreme. Die mag ich am liebsten. Ich backe sie für die Party!"],["Tom","Kannst du das?"],["Mia","Äh … Ich habe einen Plan."],["Der Plan heißt Jonas. Um acht Uhr ruft Mia ihn in Hamburg an. Mit Video. Jonas sitzt in einer Küche, und neben ihm sitzt eine kleine alte Frau mit weißen Locken."],["Jonas","Hallo Mia! Das ist meine Oma Gerda. Oma, das ist Mia."],["Oma Gerda","Ah, die Frau vom Bächle! Hallo, Mia!"],["Mia wird rot. Elif und Tom lachen im Hintergrund."],["Jonas","Also, Pastéis de Nata. Hast du Blätterteig?"],["Mia","Ja. Und Milch, Eier, Zucker, Mehl und Vanille."],["Jonas","Gut. Magst du Zimt?"],["Mia","Ich mag Zimt, aber Vanille mag ich lieber."],["Jonas","Dann nur ein bisschen Zimt. Erst machst du die Creme. Rühren, rühren, rühren!"],["Mia rührt. Elif filmt alles. Tom isst Schokolade. Nach einer Stunde sind die ersten zwölf Törtchen im Ofen. Zweihundertfünfzig Grad."],["Zwanzig Minuten später riecht es komisch. Sehr komisch."],["Tom","Mia … riechst du das?"],["Mia macht den Ofen auf. Rauch! Die Törtchen sind schwarz. Ganz schwarz."],["Oma Gerda","Mehr Butter, Kind! Und nicht so heiß! Zweihundert Grad, nicht zweihundertfünfzig!"],["Die zweite Runde ist besser. Viel besser. Goldbraun und süß. Bruno, unten bei Tom, hat die schwarzen Törtchen gegessen. Er mag alles."],["Elif","Mia, die sind perfekt! Oh, und noch etwas: Mein Freund Lukas aus der Uni kommt auch zur Party. Er ist Single, er ist sehr nett, und ich habe ihm ein Foto von dir gezeigt. Er findet dich toll!"],["Mia","Elif!"],["Mia sieht auf das Handy. Jonas ist noch da, im Video. Er sagt nichts. Er lächelt nicht mehr."],["Jonas","Ich … ich muss Schluss machen. Oma ist müde. Tschüss, Mia."],["Klick. Der Bildschirm ist schwarz. Wie die ersten Törtchen."]],"q":["Was isst Elif am liebsten?","Welche Pierogi mag Tom lieber?","Warum sind die ersten Törtchen schwarz?","Richtig oder falsch? Jonas freut sich über Lukas.","Und du? Was isst du gern? Was isst du lieber? Was isst du am liebsten?"],"a":["Mantı. „Am liebsten esse ich Mantı – kleine Nudeln mit Fleisch.“","Mit Kartoffeln und Käse. „Die esse ich lieber als die mit Fleisch.“","The oven was too hot. Oma Gerda: „Zweihundert Grad, nicht zweihundertfünfzig!“","Falsch. „Er sagt nichts. Er lächelt nicht mehr.“ Then he ends the call quickly.","Example: Ich esse gern Pasta. Ich esse lieber Pizza. Am liebsten esse ich Sushi."],"w":[["mögen (mag, magst)","to like","Ich mag Zimt."],["lieber","rather, prefer","Vanille mag ich lieber."],["am liebsten","most of all","Die mag ich am liebsten."],["das Fleisch","meat","kleine Nudeln mit Fleisch"],["der Zucker","sugar","Milch, Eier, Zucker, Mehl …"],["der Ofen, die Öfen","oven","Die Törtchen sind im Ofen."],["das Grad, die Grad","degree","Zweihundert Grad!"],["riechen","to smell","Riechst du das?"],["der Rauch","smoke","Rauch!"],["schwarz / goldbraun","black / golden brown","Die Törtchen sind schwarz."],["die Creme, die Cremes","cream, custard","Erst machst du die Creme."],["planen","to plan","Sie planen das Essen."],["perfekt","perfect","Die sind perfekt!"],["der Bildschirm, die Bildschirme","screen","Der Bildschirm ist schwarz."],["erst","first","Erst machst du die Creme."]],"c":[["lieber als","rather than","Die esse ich lieber als die mit Fleisch."],["im Hintergrund","in the background","Elif und Tom lachen im Hintergrund."],["Ich finde dich toll.","I think you're great.","Er findet dich toll!"],["Schluss machen","to end (a call), finish","Ich muss Schluss machen."]],"x":[["die Temperatur, die Temperaturen","temperature",""],["sonnig","sunny",""],["windig","windy",""],["bewölkt","cloudy",""],["Es schneit.","it's snowing",""]],"g":["mögen und gern – lieber – am liebsten",["mögen + noun: ich mag, du magst, er mag, wir mögen, ihr mögt, sie mögen: Ich mag Zimt.","gern + verb: Ich esse gern Käse.","Comparison: gern → lieber → am liebsten: Ich esse gern Börek, lieber Baklava, am liebsten Mantı.","Compare two things with lieber als: Ich trinke lieber Tee als Kaffee.","Beispiele: Vanille mag ich lieber. · Was isst du am liebsten?"]]},{"n":35,"t":"Elifs Party","l":"A1","review":false,"p":[["Samstag, acht Uhr abends. Die Party ist im Studentenwohnheim, in der großen Küche im dritten Stock. Es gibt Musik, Luftballons und sehr viel Essen."],["Mia kommt mit dem Bus. In der Hand hat sie eine Schachtel mit zwölf goldbraunen Törtchen."],["Elif","Mia! Du bist da! Und die Pastéis! Sind die von dir?"],["Mia","Ja, von mir. Na ja, von mir und von Jonas' Oma. Alles Gute zum Geburtstag, Elif! Und hier – ein kleines Geschenk von mir."],["Es ist ein Schal, rot wie die türkische Fahne. Elif umarmt sie."],["Elif","Komm, ich stelle dich vor. Das ist mein Bruder Emre. Er ist gestern aus der Türkei gekommen, mit dem Flugzeug."],["Emre","Hallo! Elif spricht nur von dir. Und von Felix, dem Kater!"],["Tom ist auch da – mit Bruno. Hunde sind im Wohnheim eigentlich verboten. Aber heute ist Geburtstag."],["Elif","Und das ist Lukas. Er studiert mit mir Medizin."],["Lukas ist groß und blond. Er hat eine Brille und ein nettes Lächeln."],["Lukas","Hallo, Mia. Freut mich. Woher kommst du?"],["Mia","Aus Portugal. Aus Porto. Und du?"],["Lukas","Aus Kiel, aus dem Norden. Ich wohne hier bei einer Gastfamilie. Ich fahre jeden Tag mit dem Fahrrad zur Uni."],["Lukas ist wirklich nett. Er erzählt lustige Geschichten vom Krankenhaus. Mia lacht. Aber sie sieht immer wieder zur Tür."],["Um zehn Uhr kommt Jonas. Direkt vom Bahnhof, mit seiner Tasche. Er bringt Elif eine Flasche Wein aus Hamburg. Dann sieht er Mia. Mia lacht gerade mit Lukas."],["Jonas kommt nicht zu Mia. Er geht zu Tom und Bruno."],["Nach einer halben Stunde geht Mia zu ihm."],["Mia","Hallo! Du bist zurück! Wie geht es deiner Oma?"],["Jonas","Gut, danke. Sie ist wieder zu Hause."],["Mia","Und … wie war die Fahrt?"],["Jonas","Lang. Sieben Stunden."],["Kurze Antworten. Kein Lächeln. Dann kommt Lukas mit zwei Gläsern."],["Lukas","Mia, hier ist dein Wein. Und – nächsten Sonntag gehe ich zu einem Konzert im Theater. Kommst du mit?"],["Mia sagt nichts. Jonas stellt sein Glas auf den Tisch."],["Jonas","Ich bin müde. Die Reise. Gute Nacht, Elif. Alles Gute."],["Und weg ist er."],["Um Mitternacht fährt Mia mit dem letzten Bus nach Hause. Sie sieht aus dem Fenster und denkt nach. Warum ist sie so traurig? Lukas ist nett. Aber Lukas ist nicht Jonas."],["Plötzlich ist alles klar. Morgen spricht sie mit Jonas. Morgen früh. Mit Croissants. Und mit der Wahrheit."]],"q":["Was schenkt Mia Elif?","Woher kommt Lukas und wo wohnt er?","Was bringt Jonas Elif mit?","Richtig oder falsch? Jonas bleibt bis Mitternacht auf der Party.","Und du? Wie fährst du zur Arbeit oder zum Kurs? Bei wem wohnst du? (mit dem …, bei …)"],"a":["Einen roten Schal (und die Törtchen). „Es ist ein Schal, rot wie die türkische Fahne.“","Aus Kiel. Er wohnt bei einer Gastfamilie. „Aus Kiel, aus dem Norden. Ich wohne hier bei einer Gastfamilie.“","Eine Flasche Wein aus Hamburg. „Er bringt Elif eine Flasche Wein aus Hamburg.“","Falsch. He leaves early: „Ich bin müde. Die Reise. Gute Nacht, Elif.“","Example: Ich fahre mit dem Bus zur Arbeit. Ich wohne bei meinen Eltern."],"w":[["mit / von / zu / bei / aus (+ Dativ)","with / from, of / to / at, with / from","Ich wohne bei einer Gastfamilie."],["das Geschenk, die Geschenke","present","ein kleines Geschenk von mir"],["der Schal, die Schals","scarf","Es ist ein Schal."],["der Luftballon, die Luftballons","balloon","Musik, Luftballons und Essen"],["die Schachtel, die Schachteln","box (small)","eine Schachtel mit zwölf Törtchen"],["das Flugzeug, die Flugzeuge","aeroplane","mit dem Flugzeug"],["vorstellen","to introduce","Ich stelle dich vor."],["die Gastfamilie, die Gastfamilien","host family","bei einer Gastfamilie"],["der Norden","north","Aus Kiel, aus dem Norden."],["das Glas, die Gläser","glass","mit zwei Gläsern"],["das Konzert, die Konzerte","concert","zu einem Konzert im Theater"],["die Reise, die Reisen","journey, trip","Ich bin müde. Die Reise."],["die Mitternacht","midnight","Um Mitternacht fährt Mia nach Hause."],["letzt-","last","mit dem letzten Bus"],["die Wahrheit","truth","Mit der Wahrheit."]],"c":[["Alles Gute zum Geburtstag!","Happy birthday!","Alles Gute zum Geburtstag, Elif!"],["Kommst du mit?","Are you coming (along)?","Kommst du mit?"],["immer wieder","again and again","Sie sieht immer wieder zur Tür."],["Alles ist klar.","Everything is clear.","Plötzlich ist alles klar."]],"x":[["sagen","to say",""],["antworten","to answer",""],["sprechen","to speak",""],["sehen","to see",""],["verstehen","to understand",""]],"g":["Präpositionen mit Dativ",["mit, von, zu, bei, aus (and nach, seit) are always followed by the dative.","Dative articles: der → dem · das → dem · die → der · Plural → den (+n); ein → einem, eine → einer.","Short forms: zu dem → zum · zu der → zur · von dem → vom · bei dem → beim.","Beispiele: Mia kommt mit dem Bus. · Lukas wohnt bei einer Gastfamilie."]]},{"n":36,"t":"Sonntags ist alles zu!","l":"A1","review":false,"p":[["Sonntag, acht Uhr. Mia ist schon wach. Sie hat einen Plan: Croissants und Blumen für Jonas. Und dann die Wahrheit."],["Zuerst geht sie zum Supermarkt. Die Tür ist zu. Auf einem Schild steht: Öffnungszeiten: Montag bis Samstag von 7 bis 22 Uhr. Am Sonntag nicht."],["Dann geht sie zum Blumenladen. Auch zu. Mo–Fr 9–18 Uhr, Sa 9–14 Uhr."],["Mia steht auf der Straße. Alles ist still. Keine Autos, keine Leute. Nur Kirchenglocken."],["Dann sieht sie Licht – in der Bäckerei an der Ecke. Auf der Tür steht: Sonntags von 8 bis 11 Uhr geöffnet."],["Bäcker","Ah, die Frau mit dem Kater! Guten Morgen! Wie geht es dem Dieb?"],["Mia","Gut, danke! Er bekommt jetzt jeden Morgen Wurst von Frau Schulz. Vier Croissants, bitte."],["Bäcker","Gern. Wissen Sie, in Deutschland ist am Sonntag fast alles zu. Nur Bäckereien, Cafés und Tankstellen sind offen. Und vor Weihnachten manchmal die Geschäfte."],["Auf dem Weg nach Hause hört Mia einen Bohrer. Laut, sehr laut. Er kommt aus Wohnung eins. Aus Toms Wohnung."],["Frau Schulz steht schon vor Toms Tür. Im Morgenmantel."],["Frau Schulz","Herr Nowak! Es ist Sonntag! Am Sonntag bohrt man nicht! Sonntag ist Ruhetag!"],["Tom","Entschuldigung! Ich wollte nur ein Regal für Bruno …"],["Frau Schulz","Am Montag. Nach acht Uhr. Und vor zwanzig Uhr. Das ist die Hausordnung!"],["Tom macht die Tür zu. Mia lacht leise. Dann geht sie nach oben, zur Wohnung vier. Sie klopft."],["Jonas macht auf. Er sieht müde aus."],["Mia","Guten Morgen. Ich habe Croissants. Keine Blumen – am Sonntag gibt es keine Blumen."],["Jonas","Komm rein."],["Sie trinken Kaffee. Lange sagt niemand etwas. Dann sagt Mia:"],["Mia","Lukas ist nett. Aber ich gehe nicht mit ihm ins Konzert."],["Jonas","Nicht?"],["Mia","Nein. Ich habe die ganze Party nur an die Tür gesehen. Ich habe auf dich gewartet."],["Jonas sagt nichts. Dann lächelt er. Endlich."],["Jonas","Vor der Party war ich so froh. Ich habe sieben Stunden im Zug gesessen und habe an dich gedacht. Nach der Party war ich … ein Idiot. Entschuldigung."],["Mia","Schon gut."],["Jonas","Mia, hast du am Samstag Zeit? Am Vormittag? Wir gehen zusammen auf den Markt. Vor dem Markt trinken wir Kaffee. Und auf dem Markt muss ich dir etwas zeigen. Eine Überraschung."],["Mia","Was für eine Überraschung?"],["Jonas","Sage ich nicht. Bis Samstag musst du warten."]],"q":["Wann ist der Supermarkt geöffnet?","Was ist in Deutschland am Sonntag offen?","Warum ist Frau Schulz böse auf Tom?","Richtig oder falsch? Mia geht mit Lukas ins Konzert.","Und du? Wann hat dein Supermarkt geöffnet? Was machst du am Sonntag? Was machst du vor dem Frühstück?"],"a":["Montag bis Samstag von 7 bis 22 Uhr. „Öffnungszeiten: Montag bis Samstag von 7 bis 22 Uhr.“","Bäckereien, Cafés und Tankstellen. „Nur Bäckereien, Cafés und Tankstellen sind offen.“","He drills on Sunday, the day of rest. „Am Sonntag bohrt man nicht! Sonntag ist Ruhetag!“","Falsch. „Aber ich gehe nicht mit ihm ins Konzert.“","Example: Mein Supermarkt ist von acht bis zwanzig Uhr offen. Am Sonntag schlafe ich lange. Vor dem Frühstück dusche ich."],"w":[["vor / nach (+ Dativ, Zeit)","before / after","Vor dem Markt trinken wir Kaffee."],["die Öffnungszeiten (Plural)","opening hours","Öffnungszeiten: Montag bis Samstag …"],["geöffnet / zu","open / closed","Sonntags von 8 bis 11 Uhr geöffnet."],["das Schild, die Schilder","sign","Auf einem Schild steht …"],["der Blumenladen, die Blumenläden","flower shop","Dann geht sie zum Blumenladen."],["das Geschäft, die Geschäfte","shop","vor Weihnachten die Geschäfte"],["das Auto, die Autos","car","Keine Autos, keine Leute."],["die Tankstelle, die Tankstellen","petrol station","Cafés und Tankstellen sind offen."],["manchmal","sometimes","Und vor Weihnachten manchmal die Geschäfte."],["bohren / der Bohrer","to drill / drill","Am Sonntag bohrt man nicht!"],["das Regal, die Regale","shelf","Ich wollte nur ein Regal …"],["die Hausordnung, die Hausordnungen","house rules","Das ist die Hausordnung!"],["der Vormittag","morning (before noon)","Am Vormittag?"],["die Überraschung, die Überraschungen","surprise","Eine Überraschung."],["warten auf","to wait for","Ich habe auf dich gewartet."]],"c":[["sonntags","on Sundays","Sonntags von 8 bis 11 Uhr geöffnet."],["der Ruhetag","day of rest","Sonntag ist Ruhetag!"],["Schon gut.","It's okay.","Schon gut."],["Sage ich nicht.","I'm not telling.","Sage ich nicht."]],"x":[["nehmen","to take",""],["geben","to give",""],["putzen","to clean",""],["mit dem Bus fahren","to go by bus",""],["nach Hause gehen","to go home",""]],"g":["Präpositionen der Zeit",["um + clock time: um acht Uhr · am + days and parts of the day: am Sonntag, am Vormittag · im + months and seasons: im November, im Winter.","von … bis: von 8 bis 11 Uhr · bis: Bis Samstag musst du warten.","vor / nach + dative: vor dem Markt, nach der Party, vor Weihnachten.","-s on days = every: sonntags = every Sunday.","Beispiele: Vor der Party war ich so froh. · Die Bäckerei ist von 8 bis 11 Uhr geöffnet."]]},{"n":37,"t":"Samstag auf dem Markt","l":"A1","review":false,"p":[["Samstag, zehn Uhr. Es ist kalt, nur fünf Grad. Mia trägt ihre dünne Jacke aus Porto. Sie friert."],["Der Markt am Münster ist voll. Hier gibt es alles: Äpfel, Kartoffeln, Käse aus dem Schwarzwald, Honig, Blumen. Es gibt sogar einen Stand mit heißen Würsten."],["Jonas","Weißt du, was man hier unbedingt essen muss? Eine „Lange Rote“. Das ist eine Wurst, fünfunddreißig Zentimeter lang. Man isst sie mit Zwiebeln und Senf."],["Mia","Fünfunddreißig Zentimeter? Zum Frühstück?"],["Jonas","In Freiburg isst man immer eine Lange Rote. Das ist Tradition!"],["Sie essen die Würste. Dann nimmt Jonas Mias Hand."],["Jonas","Komm. Jetzt die Überraschung."],["Auf der anderen Seite vom Münster steht ein neuer Stand. Ein kleiner Wagen, blau und weiß, mit bunten Fliesen. Auf einem Schild steht: Sabores de Portugal."],["Mia bleibt stehen. Es gibt Pastéis de Nata. Es gibt Bacalhau, den Stockfisch. Es gibt Vinho Verde und Sardinen in bunten Dosen. Hinter dem Wagen steht eine Frau mit grauen Locken und einer Schürze."],["Fátima: Bom dia! Was darf's sein?"],["Mia","Bom dia! Sie sind … aus Portugal?"],["Fátima: Aus Lissabon! Ich bin Fátima. Seit dreißig Jahren in Freiburg. Seit zwei Wochen mit dem Wagen hier auf dem Markt."],["Und plötzlich sprechen Mia und Fátima Portugiesisch. Schnell, laut, mit Lachen. Mia hat Tränen in den Augen. Jonas versteht nichts, aber er lächelt."],["Mia","Jonas, woher weißt du das?"],["Jonas","Ich kaufe hier jeden Samstag ein, für das Café. Letzten Samstag habe ich den Wagen gesehen. Und ich habe gedacht: Das muss Mia sehen."],["Sie sitzen auf einer Bank und essen Pastéis. Die sind besser als Mias Pastéis. Viel besser."],["Jonas","Mia, darf ich dir etwas sagen? Ein Geheimnis?"],["Mia","Ja, klar."],["Jonas","In Freiburg gibt es viele Cafés. Aber es gibt kein Café wie das Café von deinem Opa. Ich möchte ein eigenes Café. Klein, mit Musik, mit Kuchen aus aller Welt."],["Mia","Das ist eine tolle Idee! Was braucht man für ein Café?"],["Jonas","Man braucht Geld. Viel Geld. Man braucht einen Raum. Und man braucht Mut. Ich habe noch nichts davon."],["Mia","Mut kann man lernen."],["Ein kalter Wind kommt. Mia zittert."],["Fátima: Menina! Mit dieser Jacke? Im November? In Deutschland braucht man im Winter eine richtige Jacke! Sonst bist du bald wieder krank!"],["Mia","Ich habe aber keine Winterjacke."],["Fátima: Dann musst du eine kaufen. Heute noch!"]],"q":["Was ist eine „Lange Rote“?","Was gibt es am Stand „Sabores de Portugal“?","Woher kommt Fátima, und wie lange lebt sie schon in Freiburg?","Richtig oder falsch? Jonas hat schon ein eigenes Café.","Und du? Was gibt es in deiner Stadt? Was muss man dort unbedingt essen?"],"a":["Eine Wurst, 35 Zentimeter lang, mit Zwiebeln und Senf. „Das ist eine Wurst, fünfunddreißig Zentimeter lang.“","Pastéis de Nata, Bacalhau, Vinho Verde und Sardinen. „Es gibt Pastéis de Nata. Es gibt Bacalhau … Es gibt Vinho Verde und Sardinen.“","Aus Lissabon, seit dreißig Jahren. „Aus Lissabon! … Seit dreißig Jahren in Freiburg.“","Falsch. It's his dream: „Ich möchte ein eigenes Café.“ He doesn't have money, a space or courage yet.","Example: In meiner Stadt gibt es einen großen Park und viele Restaurants. Man muss unbedingt Fish and Chips essen."],"w":[["es gibt (+ Akkusativ)","there is / there are","Es gibt einen Stand mit heißen Würsten."],["man","one, you, people","Man isst sie mit Zwiebeln und Senf."],["frieren","to be cold, freeze","Sie friert."],["dünn","thin","ihre dünne Jacke"],["der Senf","mustard","mit Zwiebeln und Senf"],["der Zentimeter, die Zentimeter","centimetre","fünfunddreißig Zentimeter lang"],["die Tradition, die Traditionen","tradition","Das ist Tradition!"],["die Seite, die Seiten","side","auf der anderen Seite"],["die Dose, die Dosen","can, tin","Sardinen in bunten Dosen"],["die Träne, die Tränen","tear","Mia hat Tränen in den Augen."],["das Geheimnis, die Geheimnisse","secret","Ein Geheimnis?"],["eigen-","own","Ich möchte ein eigenes Café."],["der Raum, die Räume","room, space","Man braucht einen Raum."],["der Mut","courage","Und man braucht Mut."],["die Winterjacke, die Winterjacken","winter coat","Ich habe keine Winterjacke."]],"c":[["unbedingt","absolutely, definitely","Was man hier unbedingt essen muss."],["aus aller Welt","from all over the world","Kuchen aus aller Welt"],["Woher weißt du das?","How do you know that?","Jonas, woher weißt du das?"],["heute noch","today, before the day ends","Heute noch!"]],"x":[["zu Hause sein","to be at home",""],["Zeit haben","to have time",""],["Lust haben","to feel like (doing)",""],["Bescheid sagen","to let someone know",""],["gut","good",""]],"g":["es gibt und man",["es gibt + accusative = there is / there are. It never changes: Es gibt einen Stand. · Es gibt viele Cafés.","man = people in general (\"you\", \"one\"). The verb takes the er/sie/es form: Man isst …, man braucht …","man is often used with modal verbs: Hier kann man alles kaufen.","Don't confuse man with der Mann (the man)!","Beispiele: In Freiburg gibt es viele Cafés. · Was braucht man für ein Café?"]]},{"n":38,"t":"Welche Jacke?","l":"A1","review":false,"p":[["Samstag, vierzehn Uhr. Elif und Mia stehen vor einem großen Kaufhaus in der Kaiser- Joseph-Straße. Elif liebt Shopping. Mia nicht."],["Elif","Also: Wir brauchen eine Winterjacke, eine Mütze, Handschuhe und vielleicht Stiefel. Los geht's!"],["Im zweiten Stock ist die Damenabteilung. Es gibt Hunderte Jacken und Mäntel. Schwarze, graue, blaue, rote, grüne, sogar pinke."],["Verkäuferin","Kann ich Ihnen helfen?"],["Mia","Ja, bitte. Ich suche eine Winterjacke. Eine warme."],["Verkäuferin","Welche Größe haben Sie?"],["Mia","Achtunddreißig, glaube ich."],["Verkäuferin","Und welche Farbe möchten Sie?"],["Mia","Hm. Vielleicht Blau? Oder Grün?"],["Elif","Nein, Pink! Pink ist modern!"],["Mia","Elif. Ich trage nie Pink."],["Die Verkäuferin bringt drei Jacken: eine dunkelblaue, eine grüne und – natürlich – eine pinke."],["Verkäuferin","Die Umkleidekabine ist dort hinten."],["Mia probiert die Jacken an. Die dunkelblaue ist zu groß. Die pinke ist … sehr pink. Die grüne passt perfekt. Sie ist lang, warm und weich."],["Mia","Welche gefällt dir besser, Elif? Die blaue oder die grüne?"],["Elif","Die grüne! Die Farbe passt zu deinen Augen."],["Mia","Was kostet sie?"],["Verkäuferin","Hundertneunundvierzig Euro."],["Mia","Hundertneunundvierzig? Das ist zu teuer."],["Verkäuferin","Moment … Diese Woche gibt es zwanzig Prozent Rabatt. Dann kostet sie hundertneunzehn Euro zwanzig."],["Mia denkt nach. Dann denkt sie an Fátima: Sonst bist du bald wieder krank!"],["Mia","Gut. Ich nehme sie."],["Dann kaufen sie noch eine Mütze – grau, mit einem Bommel – und warme Handschuhe. Die Stiefel sind zu teuer. Die kauft Mia nächsten Monat."],["Elif kauft natürlich auch etwas: einen pinken Pullover."],["Im Café im Erdgeschoss trinken sie heiße Schokolade. Mia trägt schon die neue Jacke. Ihr ist endlich warm."],["Elif","Und jetzt die wichtige Frage. Was schenkst du Jonas zum Geburtstag?"],["Mia","Zum Geburtstag?"],["Elif","Am fünfzehnten November! Das ist nächsten Mittwoch! Hast du das vergessen?"],["Mia","Nein! Ich … ich habe nur noch keine Idee. Gar keine."],["Elif","Vier Tage, Mia. Du hast vier Tage."]],"q":["Was braucht Mia für den Winter?","Welche Größe hat Mia?","Welche Jacke passt perfekt? Warum findet Elif sie gut?","Richtig oder falsch? Mia kauft auch Stiefel.","Und du? Was trägst du heute? Welche Farbe magst du am liebsten?"],"a":["Eine Winterjacke, eine Mütze, Handschuhe und vielleicht Stiefel. Elif's list.","Achtunddreißig. „Achtunddreißig, glaube ich.“","Die grüne. The colour goes with her eyes. „Die grüne! Die Farbe passt zu deinen Augen.“","Falsch. „Die Stiefel sind zu teuer. Die kauft Mia nächsten Monat.“","Example: Heute trage ich eine Jeans und einen blauen Pullover. Am liebsten mag ich Grün."],"w":[["welch- (welcher, welche, welches)","which","Welche Farbe möchten Sie?"],["das Kaufhaus, die Kaufhäuser","department store","vor einem großen Kaufhaus"],["die Mütze, die Mützen","woolly hat","eine Mütze, grau, mit einem Bommel"],["der Handschuh, die Handschuhe","glove","warme Handschuhe"],["der Stiefel, die Stiefel","boot","Die Stiefel sind zu teuer."],["der Mantel, die Mäntel","coat","Es gibt Hunderte Jacken und Mäntel."],["die Größe, die Größen","size","Welche Größe haben Sie?"],["die Farbe, die Farben","colour","Welche Farbe möchten Sie?"],["grün / grau / pink / dunkelblau","green / grey / pink / dark blue","Die grüne passt perfekt."],["tragen (er trägt)","to wear; to carry","Ich trage nie Pink."],["anprobieren","to try on","Mia probiert die Jacken an."],["passen","to fit; to match","Die Farbe passt zu deinen Augen."],["weich","soft","Sie ist lang, warm und weich."],["der Rabatt, die Rabatte","discount","zwanzig Prozent Rabatt"],["vergessen","to forget","Hast du das vergessen?"]],"c":[["Kann ich Ihnen helfen?","Can I help you?","Kann ich Ihnen helfen?"],["die Umkleidekabine","changing room","Die Umkleidekabine ist dort hinten."],["Ich nehme sie / ihn / es.","I'll take it.","Gut. Ich nehme sie."],["Los geht's!","Let's go!","Los geht's!"]],"x":[["interessant","interesting",""],["schmutzig","dirty",""],["toll","great",""],["wenig","little, few",""],["sehr","very",""]],"g":["welch-",["welch- asks for a choice from a group: Which one?","It takes the endings of der, die, das: welcher Mantel, welche Jacke, welches Kleid, welche Stiefel (plural).","Accusative masculine: welchen: Welchen Mantel nehmen Sie?","Answer with the article: Welche Jacke? – Die grüne.","Beispiele: Welche Größe haben Sie? · Welche gefällt dir besser?"]]},{"n":39,"t":"Ein Geschenk für Jonas","l":"A1","review":false,"p":[["Sonntag. Montag. Mia hat immer noch keine Idee."],["Am Montag nach dem Kurs geht sie durch die Altstadt. Sie geht in einen Buchladen. Ein Kochbuch? Jonas hat schon dreißig Kochbücher. Sie geht in einen Musikladen. Gitarrensaiten? Zu langweilig. Sie geht um den Münsterplatz, einmal, zweimal. Gegen den Wind, mit ihrer neuen grünen Jacke. Nichts."],["Dann sieht sie den blau-weißen Wagen. Fátima!"],["Fátima: Menina! Die Jacke ist schön! Was ist los? Du siehst so ernst aus."],["Mia","Ich suche ein Geschenk für Jonas. Er hat am Mittwoch Geburtstag. Und ich habe keine Idee. Ohne Idee kein Geschenk!"],["Fátima: Für Jonas? Den netten Koch? Hm. Was liebt er?"],["Mia","Kochen. Musik. Und … er hat einen Traum. Ein eigenes Café."],["Fátima: Na also! Für einen Koch ist eine Schürze wichtig. Ohne Schürze kann kein Koch arbeiten. Und auf die Schürze schreibst du den Namen von seinem Café. Für die Zukunft!"],["Mia umarmt Fátima. Das ist es!"],["In einer kleinen Straße hinter dem Münster gibt es eine Stickerei. Eine alte Frau sitzt an einer Nähmaschine."],["Mia","Guten Tag. Ich möchte eine Schürze mit einem Namen. Für ein Geschenk."],["Frau","Welcher Name?"],["Mia","Das Café hat noch keinen Namen. Es gibt das Café noch nicht. Nur in seinem Kopf."],["Frau","Ohne Namen kann ich nichts sticken."],["Mia denkt nach. Jonas. Mia. Porto. Freiburg. Felix. Brezeln. Dann hat sie es."],["Mia","„Café Bächle“."],["Frau","Café Bächle. Schön! Für wann brauchen Sie die Schürze?"],["Mia","Für Mittwoch."],["Frau","Für Mittwoch?! Das ist sehr schnell. Normalerweise brauche ich eine Woche. Aber gut – gegen zehn Euro extra mache ich das. Kommen Sie am Dienstag gegen siebzehn Uhr. Fünfunddreißig Euro, bitte."],["Mia bezahlt. Sie ist glücklich. Ein Geschenk mit einer Bedeutung."],["Am Abend liegt eine Karte unter ihrer Tür. Wie am ersten Tag in Freiburg. Die Handschrift kennt sie."],["Liebe Mia, am Mittwoch, 15. November, feiere ich meinen Geburtstag. Um 20 Uhr, in Wohnung 4. Bitte ohne Geschenke! (Okay … mit Geschenken ist auch gut.) Es gibt Essen, Musik – und eine Überraschung. Für alle. Aber besonders für dich. Jonas"],["Mia liest die Karte dreimal. Besonders für dich. Was meint er?"]],"q":["Welche Geschenk-Ideen hat Mia im Buchladen und im Musikladen? Warum nimmt sie sie nicht?","Wer hat die Idee mit der Schürze?","Was steht auf der Schürze?","Richtig oder falsch? Die Schürze ist am Mittwochabend fertig.","Und du? Was ist ein gutes Geschenk für deinen besten Freund oder deine beste Freundin? Für wen kaufst du gern Geschenke?"],"a":["Ein Kochbuch und Gitarrensaiten. Jonas has 30 cookbooks already, and strings are „zu langweilig“.","Fátima. „Für einen Koch ist eine Schürze wichtig.“","„Café Bächle“. „Café Bächle. Schön!“","Falsch. It's ready on Tuesday: „Kommen Sie am Dienstag gegen siebzehn Uhr.“","Example: Für meine beste Freundin ist ein Buch ein gutes Geschenk. Ich kaufe gern Geschenke für meine Familie."],"w":[["für / ohne / durch / um / gegen (+ Akk.)","for / without / through / around / against, about","Sie geht durch die Altstadt."],["der Buchladen, die Buchläden","bookshop","Sie geht in einen Buchladen."],["das Kochbuch, die Kochbücher","cookbook","Ein Kochbuch?"],["langweilig","boring","Zu langweilig."],["ernst","serious","Du siehst so ernst aus."],["der Traum, die Träume","dream","Er hat einen Traum."],["die Zukunft","future","Für die Zukunft!"],["der Name, die Namen","name","Ohne Namen kann ich nichts sticken."],["die Nähmaschine, die Nähmaschinen","sewing machine","an einer Nähmaschine"],["normalerweise","normally","Normalerweise brauche ich eine Woche."],["die Bedeutung, die Bedeutungen","meaning","ein Geschenk mit einer Bedeutung"],["die Karte, die Karten","card","eine Karte unter ihrer Tür"],["die Handschrift, die Handschriften","handwriting","Die Handschrift kennt sie."],["besonders","especially","Aber besonders für dich."],["meinen","to mean","Was meint er?"]],"c":[["Na also!","There you go!","Na also!"],["Das ist es!","That's it!","Das ist es!"],["gegen siebzehn Uhr","at around 5 p.m.","Kommen Sie gegen siebzehn Uhr."],["Für wann …?","For when …?","Für wann brauchen Sie die Schürze?"]],"x":[["auch","also",""],["nur","only",""],["noch","still",""],["schon","already",""],["natürlich","of course",""]],"g":["Präpositionen mit Akkusativ",["durch, für, gegen, ohne, um are always followed by the accusative. (Memory trick: DOGFU.)","für den Koch · ohne einen Namen · durch die Altstadt · um den Münsterplatz · gegen den Wind.","With pronouns: für dich, ohne mich, gegen ihn.","gegen + time = about: gegen siebzehn Uhr. um + time = exactly: um 20 Uhr.","Beispiele: Ich suche ein Geschenk für Jonas. · Ohne Namen kann ich nichts sticken."]]},{"n":40,"t":"Wiederholung: Herbst in Freiburg","l":"A1","review":true,"p":[["Dienstag, 14. November, dreiundzwanzig Uhr"],["Morgen hat Jonas Geburtstag. Die Schürze liegt auf meinem Tisch. Sie ist dunkelgrün, und darauf steht in Gold: Café Bächle. Ich habe sie heute um siebzehn Uhr abgeholt. Sie ist perfekt."],["Ich kann nicht schlafen. Also schreibe ich. Was ist in diesem Herbst passiert?"],["Im Oktober bin ich mit Jonas zum Titisee gefahren. Er ist ins Wasser gefallen, und im Zug hat er meine Hand genommen. Dann ist er nach Hamburg gefahren, zu seiner Oma. Sie war im Krankenhaus. Jetzt geht es ihr wieder gut."],["Ich hatte Heimweh. Frau Schulz hat mir von früher erzählt. Sie war Musiklehrerin, und ihr Mann Heinrich hatte die Bäckerei an der Ecke. Ich mag Frau Schulz sehr. Sie ist streng, aber sie hat ein großes Herz. Wie Herr Brandt."],["Ich habe Pastéis de Nata gebacken. Die ersten waren schwarz. Die zweiten waren gut. Elifs Party war am vierten November. Ich habe Lukas kennengelernt. Er ist nett. Aber am Sonntag nach der Party habe ich mit Jonas gesprochen. Mit Croissants und mit der Wahrheit."],["Am Sonntag ist in Deutschland alles zu! Nur die Bäckereien sind offen. Und man darf nicht bohren. Das weiß jetzt auch Tom."],["Auf dem Markt gibt es jetzt einen Wagen aus Portugal. Fátima kommt aus Lissabon. Ich spreche jeden Samstag Portugiesisch mit ihr. Das ist wie ein kleines Stück Zuhause."],["Und ich habe eine Winterjacke! Grün, warm und weich. Welche Farbe wollte Elif? Pink, natürlich."],["Jonas hat einen Traum","ein eigenes Café. Man braucht Geld, einen Raum und Mut. Ich glaube, er hat mehr Mut, als er denkt."],["Und jetzt liegt seine Karte vor mir. Eine Überraschung. Für alle. Aber besonders für dich."],["Was ist die Überraschung? Ich weiß es nicht. Aber ich weiß etwas anderes. Im September war Freiburg fremd. Jetzt ist es Mitte November, und Freiburg ist … fast mein Zuhause."],["Gute Nacht, Tagebuch. Morgen um zwanzig Uhr. Wohnung vier."]],"q":["haben oder sein? Wir ___ zum Titisee gefahren. Ich ___ Pastéis gebacken.","Perfekt: Jonas ___ ins Wasser ___ (fallen).","Präteritum: Frau Schulz ___ Musiklehrerin (sein). Ihr Mann ___ eine Bäckerei (haben).","Schreib das Datum: 15.11. → Jonas hat am ___ November Geburtstag.","Ergänze: Ich esse gern Börek, ___ Baklava und ___ Mantı.","Dativ: Mia kommt mit ___ Bus. Lukas wohnt bei ___ Gastfamilie.","Zeit: Die Bäckerei ist ___ 8 ___ 11 Uhr offen. ___ der Party war Jonas froh.","es gibt / man: Auf dem Markt ___ einen Wagen aus Portugal. Am Sonntag darf ___ nicht bohren.","welch-: ___ Jacke nimmst du? – Die grüne.","Akkusativ-Präpositionen: Mia sucht ein Geschenk ___ Jonas. ___ Namen kann die Frau nichts sticken."],"a":["sind · habe. fahren = movement → sein; backen → haben.","ist … gefallen. fallen = change of place → sein.","war · hatte. Präteritum of sein and haben.","fünfzehnten. am + ordinal number with -en.","lieber · am liebsten. gern → lieber → am liebsten.","dem · einer. mit and bei + dative: der Bus → dem Bus, eine → einer.","von … bis · Vor. von … bis for time spans; vor + dative.","gibt es · man. es gibt + accusative; man + er-form.","Welche. die Jacke → welche.","für · Ohne. für and ohne take the accusative."],"w":[],"c":[],"x":[],"g":["Wiederholung",["Perfekt with sein (movement, change) vs. haben (stories 28–31).","war / hatte (story 32) · dates am fünfzehnten November (story 33).","mögen, gern – lieber – am liebsten (story 34).","Prepositions: dative mit, von, zu, bei, aus (story 35) · time um, am, im, vor, nach (story 36) · accusative für, ohne, durch, um, gegen (story 39).","es gibt, man (story 37) · welch- (story 38).","Beispiele: Im Oktober bin ich zum Titisee gefahren. · Auf dem Markt gibt es einen Wagen aus Portugal."]],"exam":{"task":"Sie machen eine Party. Schreiben Sie eine Einladung.","points":["Wann und wo ist die Party?","Was gibt es zu essen und zu trinken?","Was sollen die Gäste mitbringen?"],"words":35,"en":"Party invitation: when/where, food and drink, what to bring."}},{"n":41,"t":"Jonas hat Geburtstag","l":"A1","review":false,"p":[["Mittwoch, zwanzig Uhr. Wohnung vier ist voll. Lena und Stefan sind da, mit Paul. Tom ist da, mit Bruno. Elif ist da, mit ihrem pinken Pullover. Frau Schulz ist da, mit ihrem Apfelstrudel und mit Felix. Fátima ist da, mit einer Kiste Pastéis. Und dann klingelt es noch einmal."],["Tom","Herr Brandt?!"],["Herr Brandt","Ich bin zu alt für Partys. Aber nicht für den Geburtstag von meinem schlimmsten Schüler."],["Alle lachen. Jonas umarmt seinen alten Lehrer."],["Dann kommen die Geschenke. Paul gibt seinem Onkel ein Bild. Darauf sind Jonas, Mia, Felix und ein riesiges Herz."],["Paul","Das bist du, und das ist deine Freundin!"],["Lena","Paul!"],["Lena schenkt ihrem Bruder ein altes Foto im Rahmen: Jonas mit fünf Jahren, mit einer Kochmütze. Tom schenkt seinem Nachbarn eine Flasche Wodka aus Polen. Elif schenkt ihrem Freund ein Kochbuch aus der Türkei – sein einunddreißigstes."],["Dann gibt Mia Jonas ihr Paket. Er macht es auf. Er nimmt die Schürze heraus und liest: Café Bächle."],["Jonas sagt nichts. Lange. Er sieht die Schürze an. Dann sieht er Mia an."],["Jonas","Café Bächle. Das ist … das ist der Name. Das ist der perfekte Name."],["Er zieht die Schürze sofort an. Alle klatschen."],["Elif","Und die Überraschung? Du hast eine Überraschung versprochen!"],["Jonas nimmt seine Gitarre."],["Jonas","Ich habe ein Lied geschrieben. Auf Deutsch – und ein bisschen auf Portugiesisch. Fátima hat mir mit den Wörtern geholfen. Es ist für meine Nachbarin. Und Lena hat recht: Ich singe nicht gut. Bitte nicht lachen."],["Er singt. Er singt wirklich nicht gut. Aber das Lied ist schön. Es geht um eine Frau mit einem großen Koffer, um einen Kater mit Brezeln, um ein Bächle und um einen Mann mit einem hässlichen Hirsch-Pullover."],["Niemand lacht. Fátima weint. Frau Schulz weint auch."],["Nach dem Lied geht Mia auf den Balkon. Sie braucht frische Luft. Draußen fällt Schnee. Der erste Schnee in diesem Jahr. Jonas kommt zu ihr."],["Jonas","Hat dir das Lied gefallen?"],["Mia","Das Lied war furchtbar."],["Jonas","Oh."],["Mia","Und das Schönste, was ich je gehört habe."],["Drinnen will Felix auf den Balkon. Aber Frau Schulz nimmt ihn auf den Arm."],["Frau Schulz","Heute nicht, Felix. Heute nicht."],["Und auf dem Balkon, im ersten Schnee, küsst Jonas Mia. Endlich."]],"q":["Warum ist es eine Überraschung, dass Herr Brandt kommt?","Was schenkt Paul seinem Onkel?","Was ist Jonas' Überraschung?","Richtig oder falsch? Felix stört dieses Mal.","Und du? Was hast du deiner Mutter oder deinem Vater zum Geburtstag geschenkt?"],"a":["He said he was too old for parties. Story 33: „Danke, aber ich bin zu alt für Partys.“","Ein Bild mit Jonas, Mia, Felix und einem Herz. „Paul gibt seinem Onkel ein Bild.“","A song he wrote for Mia. „Ich habe ein Lied geschrieben … Es ist für meine Nachbarin.“","Falsch. „Heute nicht, Felix.“ Frau Schulz holds him back.","Example: Ich habe meiner Mutter Blumen geschenkt. Meinem Vater habe ich ein Buch geschenkt."],"w":[["meinen / meinem / meiner …","my (acc. / dat.)","Lena schenkt ihrem Bruder ein Foto."],["schenken","to give (as a present)","Tom schenkt seinem Nachbarn Wodka."],["das Bild, die Bilder","picture","Paul gibt seinem Onkel ein Bild."],["der Rahmen, die Rahmen","frame","ein altes Foto im Rahmen"],["die Kiste, die Kisten","crate, box","mit einer Kiste Pastéis"],["das Lied, die Lieder","song","Ich habe ein Lied geschrieben."],["versprechen (versprochen)","to promise","Du hast eine Überraschung versprochen!"],["klatschen","to clap","Alle klatschen."],["der Schnee","snow","Draußen fällt Schnee."],["küssen","to kiss","Jonas küsst Mia."],["furchtbar","terrible","Das Lied war furchtbar."],["frisch","fresh","Sie braucht frische Luft."],["die Luft","air","frische Luft"],["drinnen / draußen","inside / outside","Drinnen will Felix auf den Balkon."],["endlich","finally","Endlich."]],"c":[["recht haben","to be right","Lena hat recht."],["Es geht um …","It's about …","Es geht um eine Frau mit einem Koffer."],["das Schönste, was ich je gehört habe","the most beautiful thing I've ever heard","Und das Schönste, was ich je gehört habe."],["auf den Arm nehmen","to pick up","Frau Schulz nimmt ihn auf den Arm."]],"x":[["hier","here",""],["dort","there",""],["ein bisschen","a little",""],["das Land, die Länder","country",""],["die Muttersprache, die Muttersprachen","mother tongue",""]],"g":["Possessivartikel im Akkusativ und Dativ",["mein, dein, sein, ihr, unser, euer, Ihr take the same endings as ein.","Accusative: meinen (der) · meine (die) · mein (das) · meine (plural). Jonas umarmt seinen Lehrer.","Dative: meinem (der/das) · meiner (die) · meinen + -n (plural). Paul gibt seinem Onkel ein Bild.","Verbs like geben, schenken, bringen have two objects: a person (dative) + a thing (accusative).","Beispiele: Lena schenkt ihrem Bruder ein Foto. · Er nimmt seine Gitarre."]]},{"n":42,"t":"Nach der Party","l":"A1","review":false,"p":[["Donnerstag, neun Uhr. Wohnung vier sieht schlimm aus. Überall Gläser, Teller und Papier. Auf dem Sofa schläft Bruno. Tom hat ihn gestern Nacht vergessen."],["Mia und Jonas räumen zusammen auf. Sie lächeln die ganze Zeit."],["Jonas","Wer hat den ganzen Apfelstrudel aufgegessen?"],["Mia","Felix. Um Mitternacht. Frau Schulz hat es nicht gesehen. Sie hat mit Herrn Brandt getanzt."],["Jonas","Herr Brandt hat getanzt?!"],["Mia","Ja! Und er hat Fátima seine Telefonnummer gegeben."],["Jonas lacht so laut, Bruno wacht auf."],["Mia wäscht die Gläser ab. Jonas bringt den Müll runter. Dann ruft Tom an."],["Tom","Ist Bruno bei euch? Ich bin um zwei Uhr eingeschlafen und habe ihn ganz vergessen!"],["Jonas","Ja, er ist hier. Er hat die Wurst vom Tisch aufgegessen und ist dann auf dem Sofa eingeschlafen. Wie du."],["Um elf Uhr ruft Elif an. Mit Video, natürlich."],["Elif","Mia! Ist es wahr? Habt ihr euch geküsst?"],["Mia","Woher weißt du das?"],["Elif","Paul hat es gesehen! Er hat durch das Fenster geschaut. Er hat es allen erzählt. Auch Herrn Brandt!"],["Mia wird rot. Jonas nimmt das Handy."],["Jonas","Ja, Elif. Wir haben uns geküsst. Bist du jetzt zufrieden?"],["Elif","Aaaaah! Ich wusste es! Seit dem ersten Tag im Kurs!"],["Am Nachmittag ruft Mia ihre Mutter in Porto an. Sie erzählt alles: die Party, das Lied, den Schnee, den Balkon."],["Mama","Mia, ich habe es gewusst. Schon im September. Beim Videoanruf. Ich habe sein Gesicht gesehen."],["Mia","Mama!"],["Mama","Und Rui hat es auch gewusst. Wir haben gewettet. Er hat zehn Euro gewonnen."],["Mia lacht. Sie ist so glücklich wie lange nicht."],["Am Abend sitzt sie am Laptop. Sie macht ihre Bank-App auf. Sie will nur kurz die Miete überweisen."],["Kontostand","412,35 Euro."],["Mia sieht die Zahl an. Einmal. Zweimal. Die Miete kostet sechshundertfünfzig Euro. Am ersten Dezember muss sie zahlen. Das ist in zwei Wochen."],["Sie hat in Portugal Geld gespart. Für drei Monate. Und jetzt ist schon Mitte November. Bald sind drei Monate vorbei."],["Mia macht den Laptop zu. Das Glück von heute Morgen ist plötzlich ganz klein."],["Sie braucht einen Job. Sofort."]],"q":["Wer hat den Apfelstrudel aufgegessen?","Warum ist Bruno in Jonas' Wohnung?","Woher weiß Elif von dem Kuss?","Richtig oder falsch? Mia hat genug Geld für die Miete.","Und du? Was hast du gestern Abend gemacht? Wann bist du eingeschlafen? Wann bist du aufgewacht?"],"a":["Felix, um Mitternacht. „Felix. Um Mitternacht.“","Tom forgot him. Tom: „Ich bin um zwei Uhr eingeschlafen und habe ihn ganz vergessen!“","Paul saw it through the window and told everyone. „Paul hat es gesehen! Er hat durch das Fenster geschaut.“","Falsch. She has 412,35 €, but the rent is 650 €.","Example: Gestern Abend habe ich ferngesehen. Ich bin um elf eingeschlafen und um sieben aufgewacht."],"w":[["aufräumen (aufgeräumt)","to tidy up","Mia und Jonas räumen zusammen auf."],["aufessen (aufgegessen)","to eat up","Wer hat den Apfelstrudel aufgegessen?"],["abwaschen (abgewaschen)","to wash up","Mia wäscht die Gläser ab."],["der Müll","rubbish","Jonas bringt den Müll runter."],["wahr","true","Ist es wahr?"],["wetten (gewettet)","to bet","Wir haben gewettet."],["gewinnen (gewonnen)","to win","Er hat zehn Euro gewonnen."],["die Miete, die Mieten","rent","Die Miete kostet 650 Euro."],["überweisen","to transfer (money)","Sie will die Miete überweisen."],["der Kontostand","account balance","Kontostand: 412,35 Euro."],["zahlen","to pay","Am ersten Dezember muss sie zahlen."],["sparen (gespart)","to save","Sie hat Geld gespart."],["die Mitte","middle","Und jetzt ist schon Mitte November."],["vorbei","over, past","Bald sind drei Monate vorbei."],["der Job, die Jobs","job","Sie braucht einen Job."]],"c":[["die ganze Zeit","the whole time","Sie lächeln die ganze Zeit."],["Ich habe es gewusst!","I knew it!","Mia, ich habe es gewusst."],["so glücklich wie lange nicht","happier than in a long time","so glücklich wie lange nicht"],["Bist du jetzt zufrieden?","Are you happy now?","Bist du jetzt zufrieden?"]],"x":[["die Fremdsprache, die Fremdsprachen","foreign language",""],["die Hauptstadt, die Hauptstädte","capital",""],["der Ausländer, die Ausländer","foreigner (m)",""],["die Ausländerin, die Ausländerinnen","foreigner (f)",""],["Deutschland","Germany",""]],"g":["Perfekt von trennbaren Verben",["Separable verbs put -ge- between the prefix and the stem: aufgeräumt, eingeschlafen, angerufen.","Regular: prefix + ge + stem + t: aufräumen → aufgeräumt.","Irregular: prefix + ge + stem + en: aufessen → aufgegessen · einschlafen → eingeschlafen.","haben or sein as usual: Ich bin eingeschlafen (change of state) · Wer hat aufgeräumt?","Beispiele: Wer hat den Strudel aufgegessen? · Ich bin um zwei Uhr eingeschlafen."]]},{"n":43,"t":"Mia sucht Arbeit","l":"A1","review":false,"p":[["Freitag. Mia sitzt in der Bibliothek, am Laptop. Sie sucht Stellenanzeigen. Webdesigner, Freiburg."],["Es gibt viele Anzeigen. Aber fast immer steht da: Sehr gute Deutschkenntnisse (C1). Manchmal steht da: Deutsch B2. Nie steht da: Deutsch A1 – kein Problem."],["Nach dem Kurs bleibt Mia im Kursraum. Herr Brandt packt seine Tasche."],["Mia","Herr Brandt, haben Sie einen Moment Zeit? Ich suche Arbeit. Aber alle Firmen wollen sehr gutes Deutsch."],["Herr Brandt","Was haben Sie in Portugal gemacht?"],["Mia","Ich bin Webdesignerin. Ich habe fünf Jahre in einer Agentur in Porto gearbeitet. Ich habe meistens Websites für Restaurants und Hotels gemacht. Ich arbeite fast immer auf Englisch. Mein Englisch ist sehr gut."],["Herr Brandt","Dann haben Sie gute Chancen. Viele Agenturen arbeiten international. Also, so machen Sie es: Zuerst schreiben Sie einen Lebenslauf. Auf Deutsch, mit Foto. Dann schreiben Sie ein Anschreiben – kurz und klar. Danach suchen Sie Firmen mit Englisch. Und zum Schluss rufen Sie an. Telefonieren ist in Deutschland oft besser als eine E-Mail."],["Mia","Telefonieren? Auf Deutsch? Ich telefoniere nie auf Deutsch. Nur mit Elif. Und mit der Arztpraxis."],["Herr Brandt","Dann ist es Zeit. Ich korrigiere Ihren Lebenslauf. Bringen Sie ihn am Montag mit."],["Am Wochenende schreibt Mia. Zuerst den Lebenslauf: Name, Adresse, Geburtsdatum, Ausbildung, Berufserfahrung, Sprachen. Dann das Anschreiben. Sie schreibt es fünfmal. Danach liest Jonas es. Er korrigiert drei Fehler. Herr Brandt korrigiert am Montag noch elf."],["Am Dienstagabend kommt Jonas von der Arbeit. Er hat einen Zettel in der Hand."],["Jonas","Mia! Ein Gast im Café ist Chefin von einer Agentur. Sie kommt oft zum Frühstück, meistens am Dienstag. Heute hat sie erzählt: Sie sucht eine Webdesignerin. Dringend! Sie hat mir die Anzeige gegeben."],["Mia liest:"],["Agentur Keller – Design & Web, Freiburg. Wir suchen: Webdesigner (m/w/d), ab Januar, Vollzeit. Sie haben: Erfahrung mit Websites, Kreativität, gutes Englisch. Deutsch: Grundkenntnisse reichen – Sie lernen bei uns weiter. Interesse? Bitte rufen Sie zuerst an: Frau Keller, 0761 / 45 39 20."],["Mia","Grundkenntnisse reichen! Das bin ich!"],["Jonas","Ruf sie morgen an!"],["Mia","Anrufen. Auf Deutsch. Bei einer Chefin."],["Mia sieht die Telefonnummer an. Ihr Herz klopft schon jetzt."]],"q":["Was steht fast immer in den Stellenanzeigen?","Was hat Mia in Portugal gemacht?","Was soll Mia zuerst, dann, danach und zum Schluss machen?","Richtig oder falsch? Frau Keller sucht eine Webdesignerin mit sehr gutem Deutsch.","Und du? Was machst du oft, manchmal, nie? Wie suchst du Arbeit in deinem Land?"],"a":["„Sehr gute Deutschkenntnisse (C1)“. „Aber fast immer steht da: Sehr gute Deutschkenntnisse.“","Sie war Webdesignerin in einer Agentur in Porto, fünf Jahre lang. „Ich habe fünf Jahre in einer Agentur in Porto gearbeitet.“","Lebenslauf schreiben, Anschreiben schreiben, Firmen mit Englisch suchen, anrufen. Herr Brandt: „Zuerst … Dann … Danach … Und zum Schluss rufen Sie an.“","Falsch. „Deutsch: Grundkenntnisse reichen.“","Example: Ich lese oft. Ich gehe manchmal ins Kino. Ich rauche nie. In meinem Land sucht man Arbeit meistens im Internet."],"w":[["meistens / selten","mostly / rarely","Ich habe meistens Websites gemacht."],["zuerst / danach / zum Schluss","first / after that / finally","Zuerst schreiben Sie einen Lebenslauf."],["die Stellenanzeige, die Stellenanzeigen","job advert","Sie sucht Stellenanzeigen."],["die Firma, die Firmen","company","Alle Firmen wollen sehr gutes Deutsch."],["die Agentur, die Agenturen","agency","in einer Agentur in Porto"],["der Lebenslauf, die Lebensläufe","CV","Ich korrigiere Ihren Lebenslauf."],["das Anschreiben, die Anschreiben","cover letter","Dann schreiben Sie ein Anschreiben."],["die Ausbildung, die Ausbildungen","education, training","Ausbildung, Berufserfahrung, Sprachen"],["die Erfahrung, die Erfahrungen","experience","Erfahrung mit Websites"],["die Sprache, die Sprachen","language","Sprachen"],["telefonieren","to phone","Ich telefoniere nie auf Deutsch."],["korrigieren","to correct","Er korrigiert drei Fehler."],["der Gast, die Gäste","guest","Ein Gast im Café ist Chefin."],["dringend","urgent(ly)","Sie sucht eine Webdesignerin. Dringend!"],["reichen","to be enough","Grundkenntnisse reichen."]],"c":[["Haben Sie einen Moment Zeit?","Do you have a moment?","Herr Brandt, haben Sie einen Moment Zeit?"],["gute Chancen haben","to have a good chance","Dann haben Sie gute Chancen."],["ab Januar","from January","ab Januar, Vollzeit"],["Vollzeit / Teilzeit","full-time / part-time","Vollzeit"]],"x":[["die Schweiz","Switzerland",""],["der Iran","Iran",""],["Afghanistan","Afghanistan",""],["die USA (plural only)","the USA",""],["Spanien","Spain",""]],"g":["Häufigkeit und Reihenfolge",["How often? immer (100%) → meistens → oft → manchmal → selten → nie (0%).","These words usually come after the verb: Ich telefoniere nie auf Deutsch.","Order of steps: zuerst → dann → danach → zum Schluss.","In position 1, the verb comes next (position 2): Zuerst schreiben Sie …, Danach liest Jonas es.","Beispiele: Sie kommt oft zum Frühstück, meistens am Dienstag. · Zum Schluss rufen Sie an."]]},{"n":44,"t":"Am Telefon","l":"A1","review":false,"p":[["Mittwoch, acht Uhr. Mia sitzt auf dem Sofa. Vor ihr liegt ein Zettel mit Sätzen: Guten Tag, mein Name ist … Ich rufe an wegen der Anzeige … Jonas sitzt neben ihr. Felix sitzt auf dem Zettel."],["Jonas","Wir üben noch einmal. Ich bin Frau Keller. „Keller, Agentur Keller, guten Tag?“"],["Mia","Guten Tag, mein Name ist Mia Costa. Ich rufe an wegen der Anzeige."],["Jonas","Perfekt. Jetzt ruf an. Ich bin hier."],["Mia wählt die Nummer. Es klingelt. Einmal. Zweimal. Dreimal."],["Frau Keller","Agentur Keller, Keller am Apparat. Guten Morgen!"],["Mia","Guten Morgen! Mein Name ist Mia Costa. Ich rufe an wegen der Anzeige. Sie suchen eine Webdesignerin?"],["Frau Keller","Ja, genau! Woher kommen Sie, Frau Costa? Aus Spanien?"],["Mia","Nein, nicht aus Spanien, sondern aus Portugal. Aus Porto."],["Frau Keller","Ah, Porto! Schöne Stadt. Sie sprechen kein Deutsch, oder? Sollen wir Englisch sprechen?"],["Mia","Doch! Ich spreche Deutsch. Ein bisschen. Ich lerne seit September."],["Frau Keller","Seit September? Respekt! Haben Sie keine Erfahrung mit Online-Shops?"],["Mia","Doch, ich habe drei Online-Shops gemacht. Für ein Hotel, für einen Weinhändler und für eine Bäckerei."],["Frau Keller","Sehr gut. Wie ist Ihr Nachname noch mal? Können Sie das bitte buchstabieren?"],["Mia","C – O – S – T – A."],["Frau Keller","Danke. Kommen Sie doch zu einem Gespräch. Haben Sie am Montag Zeit? Um zehn?"],["Mia","Am Montag um zehn habe ich leider Kurs."],["Frau Keller","Kein Problem. Dann nicht am Montag, sondern am Dienstag. Am fünften Dezember, um vierzehn Uhr. Geht das?"],["Mia","Ja, das geht!"],["Frau Keller","Bringen Sie bitte Ihren Lebenslauf und Ihr Portfolio mit. Unsere Adresse ist Bertoldstraße 18, dritter Stock. Bis Dienstag, Frau Costa!"],["Mia","Bis Dienstag! Auf Wiederhören!"],["Mia legt auf. Sie sieht Jonas an. Dann schreit sie: „Ich habe ein Vorstellungsgespräch!“ Felix springt vom Zettel. Jonas umarmt sie."],["Jonas","Du hast „Auf Wiederhören“ gesagt! Wie eine echte Deutsche!"],["Um neun klopft es an der Tür. Frau Schulz."],["Frau Schulz","Guten Morgen, Frau Costa. Entschuldigung, eine Sache noch. Am ersten Dezember ist die Miete fällig. Sie haben doch ein deutsches Konto, oder?"],["Mia","Ein deutsches Konto? Nein … Ich habe nur ein Konto in Portugal."],["Frau Schulz","Dann müssen Sie schnell eins eröffnen. Ohne Konto keine Überweisung. Und ohne Überweisung …"],["Sie sagt den Satz nicht zu Ende. Aber Mia versteht."]],"q":["Woher kommt Mia? Was denkt Frau Keller zuerst?","Wofür hat Mia Online-Shops gemacht?","Wann ist das Vorstellungsgespräch?","Richtig oder falsch? Mia hat ein deutsches Konto.","Und du? Hast du schon einmal auf Deutsch telefoniert? Buchstabiere deinen Nachnamen."],"a":["Aus Portugal. Frau Keller denkt: aus Spanien. „Nein, nicht aus Spanien, sondern aus Portugal.“","Für ein Hotel, einen Weinhändler und eine Bäckerei. „Für ein Hotel, für einen Weinhändler und für eine Bäckerei.“","Am Dienstag, 5. Dezember, um 14 Uhr. „Am fünften Dezember, um vierzehn Uhr.“","Falsch. „Nein … Ich habe nur ein Konto in Portugal.“","Example: Nein, noch nie. Mein Nachname ist Taylor: T – A – Y – L – O – R."],"w":[["doch","yes (after a negative question)","Sie sprechen kein Deutsch? – Doch!"],["sondern","but (rather)","nicht aus Spanien, sondern aus Portugal"],["der Satz, die Sätze","sentence","ein Zettel mit Sätzen"],["üben","to practise","Wir üben noch einmal."],["wählen","to dial; to choose","Mia wählt die Nummer."],["der Nachname, die Nachnamen","surname","Wie ist Ihr Nachname noch mal?"],["buchstabieren","to spell","Können Sie das bitte buchstabieren?"],["das Gespräch, die Gespräche","conversation, interview","Kommen Sie doch zu einem Gespräch."],["das Vorstellungsgespräch, die Vorstellungsgespräche","job interview","Ich habe ein Vorstellungsgespräch!"],["auflegen","to hang up","Mia legt auf."],["schreien","to shout","Dann schreit sie."],["das Konto, die Konten","bank account","Sie haben doch ein deutsches Konto?"],["eröffnen","to open (an account)","Dann müssen Sie schnell eins eröffnen."],["die Überweisung, die Überweisungen","bank transfer","Ohne Konto keine Überweisung."],["fällig","due","Am ersten Dezember ist die Miete fällig."]],"c":[["Ich rufe an wegen …","I'm calling about …","Ich rufe an wegen der Anzeige."],["… am Apparat","… speaking (phone)","Keller am Apparat."],["Geht das? – Ja, das geht.","Is that okay? – Yes, that works.","Geht das?"],["Auf Wiederhören!","Goodbye! (on the phone)","Bis Dienstag! Auf Wiederhören!"]],"x":[["England","England",""],["Polen","Poland",""],["Deutsch","German (language)",""],["Englisch","English",""],["Persisch","Persian",""]],"g":["ja, nein, doch und sondern",["Positive question → ja or nein: Sprechen Sie Deutsch? – Ja. / Nein.","Negative question (with nicht / kein) → doch = \"yes, I do!\": Sie sprechen kein Deutsch? – Doch!","sondern corrects a negative: nicht A, sondern B: nicht aus Spanien, sondern aus Portugal.","aber = but (contrast) · sondern = but rather (correction, only after nicht/kein).","Beispiele: Haben Sie keine Erfahrung? – Doch, ich habe drei Online-Shops gemacht. · Nicht am Montag, sondern am Dienstag."]]},{"n":45,"t":"Miete, Konto, Geld","l":"A1","review":false,"p":[["Donnerstag, nach dem Kurs. Mia sitzt in einer Bank am Bertoldsbrunnen. Vor ihr sitzt ein Berater, Herr Wagner. Er trägt eine Krawatte mit kleinen Fahrrädern."],["Herr Wagner","Sie möchten also ein Girokonto eröffnen. Haben Sie Ihren Pass und Ihre Anmeldung dabei?"],["Mia","Ja, hier. Die Anmeldung war ein Abenteuer."],["Herr Wagner","Das glaube ich. Also: Das Konto kostet vier Euro neunzig im Monat. Sie bekommen eine Karte für den Geldautomaten und eine App."],["Mia","Vier Euro neunzig? Jeden Monat? Das ist ein bisschen teuer."],["Herr Wagner","Für Studenten und Azubis ist es kostenlos. Sind Sie Studentin?"],["Mia","Nein. Ich lerne nur Deutsch."],["Herr Wagner","Dann leider nicht. Wie viel Geld möchten Sie einzahlen?"],["Mia denkt an ihr Konto in Portugal. Vierhundertzwölf Euro."],["Mia","Wie viel muss ich einzahlen?"],["Herr Wagner","Nichts. Null Euro. Aber Sie brauchen Geld für die Miete, nehme ich an. Wie hoch ist die Miete?"],["Mia","Sechshundertfünfzig Euro. Warm."],["Herr Wagner","Und wie viel verdienen Sie im Monat?"],["Mia","Im Moment … nichts. Ich habe am Dienstag ein Vorstellungsgespräch."],["Herr Wagner","Dann viel Glück! Wirklich."],["Sie unterschreibt sieben Formulare. Nach einer Stunde hat Mia ein deutsches Konto. Aber kein Geld darauf."],["Am Abend ruft sie Mama an. Sie will nicht fragen. Aber sie muss."],["Mia","Mama … ich brauche Hilfe. Nur dieses Mal. Ich habe nur noch vierhundertzwölf Euro, und die Miete kostet sechshundertfünfzig."],["Mama","Mia! Warum sagst du das erst jetzt? Wie viel brauchst du?"],["Mia","Zweihundertfünfzig. Vielleicht dreihundert. Ich zahle alles zurück. Versprochen."],["Mama","Ich schicke dir tausend Euro."],["Mia","Tausend? Nein, Mama, das ist zu viel!"],["Mama","Das ist nicht zu viel. Ein neues Leben ist teuer. Und du bist meine Tochter. Basta."],["Mia sagt danke. Viele Male. Nach dem Gespräch weint sie ein bisschen. Aus Dankbarkeit, aus Stolz, aus Müdigkeit."],["Dann macht sie einen Plan auf einem Zettel:"],["Miete","650 €"],["Essen","250 €"],["Handy und Internet","40 €"],["Deutschkurs","360 €"],["Zusammen","1.300 € im Monat."],["Eintausenddreihundert Euro im Monat. Ohne Kino, ohne Pizza, ohne Pastéis."],["Sie braucht diesen Job. Am Dienstag um vierzehn Uhr. Vier Tage."],["Sie macht den Laptop auf. Das Portfolio muss perfekt sein. Aber der Laptop macht ein komisches Geräusch. Krrrrr. Klick. Dann ist der Bildschirm blau."]],"q":["Was braucht Mia für das Konto?","Wie viel kostet das Konto im Monat?","Wie viel Geld schickt Mama?","Richtig oder falsch? Mia braucht ungefähr 1.300 Euro im Monat.","Und du? Wie viel kostet eine Wohnung in deiner Stadt? Wie viel Geld brauchst du im Monat für Essen?"],"a":["Ihren Pass und ihre Anmeldung. „Haben Sie Ihren Pass und Ihre Anmeldung dabei?“","Vier Euro neunzig. „Das Konto kostet vier Euro neunzig im Monat.“","Tausend Euro. „Ich schicke dir tausend Euro.“","Richtig. Her plan: „Zusammen: 1.300 € im Monat.“","Example: Eine Wohnung kostet in meiner Stadt ungefähr tausend Euro. Für Essen brauche ich dreihundert Euro."],"w":[["hundert / tausend","hundred / thousand","Ich schicke dir tausend Euro."],["wie viel / wie viele","how much / how many","Wie viel brauchst du?"],["der Berater, die Berater","adviser","Vor ihr sitzt ein Berater."],["das Girokonto, die Girokonten","current account","Sie möchten ein Girokonto eröffnen."],["der Geldautomat, die Geldautomaten","cash machine","eine Karte für den Geldautomaten"],["kostenlos","free (of charge)","Für Studenten ist es kostenlos."],["einzahlen","to pay in","Wie viel muss ich einzahlen?"],["hoch","high","Wie hoch ist die Miete?"],["verdienen","to earn","Wie viel verdienen Sie im Monat?"],["zurückzahlen","to pay back","Ich zahle alles zurück."],["die Tochter, die Töchter","daughter","Du bist meine Tochter."],["das Leben","life","Ein neues Leben ist teuer."],["das Internet","internet","Handy und Internet: 40 €"],["das Geräusch, die Geräusche","noise","ein komisches Geräusch"],["ungefähr","about, roughly","ungefähr 1.300 Euro"]],"c":[["zu viel","too much","Das ist zu viel!"],["im Monat","per month","1.300 € im Monat"],["… warm / kalt","rent incl. / excl. heating","Sechshundertfünfzig Euro. Warm."],["Versprochen!","Promise!","Ich zahle alles zurück. Versprochen."]],"x":[["Französisch","French",""],["Italienisch","Italian",""],["Spanisch","Spanish",""],["Türkisch","Turkish",""],["Arabisch","Arabic",""]],"g":["große Zahlen, wie viel / wie viele, zu",["100 hundert · 650 sechshundertfünfzig · 1.000 (ein)tausend · 1.300 eintausenddreihundert. Big numbers are written as one word.","Germans write a dot for thousands (1.300) and a comma for decimals (412,35).","wie viel + uncountable (Geld, Zeit) · wie viele + plural (Wie viele Formulare?).","zu + adjective = too: zu teuer, zu viel, zu klein.","Beispiele: Wie viel verdienen Sie im Monat? · Tausend? Das ist zu viel!"]]},{"n":46,"t":"Der Schreibtisch","l":"A1","review":false,"p":[["Freitag, neun Uhr. Mia steht in einem Computerladen in der Altstadt. Der Verkäufer hat lange Haare und eine Kaffeetasse in der Hand."],["Verkäufer","Hm. Die Festplatte ist okay. Ihre Daten sind sicher. Aber das Motherboard ist kaputt. Die Reparatur dauert eine Woche."],["Mia","Eine Woche? Ich habe am Dienstag ein Vorstellungsgespräch!"],["Verkäufer","Tut mir leid. Wir haben zu viele Aufträge. Weihnachtszeit."],["Mia ruft Elif an. Elif hat immer eine Lösung."],["Elif","Kein Problem! Komm in die Unibibliothek. Im ersten Stock gibt es einen Computerraum. Ich habe einen Studentenausweis. Du kannst meinen Computerplatz benutzen."],["Im Computerraum ist es still. Nur Tastaturen klicken. Mia lädt ihre Dateien aus der Cloud. Zum Glück!"],["Zuerst sieht sie sich die Website von der Agentur Keller an. Die Agentur ist modern. Auf den Fotos sieht man ein helles Großraumbüro. Es gibt große Schreibtische, bunte Bürostühle, eine riesige Kaffeemaschine und einen Tischkicker. Auf einem Foto sitzt ein Hund unter einem Schreibtisch."],["Elif","Ein Bürohund! Das ist ein gutes Zeichen."],["Dann arbeitet Mia an ihrem Portfolio. Drei Projekte aus Porto: die Website für das Hotel, der Onlineshop für den Weinhändler und die Website für die Bäckerei. Und ein neues Projekt: eine Website für Café Bächle. Das Café gibt es noch nicht. Aber die Website gibt es jetzt."],["Am Abend kocht Jonas eine Gemüsesuppe. Er sieht das Portfolio auf Elifs Laptop. Er sieht die Website für Café Bächle. Die Startseite zeigt eine Kaffeetasse, ein Bächle und einen grauen Kater."],["Jonas","Mia … Das ist mein Café. Das ist genau mein Café."],["Mia","Ich weiß."],["Am Wochenende übt Mia mit Jonas und Elif. Herr Brandt hat eine Liste geschickt: Typische Fragen im Vorstellungsgespräch. Warum möchten Sie bei uns arbeiten? Was sind Ihre Stärken? Was sind Ihre Schwächen? Wo sehen Sie sich in fünf Jahren?"],["Jonas","Was sind deine Schwächen?"],["Mia","Ich kann nicht backen. Ich kann nicht Fußball spielen. Ich verliere immer meine Schlüssel."],["Elif","Sag das nicht im Gespräch!"],["Dienstag, dreizehn Uhr fünfzehn. Mia ist fertig. Schwarze Hose, weiße Bluse, die grüne Winterjacke. Das Portfolio ist auf einem USB-Stick. Die Mappe mit dem Lebenslauf ist in der Tasche."],["Sie geht zur Wohnungstür. Sie sucht in der Jackentasche. In der Handtasche. Auf der Kommode."],["Kein Schlüssel."],["Ihr Hausschlüssel, ihr Wohnungsschlüssel, ihr Fahrradschlüssel – alle am selben Schlüsselbund. Und der Schlüsselbund ist weg."]],"q":["Was ist mit Mias Laptop los? Wie lange dauert die Reparatur?","Wo arbeitet Mia an ihrem Portfolio?","Was sieht man auf den Fotos von der Agentur Keller?","Richtig oder falsch? Das Café Bächle gibt es schon.","Und du? Was sind deine Stärken und deine Schwächen? Was liegt auf deinem Schreibtisch?"],"a":["Das Motherboard ist kaputt. Die Reparatur dauert eine Woche. „Die Reparatur dauert eine Woche.“","Im Computerraum in der Unibibliothek. Elif: „Im ersten Stock gibt es einen Computerraum.“","Ein helles Großraumbüro, Schreibtische, Bürostühle, eine Kaffeemaschine, einen Tischkicker und einen Bürohund.","Falsch. „Das Café gibt es noch nicht. Aber die Website gibt es jetzt.“","Example: Ich bin geduldig und kreativ. Ich bin manchmal zu langsam. Auf meinem Schreibtisch liegen ein Laptop und eine Kaffeetasse."],"w":[["der Schreibtisch, die Schreibtische","desk","Es gibt große Schreibtische."],["der Bürostuhl, die Bürostühle","office chair","bunte Bürostühle"],["das Büro, die Büros","office","ein helles Großraumbüro"],["die Kaffeemaschine, die Kaffeemaschinen","coffee machine","eine riesige Kaffeemaschine"],["der Computerladen, die Computerläden","computer shop","in einem Computerladen"],["die Reparatur, die Reparaturen","repair","Die Reparatur dauert eine Woche."],["die Lösung, die Lösungen","solution","Elif hat immer eine Lösung."],["der Studentenausweis, die Studentenausweise","student ID","Ich habe einen Studentenausweis."],["die Datei, die Dateien","file","Mia lädt ihre Dateien."],["die Tastatur, die Tastaturen","keyboard","Nur Tastaturen klicken."],["die Stärke / die Schwäche","strength / weakness","Was sind Ihre Stärken?"],["verlieren","to lose","Ich verliere immer meine Schlüssel."],["die Hose, die Hosen","trousers","Schwarze Hose, weiße Bluse."],["die Bluse, die Blusen","blouse","weiße Bluse"],["der Schlüssel, die Schlüssel","key","Kein Schlüssel."]],"c":[["Zum Glück!","Luckily!","Zum Glück!"],["ein gutes Zeichen","a good sign","Das ist ein gutes Zeichen."],["Wo sehen Sie sich in fünf Jahren?","Where do you see yourself in five years?","Wo sehen Sie sich in fünf Jahren?"],["der Schlüsselbund","bunch of keys","alle am selben Schlüsselbund"]],"x":[["Ich spreche ein bisschen Deutsch.","I speak a little German.",""],["Ich komme aus dem Iran.","I come from Iran.",""],["das Gefühl, die Gefühle","feeling",""],["die Angst, die Ängste","fear",""],["die Freude, die Freuden","joy",""]],"g":["zusammengesetzte Nomen (Komposita)",["German joins nouns into one long word: der Schreibtisch, die Kaffeemaschine, der Hausschlüssel.","The last word decides the article and the plural: das Haus + die Tür → die Haustür.","The first word describes the second: Kaffeetasse = a cup for coffee.","Sometimes there is a linking -s- or -n-: Arbeitsplatz, Wochenende.","Beispiele: Es gibt eine riesige Kaffeemaschine. · Ihr Hausschlüssel ist weg."]]},{"n":47,"t":"Wo ist mein Schlüssel?","l":"A1","review":false,"p":[["Dreizehn Uhr siebzehn. Mia sucht."],["Auf dem Tisch? Nein. Da liegen nur Papiere. Unter dem Tisch? Nein. Auf dem Sofa? Nein. Zwischen den Kissen? Nur ein Kugelschreiber und zwei Cent. Unter dem Sofa? Staub. Viel Staub."],["In der Küche","Neben der Kaffeemaschine? Nein. Auf dem Kühlschrank? Nein. Im Kühlschrank? Mia macht ihn auf. Butter, Milch, Käse. Kein Schlüssel. Natürlich nicht. Aber man weiß ja nie."],["Im Bad","Neben dem Waschbecken? In der Dusche? Hinter der Tür? Nichts."],["Dreizehn Uhr fünfundzwanzig. Mia ruft Jonas an. Er ist im Café."],["Jonas","Mia! Bist du schon unterwegs?"],["Mia","Nein! Mein Schlüssel ist weg! Ich kann die Tür nicht abschließen. Und unten kann ich die Haustür nicht aufmachen!"],["Jonas","Ruhig, ganz ruhig. Wo war er gestern Abend?"],["Mia","Gestern Abend? Ich bin nach Hause gekommen. Ich habe die Tür aufgemacht. Dann … das Telefon hat geklingelt. Elif."],["Jonas","Und der Schlüssel? Steckt er vielleicht noch außen in der Tür?"],["Mia macht die Tür auf. Sie sieht auf das Schloss. Nein. Kein Schlüssel. Aber vor der Tür, auf der Fußmatte, liegen ein paar graue Haare."],["Graue Haare. Katzenhaare."],["Mia","Felix!"],["Sie läuft die Treppe hinunter und klingelt bei Frau Schulz."],["Frau Schulz","Frau Costa? Sie sehen so elegant aus!"],["Mia","Frau Schulz, wo ist Felix?"],["Frau Schulz","In seinem Korb, im Wohnzimmer. Neben der Heizung. Warum?"],["Felix liegt in seinem Korb. Er schläft. Und unter Felix glänzt etwas. Etwas aus Metall."],["Der Schlüsselbund."],["Frau Schulz","Ach, Felix! Er sammelt Sachen. Alles, was glänzt. Letzte Woche war meine Brille in seinem Korb. Und zwei Löffel. Sie müssen den Schlüssel gestern in der Tür gelassen haben."],["Mia","Felix, du bist ein Dieb! Ein süßer Dieb, aber ein Dieb!"],["Felix","Miau."],["Dreizehn Uhr achtunddreißig. Mia rennt zur Straßenbahn. Die Bahn steht schon an der Haltestelle. Die Türen gehen zu – nein, ein Mann hält die Tür auf. Mia springt hinein."],["Vierzehn Uhr eins. Bertoldstraße 18, dritter Stock. Mia steht vor einer Glastür. Ihr Herz klopft. Sie atmet tief ein. Und aus."],["Auf der anderen Seite der Tür sitzt ein großer brauner Hund. Und neben ihm steht eine Frau mit kurzen roten Haaren. Mia kennt sie. Woher?"]],"q":["Wo sucht Mia den Schlüssel in der Küche?","Was liegt auf der Fußmatte?","Wo ist der Schlüsselbund am Ende?","Richtig oder falsch? Mia kommt zu spät zum Vorstellungsgespräch.","Und du? Wo liegt dein Schlüssel jetzt? Was ist auf, unter und neben deinem Tisch?"],"a":["Neben der Kaffeemaschine, auf dem Kühlschrank und im Kühlschrank. „Neben der Kaffeemaschine? Nein. Auf dem Kühlschrank? Nein. Im Kühlschrank?“","Graue Haare – Katzenhaare. „Auf der Fußmatte liegen ein paar graue Haare.“","Unter Felix, in seinem Korb. „Und unter Felix glänzt etwas.“","Falsch (fast!). She arrives at 14:01 – one minute late, but there.","Example: Mein Schlüssel liegt in meiner Tasche. Auf meinem Tisch steht ein Laptop. Unter dem Tisch liegt meine Tasche."],"w":[["unter / über","under / over, above","Unter dem Sofa? Staub."],["neben / zwischen","next to / between","Zwischen den Kissen?"],["hinter / vor","behind / in front of","Hinter der Tür? Nichts."],["das Kissen, die Kissen","cushion, pillow","zwischen den Kissen"],["der Kugelschreiber, die Kugelschreiber","pen","ein Kugelschreiber und zwei Cent"],["der Staub","dust","Staub. Viel Staub."],["das Waschbecken, die Waschbecken","washbasin","Neben dem Waschbecken?"],["abschließen","to lock","Ich kann die Tür nicht abschließen."],["das Schloss, die Schlösser","lock","Sie sieht auf das Schloss."],["die Heizung, die Heizungen","heating, radiator","Neben der Heizung."],["das Wohnzimmer, die Wohnzimmer","living room","im Wohnzimmer"],["der Korb, die Körbe","basket","In seinem Korb."],["glänzen","to shine, glitter","Unter Felix glänzt etwas."],["der Dieb, die Diebe","thief","Felix, du bist ein Dieb!"],["die Haltestelle, die Haltestellen","(bus/tram) stop","an der Haltestelle"]],"c":[["Man weiß ja nie.","You never know.","Aber man weiß ja nie."],["Ruhig, ganz ruhig.","Calm down.","Ruhig, ganz ruhig."],["unterwegs sein","to be on the way","Bist du schon unterwegs?"],["die Tür aufhalten","to hold the door","Ein Mann hält die Tür auf."]],"x":[["die Liebe","love",""],["nervös","nervous",""],["entspannt","relaxed",""],["gestresst","stressed",""],["zufrieden","satisfied",""]],"g":["Wo? – Wechselpräpositionen mit Dativ",["Nine prepositions can take dative or accusative: in, an, auf, unter, über, neben, hinter, vor, zwischen.","For Wo? (location, no movement) → dative: auf dem Tisch, unter dem Sofa, neben der Kaffeemaschine, zwischen den Kissen.","(For Wohin? – movement – they take the accusative. More in story 56.)","Typical verbs for Wo?: liegen, stehen, sitzen, hängen, sein.","Beispiele: Der Schlüssel liegt unter dem Kater. · Felix liegt in seinem Korb, neben der Heizung."]]},{"n":48,"t":"Das Vorstellungsgespräch","l":"A1","review":false,"p":[["Dann weiß Mia es","Die Frau mit den roten Haaren sitzt jeden Dienstag im Café Sonne. Immer am Fenster. Immer ein Cappuccino und ein Croissant."],["Frau Keller","Frau Costa! Herzlich willkommen. Ich bin Sabine Keller. Und das ist Otto, unser Bürohund. Er beißt nicht."],["Mia","Guten Tag! Entschuldigung, ich bin eine Minute zu spät. Normalerweise komme ich nicht zu spät."],["Frau Keller","Eine Minute? Kein Problem. Kommen Sie. Mein Kollege wartet schon."],["Im Besprechungsraum sitzt ein junger Mann mit Bart und schwarzem Pullover. Er lächelt nicht."],["Frau Keller","Das ist Max Berger, unser Art Director. Bitte, setzen Sie sich. Möchten Sie etwas trinken? Wasser? Kaffee?"],["Mia","Ein Wasser, bitte."],["Max","Frau Costa, warum möchten Sie bei uns arbeiten?"],["Mia","Ich mag Ihre Projekte sehr. Sie sind modern, aber nicht kalt. Und Sie arbeiten international. Ich spreche Portugiesisch, Englisch und Spanisch. Mein Deutsch ist noch nicht gut. Aber ich lerne schnell."],["Max","Wie lange lernen Sie schon Deutsch?"],["Mia","Seit drei Monaten."],["Max","Drei Monate? Und Sie machen ein Vorstellungsgespräch auf Deutsch?"],["Mia","Ja. Es ist nicht leicht. Aber ich möchte nicht immer Englisch sprechen. Ich wohne hier. Ich möchte hier leben."],["Max schreibt etwas auf. Mia sieht nicht, was."],["Frau Keller","Was sind Ihre Schwächen?"],["Mia denkt an Elif","Sag das nicht!"],["Mia","Ich bin manchmal zu perfektionistisch. Ich arbeite nicht gern schnell und schlecht. Ich arbeite lieber langsam und gut. Und … ich verliere manchmal meine Schlüssel."],["Frau Keller lacht. Max nicht."],["Dann zeigt Mia ihr Portfolio. Das Hotel. Der Onlineshop. Die Bäckerei. Und zum Schluss: Café Bächle."],["Max","Café Bächle? Das Café kenne ich nicht. Wo ist das?"],["Mia","Es existiert noch nicht. Es ist ein Traum von einem Freund. Ich habe die Website für seinen Traum gemacht."],["Max sieht lange auf den Bildschirm. Dann sagt er zum ersten Mal etwas Freundliches."],["Max","Das ist sehr gut. Die Farben, die Fotos, der Kater. Das hat eine Seele."],["Frau Keller","Letzte Frage: Wie viel möchten Sie verdienen?"],["Mia","Das … weiß ich nicht genau. Was ist normal in Freiburg?"],["Frau Keller","Das besprechen wir später. Frau Costa, vielen Dank. Wir haben noch zwei andere Kandidaten. Wir rufen Sie bis Freitag an."],["Draußen auf der Straße zittern Mias Knie. War das gut? War das schlecht? Max hat nur einmal gelächelt. Oder war das gar kein Lächeln?"],["Mittwoch","kein Anruf. Donnerstag: kein Anruf. Freitag: Mia hat das Handy immer in der Hand. Zehn Uhr. Zwölf Uhr. Sechzehn Uhr. Achtzehn Uhr."],["Kein Anruf."]],"q":["Woher kennt Mia Frau Keller?","Wie lange lernt Mia schon Deutsch?","Was sagt Mia über ihre Schwächen?","Richtig oder falsch? Max findet die Website von Café Bächle schlecht.","Und du? Warum möchtest du Deutsch lernen? Was kannst du noch nicht gut? (Ich kann noch nicht …)"],"a":["Aus dem Café Sonne. Frau Keller sitzt dort jeden Dienstag. „Die Frau mit den roten Haaren sitzt jeden Dienstag im Café Sonne.“","Seit drei Monaten. „Seit drei Monaten.“","She is sometimes too perfectionist – and she sometimes loses her keys. „Ich bin manchmal zu perfektionistisch … Und … ich verliere manchmal meine Schlüssel.“","Falsch. „Das ist sehr gut. … Das hat eine Seele.“","Example: Ich möchte in Deutschland arbeiten. Ich kann noch nicht gut telefonieren."],"w":[["der Kollege, die Kollegen / die Kollegin","colleague","Mein Kollege wartet schon."],["der Besprechungsraum, die Besprechungsräume","meeting room","Im Besprechungsraum sitzt ein Mann."],["beißen","to bite","Er beißt nicht."],["sich setzen","to sit down","Bitte, setzen Sie sich."],["leicht","easy; light","Es ist nicht leicht."],["leben","to live","Ich möchte hier leben."],["aufschreiben","to write down","Max schreibt etwas auf."],["existieren","to exist","Es existiert noch nicht."],["die Seele, die Seelen","soul","Das hat eine Seele."],["besprechen","to discuss","Das besprechen wir später."],["später","later","Das besprechen wir später."],["der Kandidat, die Kandidaten","candidate","zwei andere Kandidaten"],["der Anruf, die Anrufe","phone call","Kein Anruf."],["das Knie, die Knie","knee","Mias Knie zittern."],["der Bart, die Bärte","beard","ein junger Mann mit Bart"]],"c":[["zu spät kommen","to be late","Normalerweise komme ich nicht zu spät."],["Wie lange …schon?","How long … (already)?","Wie lange lernen Sie schon Deutsch?"],["noch nicht","not yet","Mein Deutsch ist noch nicht gut."],["Wir rufen Sie an.","We'll call you.","Wir rufen Sie bis Freitag an."]],"x":[["lieben","to love",""],["Super!","super!",""],["Prima!","great!",""],["Wie schön!","how lovely!",""],["Schade!","what a pity!",""]],"g":["Die Position von nicht",["nicht + whole sentence → at the end: Er lächelt nicht. · Das Café kenne ich nicht.","But before these: adjectives (nicht leicht), adverbs (nicht gern), places (nicht in Freiburg), the second verb part (Ich möchte nicht immer Englisch sprechen).","nicht before a word = only that word is negated: Ich komme nicht zu spät.","noch nicht = not yet: Mein Deutsch ist noch nicht gut.","Beispiele: Es ist nicht leicht. · Max lächelt nicht."]]},{"n":49,"t":"Auf dem Weihnachtsmarkt","l":"A1","review":false,"p":[["Samstag. Mia liegt auf dem Sofa. Sie will nicht raus. Kein Anruf, kein Job."],["Um fünf Uhr kommt eine Nachricht in der Gruppe „Lindenstraße & Co.“:"],["Elif","Weihnachtsmarkt! Heute! Treffpunkt: Viertel nach sechs am Rathausplatz, beim großen Weihnachtsbaum. Keine Ausreden, Mia!"],["Tom","Ich komme um halb sieben. Ich arbeite bis sechs."],["Jonas","Ich hole Mia ab. Um sechs. Sie kommt mit. 😊"],["Um sechs klopft Jonas. Mia zieht die grüne Jacke an, die graue Mütze und die Handschuhe."],["Der Weihnachtsmarkt ist wie ein Traum. Kleine Holzhäuser mit Lichtern. Es riecht nach Zimt, nach Glühwein, nach gebrannten Mandeln und nach Bratwurst. Ein Chor singt."],["Elif kommt zu spät, natürlich. Um fünf nach halb sieben. Tom kommt um Viertel vor sieben, mit Bruno. Bruno trägt eine rote Weihnachtsmütze."],["Dann sieht Mia bekannte Gesichter. Frau Schulz, mit einem großen Mann."],["Frau Schulz","Frau Costa! Das ist mein Sohn Michael. Er ist schon heute gekommen, nicht erst an Weihnachten. Eine Überraschung!"],["Michael","Sie sind die Nachbarin mit dem Handy-Kurs? Danke! Jetzt ruft Mama mich jeden Tag an. Jeden Tag!"],["Und neben dem Glühweinstand stehen – Herr Brandt und Fátima. Zusammen. Herr Brandt hält Fátimas Hand."],["Elif","Aaaah! Herr Brandt!"],["Herr Brandt","Frau Yılmaz. Bitte. Nicht so laut."],["Alle trinken Glühwein. Paul trinkt Kinderpunsch. Tom isst seine zweite Bratwurst. Mia lacht wieder. Ein bisschen."],["Kurz vor sieben klingelt ihr Handy. Eine Freiburger Nummer. Mia geht ein paar Schritte weg, hinter ein Holzhaus."],["Frau Keller","Frau Costa? Hier ist Sabine Keller. Entschuldigen Sie – es ist Samstagabend. Ich wollte schon am Freitag anrufen, aber ich war den ganzen Tag beim Kunden in Basel."],["Mia","Kein Problem!"],["Frau Keller","Max hat gesagt: „Ruf sie heute noch an. Sonst nimmt eine andere Agentur sie.“ Also: Wir möchten Sie gern einstellen. Ab dem zweiten Januar. Haben Sie Interesse?"],["Mia sagt nichts. Drei Sekunden. Fünf Sekunden."],["Frau Keller","Frau Costa? Sind Sie noch da?"],["Mia","Ja! Ja, ja, ja! Ich habe Interesse! Sehr!"],["Frau Keller","Wunderbar. Den Vertrag schicke ich Ihnen am Montag. Schöne Feiertage, Frau Costa! Und grüßen Sie Jonas."],["Mia kommt zurück zum Glühweinstand. Alle sehen sie an."],["Mia","Ich habe den Job!"],["Elif schreit. Tom wirft seine Mütze in die Luft. Bruno bellt. Frau Schulz klatscht. Herr Brandt lächelt – richtig, mit Zähnen. Und Jonas hebt Mia hoch und dreht sie im Kreis."],["Später, um halb zehn, gehen Mia und Jonas zu Fuß nach Hause. Es schneit leise."],["Jonas","Und Weihnachten? Fliegst du nach Porto?"],["Mia","Die Flüge sind sehr teuer. Und am zweiten Januar beginnt mein Job. Ich weiß noch nicht."],["Jonas","Lena fragt: Möchtest du Weihnachten mit uns feiern? Mit der ganzen Familie Weber. Meine Eltern kommen auch."],["Seine Eltern. Mia bleibt stehen."]],"q":["Wann und wo treffen sich die Freunde?","Wer ist Michael? Warum ist er schon da?","Warum ruft Frau Keller erst am Samstag an?","Richtig oder falsch? Mia beginnt ihren Job am ersten Januar.","Und du? Wann stehst du normalerweise auf? Sag es informell (z. B. „um Viertel nach sieben“). Was machst du gern im Winter?"],"a":["Um Viertel nach sechs am Rathausplatz, beim großen Weihnachtsbaum. Elif's message.","Frau Schulz' Sohn. He came early as a surprise. „Er ist schon heute gekommen, nicht erst an Weihnachten.“","She was with a client in Basel all day on Friday. „Ich war den ganzen Tag beim Kunden in Basel.“","Falsch. „Ab dem zweiten Januar.“","Example: Ich stehe um Viertel vor sieben auf. Im Winter trinke ich gern Tee und gehe auf den Weihnachtsmarkt."],"w":[["Viertel nach / Viertel vor","quarter past / quarter to","Treffpunkt: Viertel nach sechs."],["halb (sieben)","half past (six)","Ich komme um halb sieben."],["kurz vor / kurz nach","just before / just after","Kurz vor sieben klingelt ihr Handy."],["der Weihnachtsmarkt, die Weihnachtsmärkte","Christmas market","Der Weihnachtsmarkt ist wie ein Traum."],["der Treffpunkt, die Treffpunkte","meeting point","Treffpunkt: am Rathausplatz"],["das Licht, die Lichter","light","Kleine Holzhäuser mit Lichtern."],["der Glühwein","mulled wine","Alle trinken Glühwein."],["der Chor, die Chöre","choir","Ein Chor singt."],["abholen","to pick up","Ich hole Mia ab."],["der Kunde, die Kunden","client, customer","beim Kunden in Basel"],["einstellen","to hire","Wir möchten Sie gern einstellen."],["der Vertrag, die Verträge","contract","Den Vertrag schicke ich am Montag."],["schneien","to snow","Es schneit leise."],["der Flug, die Flüge","flight","Die Flüge sind sehr teuer."],["die Feiertage (Plural)","holidays","Schöne Feiertage!"]],"c":[["Keine Ausreden!","No excuses!","Keine Ausreden, Mia!"],["Sind Sie noch da?","Are you still there?","Frau Costa? Sind Sie noch da?"],["Grüßen Sie …!","Say hello to …!","Und grüßen Sie Jonas."],["zu Fuß gehen","to walk","Sie gehen zu Fuß nach Hause."]],"x":[["Das stimmt nicht.","that's not right.",""],["Ich weiß nicht.","I don't know.",""],["Macht nichts.","never mind.",""],["Gern geschehen.","you're welcome.",""],["Einverstanden.","agreed.",""]],"g":["die Uhrzeit informell",["In everyday speech, Germans use a 12-hour clock with Viertel and halb.","Viertel nach sechs = 6:15 · Viertel vor sieben = 6:45.","halb sieben = 6:30! (halb means \"half way to\" the next hour, not \"half past\".)","fünf nach halb sieben = 6:35 · zehn vor sieben = 6:50 · kurz vor sieben = just before 7.","Beispiele: Treffpunkt: Viertel nach sechs. · Ich komme um halb sieben."]]},{"n":50,"t":"Große Wiederholung: Ein neues Leben","l":"A1","review":true,"p":[["Herr Brandt","Heute ist unser letzter Tag im A1-Kurs. Jeder spricht drei Minuten über sein neues Leben. Frau Costa, bitte."],["Mia steht auf. Ihre Hände sind kalt. Aber sie lächelt."],["„Guten Morgen. Mein Name ist Mia Costa. Ich komme aus Porto, aus Portugal. Ich bin achtundzwanzig Jahre alt, und ich bin Webdesignerin."],["Im September bin ich nach Freiburg gekommen. Mit einem großen Koffer und ohne Deutsch. Am ersten Tag hatte ich kein Bett. Ich habe auf dem Boden geschlafen. Das war nicht schön."],["Aber ich hatte Glück. Ich habe wunderbare Nachbarn. Frau Schulz wohnt im Erdgeschoss. Sie ist meine Vermieterin und meine Freundin. Sie war früher Musiklehrerin. Ihr Kater Felix ist ein Dieb. Er hat jeden Morgen eine Brezel aus der Bäckerei geholt – für mich! Und letzte Woche hat er meinen Schlüssel gestohlen."],["In Wohnung eins wohnt Tom, mit seinem Hund Bruno. Tom ist Busfahrer, und er macht immer Witze. Bruno hat Angst vor Felix."],["Und in Wohnung vier wohnt Jonas. Er ist Koch im Café Sonne. Er kocht sehr gut, aber er singt sehr schlecht. Seit dem fünfzehnten November ist er mein Freund."],["Im Kurs habe ich Elif kennengelernt. Sie kommt aus der Türkei und studiert Medizin. Sie ist meine beste Freundin hier. Sie ist immer zu spät, aber sie hat immer eine Lösung."],["Ich habe viel gelernt. Ich kann jetzt einkaufen, telefonieren und zum Arzt gehen. Ich kann eine Wohnung anmelden – das war schwer! Ich kann ein Konto eröffnen. Und ich kann ein Vorstellungsgespräch auf Deutsch machen."],["Am zweiten Januar beginne ich meinen neuen Job bei der Agentur Keller. Ich bin sehr froh, aber auch ein bisschen nervös."],["Was ist schwer? Der, die, das. Immer noch! Und die Uhrzeit: Halb sieben ist nicht sieben Uhr dreißig, sondern sechs Uhr dreißig. Das ist verrückt!"],["Was mag ich in Freiburg am liebsten? Die Bächle. Den Markt am Samstag. Und die Menschen."],["Ich möchte Danke sagen. Danke, Elif. Danke, Tom. Und danke, Herr Brandt. Sie sind streng. Aber Sie haben ein großes Herz. Und Sie haben jetzt eine Freundin aus Lissabon.“"],["Die Klasse lacht und klatscht. Herr Brandt wird ein bisschen rot."],["Herr Brandt","Danke, Frau Costa. Und ja: Halb sieben ist wirklich sechs Uhr dreißig. Willkommen in Deutschland. Und noch etwas: Im Januar beginnt der A2-Kurs. Abends, zweimal pro Woche. Für Leute mit Job. Ich hoffe, ich sehe Sie dort."],["Mia","Ganz sicher!"],["Am Abend schreibt Mia Jonas eine Nachricht: Sag Lena: Ja. Ich feiere Weihnachten mit euch."],["Die Antwort kommt sofort: Super! 😊 Meine Mutter freut sich schon. Sie hat gesagt: „Endlich lerne ich die Frau vom Bächle kennen.“"],["Die ganze Familie Weber. Am Heiligabend. Mia sieht auf ihren Kalender. Noch neun Tage."]],"q":["der, die, das? ___ Schlüssel · ___ Wohnung · ___ Fenster","Ergänze im Akkusativ: Ich brauche ___ Winterjacke und ___ Mantel (ein).","Stell nicht an die richtige Stelle: Mein Deutsch ist perfekt.","Perfekt: Mia ___ nach Freiburg ___ (kommen). Sie ___ auf dem Boden ___ (schlafen).","Präteritum: Frau Schulz ___ Musiklehrerin. Am ersten Tag ___ Mia kein Bett.","Modalverb: Mia ___ jetzt telefonieren (können). Sie ___ keinen Alkohol trinken (dürfen, beim Arzt).","Präposition + Artikel: Der Schlüssel liegt ___ ___ Kater (unter). Mia fährt ___ ___ Bus (mit).","Possessiv: Paul gibt ___ Onkel ein Bild (sein).","doch oder ja? „Sie sprechen kein Deutsch?“ – „___, ein bisschen!“","Uhrzeit: 18:45 = Viertel ___ sieben. 18:30 = ___ sieben."],"a":["der Schlüssel · die Wohnung · das Fenster. Learn every noun with its article (stories 5, 46).","eine · einen. Accusative: only masculine changes, ein → einen (story 11).","Mein Deutsch ist nicht perfekt. nicht goes before the adjective (story 48).","ist … gekommen · hat … geschlafen. Movement → sein; schlafen → haben (stories 29, 31).","war · hatte. Präteritum of sein and haben (story 32).","kann · darf. ich/er kann, ich/er darf, infinitive at the end (stories 18, 27).","unter dem · mit dem. Wo? + dative (story 47); mit + dative (story 35).","seinem. Dative masculine: sein → seinem (story 41).","Doch. Answer to a negative question (story 44).","vor · halb. Viertel vor sieben = 6:45; halb sieben = 6:30 (story 49)."],"w":[],"c":[],"x":[],"g":["A1 auf einen Blick",["Verbs: present tense, stem change, separable verbs, sein/haben, modal verbs (können, müssen, wollen, dürfen, sollen, möchten, mögen), imperative, Perfekt with haben and sein, war/hatte.","Nouns and articles: der/die/das, ein/kein, plural, accusative, dative, possessive articles, compound nouns.","Pronouns: ich – mich – mir, man, es gibt.","Sentences: verb in position 2, yes/no questions, W-questions, nicht/kein, und/aber/oder/denn/sondern, doch.","Prepositions: place (in, an, auf, unter …), direction (nach, zu), time (um, am, im, vor, nach, von … bis), dative (mit, bei, aus, von, zu), accusative (für, ohne, durch, um, gegen).","Beispiele: Im September bin ich nach Freiburg gekommen. · Am zweiten Januar beginne ich meinen neuen Job."]],"exam":{"task":"Sie haben eine Anzeige gesehen: „Café sucht Aushilfe“. Schreiben Sie eine kurze E-Mail.","points":["Stellen Sie sich vor.","Wann haben Sie Zeit?","Fragen Sie nach dem Lohn."],"words":40,"en":"Reply to a job ad: introduce yourself, when you are free, ask about pay."}},{"n":51,"t":"Heiligabend","l":"A2","review":false,"p":[["Vierundzwanzigster Dezember, siebzehn Uhr. Mia steht vor Lenas Haus in der Wiehre. In der Hand hat sie einen Bolo Rei, einen portugiesischen Weihnachtskuchen. Sie hat ihn bei Fátima gekauft, weil ihre eigenen Kuchen immer schwarz werden."],["Jonas","Bist du nervös?"],["Mia","Ja. Sehr. Weil es deine Eltern sind. Weil ich nicht weiß, was man an Weihnachten in Deutschland macht. Und weil mein Deutsch nicht perfekt ist."],["Jonas","Dein Deutsch ist super. Und meine Mutter liebt dich schon, weil ich so viel von dir erzähle."],["Die Tür geht auf. Eine kleine Frau mit kurzen grauen Haaren und einer roten Brille umarmt Mia sofort."],["Ingrid","Endlich! Die Frau vom Bächle! Ich bin Ingrid. Komm rein, komm rein, es ist kalt!"],["Im Wohnzimmer steht ein großer Weihnachtsbaum mit Kerzen und Strohsternen. Unter dem Baum liegen viele Geschenke. Paul läuft im Kreis, weil er so aufgeregt ist."],["Am Fenster steht ein großer Mann mit weißem Bart. Er gibt Mia die Hand."],["Klaus","Klaus Weber. Guten Abend."],["Mehr sagt er nicht. Jonas flüstert: „Mein Vater redet nicht viel. Er war dreißig Jahre Ingenieur.“"],["Um sechs gehen alle in die Kirche, weil das bei Webers Tradition ist. Danach ist Bescherung. Paul bekommt einen Fußball, ein Buch und ein Kuscheltier, einen grauen Kater."],["Paul","Der heißt Felix Zwei!"],["Zum Essen gibt es Kartoffelsalat mit Würstchen."],["Mia","Kartoffelsalat? An Heiligabend?"],["Lena","Ja! Das essen viele Deutsche an Heiligabend, weil es einfach ist. Am fünfundzwanzigsten gibt es dann Gans."],["Nach dem Essen fragt Klaus. Zum ersten Mal."],["Klaus","Frau Costa, warum sind Sie eigentlich nach Freiburg gekommen?"],["Mia","Bitte, sagen Sie Mia. Ich bin gekommen, weil ich etwas Neues wollte. Meine Agentur in Porto hat zugemacht. Und eine Freundin hat in Freiburg studiert. Sie hat immer gesagt: Freiburg ist die schönste Stadt in Deutschland."],["Klaus","Und? Hat sie recht?"],["Mia","Ja. Weil die Menschen hier so nett sind."],["Klaus nickt. Er lächelt nicht, aber er nickt."],["Um zehn Uhr bringt Mia Teller in die Küche. Die Tür ist halb offen. Drinnen stehen Jonas und sein Vater. Sie sprechen leise, aber Mia hört alles."],["Klaus","Ein eigenes Café? Jonas, das ist verrückt. Weißt du, wie viele Cafés jedes Jahr zumachen?"],["Jonas","Ich weiß. Aber ich will es versuchen."],["Klaus","Warum? Weil deine neue Freundin eine schöne Website gemacht hat?"],["Mia bleibt stehen. Der Teller in ihrer Hand zittert."]],"q":["Warum hat Mia den Bolo Rei bei Fátima gekauft?","Warum ist Mia nervös? (Nenne zwei Gründe.)","Was essen viele Deutsche an Heiligabend? Warum?","Richtig oder falsch? Klaus findet die Idee mit dem Café super.","Und du? Warum lernst du Deutsch? (Ich lerne Deutsch, weil …)"],"a":["Because her own cakes always turn out black. „… weil ihre eigenen Kuchen immer schwarz werden.“","They are Jonas's parents, she doesn't know German Christmas customs, her German isn't perfect. „Weil es deine Eltern sind. Weil ich nicht weiß …“","Kartoffelsalat mit Würstchen, because it's simple. „… weil es einfach ist.“","Falsch. „Ein eigenes Café? Jonas, das ist verrückt.“","Example: Ich lerne Deutsch, weil ich in Deutschland arbeiten möchte."],"w":[["weil","because","… weil es deine Eltern sind."],["Heiligabend","Christmas Eve","An Heiligabend?"],["der Weihnachtsbaum, die Weihnachtsbäume","Christmas tree","Im Wohnzimmer steht ein großer Weihnachtsbaum."],["die Kerze, die Kerzen","candle","mit Kerzen und Strohsternen"],["die Bescherung","giving of presents","Danach ist Bescherung."],["aufgeregt","excited","weil er so aufgeregt ist"],["flüstern","to whisper","Jonas flüstert."],["reden","to talk","Mein Vater redet nicht viel."],["der Ingenieur, die Ingenieure","engineer","Er war dreißig Jahre Ingenieur."],["das Kuscheltier, die Kuscheltiere","cuddly toy","ein Kuscheltier, einen grauen Kater"],["die Gans, die Gänse","goose","Am fünfundzwanzigsten gibt es Gans."],["der Mensch, die Menschen","person, human","Die Menschen hier sind so nett."],["nicken","to nod","Klaus nickt."],["zittern","to shake, tremble","Der Teller zittert."]],"c":[["die Hand geben","to shake hands","Er gibt Mia die Hand."],["Sagen Sie … zu mir. / Sagen Sie Mia.","Call me …","Bitte, sagen Sie Mia."],["etwas Neues","something new","weil ich etwas Neues wollte"],["im Kreis laufen","to run in circles","Paul läuft im Kreis."]],"x":[["die Schicht, die Schichten","shift",""]],"g":["Nebensatz mit weil",["weil (because) starts a subordinate clause. The conjugated verb goes to the end.","Ich bin nervös. Es sind deine Eltern. → Ich bin nervös, weil es deine Eltern sind.","Separable verbs join together at the end: …, weil die Agentur zumacht. Perfekt: …, weil die Agentur zugemacht hat.","Compare denn (story 25): no change in word order. …, denn es ist einfach.","Answer a Warum? question with Weil …: Warum? – Weil die Menschen so nett sind.","Beispiele: Paul läuft im Kreis, weil er so aufgeregt ist. · Sie hat ihn gekauft, weil ihre Kuchen immer schwarz werden."]]},{"n":52,"t":"Ich glaube, dass …","l":"A2","review":false,"p":[["Mia stellt den Teller auf den Tisch. Dann geht sie in die Küche. Jonas und Klaus sehen sie überrascht an."],["Mia","Entschuldigung. Ich habe alles gehört. Und ich möchte etwas sagen. Ich glaube, dass Jonas ein sehr guter Koch ist. Ich weiß, dass er Mut hat. Und die Website habe ich gemacht, weil ich an seinen Traum glaube. Nicht umgekehrt."],["Stille. Klaus sieht Mia lange an. Dann sagt er nur: „Gute Nacht.“ Und er geht."],["Auf dem Heimweg sagt Jonas nichts. Dann, vor der Haustür, nimmt er Mias Hand."],["Jonas","Niemand hat jemals so mit meinem Vater gesprochen. Niemand."],["Mia","War das schlimm?"],["Jonas","Nein. Ich glaube, dass es wunderbar war."],["Am fünfundzwanzigsten Dezember sind sie wieder bei Lena. Es gibt Gans mit Rotkohl und Klößen. Die Stimmung ist ein bisschen komisch. Klaus isst still."],["Nach dem Essen steht er auf."],["Klaus","Ich möchte etwas sagen. Gestern habe ich gesagt, dass ein Café verrückt ist. Das war nicht fair."],["Alle sehen ihn an. Ingrid legt ihre Gabel auf den Teller."],["Klaus","Ich erzähle euch etwas. Das wisst ihr nicht. Mit fünfundzwanzig hatte ich auch einen Traum. Ein Fahrradgeschäft. Ich habe zwei Jahre gearbeitet, Tag und Nacht. Dann war das Geld weg. Ich musste zumachen. Danach war ich dreißig Jahre Ingenieur. Ein guter Job. Aber nicht mein Traum."],["Jonas","Papa … das wusste ich nicht."],["Klaus","Ich habe Angst, dass dir das Gleiche passiert. Das ist alles. Ich habe Angst. Nicht, dass du schlecht bist."],["Er nimmt einen Umschlag aus seiner Jacke und gibt ihn Jonas. Darin ist ein altes Foto: ein junger Mann mit langen Haaren vor einem kleinen Laden. Auf dem Schild steht: Rad- Weber. Und auf der Rückseite steht: Ich hoffe, dass du mehr Glück hast als ich. Und mehr Mut. – Papa"],["Jonas sagt nichts. Er umarmt seinen Vater. Lange."],["Ingrid","Na endlich! Ich finde, dass ihr beide sehr stur seid. Wie zwei alte Esel."],["Alle lachen. Paul ruft","„Opa ist ein Esel!“"],["Später, beim Abschied, gibt Klaus Mia die Hand. Diesmal hält er sie ein bisschen länger."],["Klaus","Mia. Ich glaube, dass mein Sohn eine gute Wahl getroffen hat."],["Am siebenundzwanzigsten Dezember bekommt Mia zwei Nachrichten. Die erste ist eine E-Mail von Frau Keller: Willkommen im Team! Im Anhang finden Sie unsere Hausregeln."],["Die zweite ist eine SMS von Max: Hallo Mia. Bring am 2. Januar viel Geduld mit. Wir haben einen schwierigen Kunden. Er heißt Herr Krause."],["Krause? Mia kennt einen Herrn Krause. Aus dem Bürgeramt."]],"q":["Was sagt Mia zu Klaus in der Küche?","Was war der Traum von Klaus?","Wovor hat Klaus Angst?","Richtig oder falsch? Klaus sagt am Ende, dass Mia nicht gut für Jonas ist.","Und du? Was glaubst du: Ist ein eigenes Café eine gute Idee? (Ich glaube, dass …)"],"a":["That Jonas is a very good cook, that he has courage, and that she believes in his dream. „Ich glaube, dass Jonas ein sehr guter Koch ist. Ich weiß, dass er Mut hat.“","Ein Fahrradgeschäft, „Rad-Weber“. „Mit fünfundzwanzig hatte ich auch einen Traum. Ein Fahrradgeschäft.“","That the same thing happens to Jonas. „Ich habe Angst, dass dir das Gleiche passiert.“","Falsch. „Ich glaube, dass mein Sohn eine gute Wahl getroffen hat.“","Example: Ich glaube, dass ein Café eine gute Idee ist, aber es ist auch ein Risiko."],"w":[["dass","that","Ich glaube, dass Jonas ein guter Koch ist."],["glauben an","to believe in","weil ich an seinen Traum glaube"],["hoffen","to hope","Ich hoffe, dass du mehr Glück hast."],["überrascht","surprised","Sie sehen sie überrascht an."],["der Heimweg","the way home","Auf dem Heimweg sagt Jonas nichts."],["die Stimmung, die Stimmungen","mood, atmosphere","Die Stimmung ist ein bisschen komisch."],["die Gabel, die Gabeln","fork","Ingrid legt ihre Gabel auf den Teller."],["der Umschlag, die Umschläge","envelope","Er nimmt einen Umschlag aus der Jacke."],["der Laden, die Läden","shop","vor einem kleinen Laden"],["die Rückseite, die Rückseiten","back (of a page)","auf der Rückseite"],["stur","stubborn","Ihr seid beide sehr stur."],["der Esel, die Esel","donkey","Wie zwei alte Esel."],["der Abschied, die Abschiede","goodbye, farewell","beim Abschied"],["schwierig","difficult","einen schwierigen Kunden"],["die Geduld","patience","Bring viel Geduld mit."]],"c":[["nicht umgekehrt","not the other way round","Nicht umgekehrt."],["das Gleiche","the same (thing)","dass dir das Gleiche passiert"],["eine gute Wahl treffen","to make a good choice","eine gute Wahl getroffen"],["im Anhang","attached (email)","Im Anhang finden Sie unsere Hausregeln."]],"x":[["die Fortbildung, die Fortbildungen","further training",""],["die Bewerbung, die Bewerbungen","job application",""]],"g":["Nebensatz mit dass",["dass (that) introduces what someone thinks, knows, hopes or says. The verb goes to the end.","Typical verbs before dass: glauben, wissen, denken, hoffen, finden, sagen, Angst haben.","Er ist ein guter Koch. → Ich glaube, dass er ein guter Koch ist.","Perfekt in a dass-clause: …, dass mein Sohn eine gute Wahl getroffen hat.","In speaking, dass is sometimes left out: Ich glaube, er ist ein guter Koch. (then normal word order)","Beispiele: Ich weiß, dass er Mut hat. · Ich habe Angst, dass dir das Gleiche passiert."]]},{"n":53,"t":"Wenn …, dann …","l":"A2","review":false,"p":[["Achtundzwanzigster Dezember. Mia und Jonas sitzen auf dem grünen Sofa – dem Elefant- Sofa. Mia liest die Hausregeln von der Agentur Keller vor."],["Hausregeln – Agentur Keller"],["1. Wenn Sie krank sind, rufen Sie bitte bis neun Uhr an."],["2. Wenn Sie Urlaub möchten, sprechen Sie mit Sabine. Mindestens vier Wochen vorher."],["3. Wenn Sie Kaffee trinken, spülen Sie danach Ihre Tasse. Unsere Spülmaschine ist kein Zauberer."],["4. Wenn Otto bellt, ist der Postbote da. Keine Panik."],["5. Wenn Sie eine Idee haben, sagen Sie es laut. Es gibt keine dummen Ideen."],["6. Wenn Herr Krause anruft, bleiben Sie ruhig. Immer."],["Jonas","Regel Nummer sechs ist komisch."],["Mia","Ja. Wenn das der Herr Krause vom Bürgeramt ist, dann habe ich ein Problem. Er hat gesagt, dass er eine Ausnahme für mich macht. Nur einmal."],["Jonas","Es gibt tausend Krauses in Deutschland."],["Mia","Hoffentlich."],["Am Nachmittag ruft Mia in Porto an. Mama und Rui sitzen vor dem Laptop. Hinter ihnen sieht Mia das alte Wohnzimmer, das Fenster und, ganz klein, das Meer."],["Mama","Mia! Wie war Weihnachten bei der Familie von Jonas?"],["Mia","Zuerst schwierig, dann wunderschön. Sein Vater ist sehr streng. Aber er hat ein gutes Herz."],["Mama","Wie dein Opa. Wenn ich an Opa denke, dann sehe ich ihn immer im Café, mit seinem Lächeln."],["Rui","Mia! Große Neuigkeit! Wenn ich im Februar meine Deutschprüfung bestehe, komme ich im März nach Freiburg. Für eine Woche!"],["Mia","Wirklich? Das ist toll!"],["Rui","Und dann lerne ich Jonas kennen. Und Felix. Und den Brezel-Bäcker."],["Mama","Und ich? Wann sehe ich dich, Mia?"],["Mia","Wenn ich im Sommer Urlaub bekomme, komme ich nach Porto. Versprochen. Aber im ersten Jahr gibt es nicht viel Urlaub."],["Mama","Dann komme ich eben zu dir. Wenn du nicht zum Meer kommst, kommt das Meer zu dir. Ich bringe Sardinen mit."],["Mia lacht, aber ihre Augen sind ein bisschen nass."],["Am Abend fragt Jonas:"],["Jonas","Was machen wir an Silvester? Wenn du willst, gehen wir auf den Schlossberg. Von dort sieht man das ganze Feuerwerk über der Stadt."],["Mia","In Porto feiern wir am Strand. Mit Musik, mit Tanzen, mit zwölf Rosinen um Mitternacht. Das ist die schönste Party der Welt."],["Jonas","Die schönste? Warte nur. Wenn du Silvester in Freiburg erlebt hast, sagst du das nicht mehr."],["Mia","Das werden wir sehen."]],"q":["Was soll man machen, wenn man krank ist?","Was bedeutet es, wenn Otto bellt?","Wann kommt Rui nach Freiburg? Unter welcher Bedingung?","Richtig oder falsch? Mama will im Sommer nach Freiburg kommen, wenn Mia nicht nach Porto kommt.","Und du? Was machst du, wenn du krank bist? Was machst du, wenn du Urlaub hast?"],"a":["Bis neun Uhr anrufen. „Wenn Sie krank sind, rufen Sie bitte bis neun Uhr an.“","The postman is there. „Wenn Otto bellt, ist der Postbote da.“","Im März, if he passes his German exam in February. „Wenn ich im Februar meine Deutschprüfung bestehe, komme ich im März nach Freiburg.“","Richtig. „Dann komme ich eben zu dir.“","Example: Wenn ich krank bin, bleibe ich im Bett. Wenn ich Urlaub habe, fahre ich ans Meer."],"w":[["wenn","if; whenever","Wenn Sie krank sind, rufen Sie an."],["die Regel, die Regeln","rule","Regel Nummer sechs ist komisch."],["mindestens","at least","Mindestens vier Wochen vorher."],["vorher","before(hand)","vier Wochen vorher"],["spülen","to wash (dishes)","Spülen Sie danach Ihre Tasse."],["die Spülmaschine, die Spülmaschinen","dishwasher","Unsere Spülmaschine ist kein Zauberer."],["dumm","stupid","Es gibt keine dummen Ideen."],["hoffentlich","hopefully","Hoffentlich."],["die Neuigkeit, die Neuigkeiten","news","Große Neuigkeit!"],["bestehen","to pass (an exam)","Wenn ich die Prüfung bestehe …"],["kennenlernen","to get to know","Dann lerne ich Jonas kennen."],["Silvester","New Year's Eve","Was machen wir an Silvester?"],["das Feuerwerk, die Feuerwerke","fireworks","das ganze Feuerwerk über der Stadt"],["der Strand, die Strände","beach","In Porto feiern wir am Strand."],["erleben","to experience","Wenn du Silvester in Freiburg erlebt hast …"]],"c":[["vorlesen","to read aloud","Mia liest die Hausregeln vor."],["… eben","(then) simply","Dann komme ich eben zu dir."],["der Welt","in the world","die schönste Party der Welt"],["Das werden wir sehen.","We'll see.","Das werden wir sehen."]],"x":[["der Arbeitgeber, die Arbeitgeber","employer",""],["die Überstunde, die Überstunden","overtime hour",""]],"g":["Nebensatz mit wenn",["wenn = if (condition) or whenever (repeated situation). The verb goes to the end of the wenn-clause.","If the wenn-clause comes first, the main clause starts with the verb (verb – verb): Wenn Sie krank sind, rufen Sie an.","You can add dann: Wenn ich an Opa denke, dann sehe ich ihn im Café.","Main clause first: Ich komme nach Porto, wenn ich Urlaub bekomme.","Beispiele: Wenn Otto bellt, ist der Postbote da. · Wenn du willst, gehen wir auf den Schlossberg."]]},{"n":54,"t":"Silvester: Freiburg oder Porto?","l":"A2","review":false,"p":[["Einunddreißigster Dezember, zweiundzwanzig Uhr. In Mias Küche stehen Elif, Tom, Jonas und Mia um einen kleinen Topf. Darin schmilzt Wachs."],["Elif","Das heißt Wachsgießen. Eine deutsche Tradition! Man gießt das heiße Wachs ins kalte Wasser. Die Form zeigt die Zukunft."],["Tom gießt als Erster. Seine Figur sieht aus wie eine Wurst."],["Jonas","Eine Wurst bedeutet: Du wirst nächstes Jahr dicker."],["Tom","Nein! Das bedeutet: Ich werde reicher. Eine Wurst ist teurer als ein Brot!"],["Dann gießt Mia. Ihre Figur hat vier Wände und ein Dach. Ein kleines Haus."],["Elif","Ein Haus! Das bedeutet: ein neues Zuhause."],["Mia sieht Jonas an. Jonas sieht schnell weg."],["Um elf gehen sie auf den Schlossberg. Nur Tom bleibt zu Hause, weil Bruno Angst vor dem Feuerwerk hat. Es ist kalt, minus vier Grad. Der Schnee knirscht unter den Schuhen."],["Mia","In Porto ist es jetzt wärmer. Zwölf Grad, vielleicht."],["Jonas","Aber hier ist es schöner. Mit Schnee!"],["Mia","In Porto ist das Feuerwerk größer. Und die Party ist lauter. Wir tanzen am Strand bis morgens um sechs."],["Elif","In İzmir ist das Essen besser. Meine Mutter kocht für dreißig Leute."],["Jonas","Okay, okay! Porto ist größer, wärmer und lauter. İzmir ist leckerer. Aber Freiburg ist gemütlicher. Und die Aussicht ist hier höher."],["Mia","Höher, ja. Weil du mich jedes Mal auf einen Berg schleppst!"],["Die Aussicht ist wirklich fantastisch. Unten liegt die Stadt, mit tausend Lichtern. Das Münster leuchtet. Viele Leute stehen oben am Turm, mit Sekt und Wunderkerzen."],["Fünf Minuten vor Mitternacht ruft Tom an. Mit Video. Bruno liegt unter dem Bett, nur seine Nase ist zu sehen."],["Tom","Frohes neues Jahr! Bruno sagt auch Hallo. Er ist ein mutiger Hund. Mutiger als ich!"],["Dann zählen alle zusammen: „Zehn, neun, acht, sieben, sechs, fünf, vier, drei, zwei, eins – Frohes neues Jahr!“"],["Über der Stadt explodieren Farben: Rot, Gold, Grün, Blau. Die Glocken vom Münster läuten. Jonas küsst Mia."],["Jonas","Und? Ist das schöner als Porto?"],["Mia","Nicht schöner. Anders. Und … vielleicht ein bisschen romantischer."],["Jonas","Das nächste Jahr wird noch besser als dieses."],["Mia","Besser als dieses Jahr? Das ist schwer."],["Elif","Leute! Morgen frühstücken wir zusammen. Und jeder bringt seine guten Vorsätze mit. Drei Stück! Aufgeschrieben!"],["Auf dem Heimweg denkt Mia nach. Zwei Vorsätze sind leicht. Aber der dritte? Den kann sie nicht laut sagen. Noch nicht."]],"q":["Was ist Wachsgießen?","Was bedeutet Mias Figur?","Warum bleibt Tom zu Hause?","Richtig oder falsch? Mia sagt, dass Freiburg schöner als Porto ist.","Und du? Vergleiche deine Stadt mit einer anderen Stadt. (… ist größer / kleiner / schöner als …)"],"a":["A German New Year's tradition: you pour hot wax into cold water, and the shape shows the future. „Die Form zeigt die Zukunft.“","Ein Haus – ein neues Zuhause. „Ein Haus! Das bedeutet: ein neues Zuhause.“","Bruno is afraid of the fireworks. „… weil Bruno Angst vor dem Feuerwerk hat.“","Falsch. „Nicht schöner. Anders. Und … vielleicht ein bisschen romantischer.“","Example: London ist größer als Freiburg, aber Freiburg ist ruhiger und grüner."],"w":[["größer / wärmer / besser / höher","bigger / warmer / better / higher","In Porto ist es jetzt wärmer."],["als","than","Eine Wurst ist teurer als ein Brot."],["der Topf, die Töpfe","pot","um einen kleinen Topf"],["schmelzen","to melt","Darin schmilzt Wachs."],["gießen","to pour","Man gießt das Wachs ins Wasser."],["die Form, die Formen","shape","Die Form zeigt die Zukunft."],["reich","rich","Ich werde reicher."],["die Wand, die Wände","wall","vier Wände und ein Dach"],["die Aussicht, die Aussichten","view","Die Aussicht ist fantastisch."],["lecker","delicious","İzmir ist leckerer."],["mutig","brave","Er ist ein mutiger Hund."],["leuchten","to shine, glow","Das Münster leuchtet."],["die Glocke, die Glocken","bell","Die Glocken vom Münster läuten."],["anders","different","Nicht schöner. Anders."],["der Vorsatz, die Vorsätze","resolution","seine guten Vorsätze"]],"c":[["Frohes neues Jahr!","Happy New Year!","Frohes neues Jahr!"],["als Erster","as the first one","Tom gießt als Erster."],["Angst haben vor","to be afraid of","Bruno hat Angst vor dem Feuerwerk."],["nur … ist zu sehen","only … can be seen","nur seine Nase ist zu sehen"]],"x":[["sich bewerben","to apply",""]],"g":["der Komparativ",["Comparative = adjective + -er: schön → schöner, laut → lauter.","Short adjectives often add an umlaut: warm → wärmer, groß → größer, alt → älter.","Irregular: gut → besser · viel → mehr · gern → lieber · hoch → höher.","Compare two things with als: Eine Wurst ist teurer als ein Brot.","Beispiele: In Porto ist das Feuerwerk größer. · Bruno ist mutiger als ich!"]]},{"n":55,"t":"Gute Vorsätze","l":"A2","review":false,"p":[["Neujahr, zwölf Uhr mittags. Alle sind müde, aber hungrig. In Mias Küche gibt es Rührei, Brötchen, Lachs, Obstsalat und sehr viel Kaffee. Frau Schulz bringt Berliner – Krapfen mit Marmelade."],["Frau Schulz","Vorsicht! In Berlin gibt es eine Tradition: In einem Berliner ist Senf statt Marmelade."],["Tom beißt in seinen Berliner. Sein Gesicht wird rot."],["Tom","Senf! Natürlich ich. Ich habe immer das meiste Pech!"],["Dann liest jeder seine Vorsätze vor."],["Elif","Nummer eins: Ich lerne jeden Tag zwei Stunden. Ich will die beste Studentin im Semester sein. Nummer zwei: Ich komme pünktlicher. Nummer drei: Ich esse weniger Süßes."],["Tom","Nummer drei ist für dich am schwierigsten."],["Elif","Und deine?"],["Tom","Erstens: Ich esse weniger Wurst. Zweitens: Ich mache den Führerschein für den Fernbus. Dann verdiene ich am meisten von allen Busfahrern. Drittens: Ich bringe Bruno bei, dass Katzen nicht gefährlich sind."],["Frau Schulz","Das ist der unmöglichste Vorsatz von allen."],["Jonas","Mein wichtigster Vorsatz: Ich schreibe einen Businessplan für Café Bächle. Bis Ostern. Mein Vater hilft mir. Er ist der genaueste Mensch der Welt."],["Alle klatschen. Jonas wird ein bisschen rot."],["Elif","Und Mia?"],["Mia","Erstens: Ich spreche bei der Arbeit so viel Deutsch wie möglich. Zweitens: Ich lerne so gut backen wie Jonas' Oma."],["Jonas","Das ist der mutigste Vorsatz!"],["Elif","Und drittens?"],["Mia","Drittens ist … geheim."],["Elif","Mia!"],["Mia","Geheim!"],["Nach dem Frühstück fragt Frau Schulz:"],["Frau Schulz","Was war Ihr schönster Moment im letzten Jahr, Frau Costa?"],["Mia","Das ist schwer. Der schönste Moment … vielleicht der erste Schnee. Auf dem Balkon. Und der lustigste: Jonas im Titisee. Und der schlimmste: die schwarzen Pastéis."],["Frau Schulz","Und Freiburg? Ist Freiburg so schön wie Porto?"],["Mia","Fast so schön wie Porto. Aber das Wetter ist nicht so gut wie in Porto."],["Am Abend räumt Jonas die Küche auf. Auf dem Tisch liegt Mias Zettel. Sie hat ihn vergessen. Er liest – nur eine Zeile."],["Drittens","Ich möchte mit Jonas zusammenwohnen. Mein größter Wunsch."],["Jonas lächelt. Er nimmt einen Stift und schreibt darunter: Ich auch. Dann legt er den Zettel zurück."],["Mia findet ihn um elf Uhr. Sie liest den Zettel dreimal. Sie kann lange nicht einschlafen."],["Dabei ist morgen der wichtigste Tag des Jahres: ihr erster Arbeitstag."]],"q":["Was ist die Berliner Tradition an Neujahr?","Was ist Jonas' wichtigster Vorsatz?","Was war Mias schönster Moment im letzten Jahr?","Richtig oder falsch? Mia findet, dass Freiburg genauso gutes Wetter hat wie Porto.","Und du? Was sind deine drei guten Vorsätze? Was war dein schönster Moment im letzten Jahr?"],"a":["One doughnut is filled with mustard instead of jam. „In einem Berliner ist Senf statt Marmelade.“","A business plan for Café Bächle by Easter. „Ich schreibe einen Businessplan für Café Bächle. Bis Ostern.“","Der erste Schnee auf dem Balkon. „Der schönste Moment … vielleicht der erste Schnee.“","Falsch. „Aber das Wetter ist nicht so gut wie in Porto.“","Example: Ich mache mehr Sport, ich lerne jeden Tag Deutsch und ich lese mehr. Mein schönster Moment war mein Urlaub in Italien."],"w":[["am schwierigsten / am meisten","the most difficult / the most","Nummer drei ist für dich am schwierigsten."],["der/die/das beste, schönste …","the best, most beautiful …","Ich will die beste Studentin sein."],["so … wie","as … as","Ist Freiburg so schön wie Porto?"],["Neujahr","New Year's Day","Neujahr, zwölf Uhr mittags."],["das Rührei","scrambled eggs","Es gibt Rührei, Brötchen, Lachs …"],["die Marmelade, die Marmeladen","jam","Krapfen mit Marmelade"],["statt","instead of","Senf statt Marmelade"],["das Pech","bad luck","Ich habe immer das meiste Pech!"],["pünktlich","punctual, on time","Ich komme pünktlicher."],["der Führerschein, die Führerscheine","driving licence","Ich mache den Führerschein."],["gefährlich","dangerous","dass Katzen nicht gefährlich sind"],["unmöglich","impossible","der unmöglichste Vorsatz"],["genau","exact, precise","der genaueste Mensch der Welt"],["der Wunsch, die Wünsche","wish","Mein größter Wunsch."],["zusammenwohnen","to live together","Ich möchte mit Jonas zusammenwohnen."]],"c":[["Vorsicht!","Careful!","Vorsicht! In Berlin gibt es eine Tradition."],["so viel wie möglich","as much as possible","so viel Deutsch wie möglich"],["erstens, zweitens, drittens","firstly, secondly, thirdly","Erstens: Ich esse weniger Wurst."],["jemandem etwas beibringen","to teach someone sth.","Ich bringe Bruno bei, dass …"]],"x":[["Vollzeit arbeiten","to work full-time",""],["Teilzeit arbeiten","to work part-time",""]],"g":["Superlativ und so … wie",["Superlative after a verb: am + adjective + -sten: am schönsten, am schwierigsten.","Before a noun: article + adjective + -ste: der schönste Moment, die beste Studentin.","Irregular: gut → am besten · viel → am meisten · gern → am liebsten · groß → am größten.","Equal: so + adjective + wie: Freiburg ist fast so schön wie Porto. Not equal: nicht so … wie.","Beispiele: Das ist der unmöglichste Vorsatz von allen. · Das Wetter ist nicht so gut wie in Porto."]]},{"n":56,"t":"Ich muss mich beeilen!","l":"A2","review":false,"p":[["Zweiter Januar, sieben Uhr vierzig. Mia wacht auf. Sie sieht auf die Uhr. Sieben Uhr vierzig?! Der Wecker hat um sechs Uhr dreißig geklingelt. Sie hat ihn ausgemacht und ist wieder eingeschlafen."],["Mia","Nein, nein, nein! Ich muss mich beeilen!"],["Sie wäscht sich in zwei Minuten. Sie zieht sich in drei Minuten an. Sie kämmt sich in der Straßenbahn. Die Bahn hat fünf Minuten Verspätung. Natürlich."],["Um acht Uhr achtundfünfzig steht Mia vor der Glastür in der Bertoldstraße. Sie ist außer Atem. Otto, der Bürohund, freut sich sehr und springt an ihr hoch."],["Frau Keller","Guten Morgen, Mia! Pünktlich! Darf ich Sie den anderen vorstellen? Und – wir duzen uns hier alle. Ich bin Sabine."],["Im Großraumbüro sitzen vier Leute. Max mit seinem Bart. Eine junge Frau mit grünen Haaren: Jana, die Praktikantin. Und ein Mann mit Kopfhörern: Kemal, der Programmierer."],["Mia","Hallo! Ich bin Mia. Ich freue mich sehr, dass ich hier bin."],["Kemal","Willkommen! Setz dich. Das ist dein Platz, am Fenster."],["Mia setzt sich. Auf ihrem Schreibtisch stehen ein großer Bildschirm, eine Pflanze und eine Tasse mit ihrem Namen. Sie fühlt sich sofort wohl."],["Um elf Uhr wird es plötzlich still im Büro. Otto legt sich unter den Tisch. Jana sieht nervös aus."],["Jana","Er kommt."],["Mia","Wer?"],["Max","Herr Krause. Unser schwierigster Kunde. Er hat ein Blumengeschäft in der Altstadt. Seit Oktober. Vorher war er dreißig Jahre beim Bürgeramt."],["Die Tür geht auf. Ein Mann mit grauem Anzug und strenger Brille kommt herein. Mia erkennt ihn sofort. Platz sechs. B 47."],["Herr Krause","Guten Morgen. Ich möchte mich nicht lange aufhalten. Ich ärgere mich seit drei Monaten über diese Website. Drei Designer, drei Entwürfe, alles falsch."],["Dann sieht er Mia. Er bleibt stehen."],["Herr Krause","Frau Costa? Die Dame ohne Wohnungsgeberbestätigung?"],["Mia","Guten Morgen, Herr Krause. Ich habe sie dann gebracht. Am Donnerstag, um acht. Pünktlich."],["Herr Krause","Das stimmt. Sie haben sich an die Regeln gehalten. Das gefällt mir."],["Er dreht sich zu Sabine um."],["Herr Krause","Ich möchte, dass Frau Costa mein Projekt macht. Nur Frau Costa. Bis Freitag möchte ich drei Entwürfe sehen. Guten Tag."],["Und weg ist er."],["Max sieht Mia an. Jana sieht Mia an. Kemal nimmt seine Kopfhörer ab."],["Max","Willkommen im Team. Du hast vier Tage."]],"q":["Warum kommt Mia fast zu spät?","Wer arbeitet in der Agentur? (Nenne drei Personen.)","Woher kennt Mia Herrn Krause?","Richtig oder falsch? Herr Krause möchte nicht mit Mia arbeiten.","Und du? Was machst du morgens? (Ich wasche mich, ich ziehe mich an …) Wann musst du dich beeilen?"],"a":["She turned off the alarm and fell asleep again; the tram was late. „Sie hat ihn ausgemacht und ist wieder eingeschlafen.“","Sabine Keller, Max, Jana (Praktikantin), Kemal (Programmierer) – und Otto.","From the Bürgeramt (story 19). „Platz sechs. B 47.“","Falsch. „Ich möchte, dass Frau Costa mein Projekt macht. Nur Frau Costa.“","Example: Ich dusche mich, ich ziehe mich an und ich frühstücke. Ich muss mich jeden Morgen beeilen!"],"w":[["sich beeilen","to hurry","Ich muss mich beeilen!"],["sich waschen / sich kämmen","to wash / to comb one's hair","Sie wäscht sich in zwei Minuten."],["sich freuen","to be happy, glad","Ich freue mich sehr, dass ich hier bin."],["sich setzen / sich legen","to sit down / to lie down","Otto legt sich unter den Tisch."],["sich fühlen","to feel","Sie fühlt sich sofort wohl."],["sich ärgern über","to be annoyed about","Ich ärgere mich über diese Website."],["sich umdrehen","to turn around","Er dreht sich zu Sabine um."],["die Verspätung, die Verspätungen","delay","Die Bahn hat fünf Minuten Verspätung."],["die Praktikantin, die Praktikantinnen","intern (f)","Jana, die Praktikantin"],["der Programmierer, die Programmierer","programmer","Kemal, der Programmierer"],["die Kopfhörer (Plural)","headphones","ein Mann mit Kopfhörern"],["die Pflanze, die Pflanzen","plant","eine Pflanze und eine Tasse"],["der Anzug, die Anzüge","suit","mit grauem Anzug"],["erkennen","to recognise","Mia erkennt ihn sofort."],["der Entwurf, die Entwürfe","draft, design","drei Entwürfe"]],"c":[["außer Atem","out of breath","Sie ist außer Atem."],["sich duzen","to say du to each other","Wir duzen uns hier alle."],["sich wohlfühlen","to feel comfortable","Sie fühlt sich sofort wohl."],["sich an die Regeln halten","to stick to the rules","Sie haben sich an die Regeln gehalten."]],"x":[["selbstständig","self-employed",""],["zuverlässig","reliable",""]],"g":["reflexive Verben (Akkusativ)",["Reflexive verbs have a pronoun that refers back to the subject: Ich wasche mich.","Reflexive pronouns (accusative): mich, dich, sich, uns, euch, sich. Only er/sie/es/sie/Sie use sich.","Many reflexive verbs have no English \"myself\": sich beeilen (hurry), sich freuen (be glad), sich setzen (sit down).","In the Perfekt, they use haben: Sie haben sich an die Regeln gehalten.","Beispiele: Ich muss mich beeilen! · Mia setzt sich ans Fenster."]]},{"n":57,"t":"Was wünschen Sie sich?","l":"A2","review":false,"p":[["Mittwoch, zehn Uhr. Mia steht vor dem Blumengeschäft in der Konviktstraße. Über der Tür steht in alten Buchstaben: Blumen Krause – seit 1985."],["Drinnen riecht es nach Rosen und nach Erde. Herr Krause trägt keinen Anzug, sondern eine grüne Schürze. Er sieht ganz anders aus."],["Mia","Guten Morgen, Herr Krause. Darf ich mir das Geschäft ansehen? Ich möchte mir ein Bild machen, bevor ich die Website entwerfe."],["Herr Krause","Bitte. Waschen Sie sich zuerst die Hände, wenn Sie die Blumen anfassen."],["Mia wäscht sich die Hände. Dann sieht sie sich alles an. Sie macht sich Notizen und fotografiert die Blumen, die alten Holzregale, die Kasse von früher."],["Mia","Herr Krause, was wünschen Sie sich für die Website?"],["Herr Krause","Ich wünsche mir eine Website ohne Schnickschnack. Klar und ordentlich. Wie ein gutes Formular."],["Mia","Und die anderen drei Entwürfe? Was war falsch?"],["Herr Krause","Sie waren modern. Bunt. Laut. Aber das ist nicht mein Geschäft."],["Dann sieht Mia ein Foto an der Wand. Eine Frau mit roten Haaren, zwischen hunderten Sonnenblumen. Sie lacht."],["Mia","Wer ist das?"],["Herr Krause schweigt einen Moment."],["Herr Krause","Meine Frau, Hanna. Das Geschäft war ihr Traum. Neununddreißig Jahre. Letztes Jahr ist sie gestorben. Ich habe mir nie vorgestellt, dass ich einmal Blumen verkaufe. Ich war Beamter. Aber ich kann mir auch nicht vorstellen, dass ihr Geschäft zumacht."],["Mia","Das tut mir sehr leid."],["Herr Krause","Ich mache mir Sorgen, dass ich es nicht schaffe. Ich verstehe nichts von Blumen. Und nichts von Websites."],["Mia denkt an Frau Schulz und Heinrich. An Klaus und sein Fahrradgeschäft. Dann hat sie eine Idee."],["Drei Tage lang arbeitet sie fast ohne Pause. Max hilft ihr mit den Farben. Kemal programmiert. Jana sucht sich die schönsten Fotos aus."],["Freitag, sechzehn Uhr. Herr Krause sitzt im Besprechungsraum. Mia zeigt drei Entwürfe. Der erste ist klar und weiß. Der zweite ist grün und ruhig. Der dritte hat auf der Startseite das Foto von Hanna mit den Sonnenblumen. Darunter steht: Hannas Blumen. Seit 1985. Mit Liebe weitergeführt."],["Herr Krause sagt lange nichts. Er nimmt seine Brille ab und putzt sie. Sehr lange."],["Herr Krause","Den dritten. Genau so habe ich es mir vorgestellt. Ich habe es nur nicht gewusst."],["Als er geht, dreht er sich an der Tür noch einmal um."],["Herr Krause","Und, Frau Costa – kaufen Sie sich endlich ein Fahrrad. Ich sehe Sie jeden Morgen zur Straßenbahn rennen. Das ist nicht ordentlich."]],"q":["Wie sieht Herr Krause im Geschäft aus?","Was wünscht sich Herr Krause für die Website?","Wer ist die Frau auf dem Foto?","Richtig oder falsch? Herr Krause nimmt den ersten Entwurf.","Und du? Was wünschst du dir für dieses Jahr? Was kaufst du dir von deinem ersten Gehalt?"],"a":["Nicht im Anzug, sondern mit einer grünen Schürze. „Herr Krause trägt keinen Anzug, sondern eine grüne Schürze.“","Eine Website ohne Schnickschnack, klar und ordentlich. „Ich wünsche mir eine Website ohne Schnickschnack.“","Seine Frau Hanna. The shop was her dream; she died last year. „Meine Frau, Hanna. Das Geschäft war ihr Traum.“","Falsch. „Den dritten. Genau so habe ich es mir vorgestellt.“","Example: Ich wünsche mir mehr Zeit für meine Familie. Von meinem ersten Gehalt kaufe ich mir ein Fahrrad."],"w":[["sich etwas wünschen","to wish for sth.","Was wünschen Sie sich?"],["sich etwas vorstellen","to imagine sth.","Genau so habe ich es mir vorgestellt."],["sich etwas ansehen","to have a look at sth.","Darf ich mir das Geschäft ansehen?"],["sich die Hände waschen","to wash one's hands","Mia wäscht sich die Hände."],["sich Sorgen machen","to worry","Ich mache mir Sorgen."],["sich etwas aussuchen","to choose sth.","Jana sucht sich die schönsten Fotos aus."],["der Buchstabe, die Buchstaben","letter (of the alphabet)","in alten Buchstaben"],["die Rose, die Rosen","rose","Es riecht nach Rosen."],["die Erde","earth, soil","nach Rosen und nach Erde"],["anfassen","to touch","wenn Sie die Blumen anfassen"],["ordentlich","tidy, orderly","Klar und ordentlich."],["sterben (ist gestorben)","to die","Letztes Jahr ist sie gestorben."],["der Beamte, die Beamten","civil servant","Ich war Beamter."],["verkaufen","to sell","dass ich einmal Blumen verkaufe"],["schaffen","to manage","dass ich es nicht schaffe"]],"c":[["sich ein Bild machen","to get an idea","Ich möchte mir ein Bild machen."],["sich Notizen machen","to take notes","Sie macht sich Notizen."],["ohne Schnickschnack","without frills","eine Website ohne Schnickschnack"],["Das tut mir sehr leid.","I'm very sorry.","Das tut mir sehr leid."]],"x":[["Ich habe Erfahrung in …","I have experience in …",""],["Ich interessiere mich für die Stelle.","I am interested in the position.",""]],"g":["reflexive Verben mit Dativ",["If a reflexive verb also has an accusative object, the reflexive pronoun is dative.","Ich wasche mich. (accusative) · Ich wasche mir die Hände. (dative + accusative object)","Dative reflexive pronouns: mir, dir, sich, uns, euch, sich. Only ich and du look different from the accusative.","Typical verbs: sich etwas wünschen, sich etwas vorstellen, sich etwas ansehen, sich etwas kaufen, sich Sorgen machen.","Beispiele: Was wünschen Sie sich? · Kaufen Sie sich endlich ein Fahrrad. · Ich mache mir Sorgen."]]},{"n":58,"t":"Wohin mit dem Fahrrad?","l":"A2","review":false,"p":[["Ende Januar. Auf Mias Konto ist ihr erstes Gehalt. Sie sieht die Zahl dreimal an. Dann überweist sie Mama zweihundert Euro zurück. Die erste Rate."],["Und dann folgt sie dem Rat von Herrn Krause: Sie kauft sich ein Fahrrad."],["Jonas hat eine Idee. Am Samstag fahren sie zu seinen Eltern nach Merzhausen. Hinter dem Haus ist eine große Garage. In der Garage stehen zwanzig alte Fahrräder. An der Wand hängen Reifen, Ketten und Werkzeug."],["Klaus","Das ist mein Hobby. Ich repariere alte Räder. Seit dreißig Jahren. Seit dem Laden."],["Er zeigt auf ein blaues Damenrad mit einem Korb vorne."],["Klaus","Das hier. Ich habe es letzten Winter repariert. Neue Bremsen, neues Licht. Für dich: fünfzig Euro."],["Mia","Fünfzig? Das ist zu wenig!"],["Klaus","Gut. Dann fünfundvierzig."],["Alle lachen. Sogar Klaus."],["Mia fährt mit dem blauen Fahrrad nach Hause. Es fährt wunderbar. Aber zu Hause gibt es ein neues Problem: Wohin mit dem Fahrrad?"],["Mia stellt es in den Hausflur, an die Wand, neben Toms Rad. Zehn Minuten später klopft Frau Schulz."],["Frau Schulz","Frau Costa! Fahrräder kommen nicht in den Flur. Das steht in der Hausordnung, Paragraf vier."],["Mia","Aber Toms Fahrrad steht auch im Flur!"],["Frau Schulz","Herr Nowak hört es gerade auch. Herr Nowak!"],["Tom kommt aus seiner Wohnung. Bruno versteckt sich hinter ihm."],["Tom","Wohin sollen wir die Räder denn stellen? In den Keller? Die Treppe ist so steil!"],["Frau Schulz","In den Hof. Hinter das Haus. Da steht ein Fahrradständer. Seit 1987."],["Tom und Mia sehen sich an. Ein Fahrradständer? Hinter dem Haus? Das hat niemand gewusst."],["Am Montagabend beginnt der A2-Kurs. Abends, von achtzehn bis zwanzig Uhr. Mia fährt mit dem neuen Rad zur Sprachschule. Sie stellt es vor die Schule, an den Zaun."],["Im Kursraum sitzt Herr Brandt am Lehrertisch. Er trägt einen Schal. Grün und rot, wie die portugiesische Fahne. Ein Geschenk von Fátima, natürlich."],["Herr Brandt","Guten Abend, Frau Costa. Setzen Sie sich bitte in die erste Reihe."],["Mia","Warum in die erste Reihe?"],["Herr Brandt","Weil Sie in der ersten Reihe besser hören. Und weil ich in der ersten Reihe besser sehe, wer schläft."],["Mia setzt sich in die erste Reihe. Neben ihr sitzt Tom. Elif ist nicht da – sie hat jetzt Prüfungen an der Uni."],["Um Viertel nach acht kommt Mia nach Hause. Vor ihrer Tür steht ein riesiger Karton. Jonas sitzt daneben, mit einem Werkzeugkasten."],["Jonas","Überraschung! Ein Regal. Für deine Bücher. Sie liegen ja seit September auf dem Boden."],["Mia","Hast du die Anleitung?"],["Jonas","Anleitung? Wer braucht eine Anleitung?"]],"q":["Was macht Mia mit ihrem ersten Gehalt?","Was ist das Hobby von Klaus?","Wohin soll Mia das Fahrrad stellen? Wo steht der Fahrradständer?","Richtig oder falsch? Mia sitzt im A2-Kurs in der letzten Reihe.","Und du? Wo steht dein Fahrrad oder dein Auto? Wohin legst du abends deinen Schlüssel?"],"a":["She sends 200 € back to her mother and buys a bike. „Dann überweist sie Mama zweihundert Euro zurück … Sie kauft sich ein Fahrrad.“","He repairs old bikes. „Ich repariere alte Räder. Seit dreißig Jahren.“","In den Hof, hinter das Haus. Der Fahrradständer steht hinter dem Haus. „In den Hof. Hinter das Haus. Da steht ein Fahrradständer.“","Falsch. „Mia setzt sich in die erste Reihe.“","Example: Mein Fahrrad steht im Keller. Abends lege ich meinen Schlüssel auf den Tisch."],"w":[["das Gehalt, die Gehälter","salary","Auf Mias Konto ist ihr erstes Gehalt."],["die Rate, die Raten","instalment","Die erste Rate."],["der Rat","advice","Sie folgt dem Rat von Herrn Krause."],["die Garage, die Garagen","garage","In der Garage stehen zwanzig Fahrräder."],["der Reifen, die Reifen","tyre","An der Wand hängen Reifen."],["das Werkzeug, die Werkzeuge","tool(s)","Reifen, Ketten und Werkzeug"],["reparieren","to repair","Ich repariere alte Räder."],["die Bremse, die Bremsen","brake","Neue Bremsen, neues Licht."],["sich verstecken","to hide","Bruno versteckt sich hinter ihm."],["steil","steep","Die Treppe ist so steil!"],["der Fahrradständer, die Fahrradständer","bike rack","Da steht ein Fahrradständer."],["der Zaun, die Zäune","fence","Sie stellt es an den Zaun."],["die Reihe, die Reihen","row","Setzen Sie sich in die erste Reihe."],["die Fahne, die Fahnen","flag","wie die portugiesische Fahne"],["die Anleitung, die Anleitungen","instructions","Hast du die Anleitung?"]],"c":[["Wohin mit …?","Where to put …?","Wohin mit dem Fahrrad?"],["zu wenig","too little","Fünfzig? Das ist zu wenig!"],["Das steht in …","It says in …","Das steht in der Hausordnung."],["Wer braucht …?","Who needs …?","Wer braucht eine Anleitung?"]],"x":[["die Krankenversicherung, die Krankenversicherungen","health insurance",""]],"g":["Wechselpräpositionen – Wohin? oder Wo?",["The nine two-way prepositions (in, an, auf, unter, über, neben, hinter, vor, zwischen) take:","Wohin? (movement to a place) → accusative: Sie stellt das Rad in den Flur, an die Wand.","Wo? (location, no movement) → dative: Das Rad steht im Flur, an der Wand. (story 47)","Short forms: in das → ins, an das → ans, in dem → im, an dem → am.","Beispiele: Setzen Sie sich in die erste Reihe. (Wohin?) · Sie hören in der ersten Reihe besser. (Wo?)"]]},{"n":59,"t":"Das neue Regal","l":"A2","review":false,"p":[["Zwei Stunden später steht das Regal. Ein bisschen schief, aber es steht. Auf dem Boden liegt noch eine Schraube."],["Mia","Wohin gehört die Schraube?"],["Jonas","Das ist eine Extra-Schraube. Die gibt es immer."],["Jetzt kommt der schöne Teil. Mia stellt die Bücher ins Regal: portugiesische Romane, englische Krimis, deutsche Kinderbücher zum Üben. Jonas legt die Zeitschriften auf das unterste Brett. Ganz oben stellt Mia ein Foto von Opa vor seinem Café."],["Jonas","Und das hier? Wohin soll das?"],["Er hält die Wachsfigur von Silvester in der Hand. Das kleine Haus."],["Mia","Leg es neben das Foto. Ganz oben."],["Jetzt liegt das Wachshaus neben Opas Foto. Mia lächelt."],["Dann hängt Jonas Pauls Bild an die Wand – das Bild mit dem großen Herz. Es hängt jetzt über dem Sofa."],["Jonas","Fertig! Ich bin ein Genie."],["In diesem Moment kommt Felix durch die offene Tür. Er sieht das Regal. Er springt. Ein Brett, zwei Bretter, drei Bretter – und dann sitzt er ganz oben, neben dem Wachshaus."],["Das Regal wackelt. Es wackelt sehr."],["Mia","Felix, nein!"],["Krach! Das Regal fällt nach vorne. Bücher fliegen durch das Zimmer. Felix springt in letzter Sekunde auf das Sofa und sieht sehr unschuldig aus. Das Foto von Opa liegt auf dem Teppich. Das Glas ist kaputt."],["Mia hebt das Foto auf. Opa lächelt noch. Nur das Glas ist kaputt."],["Jonas","Es tut mir so leid. Das war die Extra-Schraube, oder?"],["Mia sieht in den Karton. Ganz unten liegt ein Heft. Montageanleitung. Schritt 14: Befestigen Sie das Regal mit dieser Schraube an der Wand."],["Mia","Die Extra-Schraube kommt in die Wand. Damit das Regal nicht umfällt."],["Jonas","Ah. Okay. Vielleicht braucht man doch eine Anleitung."],["Um Mitternacht steht das Regal wieder. Diesmal gerade, und mit der Schraube an der Wand. Die Bücher stehen wieder an ihrem Platz. Das Foto von Opa steht ohne Glas im Regal. Es sieht trotzdem schön aus."],["Sie sitzen müde auf dem Boden, mit dem Rücken am Sofa."],["Jonas","Weißt du, bei mir stehen dreißig Kochbücher. Bei dir stehen jetzt hundert Bücher. Und dann noch Felix, der überall sitzt."],["Mia","Und?"],["Jonas","Wenn wir einmal zusammenwohnen – wie auf deinem Zettel – brauchen wir eine größere Wohnung. Mit vielen Regalen. Und mit vielen Schrauben in der Wand."],["Mia legt ihren Kopf auf seine Schulter."],["Am nächsten Morgen klopft Frau Schulz. Sie hat einen Brief in der Hand."],["Frau Schulz","Neuigkeiten! Herr Neumann aus Wohnung zwei zieht aus. Ende März. Drei Zimmer, großer Balkon, neue Küche. Ich suche neue Mieter. Kennen Sie vielleicht jemanden?"],["Sie sieht Mia an. Dann sieht sie zur Treppe, nach oben, zu Wohnung vier. Sie lächelt ein ganz kleines Lächeln."]],"q":["Was stellt Mia ganz oben ins Regal?","Wohin hängt Jonas Pauls Bild?","Warum fällt das Regal um?","Richtig oder falsch? Die Extra-Schraube ist nicht wichtig.","Und du? Was steht in deinem Regal? Was hängt an deiner Wand? Was liegt auf deinem Tisch?"],"a":["Ein Foto von Opa vor seinem Café (und das Wachshaus). „Ganz oben stellt Mia ein Foto von Opa vor seinem Café.“","An die Wand, über das Sofa. „Dann hängt Jonas Pauls Bild an die Wand … Es hängt jetzt über dem Sofa.“","Felix jumps on it, and it isn't fixed to the wall. „Er springt … Das Regal wackelt.“","Falsch. „Befestigen Sie das Regal mit dieser Schraube an der Wand.“","Example: In meinem Regal stehen Bücher. An der Wand hängt ein Foto. Auf dem Tisch liegt mein Handy."],"w":[["stellen / stehen","to put (upright) / to stand","Mia stellt die Bücher ins Regal. · Die Bücher stehen im Regal."],["legen / liegen","to lay / to lie","Leg es neben das Foto. · Jetzt liegt das Wachshaus neben dem Foto."],["hängen (hängt – hat gehängt / hat gehangen)","to hang","Er hängt das Bild an die Wand. · Es hängt über dem Sofa."],["setzen / sitzen","to sit (sb.) down / to sit","Dann sitzt er ganz oben."],["schief / gerade","crooked / straight","Ein bisschen schief. · Diesmal gerade."],["die Schraube, die Schrauben","screw","Auf dem Boden liegt noch eine Schraube."],["das Brett, die Bretter","shelf board","auf das unterste Brett"],["der Roman, die Romane","novel","portugiesische Romane"],["die Zeitschrift, die Zeitschriften","magazine","Jonas legt die Zeitschriften auf das Brett."],["wackeln","to wobble","Das Regal wackelt."],["unschuldig","innocent","Felix sieht sehr unschuldig aus."],["aufheben","to pick up","Mia hebt das Foto auf."],["der Teppich, die Teppiche","carpet, rug","Das Foto liegt auf dem Teppich."],["befestigen","to fix, fasten","Befestigen Sie das Regal an der Wand."],["die Schulter, die Schultern","shoulder","Mia legt ihren Kopf auf seine Schulter."]],"c":[["in letzter Sekunde","at the last second","Felix springt in letzter Sekunde auf das Sofa."],["an seinem Platz","in its place","Die Bücher stehen wieder an ihrem Platz."],["ausziehen / einziehen","to move out / in","Herr Neumann zieht aus."],["Kennen Sie jemanden?","Do you know anyone?","Kennen Sie vielleicht jemanden?"]],"x":[["die Spritze, die Spritzen","injection",""],["der Blutdruck","blood pressure",""]],"g":["stellen – stehen, legen – liegen, hängen",["Action (Wohin?) + accusative, regular verbs: stellen, legen, setzen, hängen (hat gestellt, hat gelegt, hat gehängt).","State (Wo?) + dative, irregular verbs: stehen, liegen, sitzen, hängen (hat gestanden, hat gelegen, hat gehangen).","stellen/stehen = upright (books, bottles) · legen/liegen = flat (paper, a phone) · hängen = on a wall or hook.","Action → result: Ich stelle das Buch ins Regal. → Das Buch steht im Regal.","Beispiele: Jonas legt die Zeitschriften auf das Brett. · Das Bild hängt über dem Sofa."]]},{"n":60,"t":"Wiederholung: Ein Winterabend","l":"A2","review":true,"p":[["Sonntag, 4. Februar, zweiundzwanzig Uhr"],["Es schneit wieder. Felix liegt auf dem Elefant-Sofa, neben mir. Das Regal steht gerade, mit der Schraube in der Wand. Und ich schreibe, weil so viel passiert ist."],["Weihnachten bei Familie Weber war zuerst schwierig. Ich war nervös, weil ich Jonas' Eltern nicht kannte. Klaus war streng. Aber dann hat er erzählt, dass er früher selbst einen Traum hatte: ein Fahrradgeschäft. Ich glaube, dass er Jonas jetzt besser versteht. Und"],["mich auch. Er hat mir mein Fahrrad verkauft – für fünfundvierzig Euro. Das schönste Fahrrad in Freiburg!"],["Silvester auf dem Schlossberg war kälter als in Porto, aber romantischer. Mein Wachs war ein kleines Haus. Und mein dritter Vorsatz … Jonas hat ihn gelesen. Und er hat „Ich auch“ darunter geschrieben. Wenn ich daran denke, muss ich immer noch lächeln."],["Mein erster Arbeitstag war verrückt. Ich habe verschlafen und musste mich sehr beeilen. Und dann kam Herr Krause! Der Herr Krause vom Bürgeramt. Er ist jetzt Blumenhändler und unser schwierigster Kunde. Aber er ist auch ein trauriger Mann, weil seine Frau gestorben ist. Die Website mit Hannas Foto hat ihm gefallen. Ich bin so froh."],["Ich fühle mich wohl in der Agentur. Sabine ist super. Max lächelt manchmal – wirklich! Kemal programmiert schneller als alle anderen. Und Jana hat jede Woche eine andere Haarfarbe."],["Abends gehe ich zweimal pro Woche in den A2-Kurs. Ich sitze in der ersten Reihe, weil Herr Brandt sehen will, wer schläft. Tom schläft manchmal. Er arbeitet so viel."],["Und jetzt die größte Neuigkeit: Wohnung zwei wird frei. Drei Zimmer, großer Balkon. Jonas und ich haben lange geredet. Wir möchten zusammen dort wohnen. Aber Frau Schulz sagt, dass sie fair sein muss. Es gibt zwölf Interessenten! Sie will alle kennenlernen. Auch uns. Wie im Bürgeramt."],["Ich wünsche mir diese Wohnung so sehr. Wenn wir sie bekommen, stellen wir das Elefant- Sofa ins Wohnzimmer und hängen Pauls Bild an die Wand. Und Felix? Felix kommt sowieso, wann er will."],["Morgen fängt die Woche wieder an. Sabine hat gesagt, dass ein neuer Kollege kommt. Aus Berlin. Er heißt David. Max sagt, dass er sehr gut ist. Und sehr … charmant."]],"q":["weil: Mia war nervös. Sie kannte Jonas' Eltern nicht. → Mia war nervös, weil …","dass: Klaus hatte einen Traum. → Er hat erzählt, dass …","wenn: Du bist krank. Ruf bis neun Uhr an. → Wenn …","Komparativ: Silvester in Freiburg war ___ (kalt) als in Porto.","Superlativ: Herr Krause ist unser ___ (schwierig) Kunde.","Reflexiv (Akk.): Ich musste ___ sehr beeilen.","Reflexiv (Dat.): Ich wünsche ___ diese Wohnung.","Wohin? oder Wo?: Wir stellen das Sofa ___ Wohnzimmer. Das Sofa steht ___ Wohnzimmer.","legen oder liegen? Felix ___ auf dem Sofa. Ich ___ das Buch auf den Tisch.","so … wie: Freiburg ist fast ___ schön ___ Porto."],"a":["… weil sie Jonas' Eltern nicht kannte. The verb goes to the end (story 51).","… dass er einen Traum hatte. dass + verb at the end (story 52).","Wenn du krank bist, ruf bis neun Uhr an. wenn-clause first → main clause starts with the verb (story 53).","kälter. kalt adds an umlaut (story 54).","schwierigster. der schwierigste Kunde → unser schwierigster Kunde (story 55).","mich. ich → mich (story 56).","mir. Accusative object diese Wohnung → reflexive pronoun in dative (story 57).","ins · im. Wohin? → accusative; Wo? → dative (story 58).","liegt · lege. liegen = state; legen = action (story 59).","so … wie. (story 55)"],"w":[],"c":[],"x":[],"g":["Wiederholung",["Subordinate clauses with weil, dass, wenn: the verb goes to the end (stories 51–53).","Comparative -er + als, superlative am -sten / der -ste, so … wie (stories 54–55).","Reflexive verbs: mich/dich/sich (accusative) and mir/dir/sich (dative) (stories 56–57).","Two-way prepositions: Wohin? + accusative, Wo? + dative; stellen/stehen, legen/liegen, hängen (stories 58–59).","Beispiele: Wenn wir die Wohnung bekommen, stellen wir das Sofa ins Wohnzimmer. · Ich wünsche mir diese Wohnung."]],"exam":{"task":"Ein Freund fragt: „Wie war dein Winter?“ Schreiben Sie ihm eine E-Mail.","points":["Was haben Sie an Weihnachten oder Silvester gemacht?","Was war schön, was war nicht so schön?","Welche Pläne haben Sie für das neue Jahr?"],"words":40,"en":"Email about your winter: holidays, good/bad, plans for the new year."}},{"n":61,"t":"Der neue Kollege","l":"A2","review":false,"p":[["Montag, neun Uhr. Die Glastür geht auf, und der neue Kollege kommt herein. Er ist groß, hat dunkle Locken und trägt einen langen grauen Mantel. In der Hand hat er einen Kaffeebecher aus Bambus."],["David","Moin! Ich bin David. Aus Berlin."],["Jana","„Moin“ sagt man in Hamburg, nicht in Berlin."],["David","Ich weiß. Aber es ist das schönste Wort der Welt."],["Jana wird rot. Ihre Haare sind heute lila."],["David sitzt am Schreibtisch neben Mia. Er ist freundlich. Er bringt jeden Morgen Croissants mit. Er kennt die besten Programme und die neuen Trends. Nach drei Tagen mögen ihn alle. Sogar Otto, der alte Bürohund, legt sich unter den neuen Schreibtisch."],["David","Mia, die grüne Website für den Blumenladen – die ist von dir? Die ist richtig gut. Der kleine Kater auf der Startseite gefällt mir besonders."],["Mia","Danke. Der Kater ist ein echter Kater. Er heißt Felix."],["Am Donnerstag gibt es eine große Besprechung. Ein neuer Kunde: das Freiburger Stadtmuseum. Es möchte eine moderne Website für die junge Generation. Mia hat eine Idee. Sie erzählt David in der Kaffeeküche davon: Die alten Fotos aus dem Museum sollen sich bewegen, wenn man mit der Maus darüber fährt. Wie ein Zeitfenster."],["David","Wow. Das ist genial."],["In der Besprechung fragt Sabine: „Hat jemand eine Idee für das Museum?“"],["David steht sofort auf."],["David","Ich hatte gestern Abend eine Idee. Die alten Fotos bewegen sich, wenn man mit der Maus darüber fährt. Wie ein Zeitfenster."],["Sabine","Großartig, David! Genau so etwas suchen wir."],["Mia sagt nichts. Ihr Gesicht ist heiß. Max sieht Mia an. Dann sieht er David an. Er schreibt etwas in sein kleines schwarzes Heft."],["Nach der Besprechung kommt David zu Mia."],["David","Hey, nicht böse sein. Ich habe nur schneller geredet. Wir sind ja ein Team, oder? Komm, ich lade dich zum Mittagessen ein. Ich habe ein süßes kleines Café entdeckt, ganz in der Nähe. Café Sonne."],["Mia will Nein sagen. Aber dann denkt sie: Nein, ich gehe mit. Ich sage ihm dort die Wahrheit."],["Im Café Sonne steht Jonas hinter der Theke. Er sieht Mia mit dem großen Mann mit den dunklen Locken. Sein Lächeln wird kleiner."],["David","Zwei Cappuccino, bitte. Und für die junge Dame das beste Stück Kuchen, das Sie haben."],["Jonas","Die junge Dame isst am liebsten Apfelkuchen. Das weiß ich."],["David sieht von Jonas zu Mia. Und von Mia zu Jonas."],["David","Oh. Ihr kennt euch?"],["Mia","Das ist Jonas. Mein Freund."],["David lacht. Aber nur kurz."]],"q":["Wie sieht David aus?","Was ist Mias Idee für das Stadtmuseum?","Was macht David in der Besprechung?","Richtig oder falsch? Max merkt nichts.","Und du? Beschreibe einen Kollegen oder eine Kollegin. (Der neue … ist …, die schwarzen Haare …)"],"a":["Groß, dunkle Locken, ein langer grauer Mantel. „Er ist groß, hat dunkle Locken und trägt einen langen grauen Mantel.“","The old photos move when you move the mouse over them, like a window into time. „Wie ein Zeitfenster.“","He presents Mia's idea as his own. „Ich hatte gestern Abend eine Idee.“","Falsch. „Max sieht Mia an. Dann sieht er David an. Er schreibt etwas in sein Heft.“","Example: Die neue Kollegin heißt Anna. Sie hat die langen roten Haare und den lustigen Hund."],"w":[["die Locke, die Locken","curl","Er hat dunkle Locken."],["der Becher, die Becher","mug, cup","einen Kaffeebecher aus Bambus"],["das Programm, die Programme","program, software","Er kennt die besten Programme."],["der Trend, die Trends","trend","die neuen Trends"],["die Besprechung, die Besprechungen","meeting","Am Donnerstag gibt es eine große Besprechung."],["das Museum, die Museen","museum","das Freiburger Stadtmuseum"],["die Generation, die Generationen","generation","für die junge Generation"],["sich bewegen","to move","Die Fotos sollen sich bewegen."],["genial","brilliant","Das ist genial."],["großartig","great, terrific","Großartig, David!"],["böse sein","to be angry","Hey, nicht böse sein."],["einladen (lädt ein)","to invite","Ich lade dich zum Mittagessen ein."],["entdecken","to discover","Ich habe ein Café entdeckt."],["in der Nähe","nearby","ganz in der Nähe"],["das Mittagessen","lunch","zum Mittagessen"]],"c":[["Moin!","Hi! (northern German)","Moin! Ich bin David."],["so etwas","something like that","Genau so etwas suchen wir."],["mit der Maus darüber fahren","to hover the mouse over it","wenn man mit der Maus darüber fährt"],["Ihr kennt euch?","You know each other?","Oh. Ihr kennt euch?"]],"x":[["die Krankmeldung, die Krankmeldungen","sick note",""],["die Krankenkasse, die Krankenkassen","health insurer",""]],"g":["Adjektive nach der, die, das",["After the definite article (der, die, das, dieser), the adjective ending is -e or -en.","-e: nominative singular (all genders) and accusative feminine/neuter: der neue Kollege, die grüne Website, das schönste Wort.","-en: everything else – accusative masculine, all dative, all plural: den neuen Schreibtisch, mit dem großen Mann, die alten Fotos.","Tip: the article already shows the case, so the adjective takes the \"weak\" ending.","Beispiele: Der kleine Kater gefällt mir. · Sie geht mit dem großen Mann ins Café."]]},{"n":62,"t":"Eine größere Wohnung","l":"A2","review":false,"p":[["Nach dem Mittagessen im Café Sonne sagt Mia die Wahrheit. Auf dem Rückweg, auf der Straße."],["Mia","David, die Idee mit dem Museum war meine Idee. Das weißt du."],["David","Ach, Mia. In einem Team gehören Ideen allen. Das ist doch kein großes Problem."],["Mia","Für mich ist es ein großes Problem."],["David zuckt mit den Schultern. Mia ist wütend. Aber heute Abend gibt es etwas Wichtigeres: die Besichtigung von Wohnung zwei."],["Um achtzehn Uhr stehen sieben Leute im Treppenhaus: ein junges Paar mit einem kleinen Baby, ein alter Professor mit einer runden Brille, zwei Studentinnen mit bunten Rucksäcken – und Mia und Jonas."],["Frau Schulz öffnet die Tür. Sie hat eine Mappe und einen langen Kugelschreiber in der Hand. Sie sieht aus wie Herr Krause im Bürgeramt."],["Frau Schulz","Willkommen. Die Wohnung hat drei Zimmer, eine neue Küche, ein helles Bad und einen großen Balkon nach Süden. Die Miete ist neunhundertachtzig Euro warm. Bitte ziehen Sie die Schuhe aus."],["Die Wohnung ist wunderschön. Das Wohnzimmer hat einen alten Holzboden und ein großes Fenster. Die Küche hat einen modernen Herd und eine lange Arbeitsplatte. Und vom Balkon sieht man einen kleinen Garten und ein Stück vom Schlossberg."],["Jonas","Mia. Schau dir diese Küche an. In dieser Küche kann ich alles kochen."],["Mia","Und in diesem Zimmer steht mein neues Regal. Und dein altes Sofa. Und mein grünes Elefant-Sofa."],["Jonas","Zwei Sofas?"],["Mia","Eins für uns. Eins für Felix."],["Der Professor klopft an die Wand."],["Professor","Ich habe einen großen Flügel. Ein Klavier. Ich spiele jeden Abend. Zwei Stunden. Ist das ein Problem?"],["Frau Schulz schreibt etwas in ihre Mappe."],["Die Mutter mit dem Baby fragt: „Gibt es einen Platz für einen Kinderwagen?“ Die Studentinnen fragen: „Dürfen wir eine kleine Party machen? Einmal im Monat?“ Frau Schulz schreibt und schreibt."],["Dann sind Mia und Jonas dran."],["Frau Schulz","Und Sie? Was ist Ihre Frage?"],["Jonas","Wir haben keine Frage. Wir haben eine Bitte. Wir möchten in diesem Haus bleiben. Wir mögen dieses Haus. Wir mögen unsere Nachbarn. Und wir mögen unsere Vermieterin."],["Frau Schulz sieht von ihrer Mappe auf. Ihr Gesicht ist streng. Aber ihre Augen lächeln."],["Frau Schulz","Schöne Worte, Herr Weber. Aber ich muss fair sein. Ich habe zwölf Bewerber. Deshalb mache ich etwas Besonderes. Jeder Bewerber kocht mir ein Abendessen. Ich esse bei allen. Ein Essen sagt mehr als hundert Formulare."],["Mia","Ein Abendessen?!"],["Frau Schulz","Am Donnerstag. Um neunzehn Uhr. Bei Ihnen in Wohnung vier, Herr Weber. Ich freue mich."],["Der Professor wird blass. Die Studentinnen lachen. Jonas grinst wie ein kleiner Junge."],["Jonas","Mia. Endlich ein Wettbewerb, den ich gewinnen kann."]],"q":["Was sagt David über Mias Idee?","Wie ist die Wohnung? (Nenne drei Dinge.)","Wer will die Wohnung noch? (Nenne zwei Bewerber.)","Richtig oder falsch? Frau Schulz entscheidet nach den Formularen.","Und du? Beschreibe deine Traumwohnung. (Sie hat einen großen …, eine moderne …, ein helles …)"],"a":["In a team, ideas belong to everyone. „In einem Team gehören Ideen allen.“","E.g. drei Zimmer, eine neue Küche, ein helles Bad, ein großer Balkon nach Süden, ein alter Holzboden.","Ein junges Paar mit Baby, ein alter Professor, zwei Studentinnen.","Falsch. Every applicant cooks dinner: „Ein Essen sagt mehr als hundert Formulare.“","Example: Meine Traumwohnung hat einen großen Balkon, eine moderne Küche und ein helles Wohnzimmer."],"w":[["die Besichtigung, die Besichtigungen","viewing","die Besichtigung von Wohnung zwei"],["wütend","furious","Mia ist wütend."],["das Paar, die Paare","couple","ein junges Paar"],["das Baby, die Babys","baby","mit einem kleinen Baby"],["rund","round","mit einer runden Brille"],["der Rucksack, die Rucksäcke","backpack","mit bunten Rucksäcken"],["der Süden","south","einen großen Balkon nach Süden"],["der Holzboden, die Holzböden","wooden floor","einen alten Holzboden"],["die Arbeitsplatte, die Arbeitsplatten","worktop","eine lange Arbeitsplatte"],["der Flügel, die Flügel","grand piano","Ich habe einen großen Flügel."],["der Kinderwagen, die Kinderwagen","pram","einen Platz für einen Kinderwagen"],["der Bewerber, die Bewerber","applicant","Ich habe zwölf Bewerber."],["deshalb","therefore","Deshalb mache ich etwas Besonderes."],["grinsen","to grin","Jonas grinst."],["der Wettbewerb, die Wettbewerbe","competition","Endlich ein Wettbewerb!"]],"c":[["mit den Schultern zucken","to shrug","David zuckt mit den Schultern."],["etwas Wichtigeres","something more important","heute Abend gibt es etwas Wichtigeres"],["etwas Besonderes","something special","Ich mache etwas Besonderes."],["Schau dir … an!","Look at …!","Schau dir diese Küche an."]],"x":[["die Salbe, die Salben","ointment",""],["die Untersuchung, die Untersuchungen","examination",""]],"g":["Adjektive nach ein, kein, mein",["After ein, kein and possessives, the adjective shows the gender where the article cannot.","Nominative: ein großer Balkon (der) · eine neue Küche (die) · ein helles Bad (das).","Accusative: einen großen Balkon · eine neue Küche · ein helles Bad.","Dative and plural (keine, meine): always -en: mit einem kleinen Baby, meine bunten Rucksäcke.","Beispiele: Die Wohnung hat einen großen Balkon. · Das ist doch kein großes Problem."]]},{"n":63,"t":"Jonas kocht","l":"A2","review":false,"p":[["Donnerstag. Seit sechs Uhr morgens steht Jonas in der Küche. Er hat einen Plan. Ein Menü aus Portugal und aus dem Schwarzwald – wie Mia und er."],["Mia schreibt die Menükarte. Mit schöner Schrift, auf dickem Papier:"],["Vorspeise","Heiße Kürbissuppe mit gerösteten Kernen und frischem Brot"],["Hauptgericht","Gebratener Kabeljau mit grüner Kräutersoße und kleinen Kartoffeln"],["Nachspeise","Warme Pastéis de Nata mit frischer Sahne und schwarzem Kaffee"],["Jonas","Frischer Fisch ist das Wichtigste. Ich habe ihn heute Morgen auf dem Markt gekauft. Bei Fátima. Echter portugiesischer Kabeljau."],["Um neunzehn Uhr klingelt es. Frau Schulz trägt eine elegante Bluse und eine lange Perlenkette. Felix kommt natürlich mit."],["Frau Schulz","Guten Abend. Ich hatte schon drei Abendessen diese Woche. Die Studentinnen haben Nudeln mit Ketchup gekocht. Der Professor hat Brot mit Käse gekauft. Und die junge Familie hat Pizza bestellt, weil das Baby die ganze Zeit geschrien hat."],["Die Suppe ist ein Erfolg. Heiße Suppe an einem kalten Abend – Frau Schulz isst zwei Teller."],["Frau Schulz","Mit Ingwer, oder? Und ein bisschen Orange?"],["Jonas","Sie haben eine sehr gute Zunge, Frau Schulz."],["Frau Schulz","Mein Mann war Bäcker. Ich habe fünfzig Jahre lang gutes Essen gegessen."],["Dann holt Jonas den Fisch aus dem Ofen. Er stellt die Form auf die Arbeitsplatte, neben das offene Fenster. Damit er ein bisschen abkühlt. Dann geht er kurz ins Bad, um sich die Hände zu waschen."],["Als er zurückkommt, ist der Fisch weg."],["Nicht ganz weg. Ein Stück liegt noch in der Form. Und auf dem Fensterbrett sitzt ein grauer Kater mit einem sehr zufriedenen Gesicht."],["Jonas","Felix!!!"],["Felix","Miau."],["Mia hält sich die Hand vor den Mund. Frau Schulz wird ganz still. Dann fängt sie an zu lachen. Sie lacht so sehr, dass sie Tränen in den Augen hat."],["Frau Schulz","Das … das hat mein Heinrich auch einmal erlebt! Mit einem anderen Kater, an Weihnachten, mit einer ganzen Gans!"],["Jonas ist kurz verzweifelt. Dann macht er den Kühlschrank auf. Eier, Butter, frische Kräuter, alter Käse. In zehn Minuten steht ein neuer Teller auf dem Tisch: Rührei mit frischen Kräutern, gebratenem Speck und dem letzten Stück Kabeljau."],["Jonas","Improvisierte Küche. Spezialität des Hauses."],["Frau Schulz probiert. Sie sagt nichts. Sie isst alles."],["Die Pastéis sind perfekt. Warm, süß, mit frischer Sahne. Frau Schulz isst drei."],["Um elf geht sie. An der Tür dreht sie sich um."],["Frau Schulz","Herr Weber. Ein Koch, der einen Fehler hat und trotzdem ein gutes Essen macht … das ist ein guter Koch. Aber ich habe noch acht Bewerber. Am Sonntag sage ich meine Entscheidung."],["Die Tür geht zu. Jonas lässt sich auf das Sofa fallen."],["Jonas","Drei Tage warten. Das halte ich nicht aus."]],"q":["Was gibt es als Vorspeise, Hauptgericht und Nachspeise?","Was haben die anderen Bewerber gekocht?","Was passiert mit dem Fisch?","Richtig oder falsch? Frau Schulz ist sehr böse auf Felix.","Und du? Was ist dein Lieblingsessen? Beschreibe es. (Frisches Brot mit warmer Butter …)"],"a":["Kürbissuppe – gebratener Kabeljau mit grüner Kräutersoße – warme Pastéis de Nata. The menu card.","Nudeln mit Ketchup, Brot mit Käse und bestellte Pizza. „Die Studentinnen haben Nudeln mit Ketchup gekocht …“","Felix eats it from the window sill. „Auf dem Fensterbrett sitzt ein grauer Kater mit einem sehr zufriedenen Gesicht.“","Falsch. She laughs until she cries: it reminds her of Heinrich.","Example: Mein Lieblingsessen ist frische Pasta mit roter Soße und geriebenem Käse."],"w":[["das Menü, die Menüs","(set) menu","Ein Menü aus Portugal und aus dem Schwarzwald."],["die Vorspeise / das Hauptgericht / die Nachspeise","starter / main course / dessert","Vorspeise: Heiße Kürbissuppe"],["der Kürbis, die Kürbisse","pumpkin","Kürbissuppe"],["gebraten","fried, roasted","Gebratener Kabeljau"],["die Soße, die Soßen","sauce","mit grüner Kräutersoße"],["die Sahne","cream","mit frischer Sahne"],["das Kraut, die Kräuter","herb","Rührei mit frischen Kräutern"],["der Ingwer","ginger","Mit Ingwer, oder?"],["die Zunge, die Zungen","tongue","Sie haben eine sehr gute Zunge."],["bestellen","to order","Die Familie hat Pizza bestellt."],["der Erfolg, die Erfolge","success","Die Suppe ist ein Erfolg."],["abkühlen","to cool down","Damit er ein bisschen abkühlt."],["das Fensterbrett, die Fensterbretter","window sill","Auf dem Fensterbrett sitzt ein Kater."],["verzweifelt","desperate","Jonas ist kurz verzweifelt."],["die Entscheidung, die Entscheidungen","decision","Am Sonntag sage ich meine Entscheidung."]],"c":[["Spezialität des Hauses","speciality of the house","Spezialität des Hauses."],["sich die Hand vor den Mund halten","to put one's hand over one's mouth","Mia hält sich die Hand vor den Mund."],["anfangen zu lachen","to start laughing","Dann fängt sie an zu lachen."],["Das halte ich nicht aus.","I can't stand it.","Drei Tage warten. Das halte ich nicht aus."]],"x":[["die Verletzung, die Verletzungen","injury",""]],"g":["Adjektive ohne Artikel",["With no article, the adjective takes the endings of der/die/das itself, because nothing else shows the case.","Nominative: frischer Fisch (der) · frische Sahne (die) · frisches Brot (das) · frische Kräuter (plural).","Accusative: frischen Fisch · frische Sahne · frisches Brot.","Dative: mit frischem Brot · mit frischer Sahne · mit frischen Kräutern.","Typical on menus, in recipes and in adverts: Heiße Suppe an einem kalten Abend.","Beispiele: Frischer Fisch ist das Wichtigste. · Pastéis mit frischer Sahne und schwarzem Kaffee."]]},{"n":64,"t":"Warten auf Sonntag","l":"A2","review":false,"p":[["Freitag. Mia kann sich nicht auf die Arbeit konzentrieren. Sie denkt an Wohnung zwei. An den Holzboden, an den Balkon, an die große Küche. Und an die anderen acht Bewerber."],["Dann kommt Sabine an ihren Schreibtisch."],["Sabine","Mia, hast du kurz Zeit? Ich möchte mit dir sprechen. Im Besprechungsraum. Max kommt auch."],["Mia hat plötzlich Angst. Hat sie einen Fehler gemacht?"],["Im Besprechungsraum sitzt Max. Vor ihm liegt sein kleines schwarzes Heft."],["Sabine","Max hat mir etwas erzählt. Über das Museum. Über die Idee mit den Fotos."],["Max","Ich war am Mittwoch in der Kaffeeküche. Ich habe gehört, wie du David von der Idee erzählt hast. Einen Tag vor der Besprechung."],["Sabine","Ich ärgere mich sehr über diese Sache. Nicht über dich, Mia. Über David. Und auch über mich, weil ich es nicht gemerkt habe."],["Mia","Ich wollte nichts sagen. Ich wollte keine Probleme."],["Sabine","Das verstehe ich. Aber hier darf man über Probleme sprechen. Das ist Regel Nummer fünf. Also: Du leitest das Museumsprojekt. David arbeitet mit dir. Nicht umgekehrt."],["Am Nachmittag steht David an Mias Schreibtisch. Er hat zwei Kaffee in der Hand und sieht nicht mehr so sicher aus."],["David","Mia … Es tut mir leid. Wirklich. In Berlin war mein Chef so. Wer am lautesten redet, gewinnt. Ich habe nicht nachgedacht."],["Mia","Okay. Ich nehme die Entschuldigung an. Und den Kaffee auch."],["Samstag. Mia und Jonas warten. Jonas putzt die ganze Wohnung. Zweimal. Mia sitzt auf dem Sofa und sieht auf ihr Handy."],["Jonas","Ich interessiere mich nicht für den Professor. Ich interessiere mich nicht für die Studentinnen. Ich denke nur an diese Küche."],["Mia","Und ich träume von dem Balkon. Mit Blumen von Herrn Krause."],["Sonntag, zehn Uhr. Es klopft. Frau Schulz steht vor der Tür. Sie hat einen Umschlag in der Hand. Felix sitzt neben ihr wie ein Notar."],["Frau Schulz","Ich habe mich entschieden. Es war nicht leicht. Der Professor hat am Freitag Schubert für mich gespielt. Wunderschön. Die junge Familie war so nett. Aber ich habe an mein Haus gedacht. An die Menschen hier. Und an meinen Kater."],["Sie gibt Jonas den Umschlag."],["Frau Schulz","Der Mietvertrag. Ab dem ersten April. Für Sie beide."],["Mia schreit. Jonas hebt Frau Schulz hoch – vorsichtig – und dreht sich mit ihr im Kreis."],["Frau Schulz","Herr Weber! Lassen Sie mich runter! Ich bin vierundsiebzig!"],["Jonas","Danke! Danke! Danke!"],["Frau Schulz","Bedanken Sie sich bei Felix. Er hat den Kabeljau gegessen. Das war für mich ein Zeichen. Er gehört zu Ihnen."],["Am Abend sitzen Mia und Jonas auf dem leeren Balkon von Wohnung zwei. Es ist kalt, aber sie haben eine Decke. Mia freut sich auf den Frühling. Auf die Blumen. Auf das gemeinsame Leben."],["Aber Jonas ist still. Er sieht in die Dunkelheit."]],"q":["Was hat Max in der Kaffeeküche gehört?","Worüber ärgert sich Sabine?","Was ist jetzt Mias Rolle im Museumsprojekt?","Richtig oder falsch? Frau Schulz gibt die Wohnung dem Professor.","Und du? Worauf freust du dich? Wofür interessierst du dich? Worüber ärgerst du dich?"],"a":["How Mia told David about the idea, one day before the meeting. „Ich habe gehört, wie du David von der Idee erzählt hast.“","About David – and about herself, because she didn't notice. „Ich ärgere mich sehr über diese Sache.“","She leads the project; David works with her. „Du leitest das Museumsprojekt.“","Falsch. „Der Mietvertrag. Ab dem ersten April. Für Sie beide.“","Example: Ich freue mich auf den Sommer. Ich interessiere mich für Musik. Ich ärgere mich über Verspätungen."],"w":[["warten auf (+ Akk.)","to wait for","Mia und Jonas warten auf Sonntag."],["sich konzentrieren auf (+ Akk.)","to concentrate on","Sie kann sich nicht auf die Arbeit konzentrieren."],["denken an (+ Akk.)","to think of","Sie denkt an Wohnung zwei."],["sprechen mit / über","to talk to / about","Ich möchte mit dir sprechen."],["sich interessieren für (+ Akk.)","to be interested in","Ich interessiere mich nicht für den Professor."],["träumen von (+ Dat.)","to dream of","Ich träume von dem Balkon."],["sich freuen auf / über","to look forward to / be happy about","Mia freut sich auf den Frühling."],["sich entscheiden (für)","to decide (on)","Ich habe mich entschieden."],["sich bedanken bei","to thank sb.","Bedanken Sie sich bei Felix."],["leiten","to lead, manage","Du leitest das Museumsprojekt."],["merken","to notice","weil ich es nicht gemerkt habe"],["die Entschuldigung, die Entschuldigungen","apology","Ich nehme die Entschuldigung an."],["der Notar, die Notare","notary","wie ein Notar"],["gemeinsam","shared, together","das gemeinsame Leben"],["die Dunkelheit","darkness","Er sieht in die Dunkelheit."]],"c":[["Hast du kurz Zeit?","Have you got a minute?","Mia, hast du kurz Zeit?"],["eine Entschuldigung annehmen","to accept an apology","Ich nehme die Entschuldigung an."],["Lassen Sie mich runter!","Put me down!","Herr Weber! Lassen Sie mich runter!"],["zu jemandem gehören","to belong with sb.","Er gehört zu Ihnen."]],"x":[["der Unfall, die Unfälle","accident",""],["die Allergie, die Allergien","allergy",""]],"g":["Verben mit Präpositionen",["Many verbs always go with a fixed preposition. Learn them together: warten auf, denken an, sich interessieren für.","The preposition decides the case: auf, an, für, über + accusative (here) · von, mit, bei + dative.","The meaning can change with the preposition: sich freuen auf (future) · sich freuen über (now/past).","Beispiele: Mia freut sich auf den Frühling. · Ich interessiere mich nicht für den Professor. · Ich träume von dem Balkon."]]},{"n":65,"t":"Woran denkst du?","l":"A2","review":false,"p":[["Mia","Jonas? Woran denkst du?"],["Jonas","Ach, an nichts."],["Mia","Das glaube ich nicht. Du denkst an etwas. Ich sehe es."],["Jonas schweigt. Dann sieht er Mia an."],["Jonas","Okay. Ich denke an das Geld. Die Miete ist neunhundertachtzig Euro. Du verdienst mehr als ich. Viel mehr. Ich bin Koch. Köche verdienen nicht viel."],["Mia","Und? Worüber machst du dir Sorgen? Darüber, dass ich mehr verdiene?"],["Jonas","Nein. Ja. Ein bisschen. Ich will nicht, dass du alles bezahlst. Und ich will nicht für immer im Café Sonne arbeiten. Ich bin einunddreißig."],["Mia","Wovon träumst du? Ehrlich?"],["Jonas","Das weißt du. Von Café Bächle. Davon träume ich jede Nacht. Aber wofür spare ich? Ich habe dreitausend Euro. Für ein Café braucht man fünfzigtausend. Mindestens."],["Mia nimmt seine Hand unter der Decke."],["Mia","Weißt du, worauf ich stolz bin? Darauf, dass ich nach Freiburg gekommen bin. Ohne Deutsch, ohne Bett, ohne Job. Alle haben gesagt: Das ist verrückt. Und jetzt sitze ich hier. Auf meinem eigenen Balkon. Mit dir."],["Jonas","Das ist etwas anderes."],["Mia","Wieso? Worauf wartest du? Darauf, dass jemand anders dein Café aufmacht?"],["Jonas sagt nichts. Lange. Dann lacht er leise."],["Jonas","Du klingst wie mein Vater. Der neue Vater."],["Mia","Gut. Und jetzt erzähl mir, worüber du wirklich nachdenkst. Da ist noch etwas. Ich weiß es."],["Jonas holt tief Luft."],["Jonas","Die Bäckerei an der Ecke. Die Bäckerei von Felix. Herr Haas, der Bäcker, hat mir am Dienstag etwas erzählt. Er ist siebenundsechzig. Er hört im Sommer auf. Seine Kinder wollen die Bäckerei nicht. Sie suchen einen neuen Mieter."],["Mia","Die Bäckerei von Heinrich? Die von Frau Schulz' Mann?"],["Jonas","Genau die. Mit dem alten Ofen. Mit der Holztheke. Mit dem kleinen Hof hinten. Mia, das ist … das ist Café Bächle. Ich habe es sofort gesehen."],["Mia","Und? Was hast du ihm gesagt?"],["Jonas","Nichts. Ich habe nur genickt. Und dann bin ich nach Hause gegangen und habe Angst bekommen."],["Mia","Wovor hast du Angst?"],["Jonas","Davor, dass es nicht funktioniert. Wie bei meinem Vater."],["Mia sieht in die Nacht. Unten im Hof steht ihr blaues Fahrrad. Klaus hat es repariert. Mit seinen alten, guten Händen."],["Mia","Dein Vater hat damals keinen Businessplan gehabt. Und keine Webdesignerin. Und keine Vermieterin, die Bäckereien kennt."],["Am Montagmorgen, um sieben Uhr, stehen Mia und Jonas vor der Bäckerei. Im Fenster hängt ein neues Schild: Ladenlokal zu vermieten – ab 1. Juli. Bei Interesse bitte melden."],["Jonas liest das Schild. Einmal, zweimal, dreimal."],["Jonas","Ich würde so gern …"],["Er spricht den Satz nicht zu Ende."]],"q":["Woran denkt Jonas zuerst? Worüber macht er sich Sorgen?","Wie viel Geld hat Jonas? Wie viel braucht man für ein Café?","Worauf ist Mia stolz?","Richtig oder falsch? Die Kinder von Herrn Haas wollen die Bäckerei übernehmen.","Und du? Worauf bist du stolz? Wovor hast du Angst? Wovon träumst du?"],"a":["An das Geld. That Mia pays for everything, and that he stays at Café Sonne forever. „Ich denke an das Geld.“","3.000 Euro. Mindestens 50.000 Euro. „Ich habe dreitausend Euro. Für ein Café braucht man fünfzigtausend.“","That she came to Freiburg without German, a bed or a job. „Darauf, dass ich nach Freiburg gekommen bin.“","Falsch. „Seine Kinder wollen die Bäckerei nicht.“","Example: Ich bin stolz darauf, dass ich Deutsch lerne. Ich habe Angst vor Spinnen. Ich träume von einer Reise nach Japan."],"w":[["woran / worüber / wovon / worauf / wofür / wovor","what … about, of, for, etc.","Woran denkst du?"],["daran / darüber / davon / darauf / dafür / davor","about it, of it, for it, etc.","Davon träume ich jede Nacht."],["schweigen","to be silent","Jonas schweigt."],["für immer","forever","Ich will nicht für immer im Café arbeiten."],["stolz sein auf","to be proud of","Weißt du, worauf ich stolz bin?"],["wieso","why","Wieso?"],["klingen","to sound","Du klingst wie mein Vater."],["Luft holen","to take a breath","Jonas holt tief Luft."],["aufhören","to stop, retire","Er hört im Sommer auf."],["die Holztheke","wooden counter","Mit der Holztheke."],["funktionieren","to work, function","dass es nicht funktioniert"],["damals","back then","Dein Vater hat damals keinen Businessplan gehabt."],["das Ladenlokal, die Ladenlokale","shop premises","Ladenlokal zu vermieten"],["vermieten","to let, rent out","zu vermieten – ab 1. Juli"],["sich melden","to get in touch","Bei Interesse bitte melden."]],"c":[["an nichts","about nothing","Ach, an nichts."],["etwas anderes","something different","Das ist etwas anderes."],["Angst bekommen","to get scared","Dann habe ich Angst bekommen."],["bei Interesse","if interested","Bei Interesse bitte melden."]],"x":[["sich verletzen","to get hurt",""],["sich erkälten","to catch a cold",""]],"g":["wo- und da- (Präpositionaladverbien)",["For things (not people), the preposition joins wo- (question) or da- (answer/reference).","denken an → Woran denkst du? – Daran. · träumen von → Wovon? – Davon.","Before a vowel, add -r-: woran, darauf, worüber. (wofür, davon need no -r-.)","For people, use preposition + pronoun: An wen denkst du? – An dich.","da- can point forward to a dass-clause: Ich bin stolz darauf, dass ich hier bin.","Beispiele: Wovor hast du Angst? – Davor, dass es nicht funktioniert."]]},{"n":66,"t":"Ich würde gern …","l":"A2","review":false,"p":[["Sonntagnachmittag. Mia hat alle eingeladen: Frau Schulz, Tom, Elif, Lena, Klaus und Ingrid. Es gibt Kaffee und Kuchen – gekauft, natürlich. Jonas steht vor allen, sehr nervös. Er erzählt von der Bäckerei an der Ecke."],["Jonas","Also … ich würde gern dort ein Café aufmachen. Café Bächle. Aber ich weiß nicht, wie. Was würdet ihr an meiner Stelle machen?"],["Einen Moment ist es still. Dann reden alle gleichzeitig."],["Elif","Ich würde Crowdfunding machen! Im Internet. Viele Leute geben ein bisschen Geld, und dafür bekommen sie später einen Kaffee gratis. Oder einen Kuchen."],["Tom","Ich würde mit der Bank sprechen. Und ich würde jeden Tag Würste verkaufen. Würste verkaufen sich immer."],["Lena","Ich würde nicht sofort kündigen. Ich würde zuerst einen genauen Plan machen. Mit Zahlen."],["Ingrid","Und ich würde jeden Samstag kommen und Kuchen backen. Ich backe besser als mein Sohn."],["Alle lachen. Dann ist es Klaus, der spricht."],["Klaus","An deiner Stelle würde ich zwei Dinge machen. Erstens: Ich würde mir einen erfahrenen Partner suchen. Für die Zahlen. Zweitens: Ich würde nicht den gleichen Fehler machen wie ich. Ich hatte zu wenig Geld und zu viel Stolz. Ich habe niemanden um Hilfe gebeten."],["Jonas","Und wer wäre der Partner?"],["Klaus","Ich. Wenn du willst. Ich bin Rentner. Ich habe Zeit. Und ich kann gut rechnen. Ich würde dir beim Businessplan helfen."],["Jonas sieht seinen Vater an. Er kann nicht sprechen. Ingrid nimmt Klaus' Hand."],["Dann räuspert sich Frau Schulz."],["Frau Schulz","Darf ich auch etwas sagen? Ich würde den Ofen behalten. Heinrichs Ofen. Er ist sechzig Jahre alt, aber er backt das beste Brot in Freiburg. Und ich würde mit Familie Haas sprechen. Ich kenne die Familie seit vierzig Jahren. Frau Haas war meine Schülerin. Sie hat Klavier gespielt. Sehr schlecht."],["Mia","Und ich würde die Website machen. Die gibt es ja schon."],["Jonas","Ihr seid … ihr seid verrückt. Alle."],["Elif","Und du? Was würdest du jetzt machen?"],["Jonas nimmt sein Handy. Er wählt eine Nummer. Die Nummer vom Schild im Fenster."],["Jonas","Guten Tag, Herr Haas. Hier ist Jonas Weber. Der Koch aus dem Café Sonne. Ich würde mir gern die Bäckerei ansehen. … Ja. … Ja, sehr gern. … Morgen um zehn? Das passt."],["Alle klatschen. Dann wird Jonas' Gesicht ernst."],["Jonas","Wie bitte? … Ein anderer Interessent? … Eine Kaffeekette? … Aus Hamburg. Aha. … Bis Freitag? … Ich verstehe. Danke. Bis morgen."],["Er legt auf."],["Jonas","Es gibt schon einen anderen Interessenten. Eine große Kaffeekette. Sie bietet mehr Miete. Herr Haas entscheidet am Freitag."],["Die Stimmung fällt. Nur Frau Schulz lächelt."],["Frau Schulz","Eine Kaffeekette? In Heinrichs Bäckerei? Das werden wir ja sehen."]],"q":["Was würde Elif machen?","Was würde Klaus an Jonas' Stelle machen?","Woher kennt Frau Schulz Familie Haas?","Richtig oder falsch? Jonas ist der einzige Interessent.","Und du? Was würdest du an Jonas' Stelle machen? Was würdest du gern einmal machen?"],"a":["Crowdfunding im Internet. „Ich würde Crowdfunding machen!“","Find an experienced partner for the numbers, and ask for help. „Ich würde mir einen erfahrenen Partner suchen.“","Frau Haas was her piano pupil, and she has known the family for 40 years. „Frau Haas war meine Schülerin.“","Falsch. A big coffee chain from Hamburg is also interested.","Example: Ich würde mit der Bank sprechen. Ich würde gern einmal nach Australien fliegen."],"w":[["würde (+ Infinitiv)","would","Ich würde gern dort ein Café aufmachen."],["gleichzeitig","at the same time","Dann reden alle gleichzeitig."],["das Ding, die Dinge","thing","zwei Dinge"],["erfahren","experienced","einen erfahrenen Partner"],["der Partner, die Partner","partner","Und wer wäre der Partner?"],["der Stolz","pride","zu viel Stolz"],["um Hilfe bitten","to ask for help","Ich habe niemanden um Hilfe gebeten."],["der Rentner, die Rentner","pensioner","Ich bin Rentner."],["rechnen","to calculate","Ich kann gut rechnen."],["sich räuspern","to clear one's throat","Frau Schulz räuspert sich."],["behalten","to keep","Ich würde den Ofen behalten."],["der Interessent, die Interessenten","interested party","ein anderer Interessent"],["die Kette, die Ketten","chain","eine Kaffeekette"],["bieten","to offer","Sie bietet mehr Miete."],["ernst","serious","Dann wird Jonas' Gesicht ernst."]],"c":[["an meiner / deiner Stelle","in my / your place","Was würdet ihr an meiner Stelle machen?"],["Das passt.","That works (for me).","Morgen um zehn? Das passt."],["… verkaufen sich immer","… always sell","Würste verkaufen sich immer."],["Die Stimmung fällt.","The mood drops.","Die Stimmung fällt."]],"x":[["sich ausruhen","to rest",""],["gesund werden","to get well",""]],"g":["Konjunktiv II mit würde",["würde + infinitive = would. Use it for wishes, imagined situations and advice.","Forms: ich würde, du würdest, er würde, wir würden, ihr würdet, sie würden.","würde in position 2, infinitive at the end: Ich würde gern ein Café aufmachen.","Advice: An deiner Stelle würde ich … · Wish: Ich würde gern …","Beispiele: Ich würde mit der Bank sprechen. · Was würdest du jetzt machen?"]]},{"n":67,"t":"Könnten Sie mir helfen?","l":"A2","review":false,"p":[["Montag, zehn Uhr. Die Bäckerei ist noch offen, aber halb leer. Herr Haas zeigt Jonas und Klaus alles: den Verkaufsraum mit der alten Holztheke, die Backstube mit dem großen Ofen, den kleinen Hof mit einem alten Kastanienbaum."],["Jonas","Herr Haas, könnten Sie mir sagen, wie alt der Ofen ist?"],["Herr Haas","Neunzehnhundertvierundsechzig. Heinrich Schulz hat ihn gekauft. Er läuft wie am ersten Tag."],["Klaus","Und wie hoch wäre die Miete?"],["Herr Haas","Zweitausendzweihundert Euro im Monat. Die Kette aus Hamburg würde zweitausendsiebenhundert zahlen. Das wissen Sie ja."],["Jonas schluckt. Fünfhundert Euro mehr. Jeden Monat."],["Am Dienstag hat Jonas einen Termin bei der Bank. Bei Herrn Wagner – dem Berater mit der Fahrrad-Krawatte. Mia geht mit."],["Jonas","Guten Tag, Herr Wagner. Ich hätte gern einen Kredit. Für ein Café."],["Herr Wagner","Ein Café. Interessant. Hätten Sie einen Businessplan für mich?"],["Klaus","Hier. Dreißig Seiten. Mit allen Zahlen. Für drei Jahre."],["Herr Wagner blättert. Er blättert lange. Er nickt."],["Herr Wagner","Das ist ein sehr guter Plan. Wirklich. Ein Kredit wäre möglich. Aber nicht über fünfzigtausend Euro. Höchstens über vierzigtausend. Den Rest müssten Sie selbst haben."],["Mia","Könnten Sie uns ein paar Tage Zeit geben? Wir hätten vielleicht noch eine andere Lösung."],["Herr Wagner","Natürlich. Rufen Sie mich an."],["Die andere Lösung heißt Elif. Am Mittwoch geht ihre Crowdfunding-Seite online: Café Bächle – ein Café mit Herz für Freiburg. Mit Mias Website, mit Fotos von der Bäckerei, mit einem Video von Jonas in der Küche. Und mit einem Foto von Felix, natürlich."],["Wer zwanzig Euro gibt, bekommt zehn Kaffee gratis. Wer hundert Euro gibt, bekommt seinen Namen auf einer Holztafel im Café."],["Nach einem Tag haben hundert Leute gespendet. Nach zwei Tagen sind es viertausend Euro. Herr Brandt hat zweihundert Euro gegeben. Herr Krause dreihundert – mit der Bemerkung: Für Ordnung und gutes Brot. Fátima hat fünfzig Euro gegeben und hundert Pastéis versprochen."],["Am Donnerstagabend klopft Frau Schulz bei Jonas und Mia."],["Frau Schulz","Ich war heute bei Frau Haas. Wir haben Tee getrunken. Ich habe gefragt: Wäre es nicht schön, wenn Heinrichs Ofen weiter Brot backt? Und nicht nur Kaffee aus einer Maschine?"],["Mia","Und? Was hat sie gesagt?"],["Frau Schulz","Sie hat gesagt: Das wäre schön. Aber das Geld … Ihr Mann möchte das Geld von der Kette. Sie überlegen noch. Ich gehe morgen früh noch einmal hin. Um acht Uhr. Vor der Entscheidung."],["Jonas","Frau Schulz, Sie müssen das nicht machen."],["Frau Schulz","Herr Weber. Ich bin vierundsiebzig Jahre alt. Ich muss gar nichts. Ich möchte."],["In der Nacht friert es. Der Regen von gestern wird zu Eis. Auf den Straßen. Auf dem Hof. Und auf den drei Steinstufen vor dem Haus."]],"q":["Wie alt ist der Ofen? Wer hat ihn gekauft?","Wie viel Miete würde die Kaffeekette zahlen?","Wie viel Kredit wäre möglich?","Richtig oder falsch? Herr Krause hat nichts für das Crowdfunding gegeben.","Und du? Formuliere drei höfliche Bitten. (Könnten Sie …? Hätten Sie …? Wäre es möglich, …?)"],"a":["From 1964. Heinrich Schulz bought it. „Neunzehnhundertvierundsechzig. Heinrich Schulz hat ihn gekauft.“","2.700 Euro im Monat – 500 € more than Jonas. „Die Kette aus Hamburg würde zweitausendsiebenhundert zahlen.“","Höchstens 40.000 Euro. „Höchstens über vierzigtausend.“","Falsch. „Herr Krause dreihundert – mit der Bemerkung: Für Ordnung und gutes Brot.“","Example: Könnten Sie mir bitte helfen? Hätten Sie einen Moment Zeit? Wäre es möglich, morgen zu kommen?"],"w":[["könnte / hätte / wäre","could / would have / would be","Ein Kredit wäre möglich."],["der Verkaufsraum, die Verkaufsräume","sales area","den Verkaufsraum mit der Holztheke"],["die Backstube, die Backstuben","bakehouse","die Backstube mit dem großen Ofen"],["schlucken","to swallow","Jonas schluckt."],["der Kredit, die Kredite","loan","Ich hätte gern einen Kredit."],["die Seite, die Seiten","page","Dreißig Seiten."],["blättern","to leaf through","Herr Wagner blättert."],["möglich","possible","Ein Kredit wäre möglich."],["höchstens","at most","Höchstens über vierzigtausend."],["der Rest","rest, remainder","Den Rest müssten Sie selbst haben."],["spenden","to donate","Hundert Leute haben gespendet."],["die Bemerkung, die Bemerkungen","remark","mit der Bemerkung"],["überlegen","to consider","Sie überlegen noch."],["das Eis","ice","Der Regen wird zu Eis."],["die Stufe, die Stufen","step","auf den drei Steinstufen"]],"c":[["Könnten Sie mir sagen, …?","Could you tell me …?","Könnten Sie mir sagen, wie alt der Ofen ist?"],["Ich hätte gern …","I'd like …","Ich hätte gern einen Kredit."],["Wäre es nicht schön, wenn …?","Wouldn't it be nice if …?","Wäre es nicht schön, wenn Heinrichs Ofen weiter backt?"],["Ich muss gar nichts.","I don't have to do anything.","Ich muss gar nichts. Ich möchte."]],"x":[["Mir ist schlecht.","I feel sick.",""]],"g":["Konjunktiv II – hätte, wäre, könnte (höfliche Bitten)",["haben → hätte · sein → wäre · können → könnte (umlaut + -e). These are used directly, not with würde.","Forms: ich hätte, du hättest, er hätte, wir hätten, ihr hättet, sie hätten (same pattern for wäre, könnte).","Polite requests: Könnten Sie …? · Ich hätte gern … · Wäre es möglich, …?","Also for unreal or hypothetical ideas: Ein Kredit wäre möglich.","Beispiele: Hätten Sie einen Businessplan für mich? · Könnten Sie uns ein paar Tage Zeit geben?"]]},{"n":68,"t":"Ein schlimmer Tag","l":"A2","review":false,"p":[["Mias Tagebuch, Freitag, dreiundzwanzig Uhr"],["Was für ein Tag. Ich muss alles aufschreiben, sonst kann ich nicht schlafen."],["Um sieben Uhr fünfundfünfzig wollte ich zur Arbeit fahren. Ich war schon im Treppenhaus, mit dem Fahrradhelm in der Hand. Da hörte ich einen Schrei. Draußen, vor der Haustür."],["Frau Schulz lag auf den Steinstufen. Auf dem Eis. Sie konnte nicht aufstehen. Ihr Gesicht war grau, und sie hatte große Schmerzen in der Hüfte."],["Ich wollte ihr helfen, aber ich durfte sie nicht bewegen. Das wusste ich vom Erste-Hilfe- Kurs in Porto. Ich musste sofort den Notarzt rufen. Hundertzwölf. Meine Hände zitterten. Ich konnte die Nummer zuerst nicht wählen."],["Die Frau am Telefon war sehr ruhig. Sie wollte alles genau wissen: Wo? Wer? Wie alt? Ist sie wach? Kann sie sprechen? Ich musste alles auf Deutsch erklären. Und ich konnte es. Ich weiß nicht, wie. Aber ich konnte es."],["Tom kam aus seiner Wohnung und brachte eine Decke. Bruno setzte sich neben Frau Schulz und legte seinen Kopf auf ihre Hand. Und Felix? Felix saß in der Tür und miaute die ganze Zeit. So laut. So traurig."],["Nach acht Minuten kam der Krankenwagen. Die Sanitäter waren sehr nett. Frau Schulz wollte nicht ins Krankenhaus. Sie wollte zu Frau Haas."],["„Ich muss um acht bei Frau Haas sein!“, sagte sie immer wieder. „Heute ist die Entscheidung!“"],["Der Sanitäter sagte","„Heute gehen Sie nirgendwohin. Nur ins Krankenhaus.“"],["Ich durfte im Krankenwagen mitfahren. Unterwegs rief ich Sabine an. Regel Nummer eins: Wenn du nicht kommen kannst, ruf bis neun Uhr an. Es war acht Uhr zwanzig. Sabine sagte nur: „Bleib bei ihr. Die Arbeit kann warten.“"],["Im Krankenhaus mussten wir lange warten. Dann kam eine Ärztin. Die Hüfte ist gebrochen. Frau Schulz muss heute noch operiert werden."],["Bevor sie in den OP musste, nahm Frau Schulz meine Hand. Sie war sehr blass, aber ihre Stimme war stark."],["„Frau Costa. Sie müssen zu Frau Haas gehen. Jetzt. Sagen Sie ihr, warum ich nicht kommen konnte. Und sagen Sie ihr: Heinrichs Ofen gehört nicht in eine Kaffeekette. Versprechen Sie mir das.“"],["Ich versprach es."],["Um elf stand ich in der Bäckerei. Frau Haas war hinter der Theke. Ich erzählte ihr alles: das Eis, die Stufen, das Krankenhaus. Und was Frau Schulz gesagt hatte."],["Frau Haas wurde ganz still. Dann nahm sie ihre Schürze ab."],["„Sie wollte zu mir kommen? Bei diesem Eis? Mit vierundsiebzig?“, fragte sie leise. „Ich muss mit meinem Mann sprechen.“"],["Jetzt ist es dreiundzwanzig Uhr. Die Operation ist gut gegangen, hat die Ärztin am Telefon gesagt. Jonas schläft neben mir auf dem Sofa. Er war den ganzen Nachmittag im Krankenhaus. Felix liegt auf meinen Füßen. Er wollte nicht allein unten bleiben."],["Und von Familie Haas – noch kein Wort."]],"q":["Was ist mit Frau Schulz passiert?","Warum durfte Mia Frau Schulz nicht bewegen?","Was mussten Mia und Tom machen? Was machte Bruno?","Richtig oder falsch? Frau Schulz wollte sofort ins Krankenhaus.","Und du? Was musstest du gestern machen? Was wolltest du als Kind werden? Was durftest du als Kind nicht?"],"a":["She slipped on the icy steps and broke her hip. „Frau Schulz lag auf den Steinstufen. Auf dem Eis.“ – „Die Hüfte ist gebrochen.“","She learned it in a first-aid course in Porto. „Das wusste ich vom Erste-Hilfe-Kurs in Porto.“","Mia had to call 112; Tom brought a blanket; Bruno put his head on her hand.","Falsch. „Frau Schulz wollte nicht ins Krankenhaus. Sie wollte zu Frau Haas.“","Example: Gestern musste ich lange arbeiten. Als Kind wollte ich Pilot werden. Ich durfte nicht lange fernsehen."],"w":[["wollte / konnte / musste / durfte / sollte","wanted / could / had to / was allowed / should have","Ich wollte zur Arbeit fahren."],["der Schrei, die Schreie","scream","Da hörte ich einen Schrei."],["der Schmerz, die Schmerzen","pain","Sie hatte große Schmerzen."],["die Hüfte, die Hüften","hip","Schmerzen in der Hüfte"],["der Notarzt, die Notärzte","emergency doctor","Ich musste den Notarzt rufen."],["der Krankenwagen, die Krankenwagen","ambulance","Nach acht Minuten kam der Krankenwagen."],["der Sanitäter, die Sanitäter","paramedic","Die Sanitäter waren sehr nett."],["der Helm, die Helme","helmet","mit dem Fahrradhelm"],["Erste Hilfe","first aid","vom Erste-Hilfe-Kurs"],["gebrochen","broken (bone)","Die Hüfte ist gebrochen."],["operieren","to operate","Sie muss operiert werden."],["die Operation, die Operationen","operation","Die Operation ist gut gegangen."],["der OP","operating theatre","Bevor sie in den OP musste …"],["nirgendwohin","nowhere","Heute gehen Sie nirgendwohin."],["bevor","before (conj.)","Bevor sie in den OP musste …"]],"c":[["Was für ein Tag!","What a day!","Was für ein Tag."],["immer wieder","again and again","sagte sie immer wieder"],["Versprechen Sie mir das.","Promise me.","Versprechen Sie mir das."],["noch kein Wort","not a word yet","Von Familie Haas – noch kein Wort."]],"x":[["Ich bin krankgeschrieben.","I am on sick leave.",""],["Mein Kopf tut weh.","my head hurts.",""]],"g":["Präteritum der Modalverben",["In the past, modal verbs are usually used in the Präteritum, not the Perfekt.","Stem without umlaut + -te: wollen → wollte · können → konnte · müssen → musste · dürfen → durfte · sollen → sollte · mögen → mochte.","Forms: ich konnte, du konntest, er konnte, wir konnten, ihr konntet, sie konnten (ich = er).","Second verb at the end: Sie konnte nicht aufstehen.","In stories and diaries, you also meet other verbs in the Präteritum: hörte, lag, kam, sagte (more in story 92).","Beispiele: Ich musste sofort den Notarzt rufen. · Ich durfte im Krankenwagen mitfahren."]]},{"n":69,"t":"Im Krankenhaus","l":"A2","review":false,"p":[["Montag. Frau Schulz liegt seit drei Tagen im Krankenhaus. Ihr Zimmer ist im vierten Stock, gegenüber vom Aufzug. Das Bett steht am Fenster. Von dort sieht man das Münster."],["Mia kommt nach der Arbeit, mit dem Fahrrad. Sie bringt ein Foto von Felix mit. Und eine Brezel. Aus der Bäckerei an der Ecke, natürlich."],["Frau Schulz","Endlich ein normales Essen! Seit Freitag bekomme ich nur Suppe und Pudding."],["Mia","Wie geht es Ihnen?"],["Frau Schulz","Die Hüfte tut weh. Aber der Kopf funktioniert noch. Der Arzt kommt jeden Morgen um sieben. Nach dem Frühstück kommt die Physiotherapeutin. Sie ist sehr streng. Ich mag sie."],["Im zweiten Bett liegt eine alte Dame mit weißen Locken. Sie strickt einen langen roten Schal."],["Frau Schulz","Das ist Frau Bauer. Sie ist seit einer Woche hier. Sie kommt aus dem Kaiserstuhl. Sie hat einen Weinberg. Mit dreiundachtzig!"],["Frau Bauer","Und Sie sind die Portugiesin? Renate erzählt nur von Ihnen. Und von dem Kater."],["Dann klopft es. Ein großer Mann mit grauem Bart kommt herein. Michael, der Sohn von Frau Schulz."],["Michael","Hallo, Mama. Hallo, Mia. Ich bin seit gestern Abend in Freiburg. Mit dem Nachtzug aus Hamburg. Ab morgen arbeite ich von hier, im Homeoffice. Ich bleibe, so lange Mama mich braucht."],["Frau Schulz","Ich brauche niemanden. Ich brauche nur eine neue Hüfte."],["Michael","Die hast du ja jetzt."],["Alle lachen, sogar Frau Schulz."],["Um sechs Uhr klopft es noch einmal. In der Tür steht Frau Haas. In der Hand hat sie einen großen Strauß Tulpen. Gelb und orange. Auf dem Papier steht: Hannas Blumen."],["Frau Haas","Die sind von Herrn Krause. Ich war gerade bei ihm im Geschäft. Er hat gesagt: „Für die mutigste Frau von Freiburg. Keine Rechnung.“"],["Frau Schulz","Herr Krause? Ohne Rechnung? Dann muss es mir wirklich schlecht gehen."],["Frau Haas setzt sich zu ihr ans Bett. Sie nimmt Frau Schulz' Hand."],["Frau Haas","Renate. Ich habe mit meinem Mann gesprochen. Seit Freitag reden wir über nichts anderes. Er wollte zuerst das Geld von der Kette. Aber dann hat er gehört, was passiert ist. Dass Sie bei diesem Eis zu uns kommen wollten. Für Heinrichs Ofen."],["Sie holt tief Luft."],["Frau Haas","Wir vermieten an Jonas. Nicht an die Kette. Ab dem ersten Juli. Und Heinrichs Ofen bleibt, wo er ist."],["Frau Schulz sagt nichts. Sie schließt die Augen. Eine Träne läuft über ihr Gesicht. Frau Bauer hört auf zu stricken."],["Mia ruft sofort Jonas an. Er ist noch im Café Sonne. Mia hört durch das Telefon, wie ein Teller auf den Boden fällt."],["Als Mia geht, kommt die Ärztin ins Zimmer. Sie spricht leise mit Michael auf dem Flur. Mia hört nur ein paar Wörter."],["„… nach dem Krankenhaus drei Wochen Reha … danach … ob sie wieder allein in ihrer Wohnung leben kann … das wissen wir noch nicht …“"],["Michael nickt langsam. Sein Gesicht ist ernst."]],"q":["Seit wann liegt Frau Schulz im Krankenhaus?","Wer ist Frau Bauer? Woher kommt sie?","Von wem sind die Tulpen?","Richtig oder falsch? Familie Haas vermietet die Bäckerei an die Kaffeekette.","Und du? Seit wann lernst du Deutsch? Mit wem sprichst du am meisten? Was machst du nach der Arbeit?"],"a":["Seit drei Tagen – seit Freitag. „Frau Schulz liegt seit drei Tagen im Krankenhaus.“","The woman in the second bed, 83, with a vineyard in the Kaiserstuhl. „Sie kommt aus dem Kaiserstuhl. Sie hat einen Weinberg.“","Von Herrn Krause. „Die sind von Herrn Krause.“","Falsch. „Wir vermieten an Jonas. Nicht an die Kette.“","Example: Ich lerne seit einem Jahr Deutsch. Ich spreche am meisten mit meiner Schwester. Nach der Arbeit gehe ich joggen."],"w":[["seit (+ Dativ)","since, for","Sie liegt seit drei Tagen im Krankenhaus."],["gegenüber (von)","opposite","gegenüber vom Aufzug"],["ab (+ Dativ / Zeit)","from (on)","Ab morgen arbeite ich von hier."],["der Aufzug, die Aufzüge","lift, elevator","gegenüber vom Aufzug"],["der Pudding, die Puddings","pudding","nur Suppe und Pudding"],["die Physiotherapeutin, die Physiotherapeutinnen","physiotherapist (f)","Nach dem Frühstück kommt die Physiotherapeutin."],["stricken","to knit","Sie strickt einen langen roten Schal."],["der Weinberg, die Weinberge","vineyard","Sie hat einen Weinberg."],["der Nachtzug, die Nachtzüge","night train","mit dem Nachtzug aus Hamburg"],["das Homeoffice","working from home","im Homeoffice"],["der Strauß, die Sträuße","bunch (of flowers)","einen großen Strauß Tulpen"],["die Tulpe, die Tulpen","tulip","Tulpen. Gelb und orange."],["die Rechnung, die Rechnungen","bill, invoice","Keine Rechnung."],["schließen","to close","Sie schließt die Augen."],["die Reha","rehab","drei Wochen Reha"]],"c":[["so lange …","as long as …","Ich bleibe, so lange Mama mich braucht."],["über nichts anderes","about nothing else","Seit Freitag reden wir über nichts anderes."],["aufhören zu …","to stop doing …","Frau Bauer hört auf zu stricken."],["Es geht mir schlecht.","I'm not well.","Dann muss es mir wirklich schlecht gehen."]],"x":[["der Hausmeister, die Hausmeister","caretaker",""],["die Steckdose, die Steckdosen","socket",""]],"g":["alle Präpositionen mit Dativ",["These prepositions always take the dative: aus, bei, mit, nach, seit, von, zu, gegenüber (and ab for time).","seit + present tense = something started in the past and is still true: Sie liegt seit drei Tagen hier. (not Perfekt!)","ab = from a point on (future): Ab morgen arbeite ich von hier.","gegenüber often goes with von: gegenüber vom Aufzug.","Beispiele: Michael ist seit gestern Abend in Freiburg. · Er kommt mit dem Nachtzug aus Hamburg."]]},{"n":70,"t":"Wiederholung: Ein Brief in die Reha","l":"A2","review":true,"p":[["Freiburg, den 2. April"],["Liebe Frau Schulz,"],["wie geht es Ihnen? Ist die strenge Physiotherapeutin auch in der Reha? Michael hat erzählt, dass Sie schon mit dem Rollator durch den ganzen Park laufen. Das freut mich so sehr!"],["Hier gibt es viele Neuigkeiten. Ich erzähle alles, weil Sie Neuigkeiten lieber mögen als Blumen."],["Erstens","Wir sind umgezogen! Seit gestern wohnen Jonas und ich in Wohnung zwei. Tom, Elif, Lena und Stefan haben geholfen. Und Klaus hat alle Möbel getragen, obwohl Ingrid es ihm verboten hat. Das neue Regal steht im großen Wohnzimmer, mit der Schraube in der"],["Wand. Das grüne Elefant-Sofa steht am Fenster. Und Ihr Kater liegt den ganzen Tag darauf."],["Ja, Felix wohnt bei uns, bis Sie zurückkommen. Er schläft in seinem Korb neben der Heizung. Morgens sitzt er auf dem Balkon und sieht zur Bäckerei. Ich glaube, er wartet auf Sie."],["Zweitens","Café Bächle. Das Crowdfunding ist vorbei. Zweihundertsiebzig Menschen haben gespendet. Zusammen sind es elftausend Euro! Mit dem Kredit von der Bank reicht das Geld. Klaus und Jonas sitzen jeden Abend über dem Businessplan. Sie streiten sich manchmal, aber sie lachen auch viel. Ingrid sagt, dass sie die beiden noch nie so glücklich gesehen hat."],["Am ersten Juli bekommt Jonas den Schlüssel für die Bäckerei. Heinrichs Ofen bleibt. Jonas möchte, dass Sie das erste Brot probieren. Er wartet nur auf Sie."],["Drittens","Die Arbeit. Ich leite jetzt das Projekt für das Stadtmuseum. David arbeitet mit mir. Er ist ein besserer Kollege geworden. Er bringt mir jeden Morgen einen Kaffee und sagt: „Das war deine Idee.“ Jeden Morgen! Max findet das sehr lustig."],["Und viertens","Meine Mutter kommt! In zwei Wochen, für zehn Tage. Sie will Freiburg sehen, Jonas kennenlernen und – das hat sie ganz deutlich gesagt – „die Frau, die meine Tochter gerettet hat“. Damit meint sie Sie, Frau Schulz."],["Mama spricht kein Deutsch. Jonas spricht kein Portugiesisch. Ich glaube, das wird interessant."],["Bitte werden Sie schnell gesund. Das Haus ist zu still ohne Sie. Niemand sagt uns, dass man am Sonntag nicht bohren darf."],["Viele liebe Grüße Ihre Mia"],["PS","Felix hat gestern einen Löffel in seinen Korb gebracht. Den silbernen Löffel aus Ihrer Küche. Ich glaube, er vermisst Sie."]],"q":["Adjektiv nach der: Der ___ (neu) Kollege kommt aus Berlin.","Adjektiv nach ein: Die Wohnung hat einen ___ (groß) Balkon.","Adjektiv ohne Artikel: ___ (frisch) Fisch ist das Wichtigste.","Verb + Präposition: Mia freut sich ___ den Frühling.","wo-/da-: ___ denkst du? – Ich denke ___, dass alles gut wird.","würde: Was ___ du an meiner Stelle machen?","Höfliche Bitte: ___ Sie mir bitte helfen? (können)","Präteritum: Frau Schulz ___ nicht aufstehen. (können)","seit oder ab? Sie liegt ___ drei Tagen im Krankenhaus. ___ morgen arbeitet Michael von hier.","Was ist am ersten Juli?"],"a":["neue. Nominative after der → -e (story 61).","großen. Accusative masculine after einen → -en (story 62).","Frischer. No article → the adjective shows the gender: -er (story 63).","auf. sich freuen auf = look forward to (story 64).","Woran · daran. denken an → woran / daran (story 65).","würdest. (story 66)","Könnten. (story 67)","konnte. (story 68)","seit · Ab. seit = since (still true); ab = from now on (story 69).","Jonas gets the key to the bakery. „Am ersten Juli bekommt Jonas den Schlüssel für die Bäckerei.“"],"w":[],"c":[],"x":[],"g":["Wiederholung",["Adjective endings after der (story 61), after ein (story 62), without an article (story 63).","Verbs with prepositions and wo-/da- words (stories 64–65).","Konjunktiv II: würde, hätte, wäre, könnte (stories 66–67).","Präteritum of modal verbs (story 68) · dative prepositions, seit, ab (story 69).","Beispiele: Das grüne Elefant-Sofa steht am Fenster. · Jonas möchte, dass Sie das erste Brot probieren."]],"exam":{"task":"Eine Kollegin ist krank. Schreiben Sie ihr eine Karte.","points":["Wünschen Sie gute Besserung.","Erzählen Sie kurz, was es Neues bei der Arbeit gibt.","Bieten Sie Hilfe an."],"words":40,"en":"Get-well card to a colleague: wish recovery, news from work, offer help."}},{"n":71,"t":"Wird alles gut?","l":"A2","review":false,"p":[["Samstag. Mia und Michael fahren mit dem Zug nach Bad Krozingen. Die Reha-Klinik liegt in einem großen Park. Frau Schulz sitzt auf einer Bank in der Sonne, mit einem Rollator neben sich."],["Frau Schulz","Frau Costa! Haben Sie meinen Brief bekommen? Ich habe zurückgeschrieben. Mit der Hand."],["Mia","Ja, gestern. Danke!"],["Frau Schulz","Und? Frisst Felix genug? Schläft er gut? Ich weiß nicht, ob er mich vergessen hat."],["Mia","Er hat Sie nicht vergessen. Er sitzt jeden Morgen auf dem Balkon und sieht nach unten. Zu Ihrer Tür."],["Frau Schulz sieht weg. Sie putzt ihre Brille."],["Dann sagt Michael etwas. Vorsichtig."],["Michael","Mama, ich habe nachgedacht. Ich frage mich, ob du nicht zu mir nach Hamburg kommen möchtest. Wir haben ein Gästezimmer. Ohne Treppen. Und ich könnte mich um dich kümmern."],["Es ist lange still."],["Frau Schulz","Ich weiß nicht, ob ich das kann, Michael. Ich wohne seit fünfzig Jahren in Freiburg. In diesem Haus. Heinrich ist in Freiburg. Auf dem Friedhof. Und Felix …"],["Michael","Felix kann mitkommen."],["Frau Schulz","Felix in Hamburg? Felix hasst Regen."],["Mia muss lachen, obwohl die Situation traurig ist."],["Mia","Frau Schulz, was sagt die Ärztin? Können Sie wieder allein wohnen?"],["Frau Schulz","Sie sagt, dass ich mit dem Rollator gut laufe. In der Wohnung ist alles kein Problem. Das Erdgeschoss hat keine Treppen. Aber vor dem Haus sind die drei Stufen. Die gleichen drei Stufen. Sie weiß nicht, ob ich die schaffe. Jeden Tag. Auch im Winter."],["Auf der Rückfahrt im Zug sieht Mia aus dem Fenster. Drei Stufen. Nur drei Stufen. Dann hat sie eine Idee."],["Am Montag geht sie in der Mittagspause in die Konviktstraße. Herr Krause steht in seinem Blumengeschäft."],["Mia","Herr Krause, Sie waren dreißig Jahre im Bürgeramt. Wissen Sie, ob man für eine Rampe Geld von der Stadt bekommt? Für eine ältere Dame, nach einer Hüftoperation?"],["Herr Krause nimmt seine Brille ab. Seine Augen werden ganz klar."],["Herr Krause","Für Frau Schulz?"],["Mia","Für Frau Schulz."],["Herr Krause","Die Pflegekasse zahlt bis zu viertausend Euro für den Umbau einer Wohnung. Man braucht einen Antrag. Formular vierzehn, mit einem Attest vom Arzt. Ich weiß nicht, ob Sie das allein ausfüllen können. Ich komme heute Abend vorbei und helfe Ihnen."],["Mia","Herr Krause, Sie sind ein Engel."],["Herr Krause","Ich bin ein Beamter. Im Ruhestand. Das ist fast das Gleiche."],["Am Abend sitzen Mia, Jonas, Michael und Herr Krause in der neuen Küche von Wohnung zwei. Auf dem Tisch liegen Formulare. Herr Krause hat drei verschiedene Kugelschreiber dabei. Felix liegt auf dem Formular vierzehn."],["Um elf ist alles fertig. Michael ruft seine Mutter an."],["Michael","Mama, wir haben eine Lösung. Eine Rampe. Du kannst nach Hause kommen. Wenn du möchtest."],["Am Telefon ist es still. Dann hört man nur ein leises Wort: „Danke.“"],["In der Nacht liegt Mia wach. Eine Sorge weniger. Aber am Samstag kommt Mama. Zehn Tage lang. Ob Mama Freiburg mag? Ob Mama und Jonas sich verstehen? Ohne gemeinsame Sprache?"]],"q":["Wo ist Frau Schulz? Womit läuft sie?","Was möchte Michael?","Warum weiß die Ärztin nicht, ob Frau Schulz allein wohnen kann?","Richtig oder falsch? Herr Krause kann nicht helfen, weil er nicht mehr im Bürgeramt arbeitet.","Und du? Was weißt du noch nicht? (Ich weiß nicht, ob …) Was fragst du dich manchmal?"],"a":["In der Reha-Klinik in Bad Krozingen, mit einem Rollator.","That his mother moves to Hamburg to live with him. „Ich frage mich, ob du nicht zu mir nach Hamburg kommen möchtest.“","Because of the three steps in front of the house. „Sie weiß nicht, ob ich die schaffe. Jeden Tag.“","Falsch. He knows the form and helps: „Formular vierzehn … Ich komme heute Abend vorbei und helfe Ihnen.“","Example: Ich weiß nicht, ob ich im Sommer Urlaub bekomme. Ich frage mich oft, ob mein Deutsch besser wird."],"w":[["ob","whether, if","Ich weiß nicht, ob er mich vergessen hat."],["sich fragen","to wonder","Ich frage mich, ob du …"],["die Klinik, die Kliniken","clinic","Die Reha-Klinik liegt in einem Park."],["der Rollator, die Rollatoren","walking frame","mit einem Rollator"],["fressen (frisst)","to eat (animals)","Frisst Felix genug?"],["das Gästezimmer, die Gästezimmer","guest room","Wir haben ein Gästezimmer."],["sich kümmern um","to look after","Ich könnte mich um dich kümmern."],["der Friedhof, die Friedhöfe","cemetery","Auf dem Friedhof."],["obwohl","although","obwohl die Situation traurig ist"],["die Rampe, die Rampen","ramp","Geld für eine Rampe"],["die Pflegekasse","care insurance","Die Pflegekasse zahlt bis zu 4.000 €."],["der Antrag, die Anträge","application (form)","Man braucht einen Antrag."],["das Attest, die Atteste","doctor's certificate","mit einem Attest vom Arzt"],["der Ruhestand","retirement","Im Ruhestand."],["verschieden","different, various","drei verschiedene Kugelschreiber"]],"c":[["bis zu …","up to …","bis zu viertausend Euro"],["vorbeikommen","to drop by","Ich komme heute Abend vorbei."],["Sie sind ein Engel.","You're an angel.","Herr Krause, Sie sind ein Engel."],["eine Sorge weniger","one worry less","Eine Sorge weniger."]],"x":[["der Umzug, die Umzüge","move (house)",""]],"g":["Nebensatz mit ob",["ob (whether/if) turns a yes/no question into a subordinate clause. The verb goes to the end.","Hat er mich vergessen? → Ich weiß nicht, ob er mich vergessen hat.","Typical before ob: Ich weiß nicht, … · Ich frage mich, … · Wissen Sie, …? · Kannst du mir sagen, …?","Don't confuse: ob = whether (yes/no?) · wenn = if/when (condition).","Ob …? alone = \"I wonder whether …\": Ob Mama Freiburg mag?","Beispiele: Wissen Sie, ob man Geld von der Stadt bekommt? · Sie weiß nicht, ob ich die Stufen schaffe."]]},{"n":72,"t":"Mama kommt!","l":"A2","review":false,"p":[["Samstag, vierzehn Uhr. Freiburger Hauptbahnhof, Gleis eins. Mama kommt mit dem Bus vom Flughafen Basel. Mia steht seit einer halben Stunde am Bahnhof. Jonas steht neben ihr, in einem frisch gebügelten Hemd. Er hat drei Wochen lang mit Fátima Portugiesisch geübt."],["Dann sieht Mia sie. Eine kleine Frau mit dunklen Locken und einem riesigen roten Koffer."],["Mama","(auf Portugiesisch) Mia! Minha filha!"],["Sie umarmen sich lange. Mama weint, Mia weint. Jonas hält den Koffer. Er ist sehr schwer."],["Jonas","Was ist in dem Koffer? Steine?"],["Mia","Sardinen. Wein. Käse. Und Bolo Rei. Meine Mutter glaubt, dass es in Deutschland nichts zu essen gibt."],["Dann steht Jonas vor Mama. Er holt tief Luft."],["Jonas","Muito prazer, Senhora Costa. Eu sou o Jonas."],["Mama sieht ihn an. Dann sieht sie Mia an. Dann lacht sie und küsst Jonas auf beide Wangen. Und dann redet sie – schnell, sehr schnell, auf Portugiesisch."],["Jonas","Mia … was sagt sie?"],["Mia","Sie möchte wissen, wie alt du bist. Und wo du kochst. Und wie lange du schon in Freiburg wohnst."],["Jonas","Sag ihr, dass ich einunddreißig bin. Dass ich im Café Sonne koche. Und dass ich mein ganzes Leben hier wohne."],["Mia übersetzt. Mama nickt. Dann fragt sie wieder etwas. Mia wird rot."],["Jonas","Was? Was fragt sie jetzt?"],["Mia","Sie fragt, warum du so dünn bist, wenn du Koch bist. Und … sie möchte wissen, wann du mich heiratest."],["Jonas wird auch rot. Mama lacht laut. Die Leute am Bahnhof drehen sich um."],["Am Abend kocht Jonas. Er hat lange überlegt, was er kochen soll. Etwas Deutsches? Etwas Portugiesisches? Am Ende macht er Bacalhau à Brás – Stockfisch mit Kartoffeln und Eiern. Das Lieblingsessen von Mias Opa. Fátima hat ihm verraten, wie man es richtig macht."],["Mama probiert. Alle warten. Felix wartet auch, unter dem Tisch."],["Mama","(auf Portugiesisch) Mia. Frag ihn, wer ihm das gezeigt hat."],["Mia","Sie fragt, wer dir das gezeigt hat."],["Jonas","Eine Freundin aus Lissabon. Fátima. Vom Markt."],["Mama isst noch einen Teller. Und noch einen. Dann sagt sie etwas zu Mia, ganz leise."],["Jonas","Was hat sie gesagt?"],["Mia","Sie hat gesagt: „Er weiß, wie man Bacalhau kocht. Und er weiß, wie man dich ansieht. Das reicht.“"],["Jonas sagt nichts. Er lächelt nur. Mama tätschelt seine Hand."],["Später, auf dem Balkon, sieht Mama über die Dächer von Freiburg. Sie trinkt einen Tee aus der Kaffeetasse mit Mias Namen."],["Mama","(auf Portugiesisch) Morgen will ich alles sehen. Das Münster. Den Markt. Diese Frau Schulz, die meine Tochter gerettet hat. Und kannst du mir sagen, wo dieses berühmte Bächle ist?"],["Mia","Warum?"],["Mama","Ich trete hinein. Für Rui. Er braucht auch eine nette Frau."]],"q":["Was ist in Mamas Koffer?","Was hat Jonas vorbereitet?","Was möchte Mama von Jonas wissen? (Nenne zwei Fragen.)","Richtig oder falsch? Mama findet Jonas' Bacalhau schlecht.","Und du? Stell dir vor, du triffst die Eltern von einem Freund. Was möchtest du wissen? (Ich möchte wissen, wo / wie / warum …)"],"a":["Sardinen, Wein, Käse und Bolo Rei. „Meine Mutter glaubt, dass es in Deutschland nichts zu essen gibt.“","He practised Portuguese with Fátima for three weeks and learned to cook Bacalhau à Brás.","E.g. wie alt er ist, wo er kocht, wann er Mia heiratet. „Sie möchte wissen, wie alt du bist.“","Falsch. She eats three plates: „Er weiß, wie man Bacalhau kocht.“","Example: Ich möchte wissen, woher sie kommen, was sie gern machen und wie sie sich kennengelernt haben."],"w":[["der Hauptbahnhof, die Hauptbahnhöfe","main station","Freiburger Hauptbahnhof"],["das Gleis, die Gleise","platform, track","Gleis eins"],["der Flughafen, die Flughäfen","airport","vom Flughafen Basel"],["bügeln (gebügelt)","to iron","in einem frisch gebügelten Hemd"],["das Hemd, die Hemden","shirt","ein Hemd"],["der Stein, die Steine","stone","Was ist in dem Koffer? Steine?"],["die Wange, die Wangen","cheek","auf beide Wangen"],["übersetzen","to translate","Mia übersetzt."],["dünn","thin","warum du so dünn bist"],["das Lieblingsessen","favourite food","das Lieblingsessen von Mias Opa"],["verraten","to reveal, tell","Fátima hat ihm verraten, wie …"],["tätscheln","to pat","Mama tätschelt seine Hand."],["berühmt","famous","dieses berühmte Bächle"],["retten (gerettet)","to save, rescue","die meine Tochter gerettet hat"],["hineintreten","to step into","Ich trete hinein."]],"c":[["Muito prazer. (Port.)","Nice to meet you.","Muito prazer, Senhora Costa."],["Sag ihr, dass …","Tell her that …","Sag ihr, dass ich einunddreißig bin."],["Er weiß, wie man …","He knows how to …","Er weiß, wie man Bacalhau kocht."],["Das reicht.","That's enough.","Das reicht."]],"x":[["die Kaution, die Kautionen","deposit",""],["die Nebenkosten (plural only)","utility costs",""]],"g":["indirekte W-Fragen",["A W-question can become a subordinate clause. The W-word stays, and the verb goes to the end.","Wie alt bist du? → Sie möchte wissen, wie alt du bist.","Wer hat dir das gezeigt? → Sie fragt, wer dir das gezeigt hat.","Typical openings: Sie fragt, … · Ich möchte wissen, … · Kannst du mir sagen, …? · Weißt du, …?","Indirect questions are more polite than direct ones: Können Sie mir sagen, wo das Bächle ist?","Beispiele: Sie möchte wissen, wann du mich heiratest. · Er weiß, wie man Bacalhau kocht."]]},{"n":73,"t":"Durch die Altstadt","l":"A2","review":false,"p":[["Sonntag. Mia hat einen Plan für Mama. Ohne Plan geht es nicht, denn Mama will alles sehen. In einem Tag."],["Um neun Uhr gehen sie los. Zuerst durch die Altstadt. Mama bleibt vor jedem Haus stehen. Sie fotografiert jede Tür, jedes Fenster, jede Blume."],["Mama","(auf Portugiesisch) Alles ist so sauber! Und so ordentlich! Wie in einem Puppenhaus."],["Dann gehen sie einmal um das Münster herum. Mama legt den Kopf in den Nacken und sieht den Turm hoch."],["Mia","Er ist hundertsechzehn Meter hoch. Man kann hinaufsteigen. Dreihundert Stufen."],["Mama","(auf Portugiesisch) Dreihundert Stufen? Für meine Knie? Nein, danke."],["Gegen elf Uhr kommen sie zum Markt. Und dort passiert, was Mia befürchtet hat: Mama sieht den blau-weißen Wagen. Sabores de Portugal."],["Fátima: (auf Portugiesisch) Sie müssen Mias Mutter sein! Dieselben Augen!"],["Nach drei Minuten reden die beiden wie alte Freundinnen. Nach zehn Minuten kennen sie ihre ganzen Familien. Nach zwanzig Minuten steht Mama hinter dem Wagen und verkauft Pastéis. Mia trinkt allein einen Kaffee. Eine halbe Stunde lang."],["Dann wollen sie das berühmte Bächle sehen. Sie gehen die Bächle entlang, bis zum Schwabentor. Das Wasser ist klar und kalt. Mama sieht sich um. Niemand sieht her. Dann – platsch! Ihr rechter Fuß steht im Wasser."],["Mama","(auf Portugiesisch) Für Rui!"],["Eine junge Frau mit einem Fahrrad bleibt stehen und lacht."],["Junge Frau","Wissen Sie, was das bedeutet? Wer ins Bächle tritt, heiratet einen Freiburger!"],["Mia übersetzt. Mama lacht."],["Mama","(auf Portugiesisch) Sag ihr, das ist nicht für mich. Das ist für meinen Sohn. Frag sie, ob sie Portugiesisch lernt."],["Und tatsächlich","Die junge Frau heißt Lea und studiert Romanistik. Portugiesisch und Spanisch. Mama schreibt ihr sofort Ruis Telefonnummer auf einen Zettel."],["Mia","Mama! Das kannst du nicht machen!"],["Mama","(auf Portugiesisch) Doch. Ich kann."],["Am Nachmittag ist der wichtigste Termin des Tages. Frau Schulz kommt nach Hause. Michael bringt sie mit dem Auto aus der Reha. Vor dem Haus, über den drei alten Stufen, gibt es jetzt eine neue Rampe aus Holz. Tom und Klaus haben sie am Samstag gebaut. Herr Krause hat kontrolliert, ob alles korrekt ist."],["Frau Schulz rollt mit dem Rollator die Rampe hinauf. Langsam, aber allein. Vor ihrer Tür sitzt Felix. Er hat vier Wochen auf diesen Moment gewartet."],["Er läuft nicht zu ihr. Er geht langsam. Dann reibt er seinen Kopf an ihrem Bein. Einmal. Zweimal. Und dann legt er sich auf ihre Füße."],["Frau Schulz sagt nichts. Sie kann nichts sagen."],["Dann sieht sie Mama. Zwei Frauen. Keine gemeinsame Sprache. Mama geht zu Frau Schulz und umarmt sie. Ganz fest. Ohne ein Wort."],["Frau Schulz","Ich glaube, wir verstehen uns."],["Am Abend ruft Ingrid an. Morgen gibt es Mittagessen bei Familie Weber. Mit Mama."],["Jonas","Zwei Familien. Drei Sprachen. Und mein Vater. Was soll da schiefgehen?"]],"q":["Wo gehen Mia und Mama zuerst hin? Was fotografiert Mama?","Warum steigt Mama nicht auf den Münsterturm?","Was macht Mama am Wagen von Fátima?","Richtig oder falsch? Mama tritt ins Bächle, weil sie einen Freiburger heiraten möchte.","Und du? Was würdest du einem Gast in deiner Stadt zeigen? (Wir gehen durch …, um … herum, an … entlang …)"],"a":["Durch die Altstadt. She photographs every door, window and flower.","Because of her knees – 300 steps. „Dreihundert Stufen? Für meine Knie? Nein, danke.“","She sells pastéis with Fátima. „Nach zwanzig Minuten steht Mama hinter dem Wagen und verkauft Pastéis.“","Falsch. It's for her son Rui: „Das ist für meinen Sohn.“","Example: Wir gehen durch die Altstadt, einmal um den See herum und dann am Fluss entlang bis zum Park."],"w":[["um … herum","around","einmal um das Münster herum"],["entlang (+ Akk., after the noun)","along","Sie gehen die Bächle entlang."],["bis (zu)","as far as, until","bis zum Schwabentor"],["sauber","clean","Alles ist so sauber!"],["das Puppenhaus, die Puppenhäuser","doll's house","wie in einem Puppenhaus"],["der Nacken","back of the neck","Mama legt den Kopf in den Nacken."],["der Meter, die Meter","metre","hundertsechzehn Meter hoch"],["hinaufsteigen","to climb up","Man kann hinaufsteigen."],["befürchten","to fear","was Mia befürchtet hat"],["derselbe / dieselbe / dasselbe","the same","Dieselben Augen!"],["tatsächlich","indeed, actually","Und tatsächlich: Sie heißt Lea."],["das Holz","wood","eine neue Rampe aus Holz"],["bauen","to build","Tom und Klaus haben sie gebaut."],["reiben","to rub","Er reibt seinen Kopf an ihrem Bein."],["schiefgehen","to go wrong","Was soll da schiefgehen?"]],"c":[["gegen elf Uhr","at around eleven","Gegen elf Uhr kommen sie zum Markt."],["eine halbe Stunde lang","for half an hour","eine halbe Stunde lang"],["Wir verstehen uns.","We understand each other.","Ich glaube, wir verstehen uns."],["ganz fest","very tightly","Sie umarmt sie ganz fest."]],"x":[["das Treppenhaus, die Treppenhäuser","stairwell",""],["hängen","to hang",""]],"g":["Präpositionen mit Akkusativ (komplett)",["Always accusative: durch, für, gegen, ohne, um (story 39) – and at A2 also bis and entlang.","um … herum = all the way around: um das Münster herum.","entlang usually comes after the noun: die Bächle entlang, den Fluss entlang.","bis is used alone with times and names (bis Montag, bis Basel) or with zu + dative (bis zum Schwabentor).","gegen + time = about: gegen elf Uhr.","Beispiele: Sie gehen durch die Altstadt. · Sie gehen die Bächle entlang, bis zum Schwabentor."]]},{"n":74,"t":"Zwei Familien, drei Sprachen","l":"A2","review":false,"p":[["Montag, zwölf Uhr. Das Haus der Familie Weber in Merzhausen. Im Garten blühen die ersten Tulpen. Klaus steht an der Tür, in einem Hemd mit Krawatte. Ingrid steht neben ihm, mit Schürze."],["Ingrid","Willkommen! Sie müssen Mias Mutter sein!"],["Mama lächelt und sagt etwas auf Portugiesisch. Ingrid lächelt und sagt etwas auf Deutsch. Dann lächeln beide. Und dann ist es still."],["Klaus versucht es auf Englisch."],["Klaus","Welcome! Nice to … meet you. The weather … is good."],["Mama versteht kein Wort. Sie antwortet auf Französisch."],["Mama","Bonjour, Monsieur. Enchantée."],["Klaus' Augen werden groß."],["Klaus","Vous parlez français? Ich hatte neun Jahre Französisch in der Schule!"],["Und plötzlich reden Klaus und Mama. Auf Französisch. Langsam, mit vielen Fehlern, mit Händen und Füßen. Aber sie reden. Und sie lachen."],["Jonas","Das ist unglaublich. Mein Vater lacht. Mit einer Fremden. Auf Französisch."],["Lena","Das ist das Wunder des Jahres."],["Paul sitzt neben Mama und sieht sie lange an."],["Paul","Bist du die Mama von Mia?"],["Mia","Ja, das ist meine Mama."],["Paul","Dann ist sie Mias Mama. Und Mia ist Onkel Jonas' Freundin. Und Onkel Jonas ist der Bruder meiner Mama. Dann ist sie … meine Oma?"],["Alle lachen. Ingrid gibt Paul einen Kuss auf den Kopf."],["Ingrid","Fast, Paul. Fast."],["Es gibt Schweinebraten mit Spätzle und Rotkohl. Mama isst zwei Teller. Dann holt sie ein kleines Paket aus ihrer Tasche. Sie gibt es Jonas."],["Darin ist ein altes Heft mit einem blauen Umschlag. Die Seiten sind gelb und voller Flecken. Darauf steht in einer alten Handschrift: Receitas – Café do Mar."],["Mia","(leise) Das ist das Rezeptbuch meines Opas. Aus seinem Café. Mama hat es seit seinem Tod. Sie hat es niemandem gegeben. Nicht einmal mir."],["Mama spricht. Mia übersetzt."],["Mia","Sie sagt: „Die Rezepte meines Vaters sollen nicht in einem Schrank liegen. Sie sollen in einem Café leben. In deinem Café, Jonas. Das ist der Wunsch meines Vaters. Ich weiß es.“"],["Jonas hält das Heft in beiden Händen. Wie etwas sehr Wertvolles. Er kann nicht sprechen."],["Klaus steht auf. Er holt seinen Ordner mit dem Businessplan. Er schlägt die letzte Seite auf und schreibt mit dem Kugelschreiber dazu: Spezialitäten: Rezepte von Opa Costa."],["Nach dem Essen sitzen die Frauen im Garten: Ingrid, Lena, Mama und Mia. Ingrid und Mama sprechen jetzt mit Mias Hilfe."],["Ingrid","Sag deiner Mutter, dass ich sehr froh bin. Über dich. Über die beiden."],["Mia übersetzt. Mama antwortet. Mia übersetzt nicht sofort."],["Ingrid","Was hat sie gesagt?"],["Mia","Sie hat gefragt … was aus uns wird. Ob wir heiraten. Ob ich in Deutschland bleibe. Ob ich jemals zurück nach Portugal komme."],["Ingrid sagt nichts. Lena sagt nichts. Alle sehen Mia an."],["Und Mia weiß keine Antwort."]],"q":["In welcher Sprache sprechen Klaus und Mama? Warum?","Was fragt Paul?","Was ist in Mamas Paket?","Richtig oder falsch? Mama hat Mia das Rezeptbuch schon früher gegeben.","Und du? Beschreibe deine Familie mit Genitiv oder von. (Der Bruder meiner Mutter heißt … / Das Auto von meinem Vater ist …)"],"a":["Auf Französisch. Klaus had French at school for nine years, and Mama speaks French.","Whether Mia's mother is his grandmother. „Dann ist sie … meine Oma?“","The recipe book from her father's café. „Das ist das Rezeptbuch meines Opas.“","Falsch. „Sie hat es niemandem gegeben. Nicht einmal mir.“","Example: Der Bruder meiner Mutter heißt Paulo. Das Auto von meinem Vater ist alt."],"w":[["des / der (Genitiv)","of the","das Haus der Familie Weber"],["meines / meiner (Genitiv)","of my","das Rezeptbuch meines Opas"],["blühen","to bloom","Im Garten blühen die ersten Tulpen."],["die Krawatte, die Krawatten","tie","in einem Hemd mit Krawatte"],["unglaublich","unbelievable","Das ist unglaublich."],["der/die Fremde","stranger","mit einer Fremden"],["das Wunder, die Wunder","miracle","das Wunder des Jahres"],["der Kuss, die Küsse","kiss","einen Kuss auf den Kopf"],["der Schweinebraten","roast pork","Es gibt Schweinebraten mit Spätzle."],["der Fleck, die Flecken","stain","voller Flecken"],["der Tod","death","seit seinem Tod"],["wertvoll","valuable","wie etwas sehr Wertvolles"],["der Ordner, die Ordner","folder, binder","seinen Ordner mit dem Businessplan"],["aufschlagen","to open (a book)","Er schlägt die letzte Seite auf."],["jemals","ever","Ob ich jemals zurückkomme."]],"c":[["mit Händen und Füßen","using gestures","mit Händen und Füßen"],["nicht einmal","not even","Nicht einmal mir."],["voller …","full of …","voller Flecken"],["Was wird aus uns?","What will become of us?","was aus uns wird"]],"x":[["den Müll trennen","to sort the rubbish",""],["Die Heizung ist kaputt.","the heating is broken.",""]],"g":["Genitiv und von + Dativ",["To show possession with names, add -s (no apostrophe): Mias Mama, Lenas Mann. Names ending in -s/-z get an apostrophe: Jonas' Freundin, Klaus' Augen.","Genitive articles: des + noun + -(e)s (masc./neut.) · der (fem./plural): das Wunder des Jahres, das Haus der Familie.","Possessives: meines Vaters, meiner Mutter.","In everyday speech, Germans often use von + dative instead: die Mama von Mia, das Rezeptbuch von meinem Opa.","Beispiele: Das ist der Wunsch meines Vaters. · Bist du die Mama von Mia?"]]},{"n":75,"t":"Was wird aus uns?","l":"A2","review":false,"p":[["In der Nacht nach dem Essen bei Webers kann Mia nicht schlafen. Die Frage ihrer Mutter geht ihr nicht aus dem Kopf. Was wird aus uns?"],["Sie steht auf und geht auf den Balkon. Es ist kühl, aber nicht mehr kalt. Der Frühling kommt. Nach ein paar Minuten kommt Jonas, mit zwei Tassen Tee."],["Jonas","Du denkst an die Frage deiner Mutter."],["Mia","Ja. Ich weiß nicht, was ich antworten soll. Wenn ich hier bleibe, werde ich Porto vermissen. Mama. Das Meer. Wenn ich nach Porto gehe …"],["Jonas","Dann werde ich dich vermissen. Sehr."],["Sie trinken Tee. Unten im Hof steht das blaue Fahrrad. Oben am Himmel werden die Sterne langsam blass."],["Am nächsten Tag, im Büro, ruft Sabine Mia in den Besprechungsraum. Max ist auch da. Und er lächelt. Schon wieder."],["Sabine","Mia, das Museumsprojekt wird ein großer Erfolg. Das Stadtmuseum ist begeistert. Und jetzt wollen zwei andere Museen mit uns arbeiten. In Basel und in Straßburg."],["Max","Wir werden eine neue Abteilung gründen. Nur für Museen und Kultur. Ab Oktober."],["Sabine","Und wir möchten, dass du Teamleiterin wirst. Wenn du willst."],["Mia sieht von Sabine zu Max. Teamleiterin. Nach sieben Monaten in Deutschland."],["Mia","Aber mein Deutsch …"],["Max","Dein Deutsch wird jeden Tag besser. Und deine Ideen sind schon jetzt die besten."],["Mia","Kann ich … kann ich darüber nachdenken? Ein paar Tage?"],["Sabine","Natürlich."],["Der letzte Tag von Mamas Besuch. Am Bahnhof wartet der Bus zum Flughafen. Mamas roter Koffer ist jetzt leicht. Die Sardinen sind gegessen. Dafür hat sie Schwarzwälder Schinken, Kirschwasser und ein Glas Honig von Frau Schulz dabei."],["Mama","(auf Portugiesisch) Und? Wirst du zurückkommen? Nach Porto?"],["Mia nimmt Mamas Hände."],["Mia","Mama. Ich werde Porto immer lieben. Ich werde jeden Sommer kommen. Aber ich glaube … mein Leben wird hier sein. Hier habe ich ein Zuhause gefunden. Und einen Job, der mich glücklich macht. Sie wollen, dass ich Teamleiterin werde."],["Mama sieht ihre Tochter lange an. Dann lächelt sie, mit Tränen in den Augen."],["Mama","(auf Portugiesisch) Das habe ich gewusst. Schon am Bahnhof. Als ich dich mit ihm gesehen habe."],["Dann dreht sie sich zu Jonas um. Jonas hat geübt. Lange."],["Jonas","(auf Portugiesisch) Senhora Costa, ich werde gut auf sie aufpassen. Versprochen."],["Mama umarmt ihn. Dann steigt sie in den Bus. Sie winkt, bis der Bus um die Ecke fährt."],["Auf dem Rückweg macht Mias Handy pling. Eine Nachricht von Rui."],["Mia!!! Ich habe die Deutschprüfung bestanden! Und rate mal, wer mir geschrieben hat? Eine gewisse LEA aus Freiburg. Sie sagt, Mama hat ihr meine Nummer gegeben. 😳 Ich werde im Juni kommen. Eine Woche. Bereite dich vor!"],["Mia lacht laut. Jonas fragt nicht. Er weiß schon, dass es um Mamas Bächle geht."],["Am Abend ruft Ingrid an."],["Ingrid","Mia, Jonas – Jonas' Großmutter Gerda wird im Mai neunzig. Sie macht ein großes Fest. In Hamburg. Und sie hat gesagt, dass sie die Frau vom Bächle unbedingt kennenlernen will. Persönlich. Werdet ihr kommen?"],["Jonas sieht Mia an. Mia nickt."],["Jonas","Wir werden kommen."],["Später, im Bett, flüstert Jonas noch etwas. Ganz leise."],["Jonas","Mia … in Hamburg werde ich dich etwas fragen."],["Mia","Was?"],["Jonas","Das wirst du sehen."]],"q":["Was will Sabine Mia anbieten?","Was antwortet Mia ihrer Mutter am Bahnhof?","Was verspricht Jonas Mama?","Richtig oder falsch? Rui hat die Deutschprüfung nicht bestanden.","Und du? Was wirst du nächstes Jahr machen? Was möchtest du werden?"],"a":["To become team leader of a new department for museums and culture. „Wir möchten, dass du Teamleiterin wirst.“","She will always love Porto and visit every summer, but her life will be in Freiburg. „Aber ich glaube … mein Leben wird hier sein.“","That he will take good care of her. „Ich werde gut auf sie aufpassen. Versprochen.“","Falsch. „Ich habe die Deutschprüfung bestanden!“","Example: Nächstes Jahr werde ich nach Deutschland reisen. Ich möchte Lehrerin werden."],"w":[["werden (wird, wirst)","to become; will (future)","Dein Deutsch wird jeden Tag besser."],["kühl","cool","Es ist kühl, aber nicht mehr kalt."],["der Stern, die Sterne","star","Oben werden die Sterne blass."],["begeistert","enthusiastic","Das Stadtmuseum ist begeistert."],["die Abteilung, die Abteilungen","department","eine neue Abteilung"],["gründen","to found, set up","Wir werden eine Abteilung gründen."],["die Kultur","culture","Nur für Museen und Kultur."],["die Teamleiterin, die Teamleiterinnen","team leader (f)","dass du Teamleiterin wirst"],["der Besuch, die Besuche","visit","Der letzte Tag von Mamas Besuch."],["der Schinken","ham","Schwarzwälder Schinken"],["aufpassen auf","to look after","Ich werde gut auf sie aufpassen."],["winken","to wave","Sie winkt, bis der Bus um die Ecke fährt."],["sich vorbereiten","to prepare oneself","Bereite dich vor!"],["die Großmutter, die Großmütter","grandmother","Jonas' Großmutter Gerda"],["persönlich","in person","Persönlich."]],"c":[["… geht mir nicht aus dem Kopf","I can't stop thinking about …","Die Frage geht ihr nicht aus dem Kopf."],["Rate mal!","Guess what!","Und rate mal, wer mir geschrieben hat?"],["eine gewisse …","a certain …","Eine gewisse Lea aus Freiburg."],["Das wirst du sehen.","You'll see.","Das wirst du sehen."]],"x":[["die Rückfahrkarte, die Rückfahrkarten","return ticket",""]],"g":["das Verb werden",["werden: ich werde, du wirst, er wird, wir werden, ihr werdet, sie werden. Perfekt: ist geworden.","werden + adjective/noun = to become, get: Dein Deutsch wird besser. · Ich werde Teamleiterin. · Gerda wird neunzig.","werden + infinitive = future (plans, promises, predictions): Ich werde gut auf sie aufpassen.","For plans with a time word, Germans often use the present instead: Ich komme im Juni. (more in story 99)","Beispiele: Wir werden eine neue Abteilung gründen. · In Hamburg werde ich dich etwas fragen."]]},{"n":76,"t":"Eine Reise nach Hamburg","l":"A2","review":false,"p":[["Anfang Mai. Seit einer Woche ist es warm in Freiburg. Die Leute sitzen in den Cafés draußen, und auf dem Schlossberg blühen die Kirschbäume."],["Oma Gerda feiert ihren neunzigsten Geburtstag am Samstag, dem siebzehnten Mai. In zwei Wochen. Mia und Jonas sitzen am Küchentisch und planen die Reise."],["Jonas","Also: Wir fahren am Freitag, nach der Arbeit. Oder vor der Arbeit?"],["Mia","Vor der Arbeit geht nicht. Ich muss bis zwölf Uhr arbeiten. Ab Mittag habe ich frei. Wenn Sabine Ja sagt."],["Jonas","Hast du sie noch nicht gefragt?"],["Mia","Regel Nummer zwei: Urlaub muss man vier Wochen vorher beantragen. Und heute sind es nur noch zwei Wochen."],["Am nächsten Morgen fragt Mia Sabine. Sie ist nervös."],["Sabine","Für den Geburtstag einer Neunzigjährigen? In Hamburg? Natürlich! Aber am Montag bist du wieder hier. Um neun. Das Museum in Basel kommt um zehn."],["Am Abend bucht Jonas die Tickets im Internet. Mia liest laut vor:"],["Freiburg Hauptbahnhof ab 13:04 Uhr – Hamburg Hauptbahnhof an 19:27 Uhr. Umsteigen in Mannheim, zwischen 14:30 und 14:41 Uhr. Rückfahrt: Sonntag, ab 15:12 Uhr."],["Mia","Elf Minuten zum Umsteigen in Mannheim? Ist das nicht ein bisschen knapp?"],["Jonas","Die Bahn ist immer pünktlich."],["Mia sieht ihn an. Jonas lacht."],["Jonas","Okay, okay. Fast immer."],["In den nächsten zwei Wochen ist Jonas komisch. Er ist nervös und vergesslich. Er telefoniert oft mit Lena – aber nur auf dem Balkon, mit geschlossener Tür. Einmal kommt Mia früher nach Hause, und Jonas versteckt schnell etwas in einer Schublade. Etwas Kleines."],["Mia","Was war das?"],["Jonas","Nichts! Ein Rezept. Für Oma."],["Mia fragt nicht weiter. Aber sie lächelt."],["Am Mittwoch vor der Reise bringt Mia Felix zu Frau Schulz. Seit Frau Schulz wieder zu Hause ist, wohnt er wieder unten. Aber er schläft oft bei Mia und Jonas auf dem Sofa."],["Frau Schulz","Fahren Sie nur. Felix und ich kommen zurecht. Und grüßen Sie Hamburg von mir. Ich war seit dreißig Jahren nicht mehr dort. Seit dem Tod meiner Schwester."],["Am Donnerstagabend packen sie die Koffer. Jonas packt dreimal um. Er kontrolliert ständig seine Jackentaschen. Dann geht er ins Bad. Mia hört, wie er etwas in ihre große Handtasche legt. Leise. Ganz leise. Mia sagt nichts."],["Um zehn Uhr läuft im Fernsehen die Tagesschau. Mia hört nur halb zu. Dann sagt der Sprecher:"],["„… und noch eine Meldung: Die Gewerkschaft der Lokführer hat einen Streik angekündigt. Ab Freitag, zwölf Uhr, bis Sonntagabend fahren in ganz Deutschland kaum Fernzüge.“"],["Jonas steht in der Badezimmertür. Er ist ganz blass."],["Jonas","Ab Freitag, zwölf Uhr? Unser Zug fährt um dreizehn Uhr vier!"]],"q":["Wann feiert Oma Gerda ihren Geburtstag?","Warum ist Mia nervös, als sie Sabine fragt?","Wie lange haben sie zum Umsteigen in Mannheim?","Richtig oder falsch? Jonas legt etwas Kleines in Mias Handtasche.","Und du? Wann bist du zuletzt verreist? Was machst du vor einer Reise und nach einer Reise?"],"a":["Am Samstag, dem 17. Mai. „Oma Gerda feiert ihren neunzigsten Geburtstag am Samstag, dem siebzehnten Mai.“","Rule no. 2: holidays must be requested four weeks before, and there are only two weeks left. „Und heute sind es nur noch zwei Wochen.“","Elf Minuten. „… zwischen 14:30 und 14:41 Uhr.“","Richtig. „Mia hört, wie er etwas in ihre große Handtasche legt.“","Example: Vor drei Monaten bin ich nach Spanien gefahren. Vor der Reise packe ich, nach der Reise wasche ich alles."],"w":[["zwischen (Zeit)","between","zwischen 14:30 und 14:41 Uhr"],["in (+ Dativ, Zeit)","in (future)","In zwei Wochen."],["der Kirschbaum, die Kirschbäume","cherry tree","Die Kirschbäume blühen."],["beantragen","to apply for","Urlaub muss man vorher beantragen."],["buchen","to book","Jonas bucht die Tickets."],["umsteigen","to change (trains)","Umsteigen in Mannheim"],["die Rückfahrt, die Rückfahrten","return journey","Rückfahrt: Sonntag"],["knapp","tight, barely enough","Ist das nicht ein bisschen knapp?"],["vergesslich","forgetful","Er ist nervös und vergesslich."],["die Schublade, die Schubladen","drawer","in einer Schublade"],["zurechtkommen","to cope, manage","Felix und ich kommen zurecht."],["ständig","constantly","Er kontrolliert ständig seine Taschen."],["die Meldung, die Meldungen","news item","noch eine Meldung"],["der Streik, die Streiks","strike","einen Streik angekündigt"],["ankündigen","to announce","Die Gewerkschaft hat angekündigt …"]],"c":[["Anfang / Ende Mai","at the beginning / end of May","Anfang Mai."],["am Samstag, dem 17. Mai","on Saturday, 17 May","am Samstag, dem siebzehnten Mai"],["ab … an … (Fahrplan)","departs … arrives …","ab 13:04 Uhr – an 19:27 Uhr"],["nicht weiter fragen","to ask no further","Mia fragt nicht weiter."]],"x":[["die Grenze, die Grenzen","border",""],["einsteigen","to get on",""]],"g":["temporale Präpositionen (A2)",["vor / nach + dative: vor der Arbeit, nach der Arbeit. vor + time span = ago: vor drei Monaten.","seit + dative = since/for (still true): Seit einer Woche ist es warm.","in + dative = in (future): In zwei Wochen. · ab = from … on: Ab Mittag habe ich frei.","bis = until: bis zwölf Uhr, bis Sonntagabend · zwischen + dative = between: zwischen 14:30 und 14:41 Uhr.","Beispiele: In zwei Wochen feiert Oma Gerda. · Ab Freitag, zwölf Uhr, bis Sonntagabend fahren kaum Züge."]]},{"n":77,"t":"Der Zug fällt aus","l":"A2","review":false,"p":[["Freitag, sieben Uhr. Jonas sitzt schon am Laptop. Auf der Seite der Bahn steht in roten Buchstaben: IC 2318 – Zug fällt aus. Auch der nächste Zug fällt aus. Und der übernächste."],["Jonas","Alle Züge fallen aus. Deshalb können wir nicht mit dem Zug fahren."],["Mia","Und ein Flug?"],["Jonas","Alle Flüge nach Hamburg sind ausgebucht. Wegen des Streiks wollen alle fliegen. Deshalb kostet der letzte Platz vierhundert Euro."],["Mia","Und ein Mietauto?"],["Jonas","Ich habe seit zehn Jahren kein Auto mehr gefahren. Und auf der Autobahn bin ich zu nervös."],["Sie sitzen still am Tisch. Dann hat Mia eine Idee."],["Mia","Tom! Er fährt seit April Fernbus. Sein Vorsatz! Erinnerst du dich?"],["Mia ruft Tom an. Er ist schon bei der Arbeit."],["Tom","Hamburg? Heute? Ich fahre heute nach Hamburg! Abfahrt vierzehn Uhr am Busbahnhof. Aber der Bus ist voll. Komplett voll. Wegen des Streiks."],["Mia","Oh nein."],["Tom","Trotzdem kommt ihr mit. Es gibt hinten zwei Notsitze für die Fahrer. Mein Kollege fährt nicht mit, er ist krank. Deshalb sind die Plätze frei. Aber es ist nicht bequem!"],["Mia","Das ist uns egal! Danke, Tom!"],["Um vierzehn Uhr fährt der grüne Fernbus los. Mia und Jonas sitzen ganz hinten, auf zwei kleinen Klappsitzen. Mias Knie sind fast an ihrem Kinn. Trotzdem lacht sie."],["Tom sagt durch das Mikrofon:"],["Tom","Liebe Fahrgäste, willkommen an Bord. Wir fahren heute nach Hamburg. Die Fahrt dauert ungefähr neun Stunden. Wegen des Streiks gibt es viel Verkehr. Deshalb kann es länger dauern. Trotzdem wünsche ich Ihnen eine gute Reise. Und bitte: keine Würste im Bus. Das bin nur ich."],["Die Fahrgäste lachen."],["Die Fahrt wird lang. Sehr lang. Bei Kassel gibt es einen Stau. Zwei Stunden lang bewegt sich nichts. Es ist heiß im Bus. Die Klimaanlage funktioniert nur halb. Ein Baby weint. Ein Mann schnarcht."],["Trotzdem ist es irgendwie schön. Jonas erzählt Mia Geschichten von Oma Gerda: wie sie mit achtzig noch Motorrad gefahren ist, wie sie jeden Morgen in der Elbe schwimmt – auch im Winter. Mia teilt ihre Kopfhörer mit ihm. Sie hören portugiesische Musik und sehen die grünen Felder von Hessen."],["Um Viertel nach eins in der Nacht kommt der Bus am Zentralen Omnibusbahnhof in Hamburg an. Elf Stunden Fahrt. Mias Beine fühlen sich an wie Holz."],["Tom","Endstation! Hamburg! Ihr seid die Helden des Tages."],["Sie nehmen ein Taxi zum Hotel in Altona. Mia ist so müde, dass sie fast im Taxi einschläft. Im Hotelzimmer fällt sie sofort ins Bett. Jonas trägt die Koffer. Und die Taschen. Alle Taschen? Er ist zu müde, um nachzuzählen."],["Am nächsten Morgen um acht Uhr wacht Mia auf. Die Sonne scheint. Sie hört Möwen. Hamburg!"],["Sie sucht ihre Handtasche. Neben dem Bett? Nein. Auf dem Stuhl? Nein. Im Koffer? Nein."],["Mia","Jonas … Wo ist meine Handtasche?"],["Jonas setzt sich im Bett auf. Sein Gesicht wird weiß. Nicht nur ein bisschen blass. Ganz weiß."],["Jonas","Deine … Handtasche? Die große? Die braune?"],["Mia","Ja. Warum siehst du so aus?"]],"q":["Warum können Mia und Jonas nicht fliegen?","Warum sind zwei Plätze im Fernbus frei?","Wie lange dauert die Fahrt? Warum?","Richtig oder falsch? Mia ist während der Fahrt die ganze Zeit schlecht gelaunt.","Und du? Was hast du schon einmal trotz eines Problems gemacht? (Es hat geregnet. Trotzdem …)"],"a":["All flights are fully booked, the last seat costs 400 euros. „Deshalb kostet der letzte Platz vierhundert Euro.“","Tom's colleague is ill. „Mein Kollege fährt nicht mit, er ist krank. Deshalb sind die Plätze frei.“","Elf Stunden, because of traffic and a two-hour jam near Kassel. „Bei Kassel gibt es einen Stau.“","Falsch. „Trotzdem lacht sie.“ – „Trotzdem ist es irgendwie schön.“","Example: Es hat geregnet. Trotzdem bin ich joggen gegangen."],"w":[["deshalb","that's why, therefore","Deshalb können wir nicht mit dem Zug fahren."],["trotzdem","nevertheless, anyway","Trotzdem lacht sie."],["ausfallen (fällt aus)","to be cancelled","Zug fällt aus."],["ausgebucht","fully booked","Alle Flüge sind ausgebucht."],["wegen (+ Gen./Dat.)","because of","wegen des Streiks"],["die Autobahn, die Autobahnen","motorway","auf der Autobahn"],["der Fernbus, die Fernbusse","long-distance coach","Er fährt seit April Fernbus."],["der Busbahnhof, die Busbahnhöfe","bus station","Abfahrt am Busbahnhof"],["der Fahrgast, die Fahrgäste","passenger","Liebe Fahrgäste"],["der Verkehr","traffic","Es gibt viel Verkehr."],["der Stau, die Staus","traffic jam","Bei Kassel gibt es einen Stau."],["die Klimaanlage, die Klimaanlagen","air conditioning","Die Klimaanlage funktioniert nur halb."],["schnarchen","to snore","Ein Mann schnarcht."],["teilen","to share","Mia teilt ihre Kopfhörer mit ihm."],["die Möwe, die Möwen","seagull","Sie hört Möwen."]],"c":[["Erinnerst du dich?","Do you remember?","Sein Vorsatz! Erinnerst du dich?"],["Das ist uns egal!","We don't care!","Das ist uns egal!"],["willkommen an Bord","welcome on board","willkommen an Bord"],["sich anfühlen wie …","to feel like …","Mias Beine fühlen sich an wie Holz."]],"x":[["aussteigen","to get off",""],["der Anschluss, die Anschlüsse","connection",""]],"g":["deshalb und trotzdem",["deshalb (therefore) gives a consequence. trotzdem (nevertheless) shows that something happens despite a problem.","Both are adverbs. In position 1, the verb comes next (inversion): Mein Kollege ist krank. Deshalb sind die Plätze frei.","They can also stand after the verb: Die Plätze sind deshalb frei.","Compare: weil = cause (verb at the end) · deshalb = result (verb in position 2).","Beispiele: Es gibt viel Verkehr. Deshalb kann es länger dauern. · Der Bus ist voll. Trotzdem kommt ihr mit."]]},{"n":78,"t":"Was ist passiert?","l":"A2","review":false,"p":[["Jonas","Mia … in deiner Tasche ist etwas. Etwas sehr Wichtiges. Ich habe es am Donnerstag hineingelegt."],["Mia","Was?"],["Jonas","Das kann ich nicht sagen. Noch nicht. Wir müssen die Tasche finden. Sofort."],["Mia denkt nach. In der Tasche ist ihr Portemonnaie mit fünfzig Euro und allen Karten. Ihr Pass. Und das Geschenk für Oma Gerda: eine alte blaue Fliese aus Porto, in Papier eingewickelt. Und … etwas von Jonas. Etwas Wichtiges."],["Mia","Okay. Ruhig. Was ist passiert? Wir rekonstruieren alles. Wo hatte ich die Tasche zuletzt?"],["Sie setzen sich aufs Bett und überlegen."],["Jonas","Im Bus hattest du sie auf dem Schoß. Das weiß ich. Ich habe sie gesehen."],["Mia","In Kassel, im Stau, sind wir an einer Raststätte ausgestiegen. Ich habe zwei Kaffee gekauft. Dann bin ich zum Bus zurückgerannt, weil Tom gehupt hat."],["Jonas","Hast du die Tasche mitgebracht?"],["Mia","Ich … ich weiß es nicht. Ich habe zwei Kaffeebecher getragen. In beiden Händen."],["Jonas ruft Tom an. Tom schläft noch. Er ist erst um drei Uhr ins Bett gegangen."],["Tom","Mmh? … Eine Tasche? Moment. Ich habe den Bus heute Nacht kontrolliert. Wie immer. Da war nichts. Nur eine Socke und eine Banane."],["Dann telefoniert Mia mit der Taxifirma. Die Frau am Telefon ist freundlich."],["Frau","Ich habe den Fahrer schon informiert. Er hat das Taxi kontrolliert. Leider keine Tasche."],["Mia geht zur Rezeption vom Hotel. Der Mann an der Rezeption hat gestern Nacht gearbeitet."],["Rezeption","Ich kenne Sie! Sie sind um zwei Uhr angekommen. Sie haben zwei Koffer gehabt und einen Rucksack. Ich habe keine Handtasche gesehen. Tut mir leid."],["Also Kassel. Die Raststätte. Dreihundert Kilometer entfernt."],["Mia ruft die Raststätte an. Es klingelt lange. Dann sagt eine müde Stimme:"],["Stimme","Raststätte Kassel-Ost, Fundsachen? Eine braune Handtasche? Gestern Nachmittag? … Ja, wir haben eine braune Tasche gefunden. Auf einem Tisch, neben den Toiletten. Ein Busfahrer hat sie mitgenommen. Er hat gesagt, er kennt die Besitzerin. Er hat sie nach Hamburg gebracht. Zum Fundbüro am Busbahnhof."],["Mia","Ein Busfahrer? Welcher Busfahrer?"],["Stimme","Keine Ahnung. Ein großer Mann. Mit Schnurrbart. Er hat eine Wurst gegessen."],["Mia und Jonas sehen sich an. Nicht Tom. Tom hat keinen Schnurrbart."],["Jonas","Das Fundbüro am Busbahnhof. Wann hat es offen?"],["Mia sucht im Internet","Samstag 10 bis 13 Uhr."],["Es ist neun Uhr zwanzig. Das Fest von Oma Gerda beginnt um fünfzehn Uhr. Das Fundbüro ist in St. Georg, auf der anderen Seite der Stadt."],["Jonas","Mia. Bitte. Was immer passiert: Wir müssen diese Tasche finden. Ich habe zwei Monate für das hier gespart."],["Mia","Für was?"],["Jonas","Das sage ich dir, wenn wir die Tasche haben."],["Sie ziehen sich schnell an. Mia hat ein Kribbeln im Bauch. Sie hat eine Idee, was in der Tasche ist. Aber sie traut sich nicht, daran zu denken."]],"q":["Was ist in Mias Tasche? (Nenne drei Dinge.)","Wo hatte Mia die Tasche zuletzt?","Wer hat bei der Suche geholfen? (Nenne zwei Personen.)","Richtig oder falsch? Tom hat die Tasche nach Hamburg gebracht.","Und du? Hast du schon einmal etwas verloren? Was ist passiert? Wie hast du es gefunden?"],"a":["Portemonnaie, Pass, das Geschenk für Oma Gerda (eine blaue Fliese) und etwas von Jonas.","An der Raststätte bei Kassel. „In Kassel, im Stau, sind wir an einer Raststätte ausgestiegen.“","Tom, die Frau von der Taxifirma, der Mann an der Rezeption, die Stimme an der Raststätte.","Falsch. It was a bus driver with a moustache: „Tom hat keinen Schnurrbart.“","Example: Ich habe einmal mein Handy im Zug vergessen. Ich habe die Bahn angerufen, und sie haben es gefunden."],"w":[["rekonstruieren (rekonstruiert)","to reconstruct","Wir rekonstruieren alles."],["informieren (informiert)","to inform","Ich habe den Fahrer informiert."],["kontrollieren (kontrolliert)","to check","Er hat das Taxi kontrolliert."],["bringen (gebracht) / denken (gedacht) / wissen (gewusst) / kennen (gekannt) / rennen (ist gerannt)","mixed verbs","Er hat sie nach Hamburg gebracht."],["das Portemonnaie, die Portemonnaies","wallet, purse","ihr Portemonnaie mit fünfzig Euro"],["die Fliese, die Fliesen","tile","eine alte blaue Fliese aus Porto"],["einwickeln","to wrap","in Papier eingewickelt"],["der Schoß","lap","Du hattest sie auf dem Schoß."],["die Raststätte, die Raststätten","motorway services","an einer Raststätte"],["hupen","to honk","weil Tom gehupt hat"],["die Rezeption","reception desk","an der Rezeption"],["die Fundsache, die Fundsachen","lost property","Fundsachen?"],["die Besitzerin, die Besitzerinnen","owner (f)","Er kennt die Besitzerin."],["der Schnurrbart, die Schnurrbärte","moustache","Mit Schnurrbart."],["entfernt","away, distant","Dreihundert Kilometer entfernt."]],"c":[["Keine Ahnung.","No idea.","Keine Ahnung."],["Was immer passiert …","Whatever happens …","Was immer passiert: …"],["ein Kribbeln im Bauch","butterflies in the stomach","Mia hat ein Kribbeln im Bauch."],["sich trauen","to dare","Sie traut sich nicht, daran zu denken."]],"x":[["das Gepäck","luggage",""],["die Unterkunft, die Unterkünfte","accommodation",""]],"g":["Perfekt von -ieren-Verben und Mischverben",["Verbs ending in -ieren have no ge-, and the participle ends in -t: passieren → passiert, telefonieren → telefoniert, kontrollieren → kontrolliert.","Mixed verbs change their stem like irregular verbs but end in -t like regular ones:","bringen → gebracht · denken → gedacht · wissen → gewusst · kennen → gekannt · rennen → ist gerannt · nennen → genannt.","passieren uses sein: Was ist passiert?","Beispiele: Er hat sie nach Hamburg gebracht. · Ich habe den Bus kontrolliert."]]},{"n":79,"t":"Im Fundbüro","l":"A2","review":false,"p":[["Zehn Uhr. Vor dem Fundbüro am Busbahnhof stehen schon zwölf Leute. Alle haben etwas verloren. Eine Frau sucht ihren Regenschirm. Ein Junge sucht sein Handy. Niemand sieht glücklich aus."],["Um elf Uhr zehn sind Mia und Jonas dran. Hinter dem Schalter sitzt ein älterer Mann mit Lesebrille."],["Mann","Was haben Sie verloren?"],["Mia","Eine braune Handtasche. Gestern, an der Raststätte Kassel. Jemand hat sie hierher gebracht. Ein Busfahrer."],["Mann","Eine braune Handtasche. Hm. Wir haben viele braune Taschen."],["Er geht nach hinten und kommt mit drei Taschen zurück."],["Mann","Ist eine davon Ihre?"],["Mia sieht sie an. Die erste ist zu klein. Die zweite ist aus Plastik. Die dritte ist alt und kaputt."],["Mia","Nein. Keine ist meine."],["Mann","Dann tut es mir leid. Mehr haben wir nicht. Von gestern ist nichts gekommen."],["Jonas setzt sich auf einen Stuhl. Er legt den Kopf in die Hände. Mia hat ihn noch nie so traurig gesehen."],["In diesem Moment geht die Tür auf. Ein großer Mann in einer grünen Uniform kommt herein. Er hat einen dicken Schnurrbart. Und in der Hand eine braune Handtasche."],["Busfahrer","Moin! Hat hier jemand eine braune Tasche verloren? Ich hab sie gestern in Kassel gefunden. Die Kollegin von der Raststätte hat gesagt, die gehört einem Paar aus Toms Bus. Ich kenne Tom. Jeder kennt Tom. Ich wollte sie gestern Nacht noch hier abgeben, aber da war keiner mehr da. Also hab ich sie mit nach Hause genommen."],["Mia","Das ist meine! Das ist sie!"],["Busfahrer","Sind Sie sicher? Dann sagen Sie mir, was drin ist. Das muss man fragen."],["Mia","Ein Portemonnaie mit fünfzig Euro. Ein Pass aus Portugal. Eine blaue Fliese in Papier. Und …"],["Sie sieht Jonas an."],["Jonas","Und eine kleine rote Schachtel."],["Der Busfahrer öffnet die Tasche. Er nimmt die kleine rote Schachtel heraus. Er sieht sie an. Dann sieht er Jonas an. Dann lacht er laut und gibt Jonas die Schachtel."],["Busfahrer","Viel Glück, junger Mann!"],["Um fünfzehn Uhr beginnt das Fest. In einem Restaurant direkt an der Elbe, in Blankenese. Die Sonne scheint, große Schiffe fahren vorbei. Fünfzig Gäste sind da. Oma Gerda sitzt in der Mitte, in einem blauen Kleid, mit einer Krone aus Papier."],["Oma Gerda","Die Frau vom Bächle! Endlich! Komm her, Kind!"],["Mia gibt ihr die Fliese aus Porto. Oma Gerda hält sie in den Händen."],["Oma Gerda","So ein Blau. Wie die Elbe im Juni. Die bekommt einen Platz über meinem Bett."],["Nach dem Kuchen klopft Oma Gerda an ihr Glas."],["Oma Gerda","Ich bin heute neunzig. Ich habe alles erlebt. Fast alles. Hat noch jemand etwas zu sagen? Dann bitte jetzt. Ich habe nicht mehr so viel Zeit."],["Alle lachen. Dann steht Jonas auf. Er geht zu Mia. Und vor fünfzig Gästen, an der Elbe, kniet er sich hin."],["Jonas","Mia. Du bist mit einem Koffer gekommen und ohne Bett. Du hast meinen Kater- Nachbarn gerettet, mein Lied ertragen und an meinen Traum geglaubt. Ich möchte nie wieder ohne dich sein. Willst du mich heiraten?"],["Er öffnet die kleine rote Schachtel. Darin liegt ein schmaler Ring aus Silber mit einem kleinen blauen Stein."],["Niemand sagt etwas. Alle warten. Mia kann nicht sprechen. Dann nickt sie. Und dann sagt sie es, laut, auf Deutsch und auf Portugiesisch:"],["Mia","Ja! Sim! Ja!"],["Alle klatschen. Keiner hat trockene Augen. Am wenigsten Oma Gerda."],["Oma Gerda","Seht ihr? Mit neunzig erlebt man doch noch etwas Neues!"]],"q":["Warum war der Busfahrer gestern Nacht nicht im Fundbüro?","Warum fragt der Busfahrer, was in der Tasche ist?","Was macht Oma Gerda mit der Fliese?","Richtig oder falsch? Mia sagt Nein.","Und du? Hast du schon einmal jemandem geholfen, den du nicht kanntest? Erzähl."],"a":["Nobody was there any more. „Da war keiner mehr da. Also hab ich sie mit nach Hause genommen.“","To be sure the bag really belongs to her. „Dann sagen Sie mir, was drin ist. Das muss man fragen.“","She will hang it above her bed. „Die bekommt einen Platz über meinem Bett.“","Falsch. „Ja! Sim! Ja!“","Example: Ja, ich habe einmal einer alten Frau mit ihrem Koffer geholfen. Sie war sehr dankbar."],"w":[["jemand / niemand","someone / no one","Hat hier jemand eine Tasche verloren?"],["einer / keiner","one / nobody, none","Da war keiner mehr da."],["jeder","everyone","Jeder kennt Tom."],["alle / alles","everyone / everything","Alle haben etwas verloren."],["etwas / nichts","something / nothing","Von gestern ist nichts gekommen."],["der Schalter, die Schalter","counter (office)","Hinter dem Schalter sitzt ein Mann."],["die Uniform, die Uniformen","uniform","in einer grünen Uniform"],["abgeben","to hand in","Ich wollte sie hier abgeben."],["das Schiff, die Schiffe","ship","Große Schiffe fahren vorbei."],["die Krone, die Kronen","crown","mit einer Krone aus Papier"],["sich hinknien","to kneel down","Er kniet sich hin."],["ertragen","to endure","Du hast mein Lied ertragen."],["schmal","narrow, slim","ein schmaler Ring"],["der Ring, die Ringe","ring","ein Ring aus Silber"],["trocken","dry","Keiner hat trockene Augen."]],"c":[["Ist eine davon Ihre?","Is one of them yours?","Ist eine davon Ihre?"],["Was ist drin?","What's inside?","Sagen Sie mir, was drin ist."],["Willst du mich heiraten?","Will you marry me?","Willst du mich heiraten?"],["am wenigsten","least of all","Am wenigsten Oma Gerda."]],"x":[["die Sehenswürdigkeit, die Sehenswürdigkeiten","sight, attraction",""]],"g":["Indefinitpronomen",["For people: jemand (someone) · niemand (no one) · jeder (everyone) · alle (all, + plural verb).","For things: etwas (something) · nichts (nothing) · alles (everything).","einer / eine / eins = one (of them) · keiner / keine / keins = none, nobody: Keine ist meine.","jemand/niemand/jeder take a singular verb: Niemand sieht glücklich aus. · Alle haben etwas verloren.","Beispiele: Hat hier jemand eine braune Tasche verloren? · Da war keiner mehr da."]]},{"n":80,"t":"Wiederholung: Wieder zu Hause","l":"A2","review":true,"p":[["Sonntag, 18. Mai, dreiundzwanzig Uhr"],["Wir sind wieder zu Hause. Der Streik ist vorbei, deshalb konnten wir mit dem Zug zurückfahren. Sieben Stunden, pünktlich, mit Sitzplatz. Trotzdem hat Jonas die ganze Fahrt meine Handtasche festgehalten. Mit beiden Händen."],["Ich sehe auf meine linke Hand. Ein schmaler Ring aus Silber, mit einem kleinen blauen Stein. Jonas hat erzählt, dass er ihn bei einem alten Goldschmied in der Altstadt gekauft hat. Er hat zwei Monate dafür gespart. Und der Stein ist blau, weil er an die Fliese gedacht hat. An Porto. An das Meer."],["Was für ein Wochenende. Ich will alles aufschreiben, damit ich nichts vergesse."],["Zuerst der Streik. Alle Züge sind ausgefallen. Wir wollten schon aufgeben. Aber dann Tom und sein Fernbus! Elf Stunden auf Notsitzen. Meine Knie tun immer noch weh."],["Dann die Tasche. Ich habe sie an der Raststätte in Kassel vergessen. Ein Busfahrer mit Schnurrbart hat sie gefunden und nach Hamburg gebracht. Niemand im Fundbüro wusste etwas. Und dann ist er einfach durch die Tür gekommen. Ich weiß nicht einmal, wie er heißt. Jonas hat ihm unsere Adresse gegeben. Wir werden ihn zur Hochzeit einladen."],["Die Hochzeit! Ich kann es noch nicht glauben. Ich werde Jonas heiraten. In Freiburg? In Porto? Wann? Wir wissen noch gar nichts. Nur, dass wir es wollen."],["Oma Gerda ist die beste Oma der Welt. Sie hat bis Mitternacht getanzt. Mit neunzig! Sie hat mir gesagt: „Kind, wenn er dich jemals schlecht behandelt, ruf mich an. Ich komme mit dem Motorrad.“"],["Als wir heute Abend nach Hause gekommen sind, war das Haus ganz still. Dann ist Frau Schulz mit dem Rollator die Rampe heruntergekommen. Felix saß auf dem Rollator, wie ein König."],["„Und?“, hat sie gefragt. Nur „Und?“."],["Ich habe ihr die Hand gezeigt. Sie hat sich den Ring lange angesehen. Dann hat sie gesagt: „Na endlich. Das hat gedauert.“ Aber sie hatte Tränen in den Augen."],["Jetzt ist es spät. Mein Handy hat fünfzig Nachrichten. Elif hat zwanzig Mal „AAAAH“ geschrieben. Mama hat am Telefon nur geweint. Rui hat geschrieben: „Endlich bekomme ich einen Bruder, der kochen kann.“"],["Und eine Nachricht kam von Herrn Brandt. Er schreibt sonst nie Nachrichten. Nur E-Mails mit „Sehr geehrte Frau Costa“."],["Liebe Mia, herzlichen Glückwunsch! Und eine Neuigkeit von uns: Fátima und ich werden auch heiraten. Am Samstag, dem 21. Juni. Sie und Jonas sind herzlich eingeladen. Bitte keine Geschenke. Nur gute Laune. R. B."],["Herr Brandt heiratet. In fünf Wochen. Und ich habe nichts anzuziehen."]],"q":["ob: Kommt Mama gern nach Freiburg? → Ich weiß nicht, ob …","Indirekte Frage: Wie alt bist du? → Sie möchte wissen, …","Akkusativ-Präposition: Sie gehen ___ Bächle entlang. Sie gehen ___ das Münster herum.","Genitiv: Das ist das Rezeptbuch ___ Opas (mein).","werden: Ich ___ gut auf sie aufpassen. Dein Deutsch ___ jeden Tag besser.","Zeit: ___ zwei Wochen feiert Oma Gerda. Der Streik dauert ___ Freitag ___ Sonntag.","deshalb oder trotzdem? Der Bus ist voll. ___ kommen Mia und Jonas mit.","Perfekt: Was ___ passiert? Er ___ die Tasche nach Hamburg ___ (bringen).","Indefinitpronomen: Hat hier ___ eine Tasche verloren? – Nein, hier hat ___ etwas verloren.","Was hat Jonas in Mias Tasche gelegt?"],"a":["… ob Mama gern nach Freiburg kommt. (story 71)","… wie alt du bist. (story 72)","die · um. entlang after the noun + accusative; um … herum (story 73).","meines. Genitive masculine (story 74).","werde · wird. (story 75)","In · von … bis. (story 76)","Trotzdem. Despite the problem (story 77).","ist · hat … gebracht. passieren with sein; bringen → gebracht (story 78).","jemand · niemand. (story 79)","Eine kleine rote Schachtel mit einem Ring. (story 79)"],"w":[],"c":[],"x":[],"g":["Wiederholung",["ob and indirect W-questions (stories 71–72).","Accusative prepositions incl. entlang, um … herum (story 73) · genitive (story 74) · werden (story 75).","Time prepositions in, ab, bis, zwischen, seit (story 76) · deshalb / trotzdem (story 77).","Perfekt of -ieren and mixed verbs (story 78) · indefinite pronouns (story 79).","Beispiele: Der Streik ist vorbei, deshalb konnten wir zurückfahren. · Ich werde Jonas heiraten."]],"exam":{"task":"Sie waren auf einer Reise. Schreiben Sie einen Beitrag im Forum: „Meine letzte Reise“.","points":["Wohin sind Sie gefahren und mit wem?","Was ist passiert?","Würden Sie die Reise empfehlen? Warum (nicht)?"],"words":50,"en":"Forum post about your last trip: where/with whom, what happened, recommend it?"}},{"n":81,"t":"Welches Kleid?","l":"A2","review":false,"p":[["Samstag. Mia, Elif und Fátima stehen in einer kleinen Boutique in der Gerberau. Fátima braucht ein Brautkleid. Mia braucht ein Kleid für die Hochzeit. Und Elif braucht … eigentlich nichts. Aber sie liebt Shopping."],["Fátima hat Mia am Mittwoch etwas gefragt. Am Telefon, mit zitternder Stimme: „Möchtest du meine Trauzeugin sein?“ Mia hat sofort Ja gesagt. Und Herr Brandt hat Jonas gefragt. Seinen schlimmsten Schüler. Jonas hat drei Minuten lang nichts gesagt. Dann hat er gelacht und Ja gesagt."],["Verkäuferin","Guten Tag! Wer ist die Braut?"],["Fátima: Ich. Mit dreiundsechzig. Ist das ein Problem?"],["Verkäuferin","Ganz im Gegenteil! Welchen Stil suchen Sie?"],["Fátima: Nichts Weißes. Keinen Schleier. Ich bin keine Prinzessin. Ich bin eine Frau vom Markt."],["Die Verkäuferin bringt drei Kleider. Ein hellblaues, ein cremefarbenes und ein rotes."],["Fátima: Dieses hier. Das rote."],["Elif","Rot? Für eine Hochzeit?"],["Fátima: In Portugal trägt jede Braut, was sie will. Und Rainer liebt Rot. Er trägt seit Monaten jeden Tag den rot-grünen Schal."],["Rainer! Mia braucht eine Sekunde. Herr Brandt heißt Rainer. Das hat sie nicht gewusst."],["Fátima probiert das rote Kleid an. Als sie aus der Kabine kommt, sind alle still. Sie sieht wunderschön aus. Wie eine Flamenco-Tänzerin, aber eleganter."],["Verkäuferin","Dieses Kleid wurde für Sie gemacht."],["Fátima: Ich nehme es. Und jetzt Mia. Welches Kleid möchtest du?"],["Mia sucht. Und sucht. Dieses ist zu kurz. Jenes ist zu lang. Jedes Kleid in ihrer Größe ist entweder zu teuer oder zu langweilig."],["Mia","Welche Farbe trägt eine Trauzeugin?"],["Verkäuferin","Eine Trauzeugin trägt nicht dieselbe Farbe wie die Braut. Also nicht Rot. Welche Farbe mögen Sie?"],["Elif","Grün! Wie ihre Winterjacke. Das ist ihre Farbe."],["Die Verkäuferin geht nach hinten. Sie kommt mit einem dunkelgrünen Kleid zurück. Einfach, mit einem kleinen Gürtel. Mia probiert es an. Es passt perfekt."],["Fátima: Mit diesem Kleid und deinem blauen Ring … perfeito!"],["Am Nachmittag treffen sie Jonas und Herrn Brandt in einem Café. Die Männer waren auch einkaufen. Herr Brandt hat einen neuen grauen Anzug. Jonas hat eine Krawatte gekauft. Eine rote."],["Herr Brandt","Für meinen Trauzeugen gilt eine Regel: Jeder Gast darf heute lachen. Nur der Trauzeuge nicht. Bis Samstag."],["Jonas","Jawohl, Herr Brandt."],["Herr Brandt","Rainer. Nenn mich Rainer. Wir sind jetzt fast Familie."],["Jonas sieht aus, als ob er gleich ohnmächtig wird."],["Am Abend sitzen Mia und Jonas auf dem Balkon. Es ist warm und still. Endlich Ruhe."],["Dann, um elf Uhr, kommt es von oben. Aus Mias alter Wohnung. Wohnung drei. Bumm. Bumm. Bumm-bumm-tschak."],["Mia","Was ist das?"],["Jonas","Der neue Nachbar. Er ist heute eingezogen."],["Bumm-bumm-tschak. Bumm-bumm-tschak. Lauter. Immer lauter. Ein Schlagzeug."]],"q":["Wer ist Trauzeugin? Wer ist Trauzeuge?","Welches Kleid nimmt Fátima? Warum?","Warum trägt Mia kein rotes Kleid?","Richtig oder falsch? Mia hat schon lange gewusst, dass Herr Brandt Rainer heißt.","Und du? Welche Kleidung trägst du auf einer Hochzeit? Welche Farbe magst du, und welche nicht?"],"a":["Mia (for Fátima) and Jonas (for Herr Brandt).","Das rote. In Portugal every bride wears what she wants, and Rainer loves red.","A maid of honour doesn't wear the same colour as the bride. „Eine Trauzeugin trägt nicht dieselbe Farbe wie die Braut.“","Falsch. „Herr Brandt heißt Rainer. Das hat sie nicht gewusst.“","Example: Auf einer Hochzeit trage ich einen dunklen Anzug. Ich mag Blau, aber Gelb mag ich nicht."],"w":[["dieser / diese / dieses","this","Dieses hier. Das rote."],["jener / jene / jenes","that (one)","Jenes ist zu lang."],["jeder / jede / jedes","every, each","Jede Braut trägt, was sie will."],["die Hochzeit, die Hochzeiten","wedding","ein Kleid für die Hochzeit"],["die Braut, die Bräute","bride","Wer ist die Braut?"],["das Brautkleid, die Brautkleider","wedding dress","Fátima braucht ein Brautkleid."],["der Trauzeuge / die Trauzeugin","best man / maid of honour","Möchtest du meine Trauzeugin sein?"],["der Stil, die Stile","style","Welchen Stil suchen Sie?"],["der Schleier, die Schleier","veil","Keinen Schleier."],["die Prinzessin, die Prinzessinnen","princess","Ich bin keine Prinzessin."],["entweder … oder","either … or","entweder zu teuer oder zu langweilig"],["der Gürtel, die Gürtel","belt","mit einem kleinen Gürtel"],["gelten","to apply, be valid","Für meinen Trauzeugen gilt eine Regel."],["ohnmächtig","unconscious, faint","als ob er gleich ohnmächtig wird"],["das Schlagzeug, die Schlagzeuge","drums","Ein Schlagzeug."]],"c":[["Ganz im Gegenteil!","Quite the opposite!","Ganz im Gegenteil!"],["Nichts Weißes.","Nothing white.","Nichts Weißes."],["Nenn mich …","Call me …","Nenn mich Rainer."],["Jawohl!","Yes, sir!","Jawohl, Herr Brandt."]],"x":[["verpassen","to miss",""],["übernachten","to stay overnight",""]],"g":["dieser, jener, jeder und welcher",["dieser (this), jener (that), jeder (every) and welcher (which) take the same endings as der, die, das.","der → dieser · die → diese · das → dieses · Plural → diese. Accusative masculine: diesen, jeden, welchen.","jeder is only used in the singular. For plural, use alle: jede Braut → alle Bräute.","jener is rare in speech; people say der da or das da.","Beispiele: Dieses Kleid wurde für Sie gemacht. · Jede Braut trägt, was sie will. · Welchen Stil suchen Sie?"]]},{"n":82,"t":"Der neue Nachbar","l":"A2","review":false,"p":[["Elf Uhr fünfzehn. Bumm-bumm-tschak. Mia und Jonas gehen nach oben und klingeln an der Tür von Wohnung drei. Die Musik hört auf. Ein junger Mann macht die Tür auf. Er ist groß und dünn, hat blonde Dreadlocks und trägt ein T-Shirt mit einem Totenkopf. In der Hand hält er zwei Trommelstöcke."],["Finn","Oh. Hi. Ist es zu laut?"],["Jonas","Ein bisschen. Es ist Viertel nach elf."],["Finn","Sorry! Ich bin Finn. Ich studiere Musik an der Musikhochschule. Schlagzeug. Morgen habe ich eine Prüfung. Ich muss üben."],["Mia","Kannst du nicht leiser üben?"],["Finn","Leises Schlagzeug? Das gibt es nicht."],["In diesem Moment hören sie unten eine Tür. Dann das Geräusch eines Rollators. Langsam, aber wütend. Frau Schulz steht unten an der Treppe, im Morgenmantel."],["Frau Schulz","Junger Mann! Kennen Sie die Hausordnung? Paragraf zwei: Nachtruhe ab zweiundzwanzig Uhr!"],["Finn","Entschuldigung, ich …"],["Frau Schulz","Wenn das noch einmal passiert, rufe ich einen Polizisten!"],["Sie geht zurück in ihre Wohnung. Die Tür knallt."],["Am nächsten Morgen ist Frau Schulz immer noch wütend. Sie erzählt es jedem: dem Briefträger, dem Bäcker, Herrn Krause im Blumenladen."],["Frau Schulz","Ich habe nichts gegen den Studenten. Ich habe etwas gegen den Lärm. Ich werde mit dem jungen Herrn sprechen. Mit einem Zettel. Mit der Hausordnung. Und mit einem Kollegen von Herrn Krause, vom Ordnungsamt."],["Aber am Nachmittag passiert etwas Unerwartetes. Mia sitzt auf dem Balkon. Unten im Hof sitzt Finn auf den Stufen. Er sieht traurig aus."],["Mia","Wie war die Prüfung?"],["Finn","Schlecht. Ich habe zu wenig geübt. Und jetzt hasst mich das ganze Haus. Vor allem die alte Dame."],["Dann kommt Frau Schulz mit dem Rollator aus dem Haus. Sie sieht den jungen Mann. Sie bleibt stehen."],["Frau Schulz","Sie sind Musiker?"],["Finn","Ich versuche es."],["Frau Schulz","Ich war vierzig Jahre Musiklehrerin. Klavier. Wissen Sie, was das Problem ist? Nicht der Lärm. Sie spielen nicht im Takt. Ich habe es gestern genau gehört. Das Tempo war zu schnell."],["Finn sieht sie an. Sein Mund ist offen."],["Frau Schulz","Im Keller ist ein alter Raum. Mein Mann hat dort früher Mehl gelagert. Dort ist es ruhig, und niemand hört etwas. Von fünfzehn bis neunzehn Uhr dürfen Sie dort üben. Jeden Tag. Aber nur, wenn Sie mir einmal pro Woche vorspielen. Ich korrigiere Ihr Tempo."],["Finn","Wirklich? Danke! Danke, Frau … ?"],["Frau Schulz","Schulz. Renate Schulz. Und jetzt bringen Sie mir Ihr Schlagzeug in den Keller. Und dann helfen Sie mir mit meinem Klavier. Es ist seit Jahren verstimmt."],["Am Abend hört Mia Musik aus dem Keller. Ein Schlagzeug. Und ein Klavier. Zusammen. Nicht perfekt. Aber im Takt."],["Jonas kommt auf den Balkon."],["Jonas","Ist das … Frau Schulz?"],["Mia","Ja. Mit dem neuen Nachbarn."],["Dann klingelt Mias Handy. Rui."],["Rui","Mia! Ich habe meinen Flug gebucht! Ich komme am Freitag, rechtzeitig zur Hochzeit von deinem Lehrer. Und rate mal, wer mich vom Flughafen abholt? Lea!"]],"q":["Wer ist Finn? Was macht er?","Was sagt Frau Schulz über die Hausordnung?","Was ist laut Frau Schulz das wirkliche Problem?","Richtig oder falsch? Finn darf jetzt jeden Abend um dreiundzwanzig Uhr üben.","Und du? Hattest du schon einmal laute Nachbarn? Was hast du gemacht?"],"a":["Ein Musikstudent. Er spielt Schlagzeug. „Ich studiere Musik an der Musikhochschule. Schlagzeug.“","Night-time quiet from 10 p.m. „Paragraf zwei: Nachtruhe ab zweiundzwanzig Uhr!“","He doesn't play in time; the tempo was too fast. „Sie spielen nicht im Takt.“","Falsch. Only from 3 to 7 p.m., in the cellar.","Example: Ja, meine Nachbarn haben oft laute Partys gemacht. Ich habe mit ihnen gesprochen."],"w":[["der Student (den / dem Studenten)","student","Ich habe nichts gegen den Studenten."],["der Polizist (einen Polizisten)","police officer","Ich rufe einen Polizisten!"],["der Herr (dem jungen Herrn)","gentleman","Ich werde mit dem jungen Herrn sprechen."],["der Nachbar (dem Nachbarn)","neighbour","Mit dem neuen Nachbarn."],["der Kollege (einem Kollegen)","colleague","mit einem Kollegen von Herrn Krause"],["der Totenkopf, die Totenköpfe","skull","ein T-Shirt mit einem Totenkopf"],["die Musikhochschule","music college","an der Musikhochschule"],["die Nachtruhe","night-time quiet","Nachtruhe ab zweiundzwanzig Uhr!"],["knallen","to bang, slam","Die Tür knallt."],["der Briefträger, die Briefträger","postman","dem Briefträger"],["der Lärm","noise","Ich habe etwas gegen den Lärm."],["unerwartet","unexpected","etwas Unerwartetes"],["der Takt","beat, rhythm","Sie spielen nicht im Takt."],["vorspielen","to play for sb.","wenn Sie mir vorspielen"],["verstimmt","out of tune","Es ist seit Jahren verstimmt."]],"c":[["etwas gegen … haben","to have sth. against …","Ich habe nichts gegen den Studenten."],["vor allem","above all","Vor allem die alte Dame."],["im Takt","in time (music)","Nicht perfekt. Aber im Takt."],["rechtzeitig","in time","rechtzeitig zur Hochzeit"]],"x":[["Der Zug hat Verspätung.","the train is delayed.",""],["Wo muss ich umsteigen?","where do I have to change?",""]],"g":["die n-Deklination",["Some masculine nouns add -(e)n in every case except the nominative singular.","Typical: nouns for people and animals ending in -e (der Kollege, der Junge, der Kunde) and many foreign words ending in -ent, -ist, -ant (der Student, der Polizist, der Praktikant). Also: der Herr, der Nachbar, der Mensch.","der Student → den Studenten, dem Studenten, des Studenten (plural: die Studenten).","Herr in letters and speech: Sehr geehrter Herr Krause · mit Herrn Krause.","Beispiele: Ich rufe einen Polizisten! · Ich spreche mit dem jungen Herrn."]]},{"n":83,"t":"Ich gebe es dir","l":"A2","review":false,"p":[["Freitag, achtzehn Uhr. Es klingelt. Vor der Tür steht Rui, mit einem Rucksack und einem breiten Lächeln. Hinter ihm steht Lea, mit ihrem Fahrrad."],["Rui","Mana! Endlich!"],["Mia umarmt ihren kleinen Bruder. Er ist größer geworden. Und er hat jetzt einen Bart."],["Rui","Und du musst Jonas sein. Der Mann, der kochen kann."],["Jonas","Und du bist der Bruder, der zehn Euro gewettet hat."],["Sie lachen. Lea stellt ihr Fahrrad in den Hof. Mia sieht, wie Rui ihr nachsieht. Aha."],["In der Küche öffnet Rui seinen Rucksack."],["Rui","Ich habe Geschenke. Erstens: Das ist von Mama. Für dich, Mia."],["Er gibt ihr eine kleine Schachtel. Darin sind zwei alte Ohrringe aus Gold. Die Ohrringe von Oma."],["Mia","Die Ohrringe von Oma? Mama hat sie mir immer versprochen. Für meine Hochzeit."],["Rui","Sie hat gesagt: „Gib sie ihr jetzt. Sie soll sie morgen tragen. Und bei ihrer eigenen Hochzeit auch.“"],["Mia muss sich setzen."],["Rui","Zweitens: für Jonas. Von mir."],["Er holt einen blau-weißen Schal heraus. Der Schal vom FC Porto."],["Rui","Jetzt gehörst du zur Familie. Da muss man den richtigen Verein haben. Ich schenke ihn dir."],["Jonas","Aber ich bin Fan vom SC Freiburg!"],["Rui","Jetzt nicht mehr."],["Dann wird Rui plötzlich rot."],["Rui","Und … drittens habe ich ein Problem. Morgen ist die Hochzeit. Und ich habe meinen Anzug vergessen. In Porto. Auf dem Bett."],["Mia","Rui!"],["Jonas","Kein Problem. Ich habe zwei Anzüge. Einen grauen und einen dunkelblauen. Den grauen trage ich. Den blauen leihe ich dir."],["Rui","Leihst du ihn mir wirklich?"],["Jonas","Ich leihe ihn dir. Aber nur, wenn du ihn mir sauber zurückgibst."],["Rui probiert den Anzug an. Er ist ein bisschen zu lang. Mia holt eine Nadel und näht schnell die Hose kürzer."],["Rui","Und eine Krawatte? Hast du eine Krawatte für mich?"],["Jonas","Ich habe nur noch die rote. Die habe ich Herrn Brandt versprochen. Er hat sie mir gestern zurückgegeben, weil Fátima ihm eine neue geschenkt hat. Also: Ich gebe sie dir."],["In diesem Moment kommt Felix in die Küche. Er sieht Ruis Rucksack. Er springt hinein. Und kommt mit einer Socke im Maul wieder heraus."],["Rui","Hey! Das ist meine Socke! Gib sie mir!"],["Mia","Er gibt sie dir nicht. Das macht er nie. Er sammelt alles."],["Am Abend bastelt Mia das Hochzeitsgeschenk für Herrn Brandt und Fátima. Herr Brandt hat gesagt: keine Geschenke. Aber alle aus dem alten A1-Kurs haben Fotos geschickt. Dazu kommen Fotos vom Markt, von Fátimas Wagen, vom Weihnachtsmarkt. Mia klebt alles in ein Album."],["Jonas","Willst du es ihnen morgen geben?"],["Mia","Ja. Ich gebe es ihnen nach der Trauung. Vor dem Essen."],["Um Mitternacht klingelt das Handy. Herr Brandt. Um Mitternacht?"],["Herr Brandt","Jonas. Entschuldigung, dass ich so spät anrufe. Ich habe die Ringe. Aber … ich weiß nicht mehr, wo. Haben Sie … hast du sie?"],["Jonas","Nein, Rainer. Ganz ruhig. Sie sind sicher in deiner Jackentasche. Schau mal nach."],["Lange Pause."],["Herr Brandt","Gefunden. Danke. Gute Nacht."]],"q":["Was schickt Mama für Mia?","Was schenkt Rui Jonas?","Welches Problem hat Rui? Wie löst Jonas es?","Richtig oder falsch? Felix gibt Rui die Socke zurück.","Und du? Was leihst du gern? Was leihst du nicht gern? (Ich leihe es dir / ihn dir gern …)"],"a":["Die goldenen Ohrringe von Oma. „Die Ohrringe von Oma.“","Einen Schal vom FC Porto. „Ich schenke ihn dir.“","He forgot his suit in Porto. Jonas lends him his dark blue suit. „Den blauen leihe ich dir.“","Falsch. „Er gibt sie dir nicht. Das macht er nie.“","Example: Ich leihe meine Bücher gern. Mein Fahrrad leihe ich nicht gern."],"w":[["leihen","to lend","Den blauen leihe ich dir."],["zurückgeben","to give back","wenn du ihn mir sauber zurückgibst"],["breit","broad, wide","mit einem breiten Lächeln"],["nachsehen","to look after sb. (with eyes)","wie Rui ihr nachsieht"],["der Ohrring, die Ohrringe","earring","zwei alte Ohrringe aus Gold"],["das Gold","gold","aus Gold"],["der Verein, die Vereine","club","den richtigen Verein"],["der Fan, die Fans","fan","Ich bin Fan vom SC Freiburg!"],["die Nadel, die Nadeln","needle","Mia holt eine Nadel."],["nähen","to sew","Sie näht die Hose kürzer."],["das Maul, die Mäuler","mouth (animal)","mit einer Socke im Maul"],["basteln","to make (crafts)","Mia bastelt das Hochzeitsgeschenk."],["kleben","to stick, glue","Mia klebt alles in ein Album."],["die Trauung, die Trauungen","wedding ceremony","nach der Trauung"],["nachschauen","to check","Schau mal nach."]],"c":[["Mana (Port.)","sis","Mana! Endlich!"],["zur Familie gehören","to be part of the family","Jetzt gehörst du zur Familie."],["Jetzt nicht mehr.","Not any more.","Jetzt nicht mehr."],["Gib es mir!","Give it to me!","Gib sie mir!"]],"x":[["Ich habe den Bus verpasst.","I missed the bus.",""],["das Passwort, die Passwörter","password",""]],"g":["Reihenfolge von Dativ und Akkusativ",["Two nouns: dative before accusative: Ich gebe dem Brautpaar das Album.","Two pronouns: accusative before dative: Ich gebe es ihnen. · Ich leihe ihn dir.","One pronoun + one noun: the pronoun comes first: Ich gebe ihnen das Album. · Ich gebe es dem Brautpaar.","Memory trick: short words (pronouns) first; with two pronouns, \"A before D\".","Beispiele: Leihst du ihn mir wirklich? · Gib sie ihr jetzt."]]},{"n":84,"t":"Ein Brief und ein Standesamt","l":"A2","review":false,"p":[["Samstag, acht Uhr. Jonas holt die Post aus dem Briefkasten. Ein weißer Umschlag mit einem Stempel: Stadt Freiburg im Breisgau – Amt für öffentliche Ordnung. Seine Hände zittern ein bisschen. Er öffnet den Brief am Küchentisch und liest laut vor:"],["Stadt Freiburg im Breisgau Amt für öffentliche Ordnung Freiburg, den 18.06."],["Herrn Jonas Weber Lindenstraße 12 79100 Freiburg"],["Betreff","Ihr Antrag auf eine Gaststättenerlaubnis vom 2. Mai"],["Sehr geehrter Herr Weber,"],["wir haben Ihren Antrag vom 2. Mai geprüft. Wir freuen uns, Ihnen mitzuteilen, dass Sie die Erlaubnis für den Betrieb eines Cafés in der Lindenstraße 1 erhalten. Die Erlaubnis gilt ab dem 1. August."],["Bitte beachten Sie","Die Lebensmittelkontrolle findet zwischen dem 21. und dem 25. Juli statt. Den genauen Termin teilen wir Ihnen rechtzeitig mit."],["Mit freundlichen Grüßen i. A. M. Schneider"],["Jonas","Ab dem ersten August! Wir dürfen aufmachen!"],["Mia","„Wir freuen uns, Ihnen mitzuteilen …“ Das klingt wie Herr Krause."],["Jonas","Herr Krause hat mir beim Antrag geholfen. Er hat jedes Komma kontrolliert."],["Aber es ist keine Zeit zum Feiern. Um zehn Uhr dreißig ist die Trauung. Im Standesamt, im Rathaus."],["Um zehn Uhr stehen alle vor dem alten Rathaus. Herr Brandt trägt den grauen Anzug und Fátimas Krawatte – eine grüne. Fátima trägt das rote Kleid und Rosen im Haar. Mia trägt das grüne Kleid und Omas Ohrringe. Jonas trägt den grauen Anzug. Rui trägt Jonas' blauen Anzug, ein bisschen zu weit. Lea steht neben ihm."],["Der Trauungssaal ist klein und hell. Die Standesbeamtin ist eine Frau mit kurzen grauen Haaren und einer sehr klaren Stimme."],["Standesbeamtin","Wir sind heute, am Samstag, dem 21. Juni, hier zusammengekommen, um die Ehe zu schließen zwischen Herrn Rainer Brandt, geboren am 1. April in Hamburg, und Frau Fátima Lopes, geboren am 3. März in Lissabon."],["Herr Brandt hustet nervös. Fátima nimmt seine Hand."],["Standesbeamtin","Herr Brandt, wollen Sie Frau Lopes heiraten? Dann antworten Sie mit Ja."],["Herr Brandt","Ja. Sehr gern."],["Standesbeamtin","Frau Lopes, wollen Sie Herrn Brandt heiraten?"],["Fátima: Sim! Äh – ja!"],["Alle lachen. Dann tauschen sie die Ringe. Jonas hat sie in seiner Tasche. Er hat sie dreimal kontrolliert."],["Standesbeamtin","Und jetzt bitte die Trauzeugen."],["Mia und Jonas unterschreiben im Buch. Unter ihren Namen steht das Datum: Freiburg, den 21.06."],["Standesbeamtin","Hiermit erkläre ich Sie zu Mann und Frau. Herzlichen Glückwunsch!"],["Herr Brandt küsst Fátima. Frau Schulz, in der ersten Reihe, weint in ein Taschentuch. Herr Krause, neben ihr, gibt ihr ein zweites."],["Draußen auf dem Rathausplatz werfen alle Reis. Fátima lacht und ruft:"],["Fátima: Unsere Hochzeitsreise geht vom 22. Juni bis zum 6. Juli! Nach Lissabon! Zu meiner Familie!"],["Dann gehen alle zusammen zum Fest. Zu Fuß, durch die Altstadt, über die Bächle. Das Fest findet in einem Garten am Schlossberg statt. Und das Essen kocht – natürlich – der Trauzeuge."]],"q":["Von wem ist der Brief? Was steht darin?","Wann findet die Lebensmittelkontrolle statt?","Wo und wann ist die Trauung?","Richtig oder falsch? Fátima antwortet zuerst auf Portugiesisch.","Und du? Wann und wo bist du geboren? Schreib das Datum formell (z. B. am 3. März 1990 in …)."],"a":["From the city of Freiburg (Amt für öffentliche Ordnung). Jonas gets the licence for the café from 1 August. „Die Erlaubnis gilt ab dem 1. August.“","Zwischen dem 21. und dem 25. Juli.","Im Standesamt im Rathaus, am Samstag, dem 21. Juni, um 10:30 Uhr.","Richtig. „Sim! Äh – ja!“","Example: Ich bin am 12. Februar 1995 in Manchester geboren."],"w":[["der Briefkasten, die Briefkästen","letterbox","aus dem Briefkasten"],["der Stempel, die Stempel","stamp (official)","ein Umschlag mit einem Stempel"],["der Betreff","subject (letter)","Betreff: Ihr Antrag"],["prüfen","to examine, check","Wir haben Ihren Antrag geprüft."],["mitteilen","to inform","Wir freuen uns, Ihnen mitzuteilen …"],["die Erlaubnis, die Erlaubnisse","permission, licence","Die Erlaubnis gilt ab dem 1. August."],["erhalten","to receive","dass Sie die Erlaubnis erhalten"],["beachten","to note","Bitte beachten Sie: …"],["stattfinden","to take place","Die Kontrolle findet statt."],["das Standesamt, die Standesämter","registry office","im Standesamt"],["das Rathaus, die Rathäuser","town hall","im Rathaus"],["die Ehe, die Ehen","marriage","die Ehe schließen"],["tauschen","to exchange","Sie tauschen die Ringe."],["werfen","to throw","Alle werfen Reis."],["die Hochzeitsreise, die Hochzeitsreisen","honeymoon","Unsere Hochzeitsreise geht nach Lissabon."]],"c":[["Sehr geehrter Herr … / Sehr geehrte Frau …","Dear Mr / Ms … (formal)","Sehr geehrter Herr Weber,"],["Mit freundlichen Grüßen","Yours sincerely","Mit freundlichen Grüßen"],["i. A. (im Auftrag)","on behalf of","i. A. M. Schneider"],["Herzlichen Glückwunsch!","Congratulations!","Herzlichen Glückwunsch!"]],"x":[["die App, die Apps","app",""]],"g":["Datum in Briefen und formelle Briefe",["Place and date at the top: Freiburg, den 18.06. (accusative: den). Spoken: den achtzehnten Juni.","In the text: am Samstag, dem 21. Juni · ab dem 1. August · vom 22. Juni bis zum 6. Juli · zwischen dem 21. und dem 25. Juli.","After am, vom, zum, dem, the ordinal ends in -en: am ersten, vom zweiundzwanzigsten.","Formal letter: Betreff · Sehr geehrter Herr …, / Sehr geehrte Frau …, · text (small letter after the comma) · Mit freundlichen Grüßen.","Beispiele: Die Erlaubnis gilt ab dem 1. August. · Wir sind heute, am Samstag, dem 21. Juni, hier."]]},{"n":85,"t":"Wir helfen dem Brautpaar","l":"A2","review":false,"p":[["Der Garten liegt oben am Schlossberg. Er gehört einem Freund von Herrn Brandt. Unter einem alten Nussbaum stehen lange Tische mit weißen Tischdecken. Überall hängen kleine Lampen."],["Alle helfen. Tom trägt die Tische. Elif und Lea stellen Blumen auf die Tische – Blumen von Herrn Krause, natürlich. Finn hat eine Cajón mitgebracht, eine kleine Holztrommel. Frau Schulz sitzt auf einem Stuhl und gibt Befehle."],["Frau Schulz","Herr Nowak, der Tisch steht schief! Nein, links! Noch mehr links!"],["In der kleinen Gartenküche kocht Jonas mit seiner Mutter. Ingrid hilft ihm beim Gemüse. Klaus hilft beim Grill. Es gibt Bacalhau, Kartoffelsalat, Spätzle, Sardinen, Brezeln und Pastéis. Portugal und der Schwarzwald, auf einem Tisch."],["Um vierzehn Uhr kommen die Gäste. Alle gratulieren dem Brautpaar. Der alte A1-Kurs ist fast komplett da. Herr Brandt gibt jedem die Hand. Seine Augen glänzen."],["Dann schlägt Mia mit einem Löffel an ihr Glas. Es wird still. Ihr Herz klopft. Eine Rede auf Deutsch. Vor achtzig Leuten."],["Mia","Liebe Fátima, lieber Rainer, liebe Gäste. Vor neun Monaten habe ich kein Wort Deutsch verstanden. Herr Brandt hat zu schnell gesprochen. Ich habe ihm nicht geglaubt, dass ich jemals Deutsch lernen kann. Heute halte ich eine Rede. Auf Deutsch. Bei seiner Hochzeit."],["Alle lachen."],["Mia","Ich danke Ihnen, Herr Brandt. Für Ihre Geduld. Für die Blumen, als ich krank war. Und dafür, dass Sie mir immer zugehört haben, auch wenn mein Deutsch schrecklich war. Und Fátima: Du hast mir ein Stück Heimat gegeben. Jeden Samstag. Ich wünsche euch beiden von Herzen alles Gute."],["Dann gibt Mia ihnen das Album. Herr Brandt blättert. Er sieht Fotos von seinen Schülern aus zehn Jahren. Er legt die Hand vor die Augen."],["Dann steht er auf."],["Herr Brandt","Ich bin kein Mann der großen Worte. Das wissen meine Schüler. Aber ich möchte meiner Frau etwas sagen. Fátima, du hast mir gezeigt, dass das Leben mit sechzig nicht vorbei ist. Ich vertraue dir. Ich folge dir überallhin. Sogar zum Fischmarkt um fünf Uhr"],["morgens."],["Fátima: Das werden wir sehen!"],["Dann kommt das Essen. Es schmeckt allen. Herrn Krause schmecken die Sardinen besonders. Er nimmt drei Portionen. Oma Gerda ruft aus Hamburg an und gratuliert per Video. Mama in Porto auch."],["Am Abend spielt Finn die Cajón. Tom singt ein polnisches Lied. Fátima singt einen Fado. Und Rui tanzt mit Lea. Die ganze Zeit. Den ganzen Abend."],["Jonas","Ich glaube, das Bächle hat funktioniert."],["Mia","Sag es Mama nicht. Sonst bucht sie sofort einen Flug."],["Um Mitternacht klingelt Jonas' Handy. Eine unbekannte Nummer."],["Herr Haas","Herr Weber? Hier Haas. Entschuldigung, dass ich so spät anrufe. Eine Information: Die Schlüsselübergabe für die Bäckerei ist am ersten Juli. Um acht Uhr. Seien Sie pünktlich! Meine Frau und ich fliegen um elf Uhr nach Mallorca. Zum ersten Mal seit vierzig Jahren Urlaub!"],["Jonas","Um acht. Kein Problem. Ich bin pünktlich."],["Mia sieht ihn an. Jonas. Pünktlich. Um acht Uhr morgens. Nach einer Hochzeit."]],"q":["Wer hilft bei der Feier? (Nenne drei Personen und was sie machen.)","Wofür dankt Mia Herrn Brandt?","Was sagt Herr Brandt zu Fátima?","Richtig oder falsch? Rui tanzt den ganzen Abend mit Elif.","Und du? Wem hilfst du gern? Wem dankst du heute? Was schmeckt dir am besten?"],"a":["E.g. Tom carries the tables, Elif and Lea put flowers on them, Ingrid helps with the vegetables, Klaus with the barbecue.","For his patience, the flowers when she was ill, and for always listening. „Ich danke Ihnen … Für Ihre Geduld …“","That she showed him life isn't over at sixty; he trusts her and will follow her everywhere. „Ich vertraue dir. Ich folge dir überallhin.“","Falsch. „Rui tanzt mit Lea.“","Example: Ich helfe gern meiner Nachbarin. Heute danke ich meiner Lehrerin. Pizza schmeckt mir am besten."],"w":[["gratulieren (+ Dat.)","to congratulate","Alle gratulieren dem Brautpaar."],["danken (+ Dat.)","to thank","Ich danke Ihnen, Herr Brandt."],["zuhören (+ Dat.)","to listen to","dass Sie mir immer zugehört haben"],["vertrauen (+ Dat.)","to trust","Ich vertraue dir."],["folgen (+ Dat.)","to follow","Ich folge dir überallhin."],["glauben (+ Dat. Person)","to believe sb.","Ich habe ihm nicht geglaubt."],["das Brautpaar, die Brautpaare","bridal couple","dem Brautpaar"],["der Nussbaum, die Nussbäume","walnut tree","unter einem alten Nussbaum"],["die Tischdecke, die Tischdecken","tablecloth","mit weißen Tischdecken"],["der Befehl, die Befehle","order, command","Frau Schulz gibt Befehle."],["der Grill, die Grills","barbecue","Klaus hilft beim Grill."],["die Rede, die Reden","speech","Eine Rede auf Deutsch."],["schrecklich","terrible","als mein Deutsch schrecklich war"],["die Heimat","home(land)","ein Stück Heimat"],["die Portion, die Portionen","portion","Er nimmt drei Portionen."]],"c":[["eine Rede halten","to give a speech","Heute halte ich eine Rede."],["von Herzen alles Gute","all the best, from the heart","Ich wünsche euch von Herzen alles Gute."],["kein Mann der großen Worte","not a man of many words","Ich bin kein Mann der großen Worte."],["Es schmeckt allen.","Everyone likes the food.","Es schmeckt allen."]],"x":[["der Drucker, die Drucker","printer",""],["das Ladegerät, die Ladegeräte","charger",""]],"g":["Verben mit Dativ",["Some verbs take a dative object (often a person), not an accusative.","A1 already: helfen, gefallen, gehören, schmecken, passen, danken.","A2 adds: gratulieren, zuhören, vertrauen, folgen, antworten, glauben (a person), fehlen (to be missing).","Ich danke Ihnen. · Ich vertraue dir. · Herrn Krause schmecken die Sardinen. (the food is the subject!)","Beispiele: Alle gratulieren dem Brautpaar. · Sie haben mir immer zugehört."]]},{"n":86,"t":"Entschuldigung, ich bin zu spät!","l":"A2","review":false,"p":[["Erster Juli. Sieben Uhr zweiundfünfzig. Mia wacht auf, weil Felix auf ihrem Bauch sitzt. Sie sieht auf die Uhr. Dann sieht sie auf Jonas. Jonas schläft. Tief und fest."],["Mia","Jonas! Die Schlüssel! Herr Haas! Acht Uhr!"],["Jonas springt aus dem Bett. Gestern Abend war sein letzter Arbeitstag im Café Sonne. Die Kollegen haben eine Abschiedsparty gemacht. Bis zwei Uhr nachts."],["Um acht Uhr vierundzwanzig rennt Jonas um die Ecke. Ohne Socken, mit nassen Haaren. Herr Haas steht vor der Bäckerei, mit einem Koffer und einer sehr unglücklichen Frau Haas."],["Herr Haas","Vierundzwanzig Minuten, Herr Weber. Vierundzwanzig."],["Jonas","Es tut mir so leid, dass ich zu spät gekommen bin! Ich habe verschlafen, weil ich gestern lange arbeiten musste. Und mein Wecker hat nicht geklingelt, weil ich vergessen habe, ihn zu stellen. Und dann …"],["Herr Haas","Ich habe es gewusst. Ich habe zu meiner Frau gesagt, dass Köche nie pünktlich sein können. Bäcker stehen um drei Uhr auf. Köche gehen um drei Uhr ins Bett."],["Frau Haas lacht. Dann lacht auch Herr Haas."],["Herr Haas","Na gut. Kommen Sie. Wir haben noch zwanzig Minuten. Unser Taxi kommt um Viertel vor neun."],["Er gibt Jonas einen schweren Schlüsselbund. Sieben Schlüssel. Dann zeigt er ihm noch einmal den alten Ofen."],["Herr Haas","Sie müssen wissen, dass dieser Ofen eine Seele hat. Er wird morgens langsam warm. Wie ein alter Mann. Sie dürfen ihn nie zu schnell heizen. Heinrich Schulz hat mir das gesagt, als ich die Bäckerei übernommen habe. Jetzt sage ich es Ihnen."],["Jonas","Ich verspreche Ihnen, dass ich gut auf ihn aufpassen werde."],["Um Viertel vor neun steigen Herr und Frau Haas ins Taxi. Frau Haas winkt aus dem Fenster."],["Frau Haas","Viel Glück, Café Bächle!"],["Um neun Uhr fünfzehn kommt Mia ins Büro. Fünfzehn Minuten zu spät."],["Mia","Entschuldigung, Sabine. Ich bin zu spät, weil ich Jonas wecken musste. Und weil ich dann noch zur Bäckerei gelaufen bin, weil ich unbedingt sehen wollte, wie er die Schlüssel bekommt."],["Sabine","Drei Gründe für fünfzehn Minuten. Sehr deutsch, Mia. Ich bin beeindruckt."],["Dann beginnt der Juli. Der heißeste und anstrengendste Juli in Mias Leben. Jeden Abend nach der Arbeit renoviert sie mit den anderen die alte Bäckerei. Klaus repariert die Fenster. Tom und Finn streichen die Wände – hellblau, wie die Fliese aus Porto. Elif näht Kissen. Frau Schulz sitzt in einem Stuhl im Hof und erzählt, wie die Bäckerei früher ausgesehen hat. Felix schläft auf jedem frisch gestrichenen Stuhl."],["Am dreiundzwanzigsten Juli kommt die Lebensmittelkontrolle. Eine Frau mit Klemmbrett kontrolliert alles: die Küche, den Kühlschrank, die Toiletten. Sie sagt nicht viel. Am Ende sagt sie nur: „Sehr sauber. Sie dürfen öffnen.“"],["Am ersten August, um sieben Uhr morgens, öffnet Café Bächle. Der erste Tag ist ein Fest. Alle kommen: Freunde, Nachbarn, Kollegen aus der Agentur, Gäste vom Crowdfunding. Herr Krause kommt um sieben Uhr eins und ist der erste Gast. Um achtzehn Uhr ist der ganze Kuchen weg."],["Am zweiten Tag kommen elf Gäste."],["Am dritten Tag kommen drei."]],"q":["Warum hat Jonas verschlafen?","Was sagt Herr Haas über Köche und Bäcker?","Was muss man über den alten Ofen wissen?","Richtig oder falsch? Am dritten Tag ist das Café voll.","Und du? Wann bist du zuletzt zu spät gekommen? Warum? (Ich bin zu spät gekommen, weil ich … musste / weil … hat …)"],"a":["His farewell party at Café Sonne lasted until 2 a.m., and he forgot to set his alarm. „… weil ich gestern lange arbeiten musste … weil ich vergessen habe, ihn zu stellen.“","Bakers get up at 3 a.m., cooks go to bed at 3 a.m. „Köche gehen um drei Uhr ins Bett.“","It has a soul, warms up slowly, and must never be heated too fast.","Falsch. „Am dritten Tag kommen drei.“","Example: Ich bin gestern zu spät gekommen, weil der Bus nicht gekommen ist."],"w":[["verschlafen","to oversleep","Ich habe verschlafen."],["die Abschiedsparty, die Abschiedspartys","farewell party","eine Abschiedsparty"],["stellen (Wecker)","to set (an alarm)","ihn zu stellen"],["heizen","to heat","Sie dürfen ihn nie zu schnell heizen."],["übernehmen","to take over","als ich die Bäckerei übernommen habe"],["der Grund, die Gründe","reason","Drei Gründe für fünfzehn Minuten."],["beeindruckt","impressed","Ich bin beeindruckt."],["anstrengend","exhausting","der anstrengendste Juli"],["renovieren","to renovate","Sie renoviert die Bäckerei."],["streichen (gestrichen)","to paint","Tom und Finn streichen die Wände."],["hellblau","light blue","hellblau, wie die Fliese"],["die Lebensmittelkontrolle","food inspection","Die Lebensmittelkontrolle kommt."],["das Klemmbrett, die Klemmbretter","clipboard","Eine Frau mit Klemmbrett"],["öffnen","to open","Café Bächle öffnet."],["unglücklich","unhappy","eine sehr unglückliche Frau Haas"]],"c":[["tief und fest schlafen","to be fast asleep","Jonas schläft. Tief und fest."],["Es tut mir leid, dass …","I'm sorry that …","Es tut mir so leid, dass ich zu spät gekommen bin!"],["Na gut.","All right then.","Na gut. Kommen Sie."],["Sehr deutsch!","Very German!","Sehr deutsch, Mia."]],"x":[["die Zeitung, die Zeitungen","newspaper",""],["die Sendung, die Sendungen","TV programme",""]],"g":["Nebensatz mit Modalverb oder Perfekt",["In a subordinate clause, the conjugated verb goes to the very end – after the infinitive or participle.","Modal verb: Ich musste lange arbeiten. → …, weil ich lange arbeiten musste.","Perfekt: Ich bin zu spät gekommen. → …, dass ich zu spät gekommen bin.","Future with werden: …, dass ich gut auf ihn aufpassen werde.","So: … [object] [infinitive/participle] [conjugated verb].","Beispiele: Es tut mir leid, dass ich zu spät gekommen bin. · …, weil ich Jonas wecken musste."]]},{"n":87,"t":"Das Café hat Probleme","l":"A2","review":false,"p":[["Zweite Woche. Café Bächle ist wunderschön. Die Wände sind hellblau, auf jedem Tisch stehen Blumen von Herrn Krause, und es riecht nach Zimt und frischem Kaffee. Aber das Café ist leer."],["Montag","sieben Gäste. Dienstag: fünf. Mittwoch: neun, aber vier davon sind Tom, Elif, Frau Schulz und Felix."],["Am Mittwochabend sitzt Jonas allein am Tisch in der Küche. Vor ihm liegen Rechnungen. Viele Rechnungen. Mia kommt von der Arbeit."],["Jonas","Mia, wir verlieren jeden Tag Geld. Viel Geld. Die Miete, der Strom, die Milch, die Butter … Wenn das so weitergeht, müssen wir im Oktober zumachen."],["Mia","Ruhig. Wir finden eine Lösung. Wir fragen alle."],["Am Donnerstag fragen sie alle. Und alle haben einen Rat."],["Klaus","Du solltest die Zahlen jeden Abend kontrollieren. Ruhig und genau. Und du solltest nicht in Panik geraten. Drei Monate am Anfang sind immer schwer."],["Max","Ihr solltet auf Instagram aktiv sein. Jeden Tag ein schönes Foto. Felix auf dem Tisch, der alte Ofen, die Pastéis. Die Leute lieben so etwas."],["Fátima: Ihr solltet eine portugiesische Woche machen. Mit Musik, mit Fado, mit Sardinen. Ich helfe euch. Rainer auch. Er kann jetzt „obrigado“ sagen!"],["Herr Krause","Sie sollten die Öffnungszeiten an die Tür hängen. Groß und ordentlich. Das ist das Wichtigste. Ich habe gestern nicht gewusst, ob Sie offen haben."],["Und Frau Schulz? Frau Schulz sagt etwas, das niemand erwartet hat."],["Frau Schulz","Herr Weber, Sie sollten Brot backen. Mit Heinrichs Ofen. Kuchen kaufen die Leute am Sonntag. Aber Brot kaufen sie jeden Tag. Jeden Morgen. Hier wohnen viele Familien, und die nächste Bäckerei ist einen Kilometer entfernt."],["Jonas sieht sie an."],["Jonas","Aber ich bin kein Bäcker. Ich bin Koch."],["Frau Schulz","Ich war fünfzig Jahre mit einem Bäcker verheiratet. Ich kenne alle Rezepte. Ich habe sie im Kopf. Und im Keller habe ich Heinrichs altes Buch."],["Am Freitagnachmittag kommt Paul mit Lena ins Café. Paul ist jetzt sieben. Er bestellt einen Kakao. Dann geht er nach draußen und kommt nach zwei Minuten zurück."],["Paul","Onkel Jonas, warum steht draußen im Fenster „Zu vermieten“?"],["Alle sehen sich an. Dann gehen alle nach draußen. Im großen Fenster, ganz unten in der Ecke, hängt immer noch das alte Schild von Herrn Haas: Ladenlokal zu vermieten – ab 1. Juli."],["Jonas wird rot. Mia hält sich die Hand vor den Mund. Lena lacht so laut, dass Leute auf der anderen Straßenseite stehen bleiben."],["Jonas","Zwei Wochen. Seit zwei Wochen denken die Leute, dass die Bäckerei leer ist."],["Paul","Ihr solltet besser hingucken."],["Jonas nimmt das Schild ab. Herr Krause hängt die Öffnungszeiten an die Tür. Groß und ordentlich."],["Am Abend ruft Elif an."],["Elif","Ich habe eine Idee! Meine Freundin Clara macht ein Praktikum bei der Badischen Zeitung. Sie sucht eine schöne Geschichte für die Wochenendausgabe. Eine Geschichte über eine alte Bäckerei, einen alten Ofen, eine Portugiesin, einen Kater, der Brezeln stiehlt … Ich glaube, sie würde das lieben!"]],"q":["Wie viele Gäste kommen in der zweiten Woche?","Welchen Rat gibt Max? Welchen Rat gibt Fátima?","Warum soll Jonas Brot backen?","Richtig oder falsch? Paul findet das Problem.","Und du? Ein Freund möchte Deutsch lernen. Was sollte er machen? Gib drei Ratschläge. (Du solltest …)"],"a":["Montag 7, Dienstag 5, Mittwoch 9 (4 davon Freunde).","Max: aktiv auf Instagram sein. Fátima: eine portugiesische Woche machen.","People buy cake only on Sundays, but bread every day, and the next bakery is a kilometre away. „Aber Brot kaufen sie jeden Tag.“","Richtig. „Warum steht draußen im Fenster ‚Zu vermieten‘?“","Example: Du solltest jeden Tag lesen. Du solltest deutsche Serien sehen. Du solltest mit Deutschen sprechen."],"w":[["sollte (Konjunktiv II)","should, ought to","Sie sollten Brot backen."],["der Strom","electricity","die Miete, der Strom, die Milch"],["weitergehen","to go on, continue","Wenn das so weitergeht …"],["der Rat (die Ratschläge)","advice","Alle haben einen Rat."],["aktiv","active","Ihr solltet auf Instagram aktiv sein."],["erwarten","to expect","etwas, das niemand erwartet hat"],["verheiratet","married","mit einem Bäcker verheiratet"],["der Kakao","hot chocolate","Er bestellt einen Kakao."],["die Straßenseite","side of the street","auf der anderen Straßenseite"],["stehen bleiben","to stop (walking)","Leute bleiben stehen."],["hingucken (ugs.)","to look properly","Ihr solltet besser hingucken."],["abnehmen","to take down","Jonas nimmt das Schild ab."],["das Praktikum, die Praktika","internship","ein Praktikum bei der Zeitung"],["die Ausgabe, die Ausgaben","edition","die Wochenendausgabe"],["stehlen (stiehlt)","to steal","ein Kater, der Brezeln stiehlt"]],"c":[["in Panik geraten","to panic","Du solltest nicht in Panik geraten."],["so etwas","something like that","Die Leute lieben so etwas."],["… davon","… of them","vier davon sind Tom, Elif …"],["einen Rat geben","to give advice","Welchen Rat gibt Max?"]],"x":[["herunterladen","to download",""]],"g":["Ratschläge mit sollte",["sollte is the Konjunktiv II of sollen. Use it for advice: \"you should …\".","Forms: ich sollte, du solltest, er sollte, wir sollten, ihr solltet, sie/Sie sollten.","Modal verb in position 2, infinitive at the end: Du solltest die Zahlen kontrollieren.","Negative advice: Du solltest nicht in Panik geraten.","Other ways to give advice: An deiner Stelle würde ich … · Wie wäre es mit …?","Beispiele: Ihr solltet auf Instagram aktiv sein. · Sie sollten Brot backen."]]},{"n":88,"t":"Ein Café mit Herz","l":"A2","review":false,"p":[["Montag, vier Uhr morgens. In der alten Backstube brennt Licht. Jonas steht am Ofen, mit Mehl bis zu den Ellbogen. Frau Schulz sitzt auf einem Stuhl daneben, mit Heinrichs altem Rezeptbuch auf dem Schoß. Felix schläft auf einem Mehlsack."],["Frau Schulz","Nicht so viel Wasser! Heinrich hat immer gesagt: Der Teig muss sich anfühlen wie ein Ohrläppchen."],["Jonas","Wie ein … Ohrläppchen?"],["Frau Schulz","Fassen Sie mal an Ihr Ohr. So weich muss er sein."],["Um sieben Uhr liegen die ersten Brote im Regal. Dunkle Bauernbrote, Brezeln, Brötchen. Und ein neues Brot: das „Heinrich-Brot“, mit Nüssen und Honig, nach dem alten Rezept. Am ersten Tag verkauft Jonas zwanzig Brote. Am zweiten vierzig."],["Am Mittwoch kommt Clara, die Praktikantin von der Badischen Zeitung. Sie ist jung, neugierig und schreibt sehr schnell. Sie spricht mit allen: mit Jonas, mit Mia, mit Frau Schulz, sogar mit Herrn Krause. Sie fotografiert den Ofen, die Fliesen, die Pastéis. Und Felix, natürlich."],["Am Samstag steht der Artikel in der Zeitung. Eine ganze Seite. Mia liest ihn laut vor, beim Frühstück im Café:"],["Ein Café mit Herz und Geschichte"],["In der Lindenstraße hat eine alte Bäckerei ein neues Leben bekommen. Mit viel Freundlichkeit, Kreativität und einer unglaublichen Geschichte."],["Seit 1964 backt hier derselbe Ofen. Damals hat Bäckermeister Heinrich Schulz ihn gekauft. Seine Witwe Renate Schulz erinnert sich: „Mein Mann hat jeden Morgen um drei Uhr angefangen. Seine Brötchen waren eine Berühmtheit im Viertel.“ Heute gibt sie ihr Wissen an den jungen Koch Jonas Weber weiter."],["Die Eröffnung war nur durch die Hilfe vieler Freunde möglich: 270 Menschen haben beim Crowdfunding gespendet. Die Rezepte kommen aus dem Schwarzwald – und aus Portugal. Denn Webers Verlobte, die Portugiesin Mia Costa, hat ihm das Rezeptbuch ihres Großvaters mitgebracht."],["Und dann gibt es noch Felix, den Kater. Er ist der heimliche Chef des Hauses. Er hat früher jeden Morgen Brezeln aus dieser Bäckerei gestohlen. Heute bekommt er sie kostenlos."],["Fazit","unbedingt probieren! Die Pastéis de Nata sind unvergesslich, das Heinrich-Brot ist eine kleine Sensation. Und die Gemütlichkeit gibt es gratis dazu."],["Alle klatschen. Frau Schulz liest den Satz über Heinrich zweimal. Dann noch einmal."],["Frau Schulz","„Eine Berühmtheit im Viertel.“ Das hätte ihm gefallen."],["Am Sonntagmorgen um sieben Uhr steht eine Schlange vor dem Café. Zwanzig Leute. Mit der Zeitung in der Hand."],["Jonas","Mia! Mia, komm schnell! Wir brauchen Hilfe!"],["Um zehn Uhr hilft Mia hinter der Theke. Tom kocht Kaffee. Elif verkauft Brezeln. Herr Brandt und Fátima backen Pastéis. Und Finn spielt im Hof leise Cajón."],["Um vierzehn Uhr ist alles verkauft. Alles. Jonas setzt sich erschöpft auf die Stufen vor dem Café. Er lacht und weint gleichzeitig."],["Frau Schulz rollt mit dem Rollator neben ihn."],["Frau Schulz","Wissen Sie, was diese Straße jetzt braucht? Ein Fest. Ein Straßenfest. Wie früher, in den Siebzigerjahren. Mit Musik, mit Tischen auf der Straße, mit der ganzen Nachbarschaft."],["Jonas","Ein Straßenfest? Wann?"],["Frau Schulz","In drei Wochen. Am letzten Samstag im August. Ich habe schon mit Herrn Krause gesprochen. Er besorgt die Genehmigung."]],"q":["Was ist das „Heinrich-Brot“?","Wer ist Clara?","Was steht im Artikel über Felix?","Richtig oder falsch? Nach dem Artikel kommen keine neuen Gäste.","Und du? Bilde Nomen: freundlich → die …, gemütlich → die …, eröffnen → die …, schön → die …"],"a":["A new bread with nuts and honey, made to Heinrich's old recipe.","An intern at the Badische Zeitung. „Clara, die Praktikantin von der Badischen Zeitung.“","He is the secret boss of the house; he used to steal pretzels, now he gets them for free.","Falsch. „Am Sonntagmorgen um sieben Uhr steht eine Schlange vor dem Café.“","die Freundlichkeit, die Gemütlichkeit, die Eröffnung, die Schönheit."],"w":[["die Freundlichkeit","friendliness","mit viel Freundlichkeit"],["die Kreativität","creativity","Kreativität"],["die Berühmtheit, die Berühmtheiten","celebrity, famous thing","eine Berühmtheit im Viertel"],["die Eröffnung, die Eröffnungen","opening","Die Eröffnung war nur durch Hilfe möglich."],["die Gemütlichkeit","cosiness","Die Gemütlichkeit gibt es gratis."],["unvergesslich","unforgettable","Die Pastéis sind unvergesslich."],["kostenlos","free of charge","Heute bekommt er sie kostenlos."],["heimlich","secret","der heimliche Chef des Hauses"],["die Witwe, die Witwen","widow","Seine Witwe Renate Schulz"],["der Teig, die Teige","dough","Der Teig muss weich sein."],["der Ellbogen, die Ellbogen","elbow","mit Mehl bis zu den Ellbogen"],["die Verlobte, die Verlobten","fiancée","Webers Verlobte"],["neugierig","curious","Sie ist jung und neugierig."],["die Schlange, die Schlangen","queue; snake","eine Schlange vor dem Café"],["die Genehmigung, die Genehmigungen","permit","Er besorgt die Genehmigung."]],"c":[["sich erinnern","to remember","Renate Schulz erinnert sich."],["weitergeben","to pass on","Sie gibt ihr Wissen weiter."],["Fazit: …","Conclusion: …","Fazit: unbedingt probieren!"],["Das hätte ihm gefallen.","He would have liked that.","Das hätte ihm gefallen."]],"x":[["speichern","to save",""],["ausdrucken","to print out",""]],"g":["Wortbildung",["Nouns from adjectives: -heit / -keit (always die): berühmt → die Berühmtheit, freundlich → die Freundlichkeit, gemütlich → die Gemütlichkeit.","Nouns from verbs: -ung (always die): eröffnen → die Eröffnung, genehmigen → die Genehmigung.","Female forms: -in: der Bäcker → die Bäckerin, der Portugiese → die Portugiesin.","Opposites with un-: glücklich → unglücklich, vergesslich → unvergesslich. Adjectives with -los (without): kostenlos, arbeitslos.","Beispiele: Die Eröffnung war ein Erfolg. · Die Pastéis sind unvergesslich."]]},{"n":89,"t":"Das Sommerfest","l":"A2","review":false,"p":[["Freitag, sechzehn Uhr. Morgen ist das Straßenfest. Die Lindenstraße ist für Autos gesperrt. Herr Krause hat die Genehmigung. Er hat sie laminiert und an die Laterne gehängt."],["Jetzt wird aufgebaut. Alle helfen. Frau Schulz sitzt vor dem Haus und gibt Kommandos. Wie eine Generalin."],["Frau Schulz","Herr Nowak! Die Tische kommen hierher. Vor das Café. Nein, nicht dorthin! Hierher! Zu mir!"],["Tom und Klaus tragen lange Holztische aus dem Keller. Rauf die Treppe, raus auf die Straße."],["Tom","Frau Schulz, wohin mit den Bänken?"],["Frau Schulz","Die Bänke gehören nach hinten, in den Hof. Für die älteren Leute. Dort ist Schatten."],["Finn baut vorne an der Ecke eine kleine Bühne auf. Seine Band heißt „Die Bächle-Boys“. Sie hat drei Mitglieder: Finn am Schlagzeug, ein Bassist mit grünen Haaren und – seit zwei Wochen – Frau Schulz am Klavier. Für drei Lieder."],["Mia steht oben auf einer Leiter und hängt bunte Lichterketten von Haus zu Haus. Jonas hält die Leiter unten fest."],["Mia","Noch ein bisschen nach links? Oder nach rechts?"],["Jonas","Weiter nach oben! Nein, wieder runter. Perfekt! Komm herunter, vorsichtig!"],["Elif kommt mit zwei Kisten Limonade. Paul läuft hin und her und hängt überall Luftballons auf. Felix sitzt oben auf dem Fensterbrett von Frau Schulz und beobachtet alles. Sehr kritisch."],["Um achtzehn Uhr wird der Himmel plötzlich dunkel. Ein starker Wind kommt. Die Lichterketten schaukeln. Dann donnert es."],["Herr Krause","Gewitter! Alle rein! Alles rein!"],["Alle rennen. Die Tischdecken fliegen durch die Luft. Paul jagt einem Luftballon hinterher. Tom trägt Frau Schulz' Klavierhocker ins Café. Jonas trägt Frau Schulz. Frau Schulz protestiert."],["Frau Schulz","Herr Weber! Lassen Sie mich runter! Ich kann allein gehen!"],["Zwanzig Minuten lang regnet es in Strömen. Alle stehen drinnen im Café, nass und lachend. Jonas macht heiße Schokolade für alle. Draußen läuft das Wasser durch die Bächle, so schnell wie ein kleiner Fluss."],["Dann hört der Regen auf. Die Sonne kommt wieder heraus. Über dem Schlossberg steht ein Regenbogen."],["Elif","Alle raus! Wir müssen alles noch einmal machen!"],["Und sie machen alles noch einmal. Die Tischdecken. Die Luftballons. Die Lichterketten. Um einundzwanzig Uhr ist alles fertig. Die Lichter gehen an. Die Lindenstraße sieht aus wie ein Märchen."],["Mia steht in der Mitte der Straße und sieht sich um. Hier ist sie vor fast einem Jahr angekommen. Mit einem schweren Koffer. Allein."],["Jetzt ist sie nicht mehr allein."],["Jonas kommt zu ihr. Er hat sein Handy in der Hand. Die Wetter-App."],["Jonas","Mia … Morgen: Sonne bis sechzehn Uhr. Danach: Gewitter möglich. Siebzig Prozent."],["Mia","Siebzig Prozent?"],["Frau Schulz","(von hinten) Dann feiern wir bis sechzehn Uhr. Und danach drinnen. Ich habe schon schlimmere Feste erlebt. Neunzehnhundertachtundsiebzig war Hagel!"]],"q":["Wohin kommen die Tische? Wohin kommen die Bänke? Warum?","Wer spielt in der Band „Die Bächle-Boys“?","Was macht Mia auf der Leiter?","Richtig oder falsch? Nach dem Gewitter gehen alle nach Hause.","Und du? Beschreibe deine Straße: Was ist oben, unten, links, rechts, vorne, hinten?"],"a":["Tische: vor das Café. Bänke: nach hinten in den Hof, weil dort Schatten ist.","Finn (Schlagzeug), ein Bassist mit grünen Haaren und Frau Schulz (Klavier, drei Lieder).","She hangs coloured fairy lights from house to house.","Falsch. „Alle raus! Wir müssen alles noch einmal machen!“","Example: Links ist ein Supermarkt, rechts eine Apotheke. Oben wohnt meine Nachbarin. Hinten ist ein kleiner Park."],"w":[["hierher / dorthin","(to) here / (to) there","Die Tische kommen hierher. Nicht dorthin!"],["rauf / runter (herauf / herunter)","up / down (towards / away)","Komm herunter, vorsichtig!"],["rein / raus","in / out","Alle rein! · Alle raus!"],["hin und her","back and forth","Paul läuft hin und her."],["sperren","to close off","Die Straße ist gesperrt."],["die Laterne, die Laternen","street lamp","an die Laterne"],["aufbauen","to set up","Jetzt wird aufgebaut."],["der Schatten","shade","Dort ist Schatten."],["die Bühne, die Bühnen","stage","eine kleine Bühne"],["das Mitglied, die Mitglieder","member","Sie hat drei Mitglieder."],["die Leiter, die Leitern","ladder","oben auf einer Leiter"],["die Lichterkette, die Lichterketten","fairy lights","bunte Lichterketten"],["das Gewitter, die Gewitter","thunderstorm","Gewitter! Alle rein!"],["donnern","to thunder","Dann donnert es."],["der Regenbogen, die Regenbögen","rainbow","Über dem Schlossberg steht ein Regenbogen."]],"c":[["Es regnet in Strömen.","It's pouring.","Es regnet in Strömen."],["hinterherjagen (+ Dat.)","to chase after","Paul jagt einem Luftballon hinterher."],["wie ein Märchen","like a fairy tale","wie ein Märchen"],["sich umsehen","to look around","Mia sieht sich um."]],"x":[["anmachen","to switch on",""],["ausmachen","to switch off",""]],"g":["Ortsadverbien und hin/her",["Where? oben, unten, vorne, hinten, links, rechts, drinnen, draußen, hier, dort.","hin = away from the speaker · her = towards the speaker: Komm her! · Geh hin!","Wohin? → dorthin · Woher / Wohin (to me)? → hierher.","In speech, short forms are common: rauf, runter, rein, raus (instead of herauf/hinauf, herunter/hinunter, herein/hinein, heraus/hinaus).","Beispiele: Die Tische kommen hierher, nicht dorthin! · Alle rein! · Komm herunter!"]]},{"n":90,"t":"Wiederholung: Ein Sommerabend","l":"A2","review":true,"p":[["Freitag, 29. August, dreiundzwanzig Uhr"],["Die Lichterketten leuchten vor meinem Fenster. Morgen ist das Straßenfest. Jonas schläft schon, weil er um drei Uhr aufstehen muss. Brot backen. Für zweihundert Gäste."],["Was für ein Sommer. Ich schreibe alles auf, weil ich nichts vergessen will."],["Im Juni haben Herr Brandt und Fátima geheiratet. Rainer und Fátima, muss ich jetzt sagen. Fátima hat ein rotes Kleid getragen, und ich war ihre Trauzeugin. Ich habe eine Rede gehalten. Auf Deutsch! Vor achtzig Leuten. Ich habe Herrn Brandt gedankt, weil er mir immer zugehört hat. Er hat geweint. Ganz leise, aber ich habe es gesehen."],["Rui war eine Woche hier. Er hat Jonas' Anzug getragen und den ganzen Abend mit Lea getanzt. Jetzt schreiben sie sich jeden Tag. Mama ist sehr stolz auf ihr Bächle."],["Wir haben einen neuen Nachbarn. Finn, einen Studenten. Er spielt Schlagzeug. Zuerst wollte Frau Schulz einen Polizisten rufen. Jetzt spielt sie mit ihm in einer Band. Morgen ist ihr erster Auftritt. Sie ist so nervös, dass sie heute dreimal geübt hat."],["Und das Café! Am ersten Juli hat Jonas die Schlüssel bekommen – vierundzwanzig Minuten zu spät, natürlich. Im Juli haben wir jeden Abend renoviert. Die Wände sind jetzt hellblau, wie die Fliese aus Porto. Am ersten August haben wir eröffnet."],["Dann die schlimmen Tage. Fast keine Gäste. Jonas wollte schon aufgeben. Alle haben uns Rat gegeben: Ihr solltet dies, ihr solltet das. Aber das Problem war ganz einfach: Das alte Schild „Zu vermieten“ hing noch im Fenster! Paul hat es gefunden. Ein siebenjähriger Junge."],["Jetzt backt Jonas jeden Morgen Brot. Mit Frau Schulz und mit Heinrichs Rezepten. Und nach dem Artikel in der Zeitung gibt es jeden Sonntag eine Schlange vor der Tür. Die Leute nennen das Heinrich-Brot schon „das beste Brot im Viertel“."],["Es gibt auch eine Neuigkeit für mich. Herr Brandt hat mich für die Prüfung angemeldet. Goethe-Zertifikat A2. Am zwölften September. Und am dreizehnten September fliegen Jonas und ich nach Porto. Zum ersten Mal zusammen. Zwei Wochen Urlaub."],["Ich bin nervös wegen der Prüfung. Aber Herr Brandt sagt: „Sie haben ein ganzes Jahr lang geübt. Im Leben, nicht nur im Kurs.“"],["Morgen gibt es Sonne bis sechzehn Uhr. Danach vielleicht ein Gewitter. Aber Frau Schulz hat gesagt, dass sie schon schlimmere Feste erlebt hat. Ich glaube ihr."]],"q":["dies- / jed-: ___ Kleid nehme ich (dies-). ___ Braut trägt, was sie will (jed-).","n-Deklination: Frau Schulz wollte einen ___ rufen (Polizist). Ich spreche mit dem ___ (Student).","Pronomen-Reihenfolge: Ich leihe dir den Anzug. → Ich leihe ___ ___.","Formelles Datum: Freiburg, ___ 18.06. Die Erlaubnis gilt ___ ___ 1. August.","Verb mit Dativ: Alle gratulieren ___ Brautpaar. Ich danke ___ (Sie).","Nebensatz: Ich bin zu spät, weil ich Jonas wecken ___ (müssen, Präteritum).","sollte: Du ___ nicht in Panik geraten.","Wortbildung: freundlich → die ___ · eröffnen → die ___","hin / her: Die Tische kommen ___ (zu mir). Alle ___! (ins Haus)","Was war das Problem des Cafés?"],"a":["Dieses · Jede. (story 81)","Polizisten · Studenten. n-declension: -en (story 82)","ihn dir. Two pronouns: accusative before dative (story 83).","den · ab dem. (story 84)","dem · Ihnen. (story 85)","musste. Conjugated verb at the very end (story 86).","solltest. (story 87)","die Freundlichkeit · die Eröffnung. (story 88)","hierher · rein. (story 89)","The old „Zu vermieten“ sign was still in the window. (story 87)"],"w":[],"c":[],"x":[],"g":["Wiederholung",["dieser, jeder, welcher (story 81) · n-declension (story 82) · pronoun order (story 83).","Formal letters and dates (story 84) · dative verbs (story 85).","Subordinate clauses with modal verb or Perfekt (story 86) · sollte (story 87).","Word formation -ung, -heit, -keit, -in, un-, -los (story 88) · local adverbs, hin/her (story 89).","Beispiele: Ich habe Herrn Brandt gedankt, weil er mir immer zugehört hat. · Ihr solltet dies, ihr solltet das."]],"exam":{"task":"Im Forum ist die Frage: „Kleines Café oder große Kette – wo trinkt ihr lieber Kaffee?“ Schreiben Sie Ihre Meinung.","points":["Was ist Ihre Meinung?","Geben Sie zwei Gründe (weil, denn).","Erzählen Sie ein Beispiel aus Ihrem Leben."],"words":50,"en":"Forum opinion: small café or big chain; two reasons; one example."}},{"n":91,"t":"Was für Musik?","l":"A2","review":false,"p":[["Samstag, vierzehn Uhr. Die Sonne scheint. Die Lindenstraße ist voller Menschen. Überall stehen Tische mit Essen: Fátimas Pastéis, Elifs Börek, Toms Pierogi, Ingrids Zwetschgenkuchen und natürlich Jonas' Heinrich-Brot."],["Ein kleines Mädchen steht vor dem Kuchentisch."],["Mädchen","Was für Kuchen gibt es?"],["Ingrid","Es gibt Zwetschgenkuchen, Käsekuchen und Schokoladenkuchen. Welchen möchtest du?"],["Mädchen","Den mit Schokolade! Und was für einen Kuchen isst die Katze?"],["Alle sehen zu Felix. Er sitzt auf dem Tisch neben dem Käsekuchen. Er sieht nicht unschuldig aus."],["Um fünfzehn Uhr steigt Finn auf die kleine Bühne. Er nimmt das Mikrofon."],["Finn","Hallo Lindenstraße! Wir sind die Bächle-Boys! Was für Musik wollt ihr hören?"],["Tom","Rock!"],["Elif","Pop! Etwas zum Tanzen!"],["Herr Krause","Was für eine Frage! Schlager, natürlich. Ordentliche deutsche Musik."],["Paul","Das Lied vom Kater!"],["Finn lacht."],["Finn","Okay. Wir spielen von allem etwas. Aber zuerst: eine Überraschung. Unsere Pianistin!"],["Frau Schulz rollt mit dem Rollator auf die Bühne. Jonas hilft ihr auf den Klavierhocker. Sie trägt eine elegante blaue Bluse und Lippenstift. Mia hat sie noch nie mit Lippenstift gesehen."],["Frau Schulz","Guten Tag. Ich bin seit fünfzig Jahren in dieser Straße. Das erste Lied ist für meinen Mann Heinrich. Es war sein Lieblingslied. Welches Lied, verrate ich nicht. Wer es kennt, darf mitsingen."],["Sie spielt. Am Anfang langsam, dann sicherer. Ein altes Lied aus den Sechzigerjahren. Viele ältere Leute in der Straße kennen es. Sie singen leise mit. Herr Krause singt auch. Er singt laut und falsch, aber mit geschlossenen Augen."],["Als das Lied zu Ende ist, ist es eine Sekunde ganz still. Dann klatschen alle. Laut und lange. Frau Schulz sieht auf die Tasten. Ihre Hände zittern ein bisschen."],["Mia","Was für eine Frau."],["Jonas","Was für ein Tag."],["Dann spielen die Bächle-Boys Rock, Pop und sogar einen Schlager für Herrn Krause. Die Leute tanzen auf der Straße. Klaus tanzt mit Ingrid. Rainer tanzt mit Fátima. Tom tanzt mit Bruno. Elif tanzt mit allen."],["Um sechzehn Uhr sehen alle zum Himmel. Ein paar Wolken. Aber kein Gewitter."],["Um siebzehn Uhr","immer noch kein Gewitter."],["Um achtzehn Uhr gehen die Lichterketten an. Die Wetter-App hatte unrecht."],["Frau Schulz","Was für ein Glück! Neunzehnhundertachtundsiebzig hatten wir nicht so viel Glück."],["Um Mitternacht ist das Fest vorbei. Die Straße ist leer, aber voller Konfetti. Mia trägt Teller ins Café. Frau Schulz sitzt noch draußen auf einer Bank. Sie sieht müde aus, aber sehr zufrieden."],["Frau Schulz","Frau Costa. Mia. Darf ich Sie Mia nennen?"],["Mia","Natürlich!"],["Frau Schulz","Kommen Sie morgen Nachmittag zu mir. Zum Kaffee. Ich möchte Ihnen meine Geschichte erzählen. Die ganze Geschichte. Ich glaube, es ist Zeit. Und dann möchte ich Sie um etwas bitten."]],"q":["Was für Kuchen gibt es?","Was für Musik wollen die Leute hören? (Nenne drei Wünsche.)","Für wen spielt Frau Schulz das erste Lied?","Richtig oder falsch? Um sechzehn Uhr kommt ein starkes Gewitter.","Und du? Was für Musik hörst du gern? Welches Lied magst du am liebsten?"],"a":["Zwetschgenkuchen, Käsekuchen und Schokoladenkuchen.","Rock (Tom), Pop (Elif), Schlager (Herr Krause), das Lied vom Kater (Paul).","Für ihren Mann Heinrich – es war sein Lieblingslied.","Falsch. „Ein paar Wolken. Aber kein Gewitter.“","Example: Ich höre gern Jazz. Am liebsten mag ich ein altes Lied von meiner Oma."],"w":[["was für ein / was für","what kind of","Was für Musik wollt ihr hören?"],["das Mädchen, die Mädchen","girl","Ein kleines Mädchen steht vor dem Tisch."],["der Zwetschgenkuchen","plum cake","Ingrids Zwetschgenkuchen"],["das Mikrofon, die Mikrofone","microphone","Er nimmt das Mikrofon."],["der Schlager, die Schlager","German pop song","Schlager, natürlich."],["die Pianistin, die Pianistinnen","pianist (f)","Unsere Pianistin!"],["der Lippenstift, die Lippenstifte","lipstick","Sie trägt Lippenstift."],["das Lieblingslied","favourite song","Es war sein Lieblingslied."],["mitsingen","to sing along","Wer es kennt, darf mitsingen."],["sicher","sure, confident","dann sicherer"],["die Taste, die Tasten","key (piano)","Frau Schulz sieht auf die Tasten."],["die Wolke, die Wolken","cloud","Ein paar Wolken."],["unrecht haben","to be wrong","Die Wetter-App hatte unrecht."],["das Konfetti","confetti","voller Konfetti"],["bitten um","to ask for","Ich möchte Sie um etwas bitten."]],"c":[["Was für eine Frage!","What a question!","Was für eine Frage!"],["Was für ein Glück!","What luck!","Was für ein Glück!"],["von allem etwas","a bit of everything","Wir spielen von allem etwas."],["zu Ende sein","to be over","Als das Lied zu Ende ist …"]],"x":[["aufladen","to charge",""],["Das Internet funktioniert nicht.","the internet is not working.",""]],"g":["was für ein oder welcher?",["Was für ein …? asks for the kind or type (open choice): Was für Musik wollt ihr hören? – Rock.","Welcher …? asks for one from a known group: Es gibt drei Kuchen. Welchen möchtest du? – Den mit Schokolade.","ein in was für ein takes the normal case: Was für einen Kuchen isst die Katze? (accusative). Plural / uncountable: was für (no ein).","Exclamations: Was für ein Tag! Was für eine Frau!","Beispiele: Was für Kuchen gibt es? · Welches Lied, verrate ich nicht."]]},{"n":92,"t":"Frau Schulz erzählt","l":"A2","review":false,"p":[["Sonntag, fünfzehn Uhr. Frau Schulz' Wohnzimmer. Auf dem Tisch stehen Kaffee, Apfelstrudel und ein dickes, altes Fotoalbum. Felix liegt auf dem Sofa. Frau Schulz erzählt. Und Mia hört zu."],["„Ich wurde 1951 in Berlin geboren. In Kreuzberg. Mein Vater war Straßenbahnfahrer, meine Mutter nähte Kleider für reiche Damen. Wir hatten wenig Geld, aber wir hatten ein Klavier. Es stand im Wohnzimmer und war das Wertvollste in unserer Wohnung."],["Mit sechs Jahren fing ich an, Klavier zu spielen. Ich übte jeden Tag. Meine Schwester Ilse hasste das, weil sie im gleichen Zimmer schlief."],["Mit zwanzig studierte ich Musik. Dann, 1973, bekam ich eine Stelle als Musiklehrerin. In Freiburg. Ich kannte niemanden hier. Die Stadt war klein und fremd, und die Leute sprachen einen Dialekt, den ich nicht verstand. Ich weinte jede Nacht. Ich wollte zurück nach Berlin."],["Ich wohnte damals in einem kleinen Zimmer in der Lindenstraße. In diesem Haus! Im dritten Stock. Ihrer alten Wohnung, Mia."],["Jeden Morgen ging ich zur Bäckerei an der Ecke. Ich kaufte immer ein Brötchen. Der junge Bäcker war groß und still. Er sagte nie viel. Aber nach einer Woche gab er mir jeden Morgen eine Brezel extra. Umsonst. Ohne ein Wort."],["Das war Heinrich."],["Nach drei Monaten fragte er mich endlich, ob ich mit ihm ins Kino gehen möchte. Wir sahen einen sehr schlechten Film. Ich erinnere mich an nichts. Nur an seine Hand. 1975 heirateten wir. 1977 kam Michael auf die Welt. Später kauften wir dieses Haus. Wir hatten kein Geld, aber die Bank glaubte an Heinrichs Brot."],["In den Siebzigerjahren machten wir jeden Sommer ein Straßenfest. Heinrich backte, ich spielte Klavier, die Kinder tanzten. Gestern war es wieder genau wie damals."],["Heinrich starb vor sechs Jahren. An einem Dienstag im Winter. Morgens um vier, in der Backstube. Er hatte einen Herzinfarkt. Als ich ihn fand, lag ein frisches Brot im Ofen."],["Danach wollte ich nicht mehr spielen. Sechs Jahre lang. Das Klavier war verstimmt. Ich auch."],["Und dann kamen Sie. Mit Ihrem großen Koffer. Ganz allein, ohne Deutsch, ohne Bett. Genau wie ich, 1973. Und Felix brachte Ihnen jeden Morgen eine Brezel. Ohne ein Wort.“"],["Frau Schulz macht eine Pause. Mia kann nichts sagen. Ihre Wangen sind nass."],["Frau Schulz","Ich habe Ihnen das erzählt, weil ich Sie um etwas bitten möchte. Michael möchte, dass ich im Winter zu ihm nach Hamburg komme. Von Oktober bis März. Wegen des Eises. Wegen der Stufen. Ich habe lange nachgedacht. Ich werde gehen. Nur im Winter."],["Mia","Und … Felix?"],["Frau Schulz","Felix hasst Regen. Und Hamburg ist sehr nass. Würden Sie und Jonas sich im Winter um ihn kümmern? Und um das Haus?"],["Felix hebt den Kopf. Er sieht von Frau Schulz zu Mia. Als ob er alles verstanden hat."],["Mia","Ich muss mit Jonas sprechen. Aber … ich glaube, ich weiß die Antwort schon."]],"q":["Wo und wann wurde Frau Schulz geboren?","Warum kam sie 1973 nach Freiburg?","Was gab Heinrich ihr jeden Morgen?","Richtig oder falsch? Frau Schulz will für immer nach Hamburg ziehen.","Und du? Erzähl im Präteritum: Wo wurdest du geboren? Wo wohntest du als Kind? (Ich wurde … geboren. Ich wohnte …)"],"a":["1951 in Berlin, in Kreuzberg. „Ich wurde 1951 in Berlin geboren.“","She got a job as a music teacher. „1973 bekam ich eine Stelle als Musiklehrerin.“","Eine Brezel extra, umsonst, ohne ein Wort. „Nach einer Woche gab er mir jeden Morgen eine Brezel extra.“","Falsch. „Ich werde gehen. Nur im Winter.“","Example: Ich wurde 1990 in Leeds geboren. Als Kind wohnte ich in einem kleinen Haus."],"w":[["wurde (werden, Präteritum)","became, was","Ich wurde 1951 geboren."],["ging / kam / sah / gab / fand / lag","went / came / saw / gave / found / lay","Jeden Morgen ging ich zur Bäckerei."],["fing an / starb / bekam","started / died / got","Heinrich starb vor sechs Jahren."],["übte / kaufte / heiratete","practised / bought / married","1975 heirateten wir."],["der Straßenbahnfahrer","tram driver","Mein Vater war Straßenbahnfahrer."],["die Stelle, die Stellen","job, position","eine Stelle als Musiklehrerin"],["der Dialekt, die Dialekte","dialect","einen Dialekt, den ich nicht verstand"],["umsonst","free (of charge)","Umsonst. Ohne ein Wort."],["auf die Welt kommen","to be born","1977 kam Michael auf die Welt."],["die Siebzigerjahre","the seventies","In den Siebzigerjahren"],["der Herzinfarkt, die Herzinfarkte","heart attack","Er hatte einen Herzinfarkt."],["sich erinnern an","to remember","Ich erinnere mich an nichts."],["als (+ Präteritum)","when (once, in the past)","Als ich ihn fand, …"],["sich kümmern um","to take care of","sich um ihn kümmern"],["als ob","as if","Als ob er alles verstanden hat."]],"c":[["eine Pause machen","to pause","Frau Schulz macht eine Pause."],["das Wertvollste","the most valuable thing","das Wertvollste in unserer Wohnung"],["genau wie damals","just like back then","Gestern war es genau wie damals."],["von Oktober bis März","from October to March","Von Oktober bis März."]],"x":[["Mein Akku ist leer.","my battery is dead.",""]],"g":["Präteritum (zum Lesen)",["In written stories, novels and biographies, German uses the Präteritum. In speech, people use the Perfekt (except war, hatte, modal verbs).","Regular verbs: stem + -te: üben → übte, kaufen → kaufte, heiraten → heiratete.","Irregular verbs change the stem, no ending for ich/er: gehen → ging, kommen → kam, sehen → sah, geben → gab, finden → fand, sterben → starb, werden → wurde.","At A2, you mainly need to recognise these forms when you read.","Beispiele: Jeden Morgen ging ich zur Bäckerei. · Nach einer Woche gab er mir eine Brezel."]]},{"n":93,"t":"Elif hat Prüfungsangst","l":"A2","review":false,"p":[["Mittwoch, dreiundzwanzig Uhr. Es klingelt. Vor der Tür steht Elif. Ohne Lippenstift, ohne Lächeln, mit roten Augen. In der Hand hat sie einen riesigen Stapel Bücher."],["Elif","Kann ich heute bei euch schlafen? Ich kann allein nicht lernen. Ich kann allein nicht schlafen. Ich kann gar nichts mehr."],["Mia macht Tee. Elif sitzt auf dem grünen Sofa und weint."],["Elif","Am Montag ist das Physikum. Die große Prüfung nach zwei Jahren Medizin. Wenn ich durchfalle, verliere ich mein Stipendium. Und wenn ich mein Stipendium verliere, muss ich zurück in die Türkei."],["Mia","Elif. Du lernst seit Monaten jeden Tag. Du bist die Beste in deinem Semester."],["Elif","Dass ich viel gelernt habe, weiß ich. Aber ich habe alles vergessen! Alles! Gestern wusste ich nicht einmal mehr, wie viele Knochen eine Hand hat."],["Jonas","(aus der Küche) Siebenundzwanzig."],["Elif und Mia sehen ihn an."],["Jonas","Was? Ich habe deine Karteikarten gelesen. Sie lagen auf dem Tisch."],["Elif lacht. Zum ersten Mal heute."],["In den nächsten Tagen lernt Elif bei Mia und Jonas. Jeden Morgen um sechs Uhr sitzt sie im Café Bächle, an einem Tisch am Fenster. Jonas bringt ihr Kaffee und Heinrich-Brot. Tom fragt sie in seinen Pausen ab. Er versteht kein Wort, aber er liest die Fragen laut vor."],["Tom","Was ist die … Mi-to-chon-dri-um?"],["Elif","Das Kraftwerk der Zelle!"],["Tom","Keine Ahnung, ob das stimmt. Aber es klingt gut."],["Und Frau Schulz? Frau Schulz kommt am Samstag mit einem Rat."],["Frau Schulz","Als ich jung war, hatte ich vor jedem Konzert Lampenfieber. Mein Lehrer hat mir etwas beigebracht. Wenn du nervös bist, atmest du vier Sekunden ein. Dann hältst du die Luft vier Sekunden an. Dann atmest du vier Sekunden aus. Viermal. Weil dein Körper dann ruhig wird, wird auch dein Kopf ruhig."],["Elif probiert es. Ein. Halten. Aus. Viermal."],["Elif","Es funktioniert! Ein bisschen."],["Montag, sieben Uhr. Alle stehen vor dem Café und winken. Elif fährt mit dem Fahrrad zur Uni. In ihrem Rucksack sind eine Brezel, eine Flasche Wasser und ein kleiner Zettel von Paul: Du schafst das! Mit einem Fehler. Und einem Herz."],["Um sechzehn Uhr klingelt Mias Handy. Sie ist bei der Arbeit, mitten in einer Besprechung."],["Elif","Mia! Mia! Ich habe bestanden! Mit einer Zwei!"],["Mia schreit. Sabine, Max, Kemal und Jana sehen sie an. Dann klatschen alle mit, obwohl sie nicht wissen, warum."],["Am Abend feiern sie im Café. Elif tanzt auf einem Stuhl."],["Elif","Und jetzt du, Mia! Am Freitag ist deine Prüfung!"],["Mia wird blass. Freitag. A2. Vier Teile: Hören, Lesen, Schreiben, Sprechen."],["Mia","Wenn ich durchfalle, …"],["Elif","Wenn du durchfällst, esse ich Felix' Futter. Eine Woche lang. Atmen, Mia! Vier Sekunden ein!"]],"q":["Was passiert, wenn Elif durchfällt?","Wie hilft Tom Elif beim Lernen?","Was ist der Rat von Frau Schulz?","Richtig oder falsch? Elif hat das Physikum nicht bestanden.","Und du? Was machst du, wenn du nervös bist? Beginne mit dem Nebensatz: Wenn ich nervös bin, …"],"a":["She loses her scholarship and must go back to Turkey. „Wenn ich durchfalle, verliere ich mein Stipendium.“","He reads her questions aloud in his breaks, although he understands nothing.","Breathe in for 4 seconds, hold for 4, breathe out for 4 – four times.","Falsch. „Ich habe bestanden! Mit einer Zwei!“","Example: Wenn ich nervös bin, trinke ich einen Tee und gehe spazieren."],"w":[["die Prüfungsangst","exam nerves","Elif hat Prüfungsangst."],["der Stapel, die Stapel","pile","einen riesigen Stapel Bücher"],["durchfallen (fällt durch)","to fail (an exam)","Wenn ich durchfalle, …"],["das Stipendium, die Stipendien","scholarship","Ich verliere mein Stipendium."],["das Semester, die Semester","semester","die Beste in deinem Semester"],["der Knochen, die Knochen","bone","wie viele Knochen eine Hand hat"],["die Karteikarte, die Karteikarten","flashcard","Ich habe deine Karteikarten gelesen."],["abfragen","to test, quiz sb.","Tom fragt sie ab."],["das Kraftwerk, die Kraftwerke","power station","das Kraftwerk der Zelle"],["die Zelle, die Zellen","cell","das Kraftwerk der Zelle"],["das Lampenfieber","stage fright","Ich hatte Lampenfieber."],["einatmen / ausatmen","to breathe in / out","Du atmest vier Sekunden ein."],["der Körper, die Körper","body","Weil dein Körper ruhig wird …"],["das Futter","(animal) food","esse ich Felix' Futter"],["mitten in","in the middle of","mitten in einer Besprechung"]],"c":[["Ich kann gar nichts mehr.","I can't do anything any more.","Ich kann gar nichts mehr."],["die Luft anhalten","to hold one's breath","Dann hältst du die Luft an."],["Du schaffst das!","You can do it!","Du schaffst das!"],["mit einer Zwei","with a 2 (German grade: good)","Mit einer Zwei!"]],"x":[["außerdem","besides, also",""],["die Meinung, die Meinungen","opinion",""]],"g":["der Nebensatz am Satzanfang",["A subordinate clause can come first. Then it takes position 1, and the main clause starts with the verb: verb, verb.","Ich verliere mein Stipendium, wenn ich durchfalle. → Wenn ich durchfalle, verliere ich mein Stipendium.","Works with wenn, weil, dass, ob, als, obwohl: Dass ich viel gelernt habe, weiß ich.","The comma always separates the two clauses.","Beispiele: Weil dein Körper ruhig wird, wird auch dein Kopf ruhig. · Wenn du nervös bist, atmest du vier Sekunden ein."]]},{"n":94,"t":"Felix braucht ein Zuhause","l":"A2","review":false,"p":[["Dienstagabend. Mia und Jonas klopfen bei Frau Schulz. Sie haben die Antwort. Eigentlich hatten sie sie schon am Sonntag. Aber man muss so eine Antwort richtig sagen."],["Jonas","Frau Schulz, wir kümmern uns gern um Felix. Und um das Haus. Den ganzen Winter."],["Mia","Und nicht nur im Winter. Wann immer Sie uns brauchen."],["Frau Schulz sagt nichts. Sie nickt nur. Dann holt sie einen Ordner. Natürlich einen Ordner."],["Frau Schulz","Das ist die Anleitung für Felix. Ich habe sie gestern geschrieben. Zwölf Seiten."],["Mia liest die erste Seite:"],["Felix frisst morgens um sieben und abends um sechs. Nie um 6:05. Er beschwert sich sofort."],["Er mag keine Fischdosen. Nur Huhn. Und Wurst vom Bäcker."],["Er interessiert sich für alles, was glänzt. Löffel, Schlüssel, Ringe. Passen Sie auf den Verlobungsring auf!"],["Er hat Angst vor dem Staubsauger und vor Bruno. Aber er zeigt es nicht."],["Er freut sich jeden Abend auf eine Geschichte. Ich lese ihm vor. Er mag Krimis."],["Jonas","Sie lesen ihm Krimis vor?"],["Frau Schulz","Seit vierzehn Jahren. Er schläft dabei ein. Am liebsten bei Agatha Christie."],["Am Mittwoch probieren sie es aus. Eine Nacht. Felix zieht zu Mia und Jonas, mit seinem Korb, seiner Decke und dem silbernen Löffel. Mia liest ihm einen Krimi vor. Auf Deutsch. Sehr langsam. Felix sieht sie an, als ob er sagen will: Deine Aussprache ist schrecklich."],["Um drei Uhr nachts wacht Mia auf. Der Korb ist leer. Die Wohnungstür ist offen. Natürlich – Felix kann Türen öffnen."],["Mia geht die Treppe hinunter. Vor Frau Schulz' Tür sitzt Felix. Er kratzt leise an der Tür. Miau. Miau."],["Die Tür geht auf. Frau Schulz steht im Morgenmantel da. Sie sieht Felix. Dann sieht sie Mia."],["Frau Schulz","Er muss sich an das neue Zuhause gewöhnen. Das braucht Zeit."],["Mia","Und Sie? Gewöhnen Sie sich an den Gedanken?"],["Frau Schulz","Nein. Noch nicht. Ich denke jeden Tag daran. Ich erinnere mich an jeden Winter hier. Fünfzig Winter. Aber ich muss vernünftig sein. Die Stufen, das Eis. Ich will mich nicht noch einmal über eine gebrochene Hüfte ärgern."],["Sie nimmt Felix auf den Arm. Nur für einen Moment. Dann gibt sie ihn Mia."],["Frau Schulz","Gehen Sie. Und lesen Sie ihm das zweite Kapitel vor. Dann schläft er ein. Versprochen."],["Mia liest das zweite Kapitel. Felix schläft ein. Auf ihrem Bauch."],["Am nächsten Morgen kommt Frau Schulz mit dem Rollator zur Rampe. Sie gibt Mia einen kleinen weißen Umschlag. Darauf steht in schöner, alter Handschrift: Für Mia."],["Frau Schulz","Öffnen Sie ihn erst nach Ihrer Prüfung. Nicht vorher. Nicht heimlich. Ich merke das."],["Mia","Was ist darin?"],["Frau Schulz","Etwas, das Sie lesen sollen, wenn Sie bestanden haben. Und Sie werden bestehen. Daran habe ich keinen Zweifel."],["Mia legt den Umschlag in ihre Tasche. In die braune Handtasche. Diesmal macht sie den Reißverschluss zu."]],"q":["Was ist die Antwort von Mia und Jonas?","Was steht in der „Anleitung für Felix“? (Nenne drei Dinge.)","Was passiert um drei Uhr nachts?","Richtig oder falsch? Mia darf den Umschlag sofort öffnen.","Und du? Woran musstest du dich in einer neuen Situation gewöhnen? Worauf freust du dich jeden Tag?"],"a":["They will take care of Felix and the house, all winter – and whenever she needs them. „Wir kümmern uns gern um Felix.“","E.g. eats at 7 and 6; no fish, only chicken; interested in shiny things; afraid of the hoover; loves a crime story every evening.","Felix opens the door and goes down to Frau Schulz's door. „Vor Frau Schulz' Tür sitzt Felix.“","Falsch. „Öffnen Sie ihn erst nach Ihrer Prüfung.“","Example: Ich musste mich an das deutsche Essen gewöhnen. Ich freue mich jeden Tag auf meinen Kaffee am Morgen."],"w":[["sich kümmern um","to look after","Wir kümmern uns gern um Felix."],["sich gewöhnen an","to get used to","Er muss sich an das neue Zuhause gewöhnen."],["sich erinnern an","to remember","Ich erinnere mich an jeden Winter hier."],["sich beschweren (über)","to complain (about)","Er beschwert sich sofort."],["sich freuen auf","to look forward to","Er freut sich jeden Abend auf eine Geschichte."],["sich interessieren für","to be interested in","Er interessiert sich für alles, was glänzt."],["der Verlobungsring, die Verlobungsringe","engagement ring","Passen Sie auf den Verlobungsring auf!"],["der Staubsauger, die Staubsauger","hoover","Angst vor dem Staubsauger"],["die Aussprache","pronunciation","Deine Aussprache ist schrecklich."],["kratzen","to scratch","Er kratzt leise an der Tür."],["der Gedanke, die Gedanken","thought","an den Gedanken"],["vernünftig","sensible, reasonable","Ich muss vernünftig sein."],["das Kapitel, die Kapitel","chapter","das zweite Kapitel"],["der Zweifel, die Zweifel","doubt","Daran habe ich keinen Zweifel."],["der Reißverschluss, die Reißverschlüsse","zip","Sie macht den Reißverschluss zu."]],"c":[["wann immer …","whenever …","Wann immer Sie uns brauchen."],["etwas ausprobieren","to try sth. out","Am Mittwoch probieren sie es aus."],["Das braucht Zeit.","That takes time.","Das braucht Zeit."],["Ich merke das.","I'll notice.","Nicht heimlich. Ich merke das."]],"x":[["der Vorteil, die Vorteile","advantage",""],["der Nachteil, die Nachteile","disadvantage",""]],"g":["reflexive Verben mit Präposition",["Many reflexive verbs have a fixed preposition: sich kümmern um, sich gewöhnen an, sich erinnern an, sich freuen auf/über, sich interessieren für, sich ärgern über, sich beschweren über.","Reflexive pronoun after the verb, preposition before the object: Wir kümmern uns um Felix.","With things, use da-/wo-: Ich denke jeden Tag daran. · Woran erinnern Sie sich?","Learn each verb as a block: sich + verb + preposition + case.","Beispiele: Er muss sich an das neue Zuhause gewöhnen. · Ich erinnere mich an jeden Winter hier."]]},{"n":95,"t":"Urlaub in Portugal?","l":"A2","review":false,"p":[["Donnerstagabend. Café Bächle ist schon geschlossen, aber drinnen brennt noch Licht. Alle sitzen um den großen Tisch: Elif, Tom, Finn, Lena, Rainer und Fátima, Herr Krause. Und Mia, die eigentlich lernen sollte. Morgen ist ihre Prüfung."],["Elif","Keine Prüfung heute Abend! Heute reden wir über Urlaub. Das ist gut für die Nerven."],["Jonas","Also: Wer fährt wohin?"],["Elif","Ich fliege nächste Woche in die Türkei. Nach İzmir. Zu meiner Familie. Drei Wochen nur Meer, Sonne und das Essen meiner Mutter. Meine Mutter weiß noch nicht, dass ich das Physikum bestanden habe. Ich will es ihr persönlich sagen."],["Tom","Ich fahre mit Bruno nach Polen. Zu meiner Oma nach Krakau. Mit dem Fernbus, natürlich. Ich bin der Fahrer."],["Finn","Meine Band spielt in der Schweiz. In Basel und in Zürich. Unsere erste Tournee! Drei Konzerte. Frau Schulz kommt leider nicht mit."],["Lena","Wir fahren mit dem Wohnwagen in die Niederlande. Ans Meer. Paul will unbedingt Pommes mit Mayonnaise essen. Zum Frühstück."],["Fátima: Und Rainer und ich fliegen in die USA. Nach New York."],["Alle sehen Herrn Brandt an."],["Mia","In die USA? Sie, Herr Brandt?"],["Rainer","Rainer. Und ja. Ich war noch nie außerhalb von Europa. Ich war in Frankreich, in Italien, in Österreich, in der Schweiz. Aber nie in Amerika. Fátima sagt, ich bin zu langweilig. Jetzt will ich das Gegenteil beweisen."],["Herr Krause","Ich fahre nie in Urlaub. Urlaub ist unordentlich."],["Elif","Herr Krause!"],["Herr Krause","Aber dieses Jahr fahre ich nach Italien. In die Toskana. Meine Frau Hanna wollte immer dorthin. Wir sind nie gefahren. Jetzt fahre ich. Für sie."],["Es wird still am Tisch. Dann hebt Jonas sein Glas."],["Jonas","Auf Hanna!"],["Alle","Auf Hanna!"],["Lena","Und ihr beiden? Mia, Jonas?"],["Mia","Wir fliegen nach Portugal. Am Samstag. Nach Porto. Zwei Wochen."],["Jonas","Ich war noch nie in Portugal. Ich war überhaupt selten im Ausland. Nur in der Schweiz, in Frankreich und einmal in den Niederlanden. Und ich spreche nur fünf Wörter Portugiesisch."],["Fátima: Sechs! Ich habe dir gestern noch eins beigebracht: „saudade“."],["Jonas","Ah ja. Das heißt … Sehnsucht? Heimweh? Etwas, das man nicht übersetzen kann."],["In diesem Moment klingelt Mias Handy. Mama. Mit Video."],["Mama","(auf Portugiesisch) Mia! Ich habe eine Überraschung vorbereitet. Für Samstagabend. Ein Fest. Mit der ganzen Familie. Alle Tanten, alle Onkel, alle Cousins. Und die Nachbarn. Und …"],["Mia","Mama, wie viele Leute?"],["Mama","(auf Portugiesisch) Ungefähr sechzig. Vielleicht siebzig."],["Mia übersetzt. Jonas wird blass."],["Jonas","Siebzig Portugiesen. Und ich spreche sechs Wörter."],["Elif","Das schaffst du. Atmen, Jonas! Vier Sekunden ein!"],["Aber zuerst","morgen. Neun Uhr. Goethe-Institut. Die A2-Prüfung."]],"q":["Wohin fliegt Elif? Warum will sie es ihrer Mutter persönlich sagen?","Wohin fährt Tom? Wie?","Warum fährt Herr Krause in die Toskana?","Richtig oder falsch? Jonas war schon oft in Portugal.","Und du? In welche Länder bist du schon gereist? Wohin möchtest du einmal fahren? (in die …, nach …)"],"a":["In die Türkei, nach İzmir. She wants to tell her mother in person that she passed the Physikum.","Nach Polen, nach Krakau – mit dem Fernbus (er ist der Fahrer).","His late wife Hanna always wanted to go there. „Jetzt fahre ich. Für sie.“","Falsch. „Ich war noch nie in Portugal.“","Example: Ich war schon in Spanien, in der Türkei und in den USA. Ich möchte einmal in die Schweiz fahren."],"w":[["die Türkei / die Schweiz","Turkey / Switzerland","Ich fliege in die Türkei."],["die Niederlande (Plural) / die USA (Plural)","the Netherlands / the USA","Wir fahren in die Niederlande."],["Österreich / Frankreich / Italien","Austria / France / Italy","Ich war in Frankreich, in Italien …"],["die Nerven (Plural)","nerves","Das ist gut für die Nerven."],["die Tournee, die Tourneen","tour (concerts)","Unsere erste Tournee!"],["der Wohnwagen, die Wohnwagen","caravan","mit dem Wohnwagen"],["die Pommes (Plural)","chips, fries","Pommes mit Mayonnaise"],["außerhalb von","outside of","Ich war noch nie außerhalb von Europa."],["das Gegenteil","opposite","das Gegenteil beweisen"],["beweisen","to prove","Jetzt will ich das Gegenteil beweisen."],["unordentlich","untidy","Urlaub ist unordentlich."],["das Ausland","abroad","selten im Ausland"],["die Sehnsucht","longing","Das heißt Sehnsucht?"],["vorbereiten","to prepare","Ich habe eine Überraschung vorbereitet."],["der Cousin / die Cousine","cousin","alle Cousins"]],"c":[["Wer fährt wohin?","Who's going where?","Also: Wer fährt wohin?"],["in Urlaub fahren","to go on holiday","Ich fahre nie in Urlaub."],["Auf …!","To …! (toast)","Auf Hanna!"],["noch nie","never (before)","Ich war noch nie in Portugal."]],"x":[["Ich finde, dass …","I think that …",""],["Meiner Meinung nach …","in my opinion …",""]],"g":["Länder mit Artikel",["Most countries have no article: Deutschland, Portugal, Polen, Italien → nach Portugal (where to) · in Portugal (where).","Some countries have an article – then use in + article:","feminine: die Türkei, die Schweiz → Wohin? in die Türkei · Wo? in der Schweiz · Woher? aus der Türkei.","plural: die USA, die Niederlande → in die USA · in den Niederlanden. (Also masculine: der Iran → in den Iran.)","Beispiele: Ich fliege in die Türkei. · Ich war schon in der Schweiz, aber nie in den USA."]]},{"n":96,"t":"Die Prüfung","l":"A2","review":false,"p":[["Freitag, acht Uhr fünfundvierzig. Mia steht vor dem Goethe-Institut. Sie hat zwei Kugelschreiber, ihren Pass, eine Flasche Wasser und eine Brezel von Jonas dabei. In ihrer Jackentasche ist ein Zettel von Paul: Du schaffst das! Diesmal ohne Fehler. Lena hat geholfen."],["Im Prüfungsraum sitzen zwölf Leute an einzelnen Tischen. Eine Frau aus Syrien, zwei Studenten aus China, ein älterer Herr aus Italien. Neben Mia sitzt ein junger Mann aus Brasilien. Er ist so nervös, dass sein Bein die ganze Zeit wackelt."],["Prüferin","Guten Morgen. Wir beginnen mit dem Teil „Hören“. Sie hören jeden Text zweimal. Bitte schalten Sie Ihre Handys aus."],["Hören","Durchsagen am Bahnhof, ein Gespräch beim Arzt, eine Nachricht auf dem Anrufbeantworter. Mia lächelt. Durchsagen am Bahnhof kennt sie jetzt sehr gut. Dank des Bahnstreiks."],["Lesen","eine Anzeige für eine Wohnung, eine E-Mail von einer Firma, ein Text über ein Straßenfest. Mia muss fast lachen."],["Schreiben","Sie können am Samstag nicht zum Geburtstag Ihrer Freundin kommen. Schreiben Sie ihr eine Nachricht. Entschuldigen Sie sich, erklären Sie den Grund und machen Sie einen Vorschlag."],["Mia denkt an Jonas, der vierundzwanzig Minuten zu spät kam. Sie schreibt:"],["Liebe Anna, es tut mir sehr leid, dass ich am Samstag nicht zu deinem Geburtstag kommen kann. Ich fliege am Samstag wegen eines Familienfests früh mit meinem Freund nach Porto. Wollen wir nächste Woche zusammen in mein Lieblingscafé gehen? Ich lade dich ein! Liebe Grüße, Mia"],["Um zwölf Uhr kommt der letzte Teil: Sprechen. Mit einem Partner. Mias Partner ist der nervöse junge Mann aus Brasilien. Er heißt Pedro."],["Prüfer","Teil eins: Stellen Sie sich bitte vor. Frau Costa, beginnen Sie."],["Mia atmet ein. Vier Sekunden. Halten. Aus."],["Mia","Mein Name ist Mia Costa. Ich komme aus Porto, in Portugal. Ich bin letztes Jahr im September wegen eines neuen Lebens ganz allein mit einem großen Koffer nach Freiburg gekommen. Zuerst hatte ich kein Bett, kein Deutsch und keinen Job. Heute arbeite ich als Webdesignerin in einer Agentur. Ich wohne mit meinem Verlobten und einem Kater, der nicht mir gehört, in einer Wohnung in der Lindenstraße."],["Der Prüfer lächelt. Er schreibt etwas auf."],["Prüfer","Teil drei: Planen Sie zusammen eine Party für einen Kollegen. Wann, wo, was essen Sie, wer kauft was?"],["Pedro sieht Mia hilflos an. Mia lächelt ihm zu."],["Mia","Pedro, was meinst du: Sollen wir die Party am Freitagabend machen? Ich kenne ein sehr gutes Café in der Lindenstraße. Dort gibt es das beste Brot von Freiburg."],["Pedro","Ja … gute Idee! Und ich … ich bringe brasilianische Musik mit!"],["Sie planen. Zehn Minuten lang. Am Ende lachen beide. Und die Prüfer auch."],["Um dreizehn Uhr ist alles vorbei. Draußen, vor dem Goethe-Institut, steht Jonas. Mit einem Strauß gelber Blumen. Von Herrn Krause, natürlich."],["Jonas","Und?"],["Mia","Ich weiß es nicht. In drei Wochen kommt das Ergebnis. Aber … ich glaube, es war gut."],["Jonas","Dann darfst du jetzt den Umschlag von Frau Schulz öffnen?"],["Mia","Nein. Sie hat gesagt: nach dem Bestehen. Nicht nach der Prüfung. Ich warte."],["Morgen um fünf Uhr dreißig fährt der Bus zum Flughafen. Porto wartet."]],"q":["Welche vier Teile hat die Prüfung?","Was muss Mia im Teil „Schreiben“ schreiben?","Was müssen Mia und Pedro im Teil drei planen?","Richtig oder falsch? Mia öffnet den Umschlag direkt nach der Prüfung.","Und du? Stell dich vor wie Mia: Wann, warum, wie und wohin bist du zuletzt gereist? (Ich bin letztes Jahr wegen … mit … nach … gefahren.)"],"a":["Hören, Lesen, Schreiben, Sprechen.","A message to her friend: apologise, explain why she can't come to the birthday, and suggest something.","A party for a colleague: when, where, what to eat, who buys what.","Falsch. „Sie hat gesagt: nach dem Bestehen. Nicht nach der Prüfung. Ich warte.“","Example: Ich bin letzten Sommer wegen einer Hochzeit mit dem Zug nach Berlin gefahren."],"w":[["einzeln","individual, single","an einzelnen Tischen"],["die Prüferin / der Prüfer","examiner","Die Prüferin sagt …"],["ausschalten","to switch off","Bitte schalten Sie Ihre Handys aus."],["die Durchsage, die Durchsagen","announcement","Durchsagen am Bahnhof"],["der Anrufbeantworter, die Anrufbeantworter","answering machine","eine Nachricht auf dem Anrufbeantworter"],["dank (+ Gen./Dat.)","thanks to","Dank des Bahnstreiks."],["sich entschuldigen","to apologise","Entschuldigen Sie sich."],["der Vorschlag, die Vorschläge","suggestion","Machen Sie einen Vorschlag."],["der Verlobte, die Verlobten","fiancé","mit meinem Verlobten"],["hilflos","helpless","Pedro sieht Mia hilflos an."],["zulächeln (+ Dat.)","to smile at","Mia lächelt ihm zu."],["das Ergebnis, die Ergebnisse","result","In drei Wochen kommt das Ergebnis."],["das Bestehen","passing (an exam)","nach dem Bestehen"],["syrisch / brasilianisch / Syrien / Brasilien","Syrian / Brazilian / Syria / Brazil","eine Frau aus Syrien"],["China","China","zwei Studenten aus China"]],"c":[["Stellen Sie sich bitte vor.","Please introduce yourself.","Stellen Sie sich bitte vor."],["Was meinst du?","What do you think?","Pedro, was meinst du?"],["Ich lade dich ein!","It's on me!","Ich lade dich ein!"],["Liebe Grüße","Love / Best wishes","Liebe Grüße, Mia"]],"x":[["Ich bin dafür.","I am for it.",""]],"g":["Satzstellung – TeKaMoLo",["When a sentence has several adverbials, the usual order in the middle is:","Temporal (when?) – Kausal (why?) – Modal (how? with whom?) – Lokal (where? where to?).","Ich bin letztes Jahr (Te) wegen eines neuen Lebens (Ka) ganz allein mit einem Koffer (Mo) nach Freiburg (Lo) gekommen.","Not every sentence has all four. The order stays the same: Ich fliege am Samstag (Te) mit meinem Freund (Mo) nach Porto (Lo).","One element can move to position 1 for emphasis: Am Samstag fliege ich mit meinem Freund nach Porto.","Beispiele: Ich fliege am Samstag wegen eines Familienfests früh mit meinem Freund nach Porto."]]},{"n":97,"t":"Am Flughafen","l":"A2","review":false,"p":[["Samstag, sechs Uhr fünfzehn. Flughafen Basel-Mulhouse. Die Halle ist voll, obwohl es noch dunkel ist. Mia und Jonas stehen in der Schlange am Check-in. Jonas hat seinen Pass in der Hand. Er hat ihn seit Freiburg nicht losgelassen."],["Mitarbeiterin","Guten Morgen. Ihre Pässe, bitte. Wie viele Koffer haben Sie?"],["Jonas","Zwei. Einer ist meiner, einer ist ihrer."],["Mitarbeiterin","Haben Sie die Koffer selbst gepackt?"],["Mia","Ja. Na ja … meinen habe ich gepackt. Seinen hat er gepackt. Dreimal."],["Die Koffer verschwinden auf dem Band. Mias roter, Jonas' schwarzer."],["An der Sicherheitskontrolle legt Jonas alles in eine graue Kiste: Jacke, Gürtel, Handy, Uhr. Mia legt ihre Handtasche daneben. Die braune. Mit dem Umschlag von Frau Schulz darin."],["Hinter ihnen steht eine Familie mit drei Kindern. Alle haben die gleichen blauen Rucksäcke."],["Vater","Wessen Rucksack ist das? Ist das deiner, Leon?"],["Leon","Nein, das ist nicht meiner! Meiner hat einen Dinosaurier!"],["Mutter","Dann ist es Lisas."],["Lisa","Nein! Meiner ist der mit dem Einhorn!"],["Mia lacht. Jonas nimmt ihre Handtasche vom Band."],["Jonas","Ist das deine?"],["Mia","Natürlich ist das meine. Es gibt nur eine braune Handtasche auf der Welt. Gib sie mir!"],["Zwei Stunden später landet das Flugzeug in Porto. Die Sonne scheint. Fünfundzwanzig Grad. Jonas sieht aus dem Fenster. Das Meer. Der Fluss. Die Brücken. Die Häuser mit bunten Fliesen."],["Jonas","Mia. Deine Stadt ist wunderschön."],["Mia","Ab heute ist sie auch ein bisschen deine."],["Am Gepäckband warten sie lange. Dann kommt ein schwarzer Koffer. Jonas nimmt ihn. Dann kommt noch ein schwarzer Koffer. Und noch einer."],["Mia","Jonas … ist das wirklich deiner?"],["Jonas sieht auf den Koffer. Er hat einen grünen Anhänger."],["Jonas","Nein. Meiner hat einen roten Anhänger. Mit einer Brezel darauf. Lena hat ihn mir geschenkt."],["Eine ältere Dame mit einem großen Hut kommt zu ihnen."],["Dame","(auf Englisch) Entschuldigung, ich glaube, Sie haben meinen Koffer."],["Jonas","Oh! Entschuldigung! Hier, das ist Ihrer. Und … wo ist meiner?"],["Der letzte Koffer auf dem Band ist schwarz. Mit einem roten Anhänger. Mit einer Brezel darauf."],["In der Ankunftshalle warten Mama und Rui. Mama hat ein großes Schild aus Pappe. Darauf steht: BEM-VINDO, JONAS! Und darunter, kleiner: E MIA."],["Mia","Mama! Ich bin auch da!"],["Mama","(auf Portugiesisch) Dich kenne ich schon. Ihn noch nicht so gut."],["Sie umarmt Jonas. Dann Mia. Dann noch einmal Jonas."],["Rui","Heute Abend ist das große Fest. Siebzig Gäste. Ihr werdet nicht glauben, wo wir feiern."],["Mia","Wo?"],["Rui","Im Café do Mar. Opas Café. Es gibt es noch. Unser Cousin Diogo hat es übernommen. Und er hat gesagt: Wenn ein Koch aus Deutschland kommt, muss er heute Abend in der Küche helfen."],["Jonas wird blass. Dann grinst er."]],"q":["Wem gehört der rote Koffer? Und der schwarze?","Was ist das Problem der Familie bei der Sicherheitskontrolle?","Woran erkennt Jonas seinen Koffer?","Richtig oder falsch? Auf Mamas Schild steht nur Mias Name.","Und du? Beschreibe deinen Koffer oder deine Tasche. Wie erkennst du ihn/sie? (Meiner ist … / Meine hat …)"],"a":["Der rote ist Mias, der schwarze ist Jonas'. „Mias roter, Jonas' schwarzer.“","All three children have the same blue backpack. „Wessen Rucksack ist das?“","A red tag with a pretzel on it, a present from Lena. „Meiner hat einen roten Anhänger. Mit einer Brezel darauf.“","Falsch. „BEM-VINDO, JONAS! … E MIA.“ – Jonas's name is big, Mia's is small.","Example: Meiner ist blau und hat einen gelben Anhänger. Meine Tasche ist klein und braun."],"w":[["meiner / meine / meins","mine","Einer ist meiner, einer ist ihrer."],["deiner / seiner / ihrer / unserer / eurer / Ihrer","yours / his / hers / ours / yours / yours","Hier, das ist Ihrer."],["wessen","whose","Wessen Rucksack ist das?"],["die Halle, die Hallen","hall","Die Halle ist voll."],["loslassen","to let go","Er hat ihn nicht losgelassen."],["verschwinden","to disappear","Die Koffer verschwinden auf dem Band."],["das Band, die Bänder","(conveyor) belt","auf dem Band"],["die Sicherheitskontrolle","security check","An der Sicherheitskontrolle"],["der Dinosaurier, die Dinosaurier","dinosaur","Meiner hat einen Dinosaurier!"],["das Einhorn, die Einhörner","unicorn","der mit dem Einhorn"],["landen","to land","Das Flugzeug landet in Porto."],["die Brücke, die Brücken","bridge","die Brücken"],["das Gepäckband, die Gepäckbänder","baggage carousel","Am Gepäckband warten sie."],["der Anhänger, die Anhänger","(luggage) tag","einen roten Anhänger"],["die Pappe","cardboard","ein Schild aus Pappe"]],"c":[["Das ist nicht meiner!","That's not mine!","Nein, das ist nicht meiner!"],["Ist das deine / deiner?","Is that yours?","Ist das deine?"],["Ihr werdet nicht glauben, …","You won't believe …","Ihr werdet nicht glauben, wo wir feiern."],["Bem-vindo! (Port.)","Welcome!","BEM-VINDO, JONAS!"]],"x":[["Ich bin dagegen.","I am against it.",""],["Da hast du recht.","you are right there.",""]],"g":["Possessivpronomen",["A possessive pronoun replaces a noun: mein Koffer → meiner.","It takes the endings of der, die, das: meiner (der Koffer) · meine (die Tasche) · meins (das Handy) · meine (Plural).","Accusative masculine: meinen: Ich habe meinen gepackt. Same for deiner, seiner, ihrer, unserer, eurer, Ihrer.","To ask: Wessen Koffer ist das? – Das ist meiner.","Beispiele: Ist das deiner? – Nein, meiner hat einen roten Anhänger. · Natürlich ist das meine."]]},{"n":98,"t":"Ein Fest in Porto","l":"A2","review":false,"p":[["Samstagabend, zwanzig Uhr. Das Café do Mar liegt direkt am Meer, in Foz do Douro. Es ist klein, mit blauen Fliesen an den Wänden und alten Fotos über der Theke. Auf einem Foto steht ein Mann mit weißer Schürze und einem breiten Lächeln. Opa."],["Das Café ist voll. Siebzig Gäste – vielleicht achtzig. Mia stellt Jonas allen vor. Den Tanten, den Onkeln, den Cousins, den Nachbarn, den alten Freunden von Opa. Jonas gibt allen Gästen die Hand. Er sagt jedem sein bestes Portugiesisch: „Muito prazer!“ Nach einer Stunde hat er das achtzigmal gesagt."],["Tante Rosa kneift ihn in die Wange. Onkel Paulo gibt ihm ein Glas Portwein. Die Kinder ziehen an seinem Hemd und wollen Fußball spielen."],["Jonas","Mia, was sagen sie alle?"],["Mia","Die Tanten sagen, dass du zu dünn bist. Die Onkel fragen, für welchen Fußballverein du bist. Und die Kinder wollen wissen, ob du einen Kater hast."],["Jonas","Sag den Tanten, dass ich Koch bin. Sag den Onkeln: FC Porto. Seit Juni. Und sag den Kindern: Ja, aber er gehört einer alten Dame."],["Dann ruft Cousin Diogo aus der Küche. Er ist groß, laut und trägt eine Schürze wie Opa."],["Diogo","(auf Portugiesisch) Wo ist der deutsche Koch? Komm in die Küche! Mit den Händen, nicht mit dem Mund!"],["Jonas geht in die Küche. Opas Küche. Mama legt das alte blaue Rezeptbuch auf den Tisch, auf Seite zwölf: Bacalhau com Natas. Opas berühmtestes Rezept."],["Eine Stunde lang kochen Jonas und Diogo zusammen. Ohne gemeinsame Sprache. Mit Händen, mit Zeichen, mit Lachen. Diogo zeigt auf das Olivenöl. Jonas nickt. Jonas zeigt auf die Muskatnuss. Diogo schüttelt den Kopf. Dann zuckt er mit den Schultern. Dann probiert er. Dann nickt er."],["Um zweiundzwanzig Uhr bringen sie das Essen zu den Gästen. Es ist ganz still im Café. Die alten Freunde von Opa probieren zuerst. Einer, ein sehr alter Mann mit Stock, legt die Gabel hin. Er sagt etwas zu Mama. Mama weint."],["Jonas","Was hat er gesagt? War es schlecht?"],["Mia","Er hat gesagt: „Das schmeckt wie bei Joaquim.“ Joaquim war Opa."],["Jonas sagt nichts. Er sieht zu dem Foto über der Theke. Der Mann mit der weißen Schürze lächelt."],["Dann kommt der Teil, den Mia nicht geplant hat. Rui macht einen Videoanruf auf dem großen Bildschirm im Café. Und auf dem Bildschirm erscheinen: Frau Schulz, mit Felix auf dem Schoß. Elif, braun gebrannt, aus İzmir. Tom mit Bruno, aus Krakau. Rainer und Fátima, in New York, um fünf Uhr nachmittags. Finn mit seinen Trommelstöcken, aus Zürich."],["Alle","Saúde! Prost! Auf Mia und Jonas!"],["Mia steht vor allen Gästen. Den portugiesischen und den deutschen. Den echten und denen auf dem Bildschirm."],["Mia","Ich danke euch allen. Den Freunden hier und den Freunden dort. Vor einem Jahr bin ich mit einem Koffer gegangen. Heute komme ich mit zwei Familien zurück."],["Dann fragt Tante Rosa laut, was alle wissen wollen:"],["Tante Rosa","(auf Portugiesisch) Und die Hochzeit? Wo? In Porto oder in Freiburg?"],["Alle Augen sehen auf Mia und Jonas. Achtzig hier. Fünfzehn auf dem Bildschirm."]],"q":["Wo liegt das Café do Mar? Wer hat es heute?","Was sagen die Tanten, die Onkel und die Kinder über Jonas?","Welches Rezept kocht Jonas? Was sagt der alte Mann?","Richtig oder falsch? Die Freunde aus Freiburg sind alle im Café in Porto.","Und du? Wem gibst du gern Geschenke? Mit welchen Leuten feierst du am liebsten? (mit den Freunden, mit den Kollegen …)"],"a":["Direkt am Meer, in Foz do Douro. Cousin Diogo hat es übernommen.","The aunts say he is too thin, the uncles ask which football club he supports, the children want to know if he has a cat.","Bacalhau com Natas. „Das schmeckt wie bei Joaquim.“ (Joaquim = Opa)","Falsch. They join by video from İzmir, Krakau, New York, Zürich and Freiburg.","Example: Ich gebe meinen Kindern gern Geschenke. Am liebsten feiere ich mit den Freunden aus der Schule."],"w":[["den Tanten / den Onkeln / den Kindern (Dat. Pl.)","to the aunts / uncles / children","Mia stellt Jonas den Tanten vor."],["die Tante, die Tanten","aunt","Tante Rosa"],["kneifen","to pinch","Tante Rosa kneift ihn in die Wange."],["der Portwein","port (wine)","ein Glas Portwein"],["ziehen an","to pull at","Die Kinder ziehen an seinem Hemd."],["das Zeichen, die Zeichen","sign, gesture","mit Händen, mit Zeichen"],["das Olivenöl","olive oil","Diogo zeigt auf das Olivenöl."],["die Muskatnuss","nutmeg","Jonas zeigt auf die Muskatnuss."],["den Kopf schütteln","to shake one's head","Diogo schüttelt den Kopf."],["der Stock, die Stöcke","walking stick","ein alter Mann mit Stock"],["erscheinen","to appear","Auf dem Bildschirm erscheinen …"],["braun gebrannt","tanned","Elif, braun gebrannt"],["Prost! / Saúde!","Cheers!","Saúde! Prost!"],["planen (geplant)","to plan","den Teil, den Mia nicht geplant hat"],["echt","real","den echten und denen auf dem Bildschirm"]],"c":[["jemandem jemanden vorstellen","to introduce sb. to sb.","Mia stellt Jonas allen vor."],["Das schmeckt wie bei …","It tastes like …'s","Das schmeckt wie bei Joaquim."],["Ich danke euch allen.","Thank you all.","Ich danke euch allen."],["alle Augen sehen auf …","all eyes are on …","Alle Augen sehen auf Mia und Jonas."]],"x":[["Ich bin nicht sicher.","I am not sure.",""],["Ich freue mich auf …","I look forward to …",""]],"g":["Dativ Plural",["In the dative plural, the article is den, and the noun gets an extra -n: die Gäste → den Gästen, die Kinder → den Kindern, die Freunde → den Freunden.","No extra -n if the plural already ends in -n or -s: den Tanten, den Cousins, den Autos.","Possessives and adjectives too: mit meinen alten Freunden.","Typical after dative prepositions and dative verbs: mit, zu, von, bei · danken, helfen, geben, zeigen.","Beispiele: Jonas gibt allen Gästen die Hand. · Ich danke den Freunden hier und den Freunden dort."]]},{"n":99,"t":"Nächstes Jahr …","l":"A2","review":false,"p":[["Mia sieht Jonas an. Jonas nickt. Sie haben in der Küche darüber gesprochen, zwischen zwei Tellern Bacalhau."],["Mia","Wir heiraten in Freiburg. Im Mai. Im Standesamt, mit Herrn Krause als Ehrengast. Danach feiern wir im Café Bächle. Und im August kommen wir nach Porto. Dann gibt es ein zweites Fest. Hier, im Café do Mar. Mit allen."],["Tante Rosa klatscht. Dann klatschen alle. Achtzig in Porto, fünfzehn auf dem Bildschirm. Frau Schulz ruft: „Ich backe den Kuchen!“ Und Felix springt vom Bildschirm weg."],["Zwei Wochen Porto vergehen wie zwei Tage. Mia zeigt Jonas alles: die Brücken, die alten Gassen, den Strand, Opas Grab. Jonas kocht jeden Tag mit Diogo. Und er lernt neue Wörter. Am Ende kann er zweiundvierzig."],["Samstag, siebenundzwanzigster September. Freiburg. Zu Hause riecht es nach Herbst. Auf dem Balkon liegen die ersten gelben Blätter."],["Am Abend sitzt Mia am Laptop. Eine E-Mail vom Goethe-Institut: Ihr Prüfungsergebnis ist online."],["Ihre Hände zittern. Jonas setzt sich neben sie. Felix setzt sich auf die Tastatur. Mia schiebt ihn weg. Sie klickt."],["Goethe-Zertifikat A2. Ergebnis: bestanden. Punkte: 91 von 100. Prädikat: gut."],["Mia sagt nichts. Sie kann nichts sagen. Dann steht sie auf und schreit so laut, dass Finn von oben an die Decke klopft."],["Jonas","Einundneunzig! Mia! Einundneunzig!"],["Mia","Der Umschlag! Jetzt darf ich ihn öffnen!"],["Sie holt die braune Handtasche. Der Umschlag ist noch da. Für Mia. Sie öffnet ihn. Darin ist ein altes Schwarz-Weiß-Foto und ein Brief."],["Auf dem Foto steht eine junge Frau vor einem Haus in der Lindenstraße. Mit einem großen Koffer. Und einem unsicheren Lächeln. Auf der Rückseite steht: Renate, September 1973. Der erste Tag."],["In dem Brief steht:"],["Liebe Mia,"],["wenn Sie das lesen, haben Sie bestanden. Ich habe es gewusst."],["Vor einem Jahr standen Sie genau da, wo ich vor fünfzig Jahren stand. Mit einem Koffer, ohne Deutsch, allein. Ich habe mich in Ihnen wiedererkannt. Vom ersten Tag an."],["Jetzt sind Sie keine Fremde mehr. Sie sind eine Freiburgerin. Mit Bächle-Garantie."],["Ich habe nur eine Bitte","Sagen Sie Renate zu mir. Und „du“. Das wollte ich schon lange sagen. Aber ich bin eben eine alte Berlinerin. Wir brauchen Zeit."],["Deine Renate"],["PS","Die Brezel morgen früh vor deiner Tür ist von mir. Nicht von Felix."],["Mia weint. Jonas auch. Felix nicht. Felix schläft auf der Tastatur."],["Am nächsten Morgen liegt vor der Tür eine Papiertüte. Darin ist eine Brezel. Frisch und warm."],["Mia geht nach unten. Renate steht vor ihrer Tür, mit Mantel und Koffer. Michael wartet draußen im Auto."],["Mia","Danke, Renate. Für alles."],["Renate","Nichts zu danken. Also: Ich fahre jetzt nach Hamburg. Im März komme ich zurück. Im Mai ist eure Hochzeit. Im August fahre ich mit euch nach Porto. Das habe ich gestern beschlossen."],["Mia","Nach Porto? Mit uns?"],["Renate","Ich bin noch nie geflogen. Mit vierundsiebzig wird es Zeit."],["Sie umarmt Mia. Lange. Dann rollt sie mit dem Rollator die Rampe hinunter. Am Auto dreht sie sich noch einmal um."],["Renate","Und Mia: Am Mittwoch fängt dein neuer Job als Teamleiterin an. Komm pünktlich."]],"q":["Wo und wann heiraten Mia und Jonas? Wo feiern sie?","Wie viele Punkte hat Mia in der Prüfung?","Was ist im Umschlag von Frau Schulz?","Richtig oder falsch? Frau Schulz bleibt den ganzen Winter in Freiburg.","Und du? Was machst du nächste Woche? Nächstes Jahr? (Nächste Woche fahre ich … Im Sommer …)"],"a":["Im Mai in Freiburg, im Standesamt, dann Fest im Café Bächle; im August ein zweites Fest im Café do Mar in Porto.","91 von 100 – „gut“.","An old photo of Renate on her first day in 1973, and a letter: she offers Mia „du“.","Falsch. „Ich fahre jetzt nach Hamburg. Im März komme ich zurück.“","Example: Nächste Woche fange ich einen neuen Kurs an. Im Sommer fliege ich nach Portugal."],"w":[["der Ehrengast, die Ehrengäste","guest of honour","mit Herrn Krause als Ehrengast"],["vergehen","to pass (time)","Zwei Wochen vergehen wie zwei Tage."],["die Gasse, die Gassen","lane, alley","die alten Gassen"],["das Grab, die Gräber","grave","Opas Grab"],["das Blatt, die Blätter","leaf","die ersten gelben Blätter"],["schieben","to push","Mia schiebt ihn weg."],["der Punkt, die Punkte","point","91 von 100 Punkten"],["das Prädikat","grade, rating","Prädikat: gut."],["unsicher","uncertain, shy","mit einem unsicheren Lächeln"],["wiedererkennen","to recognise","Ich habe mich in Ihnen wiedererkannt."],["die Garantie, die Garantien","guarantee","Mit Bächle-Garantie."],["beschließen","to decide","Das habe ich gestern beschlossen."],["der Mantel","coat","mit Mantel und Koffer"],["schwarz-weiß","black and white","ein altes Schwarz-Weiß-Foto"],["die Berlinerin","woman from Berlin","eine alte Berlinerin"]],"c":[["Nichts zu danken.","Don't mention it.","Nichts zu danken."],["vom ersten Tag an","from day one","Vom ersten Tag an."],["Es wird Zeit.","It's about time.","Mit vierundsiebzig wird es Zeit."],["Sag du zu mir.","Call me du.","Sagen Sie „du“."]],"x":[["Ich freue mich über …","I am happy about …",""],["Ich ärgere mich über …","I am annoyed about …",""]],"g":["Präsens für die Zukunft",["For plans and arrangements, Germans usually use the present tense + a time expression, not werden.","Morgen fängt dein Job an. · Im März komme ich zurück. · Im Mai heiraten wir.","Typical time words: morgen, übermorgen, nächste Woche, nächstes Jahr, im Mai, am Wochenende, bald, später.","Use werden for promises, predictions or when the time is not clear: Ich werde gut auf sie aufpassen. (story 75)","Beispiele: Im August fahre ich mit euch nach Porto. · Wir heiraten im Mai in Freiburg."]]},{"n":100,"t":"Große Wiederholung: Ein Jahr in Freiburg","l":"A2","review":true,"p":[["Montag, neun Uhr. Kursraum zwei, Sprachschule Freiburg. Vor Mia sitzen fünfzehn neue Kursteilnehmer. Aus Syrien, aus der Ukraine, aus Brasilien, aus Japan, aus den USA. Manche sehen nervös aus. Eine junge Frau ganz hinten sieht sehr müde aus. Neben ihr steht ein großer Koffer."],["Herr Brandt","Guten Morgen. Das ist Frau Costa. Mia. Sie war vor einem Jahr genau hier. In diesem Raum. In der ersten Reihe. Sie hat meine erste Frage nicht verstanden."],["Mia","Er hat zu schnell gesprochen!"],["Alle lachen. Herr Brandt auch."],["„Hallo zusammen. Mein Name ist Mia Costa. Ich komme aus Porto, aus Portugal. Vor einem Jahr bin ich ganz allein mit einem großen Koffer nach Freiburg gekommen. Ich hatte kein Bett, keinen Job und kein Wort Deutsch. Na ja – drei Wörter: Hallo, danke, Tschüss."],["Am ersten Abend hat mein Nachbar mir einen Zettel unter die Tür gelegt: Woher bist du? Heute ist dieser Nachbar mein Verlobter. Im Mai heiraten wir."],["Ich möchte euch erzählen, was ich in diesem Jahr gelernt habe. Nicht nur Grammatik. Sondern das Leben."],["Erstens","Fragt. Immer. Wenn ihr etwas nicht versteht, sagt: Wie bitte? Noch einmal, bitte. Langsam, bitte. Das sind die wichtigsten Wörter im Deutschkurs. Die Deutschen sind am Anfang ein bisschen kühl. Aber wenn man fragt, helfen sie gern."],["Zweitens","Habt keine Angst vor Fehlern. Ich habe tausend Fehler gemacht. Beim Arzt, auf dem Bürgeramt, im Vorstellungsgespräch. Trotzdem habe ich heute einen guten Job. Ich bin seit einer Woche Teamleiterin in einer Agentur."],["Drittens","Sprecht mit den Nachbarn. Meine Nachbarin war zuerst sehr streng. Sie hat mir die Hausordnung erklärt. Paragraf für Paragraf. Heute ist sie wie eine Oma für mich. Und ihr Kater wohnt jetzt bei mir. Er stiehlt Löffel, Schlüssel und Socken."],["Viertens","Lernt die Bürokratie lieben. Okay, das ist ein Witz. Aber bringt immer alle Papiere mit. Immer. Glaubt mir."],["Und fünftens","Wenn ihr Heimweh habt – und ihr werdet Heimweh haben –, dann geht auf den Markt. Kauft eine Brezel. Setzt euch in ein Café. Und tretet ins Bächle. Man sagt, dass man dann für immer in Freiburg bleibt. Bei mir hat es funktioniert."],["Was war am schwersten? Der, die, das. Immer noch! Und was war am schönsten? Die Menschen. Ohne sie wäre ich heute nicht hier."],["Ich habe vor einer Woche die A2-Prüfung bestanden. Wenn ich das geschafft habe, schafft ihr das auch. Viel Glück!“"],["Die Kursteilnehmer klatschen. Ein Mann aus Syrien fragt, wo das Café ist. Eine Frau aus Japan schreibt sich das Wort Bächle auf."],["Nach dem Kurs geht Mia nach Hause. Durch die Altstadt, über den Münsterplatz, die Bächle entlang. Es ist ein warmer Oktobertag. Die Bäume sind gelb und orange, wie vor einem Jahr."],["In der Lindenstraße, vor Haus Nummer vierzehn, steht eine junge Frau. Es ist die müde Frau aus dem Kurs. Mit dem großen Koffer. Sie sieht auf einen Zettel. Dann auf die Hausnummern. Dann wieder auf den Zettel. Sie sieht verloren aus."],["Mia bleibt stehen. Sie lächelt."],["Mia","Hallo! Bist du neu hier? Kann ich dir helfen?"],["Die junge Frau sieht sie an. Erleichtert."],["Junge Frau","Ja … ich bin neu hier. Ich heiße Amira."],["Mia","Freut mich, Amira. Ich bin Mia. Woher kommst du?"],["Und im Fenster von Wohnung zwei sitzt ein grauer Kater und sieht nach unten. Sehr interessiert. Morgen früh, denkt Mia, liegt vielleicht eine Brezel vor einer neuen Tür."],["ENDE"]],"q":["Verbinde mit weil: Mia ist glücklich. Sie hat die Prüfung bestanden.","Komparativ / Superlativ: Freiburg ist ___ (klein) als Porto. Die Menschen waren ___ (schön).","Reflexiv + Präposition: Wir kümmern ___ ___ Felix.","Adjektivendung: Mia hat einen ___ (neu) Job in einer ___ (modern) Agentur.","wo-/da-: ___ hast du Angst? – ___, dass es nicht funktioniert.","Konjunktiv II: ___ Sie mir bitte helfen? An deiner Stelle ___ ich anrufen.","Indirekte Frage: „Woher kommst du?“ → Mia fragt Amira, …","Genitiv: Das ist das Rezeptbuch ___ Großvaters (ihr).","Pronomen-Reihenfolge: Er gibt Mia den Ring. → Er gibt ___ ___.","Länder: Elif fliegt ___ Türkei. Rainer und Fátima fliegen ___ USA."],"a":["Mia ist glücklich, weil sie die Prüfung bestanden hat. Conjugated verb at the very end (stories 51, 86).","kleiner · am schönsten. (stories 54–55)","uns um. sich kümmern um (story 94).","neuen · modernen. After einen (acc. masc.) and einer (dat. fem.) → -en (story 62).","Wovor · Davor. Angst haben vor (story 65).","Könnten · würde. (stories 66–67)","… woher sie kommt. (story 72)","ihres. Genitive masculine: ihr → ihres Großvaters (story 74).","ihn ihr. Two pronouns: accusative before dative (story 83).","in die · in die. Countries with an article (story 95)."],"w":[],"c":[],"x":[],"g":["A2 auf einen Blick",["Sentences: subordinate clauses with weil, dass, wenn, ob, indirect questions, verb clusters at the end, subordinate clause first, deshalb / trotzdem, TeKaMoLo.","Verbs: reflexive verbs (accusative, dative, with prepositions), verbs with prepositions + wo-/da-, dative verbs, Konjunktiv II (würde, hätte, wäre, könnte, sollte), Präteritum (modal verbs, reading), Perfekt of -ieren and mixed verbs, werden, present tense for the future.","Nouns and adjectives: adjective endings (3 types), comparative / superlative / so … wie, genitive, n-declension, dative plural, word formation.","Pronouns and articles: dies-, jed-, welch-, was für ein, indefinite and possessive pronouns, pronoun order.","Prepositions: two-way prepositions (Wo? / Wohin?), stellen/stehen, all dative and accusative prepositions, time prepositions, countries with articles, hin/her.","Beispiel: Wenn ich das geschafft habe, schafft ihr das auch."]],"exam":{"task":"Sie lernen jetzt ein Jahr Deutsch. Schreiben Sie einer Freundin eine E-Mail.","points":["Was war am Anfang schwer?","Was können Sie jetzt gut?","Was sind Ihre Pläne für das nächste Jahr?"],"words":60,"en":"Email: one year of German — what was hard, what you can do now, plans."}}];
